# ============================================================================
# ENUMS E CLASSES DE DADOS - ESTRUTURAS AUXILIARES
# ============================================================================

class OrderType(Enum):
    """Tipos de ordem disponíveis"""
    MARKET = "MARKET"
    LIMIT = "LIMIT"
    STOP_LOSS = "STOP_LOSS"
    TAKE_PROFIT = "TAKE_PROFIT"
    TRAILING_STOP = "TRAILING_STOP"
    STOP_LOSS_LIMIT = "STOP_LOSS_LIMIT"

class OrderSide(Enum):
    """Lado da ordem"""
    BUY = "BUY"
    SELL = "SELL"

class OrderStatus(Enum):
    """Status da ordem"""
    NEW = "NEW"
    CANCELED = "CANCELED"
    EXPIRED = "EXPIRED"
    PENDING = "PENDING"
    FILLED = "FILLED"
    PARTIALLY_FILLED = "PARTIALLY_FILLED"
    CANCELLED = "CANCELLED"
    REJECTED = "REJECTED"

class PositionSide(Enum):
    """Lado da posição"""
    LONG = auto()
    SHORT = auto()
    NONE = auto()

class TradingMode(Enum):
    """Modo de trading"""
    PAPER = "PAPER"  # Simulação
    LIVE = "LIVE"    # Real

class TimeInForce(Enum):
    """Time in force"""
    GTC = "GTC"  # Good Till Cancel
    IOC = "IOC"  # Immediate or Cancel
    FOK = "FOK"  # Fill or Kill

class SignalType(Enum):
    """Tipos de sinal de trading"""
    STRONG_BUY = auto()
    BUY = auto()
    NEUTRAL = auto()
    SELL = auto()
    STRONG_SELL = auto()

class TaskStatus(Enum):
    """Status de uma tarefa de cálculo"""
    PENDING = "pending"
    PROCESSING = "processing"
    COMPLETED = "completed"
    FAILED = "failed"
    CANCELLED = "cancelled"

class StrategyState(Enum):
    """Estados possíveis de uma estratégia"""
    STOPPED = "STOPPED"
    RUNNING = "RUNNING"
    PAUSED = "PAUSED"
    ERROR = "ERROR"

class AlertLevel(Enum):
    """Níveis de severidade do alerta"""
    INFO = auto()      # 🔵 Informacional
    SUCCESS = auto()   # 🟢 Sucesso
    WARNING = auto()   # 🟡 Atenção
    ERROR = auto()     # 🟠 Erro
    CRITICAL = auto()  # 🔴 Crítico


class AlertSource(Enum):
    """Fonte de origem do alerta"""
    CACHE = "CacheSystem"
    ML = "MLSystem"
    RISK = "RiskEngine"
    EXECUTION = "ExecutionEngine"
    STRATEGY = "StrategyManager"
    BINANCE = "BinanceData"
    SYSTEM = "System"
    CUSTOM = "CustomRule"


class AlertType(Enum):
    """Tipo de alerta (legacy compatibility)"""
    PRICE = "price"
    VOLUME = "volume"
    INDICATOR = "indicator"
    ML = "ml"
    PATTERN = "pattern"


class AlertCondition(Enum):
    """Condição do alerta"""
    ABOVE = "above"
    BELOW = "below"
    CROSS_UP = "cross_up"
    CROSS_DOWN = "cross_down"
    DETECTED = "detected"

class TrendConfidenceRegime(Enum):
    """
    Regime de Confiança na Tendência para TrendFollowingStrategy

    Define o nível de confiança na tendência atual e controla quais
    condições de saída estão ativas em cada fase da posição.

    Filosofia: "Confiança Dinâmica na Tendência"
    - Início: Máxima cautela (pode ser falso breakout)
    - Meio: Confiança plena (tendência confirmada + capital protegido)
    - Fim: Saída controlada (EMAs indicam reversão)
    """
    ALERT = "alert"           # 🚨 Início: todas condições ATIVAS (proteção máxima)
    CONFIDENCE = "confidence" # ✅ Meio: SL/MACD/ADX DESATIVADOS, Trailing ATIVO
    EXIT = "exit"             # 🔴 Fim: todas condições REATIVADAS (saída agressiva)

