@dataclass
class QueueStats:
    """Estatísticas da fila"""
    total_enqueued: int = 0
    total_dequeued: int = 0
    current_size: int = 0
    by_priority: Dict[int, int] = None
    by_symbol: Dict[str, int] = None
    
    def __post_init__(self):
        if self.by_priority is None:
            self.by_priority = {1: 0, 2: 0, 3: 0}
        if self.by_symbol is None:
            self.by_symbol = {}

@dataclass
class Gap:
    """Representa um gap detectado"""
    symbol: str
    interval: str
    start: int              # Open_time do primeiro kline faltante
    end: int                # Open_time do último kline faltante
    missing_count: int      # Quantidade de klines faltando
    detected_at: int        # Timestamp de detecção
    priority: int = 2       # 1=high, 2=medium, 3=low
    status: str = 'detected' # detected, queued, filling, filled, failed

@dataclass
class MarketData:
    """Estrutura para dados de mercado"""
    symbol: str
    timestamp: datetime
    open: float
    high: float
    low: float
    close: float
    volume: float
    quote_volume: float
    trades: int
    
    def to_dict(self) -> Dict[str, Any]:
        """Converte para dicionário"""
        return asdict(self)

@dataclass
class Order:
    """Estrutura para ordem de trading"""
    order_id: str
    symbol: str
    side: OrderSide
    order_type: OrderType
    quantity: float
    size: float
    price: Optional[float] = None # None para market orders
    stop_price: Optional[float] = None
    created_time: datetime = None
    filled_time: Optional[datetime] = None
    status: OrderStatus = OrderStatus.PENDING
    filled_quantity: float = 0.0
    average_price: float = 0.0
    filled_size: float = 0.0
    filled_price: float = 0.0
    commission: float = 0.0
    slippage: float = 0.0
    timestamp: datetime = field(default_factory=datetime.now)

    def __post_init__(self):
        if self.created_time is None:
            self.created_time = datetime.now()
    
    def to_dict(self) -> Dict[str, Any]:
        """Converte para dicionário"""
        d = asdict(self)
        d['side'] = self.side.name
        d['order_type'] = self.order_type.name
        d['status'] = self.status.name
        return d

@dataclass
class CalculationTask:
    """
    Tarefa de cálculo de indicadores técnicos
    
    Attributes:
        task_id: ID único da tarefa
        task_type: 'single' ou 'batch'
        symbols: Lista de símbolos a processar
        interval: Intervalo temporal (ex: '1h')
        priority: 1=alta, 2=média, 3=baixa
        requester_id: Identificador do solicitante
        timestamp: Timestamp de criação
        status: Status atual da tarefa
        worker_id: ID do worker processando (se aplicável)
        klines_data: Dados de klines pré-carregados
        result: Resultado do cálculo
    """
    task_id: int
    task_type: str  # 'single' ou 'batch'
    symbols: List[str]
    interval: str
    priority: int
    requester_id: str
    timestamp: float = field(default_factory=time.time)
    status: TaskStatus = TaskStatus.PENDING
    worker_id: Optional[int] = None
    klines_data: Optional[Dict[str, List]] = None
    result: Optional[Any] = None
    error: Optional[str] = None

