@dataclass
class StorageMetrics:
    """Métricas do Storage Worker"""
    # Ingestão
    klines_ingested_total: int = 0
    klines_per_second: float = 0.0
    ingest_queue_size: int = 0
    
    # Disco
    klines_written_total: int = 0
    disk_writes_per_second: float = 0.0
    disk_write_latency_ms: float = 0.0
    total_disk_usage_mb: float = 0.0
    
    # Dedup
    duplicates_skipped: int = 0
    updates_performed: int = 0
    
    # Gaps
    gaps_detected_total: int = 0
    gaps_filled_total: int = 0
    gaps_pending: int = 0
    gaps_failed: int = 0
    
    # Backfill
    backfill_tasks_active: int = 0
    backfill_success_rate: float = 100.0
    
    # Qualidade
    data_quality_score: float = 100.0
    
    def to_dict(self) -> Dict:
        """Converte para dicionário"""
        return asdict(self)
    
    def save(self, path: str):
        """Salva métricas em JSON"""
        with open(path, 'w') as f:
            json.dump(self.to_dict(), f, indent=2)
    
    @classmethod
    def load(cls, path: str):
        """Carrega métricas de JSON"""
        with open(path, 'r') as f:
            data = json.load(f)
        return cls(**data)
    
