@dataclass(slots=True)
class ConditionCheckResult:
    """
    Resultado de uma verificação de condição individual em should_enter/should_exit

    Attributes:
        timestamp: Momento da verificação
        condition_name: Nome da condição (ex: 'rsi', 'macd', 'volume', 'bollinger')
        indicator_value: float
        threshold_value: float
        threshold_type: str - Tipo de comparação ('>', '<', '>=', '<=', 'between', 'crossover')
        passed: bool - Se a condição foi aprovada
        contribution_to_score: int - Contribuição para o score (geralmente 0 ou 1)
        notes: str - Informações adicionais

    Uso:
        Cada condição verificada em should_enter/should_exit gera um objeto deste tipo.
        Permite análise granular de quais condições aprovam/rejeitam entradas.
    """
    timestamp: datetime
    condition_name: str
    indicator_value: float
    threshold_value: float
    threshold_type: str
    passed: bool
    contribution_to_score: int = 0
    notes: str = ""

@dataclass(slots=True)
class EntryAttempt:
    """
    Registro de uma tentativa de entrada (chamada de should_enter)

    Attributes:
        timestamp: datetime
        symbol: str
        current_price: float
        conditions_checked: Lista de ConditionCheckResult
        score: int - Score total obtido
        min_score_required: int
        max_score: int
        approved: bool
        rejection_reason: Optional[str]
        tp_price: Optional[float] - Take Profit calculado (se aprovado)
        sl_price: Optional[float] - Stop Loss calculado (se aprovado)
        tp_percent: Optional[float] - Take Profit percentual (se aprovado)
        sl_percent: Optional[float] - Stop Loss percentual (se aprovado)
        notes: Optional[str] - Notas adicionais sobre o cálculo de TP/SL

    Uso:
        Cada chamada de should_enter() gera um EntryAttempt.
        Permite análise de taxa de aprovação e condições bloqueadoras.
    """
    timestamp: datetime
    symbol: str
    current_price: float
    conditions_checked: List['ConditionCheckResult']
    score: int
    min_score_required: int
    max_score: int
    approved: bool
    rejection_reason: Optional[str] = None
    tp_price: Optional[float] = None
    sl_price: Optional[float] = None
    tp_percent: Optional[float] = None
    sl_percent: Optional[float] = None
    notes: Optional[str] = None

@dataclass(slots=True)
class ExitDecision:
    """
    Registro de uma decisão de saída de posição (chamada de should_exit)

    Attributes:
        timestamp: datetime
        symbol: str
        entry_price: float
        current_price: float
        pnl: float
        pnl_percent: float
        exit_reason: str ('take_profit', 'stop_loss', 'time_limit', 'indicator')
        exit_conditions_checked: Lista de ConditionCheckResult
        time_in_position_hours: float
        should_exit: bool

    Uso:
        Cada chamada de should_exit() gera um ExitDecision.
        Permite análise de distribuição de razões de saída.
    """
    timestamp: datetime
    symbol: str
    entry_price: float
    current_price: float
    pnl: float
    pnl_percent: float
    exit_reason: str
    exit_conditions_checked: List['ConditionCheckResult']
    time_in_position_hours: float
    should_exit: bool

@dataclass
class Alert:
    """
    Estrutura de dados de um alerta - Versão híbrida
    Combina campos do sistema atual + legacy
    """
    id: str
    timestamp: datetime
    level: AlertLevel
    source: AlertSource
    title: str
    message: str
    
    # Campos opcionais - sistema atual
    details: str = ""
    symbol: str = ""
    acknowledged: bool = False
    acknowledged_at: Optional[datetime] = None
    expires_at: Optional[datetime] = None
    count: int = 1
    metadata: Dict[str, Any] = field(default_factory=dict)
    action_buttons: List[str] = field(default_factory=list)
    
    # Campos adicionais - legacy
    alert_type: str = "price"  # price, volume, indicator, ml, pattern
    condition: str = "above"   # above, below, cross_up, cross_down
    value: float = 0.0         # target value
    current_value: float = 0.0
    is_active: bool = True
    repeat: bool = True
    sound_enabled: bool = True
    telegram_enabled: bool = False
    ml_confidence_threshold: float = 0.75
    description: str = ""
    created_at: str = ""
    last_triggered: str = ""
    trigger_count: int = 0
    
    def to_dict(self) -> dict:
        """Serializa para dicionário"""
        return {
            'id': self.id,
            'timestamp': self.timestamp.isoformat(),
            'level': self.level.name,
            'source': self.source.value,
            'title': self.title,
            'message': self.message,
            'details': self.details,
            'symbol': self.symbol,
            'acknowledged': self.acknowledged,
            'acknowledged_at': self.acknowledged_at.isoformat() if self.acknowledged_at else None,
            'expires_at': self.expires_at.isoformat() if self.expires_at else None,
            'count': self.count,
            'metadata': self.metadata,
            'alert_type': self.alert_type,
            'condition': self.condition,
            'value': self.value,
            'current_value': self.current_value,
            'is_active': self.is_active,
            'repeat': self.repeat,
            'sound_enabled': self.sound_enabled,
            'telegram_enabled': self.telegram_enabled,
            'ml_confidence_threshold': self.ml_confidence_threshold,
            'description': self.description,
            'created_at': self.created_at,
            'last_triggered': self.last_triggered,
            'trigger_count': self.trigger_count
        }
    
    @classmethod
    def from_dict(cls, data: dict) -> 'Alert':
        """Deserializa de dicionário"""
        return cls(
            id=data['id'],
            timestamp=datetime.fromisoformat(data['timestamp']),
            level=AlertLevel[data['level']],
            source=AlertSource(data['source']),
            title=data['title'],
            message=data['message'],
            details=data.get('details', ''),
            symbol=data.get('symbol', ''),
            acknowledged=data.get('acknowledged', False),
            acknowledged_at=datetime.fromisoformat(data['acknowledged_at']) if data.get('acknowledged_at') else None,
            expires_at=datetime.fromisoformat(data['expires_at']) if data.get('expires_at') else None,
            count=data.get('count', 1),
            metadata=data.get('metadata', {}),
            alert_type=data.get('alert_type', 'price'),
            condition=data.get('condition', 'above'),
            value=data.get('value', 0.0),
            current_value=data.get('current_value', 0.0),
            is_active=data.get('is_active', True),
            repeat=data.get('repeat', True),
            sound_enabled=data.get('sound_enabled', True),
            telegram_enabled=data.get('telegram_enabled', False),
            ml_confidence_threshold=data.get('ml_confidence_threshold', 0.75),
            description=data.get('description', ''),
            created_at=data.get('created_at', ''),
            last_triggered=data.get('last_triggered', ''),
            trigger_count=data.get('trigger_count', 0)
        )

@dataclass
class AlertTriggerRecord:
    """Registro de disparo de alerta"""
    alert_id: str
    symbol: str
    trigger_time: str
    trigger_value: float
    alert_description: str
    notification_sent: bool

@dataclass
class SignalEntry:
    """
    Representa um sinal Qt registrado no sistema
    """
    name: str                          # Nome do sinal (ex: "data_updated")
    emitter_class: str                 # Classe que emite (ex: "CacheSystem")
    emitter_ref: Any                   # weakref para o objeto emissor
    signature: str                     # Assinatura (ex: "(str)")
    full_path: str                     # Caminho completo (ex: "CacheSystem.data_updated")
    
    # Estatísticas em tempo real
    count: int = 0                     # Total de emissões desde início
    rate_per_sec: float = 0.0          # Taxa atual (eventos/segundo)
    last_seen: Optional[datetime] = None  # Última emissão
    avg_payload_size: float = 0.0      # Tamanho médio do payload (bytes)
    
    # Estado
    is_enabled: bool = True            # Se está sendo capturado
    sample_rate: int = 1               # 1 = captura todos, 10 = captura 1 a cada 10
    
    # Buffers
    recent_messages: deque = field(default_factory=lambda: deque(maxlen=200))
    rate_window: deque = field(default_factory=lambda: deque(maxlen=60))  # 60 segundos


@dataclass
class SignalMessage:
    """
    Representa uma mensagem/payload capturada de um sinal
    """
    timestamp: datetime
    signal_name: str
    emitter_class: str
    emitter_id: str                    # repr ou id do objeto
    args: tuple                        # Argumentos do sinal
    payload_size: int                  # Tamanho em bytes
    
    def to_dict(self) -> dict:
        """Converte para dicionário para serialização"""
        return {
            'timestamp': self.timestamp.isoformat(),
            'signal': self.signal_name,
            'emitter': self.emitter_class,
            'emitter_id': self.emitter_id,
            'args': [self._serialize_arg(arg) for arg in self.args],
            'payload_size': self.payload_size
        }
    
    def _serialize_arg(self, arg):
        """Serializa um argumento para JSON"""
        if isinstance(arg, (str, int, float, bool, type(None))):
            return arg
        elif isinstance(arg, dict):
            return {k: self._serialize_arg(v) for k, v in arg.items()}
        elif isinstance(arg, (list, tuple)):
            return [self._serialize_arg(item) for item in arg]
        else:
            return str(arg)

# ============================================================================
# UTILITÁRIOS - FUNÇÕES AUXILIARES
# ============================================================================

def get_timestamp() -> int:
    """Retorna timestamp atual em milissegundos"""
    return int(time.time() * 1000)

def format_timestamp(ts: Union[int, float], fmt: str = '%Y-%m-%d %H:%M:%S') -> str:
    """Formata timestamp para string legível"""
    if ts > 1e12:  # Timestamp em milissegundos
        ts = ts / 1000
    return datetime.fromtimestamp(ts).strftime(fmt)

def safe_float(value: Any, default: float = 0.0) -> float:
    """Converte valor para float de forma segura"""
    try:
        return float(value)
    except (ValueError, TypeError):
        return default

def safe_int(value: Any, default: int = 0) -> int:
    """Converte valor para int de forma segura"""
    try:
        return int(value)
    except (ValueError, TypeError):
        return default

def calculate_percentage_change(old: float, new: float) -> float:
    """Calcula mudança percentual"""
    if old == 0:
        return 0.0
    return ((new - old) / old) * 100

def truncate_float(value: float, decimals: int = 8) -> float:
    """Trunca float para número específico de decimais"""
    multiplier = 10 ** decimals
    return int(value * multiplier) / multiplier

def generate_order_id() -> str:
    """Gera ID único para ordem"""
    return f"ORD_{get_timestamp()}_{secrets.token_hex(4)}"

def generate_cache_key(*parts: str) -> str:
    """Gera chave de cache a partir de partes"""
    return ":".join(str(part) for part in parts)

