# ============================================================================
# LOGGER SYSTEM - SISTEMA DE LOGGING AVANÇADO
# ============================================================================

class LoggerSystem(QObject):
    """
    Sistema Central de Logging
    
    - Sistema de categorias automático
    - Logs estruturados como dict
    - Suporte a traceback em logs estruturados
    - Mapeamento automático módulo → categoria
    
    SINAL:
            
        log_entry_emitted(log_dict: dict)
            - Sinal novo com log completo estruturado
            - Formato: {
                'timestamp': '2024-12-10T15:23:45.123456',
                'level': 'INFO',
                'module': 'BinanceData',
                'category': 'api',
                'message': 'Conectado com sucesso',
                'function': 'connect',
                'line': 123,
                'traceback': None,  # ou string se houver exceção
              }
    """
    
    # ========================================================================
    # SINAl QT
    # ========================================================================
    
    # Logs estruturados completos
    log_entry_emitted = Signal(dict)  # log_dict completo
    
    # ========================================================================
    # SINGLETON
    # ========================================================================
    
    _instance = None
    _initialized = False
    _loggers_cache: Dict[str, logging.Logger] = {}
    _lock = Lock()
    
    def __new__(cls):
        """Implementação Singleton thread-safe"""
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance
    
    def __init__(self):
        """
        Inicializa LoggerSystem - Executa apenas uma vez
        """
        if LoggerSystem._initialized:
            return
        
        super().__init__()
        
        try:
            # Logger local para o próprio LoggerSystem
            logger = logging.getLogger('LoggerSystem')
            
            logger.info("=" * 80)
            logger.info("INICIALIZANDO LOGGER SYSTEM")
            logger.info("=" * 80)
            
            # ================================================================
            # CONFIGURAR ROOT LOGGER
            # ================================================================
            root_logger = logging.getLogger()
            root_logger.setLevel(logging.DEBUG)
            
            # Remover handlers existentes
            for handler in root_logger.handlers[:]:
                root_logger.removeHandler(handler)
            
            logger.info("Root logger configurado (DEBUG)")
            
            # ================================================================
            # HANDLER 1: CONSOLE (INFO+)
            # ================================================================
            console_handler = logging.StreamHandler(sys.stdout)
            console_handler.setLevel(logging.INFO)
            console_formatter = logging.Formatter(
                CONSOLE_FORMAT,
                datefmt=DATE_FORMAT
            )
            console_handler.setFormatter(console_formatter)
            root_logger.addHandler(console_handler)
            logger.info(f"✅ Console handler configurado (INFO+)")
            
            # ================================================================
            # HANDLER 2: FILE COM ROTAÇÃO (DEBUG+)
            # ================================================================
            file_handler = logging.handlers.TimedRotatingFileHandler(
                MAIN_LOG_FILE,
                when='midnight',
                interval=1,
                backupCount=14,  # 14 dias de histórico
                encoding='utf-8'
            )
            file_handler.setLevel(logging.DEBUG)
            file_formatter = logging.Formatter(
                LOG_FORMAT,
                datefmt=DATE_FORMAT
            )
            file_handler.setFormatter(file_formatter)
            root_logger.addHandler(file_handler)
            logger.info(f"✅ File handler configurado: {MAIN_LOG_FILE}")
            
            # ================================================================
            # HANDLER 3: ERROR FILE (ERROR+)
            # ================================================================
            error_handler = logging.handlers.TimedRotatingFileHandler(
                ERROR_LOG_FILE,
                when='midnight',
                interval=1,
                backupCount=30,  # 30 dias de erros
                encoding='utf-8'
            )
            error_handler.setLevel(logging.ERROR)
            error_formatter = logging.Formatter(
                LOG_FORMAT + "\n%(pathname)s:%(lineno)d",
                datefmt=DATE_FORMAT
            )
            error_handler.setFormatter(error_formatter)
            root_logger.addHandler(error_handler)
            logger.info(f"✅ Error handler configurado: {ERROR_LOG_FILE}")
            
            # ================================================================
            # HANDLER 4: QT SIGNAL EMITTER (INFO+)
            # ================================================================
            qt_handler = self._create_qt_handler()
            root_logger.addHandler(qt_handler)
            logger.info("✅ Qt Signal handler: Reactive logging enabled (INFO+)")
            
            # ================================================================
            # CONFIGURAR NÍVEIS POR MÓDULO
            # ================================================================
            for module_name, level in LOG_LEVELS.items():
                module_logger = logging.getLogger(module_name)
                module_logger.setLevel(level)
                logger.debug(f"Nível configurado: {module_name} = {logging.getLevelName(level)}")
            
            LoggerSystem._initialized = True
            
            logger.info("=" * 80)
            logger.info("✅ LOGGER SYSTEM INICIALIZADO COM SUCESSO")
            logger.info("=" * 80)
            
        except Exception as e:
            logger.critical(f"❌ FALHA ao inicializar LoggerSystem: {e}", exc_info=True)
            raise
    
    # ========================================================================
    # HANDLER QT
    # ========================================================================
    
    def _create_qt_handler(self):
        """
        Cria Handler Qt - Emite o Sinal
        
        DESIGN:
            Este handler emite o sinal:
            log_entry_emitted - com log estruturado completo
            
        CATEGORIA:
            Extrai automaticamente do nome do módulo usando CATEGORY_MAPPING
        """
        logger = logging.getLogger('LoggerSystem')
        
        class HybridQtSignalHandler(logging.Handler):
            """Handler que emite ambos os sinais (antigo + novo)"""
            
            def __init__(self, logger_system_instance):
                super().__init__()
                self.logger_system = logger_system_instance
            
            def emit(self, record):
                """Processa LogRecord e emite ambos os sinais"""
                try:
                    # ========================================================
                    # EXTRAIR INFORMAÇÕES DO RECORD
                    # ========================================================
                    
                    level = record.levelname
                    module = record.name
                    message = record.getMessage()
                    
                    # Timestamp ISO com milissegundos
                    dt = datetime.fromtimestamp(record.created)
                    timestamp_iso = dt.isoformat()
                    timestamp_short = dt.strftime('%H:%M:%S.%f')[:-3]
                    
                    # Função e linha
                    function = record.funcName
                    line = record.lineno
                    pathname = record.pathname
                    
                    # Traceback (se houver exceção)
                    traceback_text = None
                    if record.exc_info:
                        import traceback as tb
                        traceback_text = ''.join(tb.format_exception(*record.exc_info))
                    
                    # ========================================================
                    # DETERMINAR CATEGORIA
                    # ========================================================
                    
                    category = 'system'  # default
                    
                    # Extrair último componente do módulo
                    # Ex: 'BinanceData' → 'BinanceData'
                    module_parts = module.split('.')
                    if len(module_parts) > 1:
                        last_part = module_parts[-1]
                        category = CATEGORY_MAPPING.get(last_part, 'system')
                    
                    # ========================================================
                    # SINAL
                    # ========================================================
                    
                    log_dict = {
                        'timestamp': timestamp_iso,
                        'timestamp_short': timestamp_short,
                        'level': level,
                        'module': module,
                        'category': category,
                        'message': message,
                        'function': function,
                        'line': line,
                        'pathname': pathname,
                        'traceback': traceback_text,
                    }
                    
                    self.logger_system.log_entry_emitted.emit(log_dict)
                    
                except Exception as e:
                    # Falha silenciosa para não quebrar logging
                    print(f"[ERROR] HybridQtSignalHandler: {e}", file=sys.stderr)
        
        return HybridQtSignalHandler(self)
    
    
    @classmethod
    def get_logger(cls, name: str) -> logging.Logger:
        """
        Retorna Logger para Módulo Específico
        
        Args:
            name: Nome do módulo (ex: 'BinanceData')
            
        Returns:
            logging.Logger configurado
        """
        if name not in cls._loggers_cache:
            with cls._lock:
                if name not in cls._loggers_cache:
                    logger = logging.getLogger(name)
                    cls._loggers_cache[name] = logger
        
        return cls._loggers_cache[name]
    
    @classmethod
    def log_api_call(cls, endpoint: str, method: str, status_code: int, duration_ms: float):
        """
        Log específico para chamadas de API --- Monitoring de Requisições
        
        Args:
            endpoint: Endpoint chamado (ex: '/api/v3/ticker/24hr')
            method: Método HTTP (GET, POST, etc)
            status_code: Código de resposta HTTP
            duration_ms: Duração da requisição em milissegundos
        
        FILOSOFIA:
            Chamadas de API são pontos críticos de falha. Logging detalhado
            permite identificar padrões de erro e problemas de rate limiting.
        """
        logger = logging.getLogger('CryptoAnalyzer.API')
        
        try:
            # Determinar nível de log baseado no status code
            if status_code < 300:
                log_level = logging.DEBUG
                status_icon = "✅"
            elif status_code < 400:
                log_level = logging.INFO
                status_icon = "↪️"
            elif status_code < 500:
                log_level = logging.WARNING
                status_icon = "⚠️"
            else:
                log_level = logging.ERROR
                status_icon = "❌"
            
            logger.log(
                log_level,
                f"{status_icon} API Call: {method} {endpoint} "
                f"→ {status_code} ({duration_ms:.2f}ms)"
            )
            
        except Exception as e:
            logger.error(f"Erro ao logar chamada de API: {e}", exc_info=True)


