# ============================================================================
# RATE LIMITER - CONTROLE INTELIGENTE DE REQUISIÇÕES
# ============================================================================

class RateLimiter:
    """
    Rate Limiter com Token Bucket Algorithm --- Proteção contra Ban de API
    
    RESPONSABILIDADES:
        - Implementar algoritmo token bucket para rate limiting
        - Suportar limites diferentes por endpoint
        - Backoff exponencial em caso de erro 429 (Too Many Requests)
        - Thread-safe para uso concurrent
        - Métricas de uso para monitoramento
    
    FILOSOFIA:
        A Binance tem limites rigorosos de requisições. Excedê-los resulta em
        ban temporário ou permanente. Este rate limiter é nossa PRIMEIRA LINHA
        DE DEFESA para operar profissionalmente dentro dos limites.
    
    ALGORITMO TOKEN BUCKET:
        - Bucket começa cheio com N tokens
        - Cada requisição consome 1 token
        - Tokens são reabastecidos a uma taxa fixa (ex: 1200 tokens/minuto)
        - Se bucket está vazio, requisição espera até reabastecimento
    
    EXEMPLO DE USO:
        rate_limiter = RateLimiter(rate_per_minute=1200)
        
        # Antes de cada requisição API
        if rate_limiter.acquire('/api/v3/ticker/24hr'):
            response = requests.get(url)
        else:
            # Tratamento de rate limit excedido
            logger.warning("Rate limit excedido, aguardando...")
    """
    
    def __init__(self, rate_per_minute: int = BINANCE_RATE_LIMIT_PER_MINUTE,
                 per_endpoint_limits: Optional[Dict[str, int]] = None):
        """
        Inicializa Rate Limiter --- Configuração de Limites
        
        Args:
            rate_per_minute: Limite global de requisições por minuto
            per_endpoint_limits: Limites específicos por endpoint (opcional)
        
        DESIGN:
            Cada endpoint pode ter seu próprio bucket separado. Isso previne
            que um endpoint "faminto" por requisições esgote o limite de outros.
        """
        # Logger local
        self.logger = LoggerSystem.get_logger('RateLimiter')
        
        try:
            self.logger.info("=" * 80)
            self.logger.info("INICIALIZANDO RATE LIMITER")
            self.logger.info("=" * 80)
            
            # Configurações de rate
            self.rate_per_minute = rate_per_minute
            self.rate_per_second = rate_per_minute / 60.0
            self.per_endpoint_limits = per_endpoint_limits or BINANCE_RATE_LIMIT_PER_ENDPOINT.copy()
            
            # Token buckets (um global + um por endpoint)
            self._lock = RLock()  # RLock permite re-entrada pelo mesmo thread
            
            # Bucket global
            self._global_bucket = {
                'tokens': float(rate_per_minute),
                'capacity': float(rate_per_minute),
                'last_update': time.time(),
                'refill_rate': self.rate_per_second
            }
            
            # Buckets por endpoint
            self._endpoint_buckets: Dict[str, Dict[str, Any]] = {}
            for endpoint, limit in self.per_endpoint_limits.items():
                self._endpoint_buckets[endpoint] = {
                    'tokens': float(limit),
                    'capacity': float(limit),
                    'last_update': time.time(),
                    'refill_rate': limit / 60.0  # Por segundo
                }
            
            # Métricas de monitoramento
            self._metrics = {
                'total_requests': 0,
                'blocked_requests': 0,
                'total_wait_time_ms': 0.0,
                'requests_by_endpoint': defaultdict(int),
                'blocks_by_endpoint': defaultdict(int),
                'last_429_error': None,  # Timestamp do último erro 429
                'consecutive_429_count': 0
            }
            
            # Backoff exponencial
            self._backoff_base = 1.0  # Segundos
            self._backoff_max = 60.0  # Máximo 1 minuto de backoff
            self._backoff_multiplier = 2.0
            
            self.logger.info(f"✅ Rate Limiter configurado:")
            self.logger.info(f"   - Global: {rate_per_minute} req/min")
            self.logger.info(f"   - Endpoints específicos: {len(self.per_endpoint_limits)}")
            self.logger.info(f"   - Refill rate: {self.rate_per_second:.2f} tokens/segundo")
            self.logger.info("=" * 80)
            
        except Exception as e:
            self.logger.error(f"❌ Erro ao inicializar RateLimiter: {e}", exc_info=True)
            raise
    
    def _refill_bucket(self, bucket: Dict[str, Any]) -> None:
        """
        Reabastece bucket com tokens --- Token Bucket Core Logic
        
        Args:
            bucket: Dicionário do bucket a ser reabastecido
        
        ALGORITMO:
            tokens_to_add = (tempo_passado) * (taxa_de_refill)
            tokens_atuais = min(tokens_atuais + tokens_to_add, capacidade_maxima)
        
        EXEMPLO:
            Se 2 segundos passaram e taxa é 20 tokens/seg:
            tokens_to_add = 2 * 20 = 40 tokens
        """
        try:
            current_time = time.time()
            time_passed = current_time - bucket['last_update']
            
            # Calcular tokens a adicionar
            tokens_to_add = time_passed * bucket['refill_rate']
            
            # Adicionar tokens respeitando capacidade máxima
            bucket['tokens'] = min(
                bucket['tokens'] + tokens_to_add,
                bucket['capacity']
            )
            
            # Atualizar timestamp
            bucket['last_update'] = current_time
            
        except Exception as e:
            self.logger.error(f"Erro ao recarregar bucket: {e}", exc_info=True)
    
    def acquire(self, endpoint: Optional[str] = None, weight: int = 1, 
                timeout: Optional[float] = None) -> bool:
        """
        Adquire permissão para fazer requisição --- Token Acquisition
        
        Args:
            endpoint: Endpoint específico (ex: '/api/v3/ticker/24hr')
            weight: Peso da requisição (algumas requisições custam mais)
            timeout: Tempo máximo para esperar em segundos (None = espera infinita)
        
        Returns:
            True se permissão concedida, False se timeout
        
        COMPORTAMENTO:
            - Se tokens disponíveis: consome e retorna imediatamente
            - Se tokens insuficientes: espera até reabastecimento ou timeout
            - Thread-safe: múltiplas threads podem chamar simultaneamente
        
        EXEMPLO:
            # Requisição simples
            if rate_limiter.acquire('/api/v3/ticker/24hr'):
                response = make_request()
            
            # Com timeout
            if rate_limiter.acquire('/api/v3/klines', timeout=5.0):
                response = make_request()
            else:
                logger.warning("Rate limit timeout, pulando requisição")
        """
        # Logger local
        logger = logging.getLogger('RateLimiter')
        
        start_time = time.time()
        
        try:
            with self._lock:
                # Incrementar métrica
                self._metrics['total_requests'] += 1
                if endpoint:
                    self._metrics['requests_by_endpoint'][endpoint] += 1
                
                # Loop de aquisição (pode precisar esperar)
                while True:
                    # Recarregar buckets
                    self._refill_bucket(self._global_bucket)
                    
                    # Verificar bucket global
                    if self._global_bucket['tokens'] < weight:
                        # Calcular tempo de espera até ter tokens suficientes
                        tokens_needed = weight - self._global_bucket['tokens']
                        wait_time = tokens_needed / self._global_bucket['refill_rate']
                        
                        # Verificar timeout
                        if timeout is not None:
                            elapsed = time.time() - start_time
                            if elapsed >= timeout:
                                self._metrics['blocked_requests'] += 1
                                logger.warning(
                                    f"⏱️ Rate limit timeout: {endpoint or 'global'} "
                                    f"(weight: {weight}, elapsed: {elapsed:.2f}s)"
                                )
                                return False
                            
                            # Ajustar wait_time para não exceder timeout
                            wait_time = min(wait_time, timeout - elapsed)
                        
                        # Aguardar reabastecimento
                        self._metrics['total_wait_time_ms'] += wait_time * 1000
                        logger.debug(f"⏳ Aguardando {wait_time:.3f}s para reabastecimento global (processando eventos)")
                        QThread.msleep(int(wait_time * 1000)) # <--- CORREÇÃO (converte segundos para milissegundos)
                        continue  # Re-verificar após espera
                    
                    # Verificar bucket do endpoint específico (se aplicável)
                    if endpoint and endpoint in self._endpoint_buckets:
                        endpoint_bucket = self._endpoint_buckets[endpoint]
                        self._refill_bucket(endpoint_bucket)
                        
                        if endpoint_bucket['tokens'] < weight:
                            tokens_needed = weight - endpoint_bucket['tokens']
                            wait_time = tokens_needed / endpoint_bucket['refill_rate']
                            
                            # Verificar timeout
                            if timeout is not None:
                                elapsed = time.time() - start_time
                                if elapsed >= timeout:
                                    self._metrics['blocked_requests'] += 1
                                    self._metrics['blocks_by_endpoint'][endpoint] += 1
                                    logger.warning(
                                        f"⏱️ Endpoint rate limit timeout: {endpoint} "
                                        f"(weight: {weight}, elapsed: {elapsed:.2f}s)"
                                    )
                                    return False
                                
                                wait_time = min(wait_time, timeout - elapsed)
                            
                            self._metrics['total_wait_time_ms'] += wait_time * 1000
                            logger.debug(
                                f"⏳ Aguardando {wait_time:.3f}s para reabastecimento "
                                f"de {endpoint} (processando eventos)"
                            )
                            QThread.msleep(int(wait_time * 1000)) # <--- CORREÇÃO
                            continue
                        
                        # Consumir tokens do bucket do endpoint
                        endpoint_bucket['tokens'] -= weight
                    
                    # Consumir tokens do bucket global
                    self._global_bucket['tokens'] -= weight
                    
                    # Sucesso!
                    wait_duration = time.time() - start_time
                    if wait_duration > 0.1:  # Log se esperou mais de 100ms
                        logger.debug(
                            f"✅ Permissão concedida após {wait_duration:.3f}s: "
                            f"{endpoint or 'global'} (weight: {weight})"
                        )
                    
                    return True
                    
        except Exception as e:
            logger.error(
                f"❌ Erro ao adquirir permissão: {e}",
                exc_info=True
            )
            # Em caso de erro, permitir requisição (fail-open)
            return True
    
    def report_429_error(self, endpoint: Optional[str] = None, 
                        retry_after: Optional[int] = None) -> float:
        """
        Reporta erro 429 (Too Many Requests) --- Backoff Management
        
        Args:
            endpoint: Endpoint que retornou 429
            retry_after: Header Retry-After da resposta (segundos)
        
        Returns:
            Tempo de backoff recomendado em segundos
        
        FILOSOFIA:
            Erros 429 indicam que excedemos o limite. Devemos:
            1. Registrar o evento
            2. Calcular backoff exponencial
            3. Drenar buckets para forçar cooldown
            4. Retornar tempo de espera recomendado
        
        EXEMPLO:
            try:
                response = requests.get(url)
                if response.status_code == 429:
                    retry_after = int(response.headers.get('Retry-After', 60))
                    wait_time = rate_limiter.report_429_error(endpoint, retry_after)
                    time.sleep(wait_time)
            except Exception as e:
                pass
        """
        logger = logging.getLogger('RateLimiter')
        
        try:
            with self._lock:
                # Atualizar métricas
                self._metrics['last_429_error'] = time.time()
                self._metrics['consecutive_429_count'] += 1
                
                # Calcular backoff exponencial
                backoff_time = min(
                    self._backoff_base * (self._backoff_multiplier ** 
                                         self._metrics['consecutive_429_count']),
                    self._backoff_max
                )
                
                # Se API forneceu Retry-After, usar o maior entre os dois
                if retry_after is not None:
                    backoff_time = max(backoff_time, float(retry_after))
                
                # Drenar buckets (forçar cooldown)
                self._global_bucket['tokens'] = 0
                if endpoint and endpoint in self._endpoint_buckets:
                    self._endpoint_buckets[endpoint]['tokens'] = 0
                
                logger.warning(
                    f"⚠️ ERRO 429 DETECTADO: {endpoint or 'global'}\n"
                    f"   - Contagem consecutiva: {self._metrics['consecutive_429_count']}\n"
                    f"   - Backoff calculado: {backoff_time:.2f}s\n"
                    f"   - Retry-After (API): {retry_after}s\n"
                    f"   - Buckets drenados para cooldown"
                )
                
                return backoff_time
                
        except Exception as e:
            logger.error(f"Erro ao processar 429: {e}", exc_info=True)
            # Retornar backoff conservador em caso de erro
            return 60.0
    
    def report_success(self) -> None:
        """
        Reporta requisição bem-sucedida --- Reset de Backoff
        
        FILOSOFIA:
            Após sucesso, resetar contador de erros 429. Isso permite que
            o sistema volte ao normal gradualmente após um período de erro.
        """
        try:
            with self._lock:
                if self._metrics['consecutive_429_count'] > 0:
                    self.logger.info(
                        f"✅ Requisição bem-sucedida após {self._metrics['consecutive_429_count']} "
                        f"erro(s) 429. Resetando backoff."
                    )
                    self._metrics['consecutive_429_count'] = 0
                    
        except Exception as e:
            self.logger.error(f"Erro ao reportar sucesso: {e}", exc_info=True)
    
    def get_available_tokens(self, endpoint: Optional[str] = None) -> float:
        """
        Retorna número de tokens disponíveis --- Monitoring
        
        Args:
            endpoint: Endpoint específico ou None para global
        
        Returns:
            Número de tokens disponíveis (float)
        
        UTILIDADE:
            Permite UI mostrar "capacidade restante" em tempo real.
            Também útil para decisions sobre throttling proativo.
        """
        try:
            with self._lock:
                if endpoint and endpoint in self._endpoint_buckets:
                    bucket = self._endpoint_buckets[endpoint]
                    self._refill_bucket(bucket)
                    return bucket['tokens']
                else:
                    self._refill_bucket(self._global_bucket)
                    return self._global_bucket['tokens']
                    
        except Exception as e:
            self.logger.error(f"Erro ao obter tokens disponíveis: {e}", exc_info=True)
            return 0.0
    
    def get_usage_percentage(self, endpoint: Optional[str] = None) -> float:
        """
        Retorna percentual de uso do rate limit --- Monitoring
        
        Args:
            endpoint: Endpoint específico ou None para global
        
        Returns:
            Percentual de uso (0.0 a 100.0)
        
        EXEMPLO:
            usage = rate_limiter.get_usage_percentage()
            if usage > 80:
                logger.warning(f"Rate limit alto: {usage:.1f}%")
        """
        try:
            with self._lock:
                if endpoint and endpoint in self._endpoint_buckets:
                    bucket = self._endpoint_buckets[endpoint]
                    self._refill_bucket(bucket)
                    available = bucket['tokens']
                    capacity = bucket['capacity']
                else:
                    self._refill_bucket(self._global_bucket)
                    available = self._global_bucket['tokens']
                    capacity = self._global_bucket['capacity']
                
                # Percentual usado = 100 - (disponível / capacidade * 100)
                return 100.0 - (available / capacity * 100.0)
                
        except Exception as e:
            self.logger.error(f"Erro ao calcular uso: {e}", exc_info=True)
            return 0.0
    
    def get_metrics(self) -> Dict[str, Any]:
        """
        Retorna métricas de uso do rate limiter --- Analytics
        
        Returns:
            Dicionário com métricas completas
        
        MÉTRICAS INCLUÍDAS:
            - Total de requisições
            - Requisições bloqueadas
            - Tempo total de espera
            - Uso por endpoint
            - Erro 429 mais recente
            - Status atual dos buckets
        """
        try:
            with self._lock:
                # Atualizar buckets para obter valores atuais
                self._refill_bucket(self._global_bucket)
                
                metrics = {
                    'summary': {
                        'total_requests': self._metrics['total_requests'],
                        'blocked_requests': self._metrics['blocked_requests'],
                        'block_rate': (
                            self._metrics['blocked_requests'] / 
                            max(self._metrics['total_requests'], 1) * 100
                        ),
                        'total_wait_time_ms': round(self._metrics['total_wait_time_ms'], 2),
                        'avg_wait_time_ms': (
                            self._metrics['total_wait_time_ms'] / 
                            max(self._metrics['total_requests'], 1)
                        )
                    },
                    'global_bucket': {
                        'tokens_available': round(self._global_bucket['tokens'], 2),
                        'capacity': self._global_bucket['capacity'],
                        'usage_percent': round(self.get_usage_percentage(), 2),
                        'refill_rate': self._global_bucket['refill_rate']
                    },
                    'endpoint_stats': {},
                    'error_429': {
                        'last_occurrence': (
                            format_timestamp(self._metrics['last_429_error'])
                            if self._metrics['last_429_error'] else 'Never'
                        ),
                        'consecutive_count': self._metrics['consecutive_429_count']
                    }
                }
                
                # Estatísticas por endpoint
                for endpoint, count in self._metrics['requests_by_endpoint'].items():
                    blocks = self._metrics['blocks_by_endpoint'][endpoint]
                    bucket = self._endpoint_buckets.get(endpoint)
                    
                    metrics['endpoint_stats'][endpoint] = {
                        'requests': count,
                        'blocks': blocks,
                        'block_rate': (blocks / max(count, 1) * 100),
                        'tokens_available': (
                            round(bucket['tokens'], 2) if bucket else 'N/A'
                        ),
                        'usage_percent': (
                            round(self.get_usage_percentage(endpoint), 2) 
                            if bucket else 'N/A'
                        )
                    }
                
                return metrics
                
        except Exception as e:
            self.logger.error(f"Erro ao coletar métricas: {e}", exc_info=True)
            return {'error': str(e)}
    
    def reset(self) -> None:
        """
        Reseta rate limiter para estado inicial --- Maintenance
        
        UTILIDADE:
            Útil para testes ou após longo período de inatividade.
            Recarrega buckets para capacidade máxima e reseta métricas.
        """
        logger = logging.getLogger('RateLimiter')
        
        try:
            with self._lock:
                logger.info("🔄 Resetando Rate Limiter...")
                
                # Resetar bucket global
                self._global_bucket['tokens'] = self._global_bucket['capacity']
                self._global_bucket['last_update'] = time.time()
                
                # Resetar buckets de endpoints
                for bucket in self._endpoint_buckets.values():
                    bucket['tokens'] = bucket['capacity']
                    bucket['last_update'] = time.time()
                
                # Resetar métricas
                self._metrics['total_requests'] = 0
                self._metrics['blocked_requests'] = 0
                self._metrics['total_wait_time_ms'] = 0.0
                self._metrics['requests_by_endpoint'].clear()
                self._metrics['blocks_by_endpoint'].clear()
                self._metrics['last_429_error'] = None
                self._metrics['consecutive_429_count'] = 0
                
                logger.info("✅ Rate Limiter resetado")
                
        except Exception as e:
            logger.error(f"Erro ao resetar rate limiter: {e}", exc_info=True)

# ============================================================================
# THEMEMANAGER
# ============================================================================

class ThemeManager:
    """
    Gerenciador de Temas HÍBRIDO --- Melhor das Implementações
    
    FUNCIONALIDADES INTEGRADAS:
    - Integração total com ConfigManager (para SettingsTab)
    - Backward compatibility com QSettings (para compatibilidade existente)
    - QSS profissional completo para Light/Dark
    - Sincronização automática entre sistemas de configuração
    - Logs estruturados e auditoria completa
    - Aplicação imediata de mudanças
    
    DESIGN PATTERN:
        Singleton-like através de class methods (não há instâncias)
        Todo o estado é mantido em variáveis de classe
    
    INTEGRAÇÃO:
        1. No main():
           ThemeManager.set_config_manager(config_manager)
           ThemeManager.set_app_instance(app)
           ThemeManager.load_from_settings()
           ThemeManager.apply(app)
        
        2. Na SettingsTab:
           ThemeManager.set_theme('dark'/'light')
        
        3. Para alternar:
           ThemeManager.toggle(app)
    
    EXEMPLO:
        # Inicialização
        ThemeManager.set_config_manager(config)
        ThemeManager.load_from_settings()
        ThemeManager.apply(QApplication.instance())
        
        # Trocar tema
        ThemeManager.set_theme('dark', apply_immediately=True)
    """
    
    # ========================================================================
    # ESTADO INTERNO (Class Variables)
    # ========================================================================
    _current = "light"  # Tema padrão é Light
    _config_manager = None  # Referência ao ConfigManager
    _app_instance = None  # Referência ao QApplication para aplicação automática
    
    # ========================================================================
    # CONFIGURAÇÃO E INICIALIZAÇÃO
    # ========================================================================
    
    @classmethod
    def set_config_manager(cls, config_manager):
        """
        Define referência ao ConfigManager --- Integração total com SettingsTab
        
        Estabelece ponte entre novo sistema (ConfigManager) e antigo (QSettings),
        garantindo sincronização automática e compatibilidade total.
        
        Args:
            config_manager: Instância do ConfigManager
        """
        logger = logging.getLogger('ui.theme')
        logger.info("Integrando ThemeManager com ConfigManager")
        
        cls._config_manager = config_manager
        
        # Sincroniza tema inicial: ConfigManager tem precedência
        if cls._config_manager:
            config_theme = cls._config_manager.get('app.theme', 'dark')
            
            # Se ConfigManager tem tema diferente, usa ele e sincroniza QSettings
            if config_theme != cls._current:
                logger.info(f"Sincronizando tema: QSettings '{cls._current}' → ConfigManager '{config_theme}'")
                cls._current = config_theme
                cls._save_to_qsettings()  # Sincroniza com QSettings para compatibilidade
            else:
                # Se são iguais, confirma sincronização
                logger.debug("Temas já sincronizados entre ConfigManager e QSettings")
        
        logger.info("Integração ThemeManager ↔ ConfigManager concluída")
    
    @classmethod
    def set_app_instance(cls, app: QApplication):
        """
        Define referência ao QApplication --- Para aplicação automática de temas
        
        Args:
            app: Instância do QApplication
        """
        cls._app_instance = app
    
    # ========================================================================
    # GETTERS E SETTERS PÚBLICOS
    # ========================================================================
    
    @classmethod
    def get_current(cls) -> str:
        """
        Retorna tema atual --- Light ou Dark
        
        Returns:
            str: 'light' ou 'dark'
        """
        return cls._current
    
    @classmethod
    def set_theme(cls, theme: str, apply_immediately: bool = True):
        """
        Define tema --- Salva em AMBOS os sistemas automaticamente
        
        Esta é a interface principal para mudança de tema.
        Sincroniza automaticamente ConfigManager e QSettings.
        
        Args:
            theme: 'light' ou 'dark'
            apply_immediately: Se True, aplica imediatamente ao QApplication
        """
        logger = logging.getLogger('ui.theme')
        logger.info(f"Definindo tema: {theme}")
        
        if theme not in ['light', 'dark']:
            logger.error(f"Tema inválido: {theme}. Deve ser 'light' ou 'dark'")
            return
        
        cls._current = theme
        
        # === SINCRONIZAÇÃO DUPLA ===
        
        # 1. Salva no ConfigManager (sistema novo)
        if cls._config_manager:
            cls._config_manager.set('app.theme', theme)
            logger.debug("Tema salvo no ConfigManager")
        else:
            logger.debug("ConfigManager não disponível")
        
        # 2. Salva no QSettings (compatibilidade)
        cls._save_to_qsettings()
        
        # 3. Aplica imediatamente se solicitado
        if apply_immediately and cls._app_instance:
            cls.apply(cls._app_instance)
        elif apply_immediately:
            # Tenta encontrar QApplication automaticamente
            app = QApplication.instance()
            if app:
                cls.apply(app)
            else:
                logger.warning("QApplication não encontrada para aplicar tema imediatamente")
        
        logger.info(f"Tema '{theme}' definido e sincronizado com sucesso")
    
    @classmethod
    def toggle(cls, app: QApplication = None):
        """
        Alterna entre temas --- Light <-> Dark
        
        Versão aprimorada que funciona com ou sem QApplication explícito.
        
        Args:
            app: QApplication (opcional, tenta detectar automaticamente)
        """
        logger = logging.getLogger('ui.theme')
        
        new_theme = "dark" if cls._current == "light" else "light"
        logger.info(f"Alternando tema: {cls._current} → {new_theme}")
        
        # Define novo tema (salva automaticamente)
        cls.set_theme(new_theme, apply_immediately=False)
        
        # Aplica ao app
        if app:
            cls.apply(app)
        elif cls._app_instance:
            cls.apply(cls._app_instance)
        else:
            # Tenta encontrar automaticamente
            app_instance = QApplication.instance()
            if app_instance:
                cls.apply(app_instance)
            else:
                logger.warning("Nenhuma QApplication disponível para aplicar tema")
        
        logger.info(f"Alternância de tema concluída: {new_theme}")
    
    # ========================================================================
    # APLICAÇÃO DE TEMAS
    # ========================================================================
    
    @classmethod
    def apply(cls, app: QApplication):
        """
        Aplica tema ao aplicativo --- QPalette + QSS profissional
        
        Versão híbrida com QSS completo da implementação original.
        
        Args:
            app: QApplication a ser estilizada
        """
        logger = logging.getLogger('ui.theme')
        logger.info(f"Aplicando tema: {cls._current}")
        
        if cls._current == "light":
            cls._apply_light_theme(app)
        else:
            cls._apply_dark_theme(app)
        
        logger.info("Tema aplicado com sucesso")
    
    @classmethod
    def load_from_settings(cls):
        """
        Carrega tema das configurações --- Compatibilidade com código existente
        
        Versão híbrida que tenta ConfigManager primeiro, depois QSettings.
        """
        logger = logging.getLogger('ui.theme')
        logger.info("Carregando tema das configurações")
        
        theme_loaded = None
        source = None
        
        # 1. Tenta ConfigManager primeiro (prioridade)
        if cls._config_manager:
            theme_loaded = cls._config_manager.get('app.theme', None)
            if theme_loaded:
                source = "ConfigManager"
        
        # 2. Se não encontrou, tenta QSettings (backward compatibility)
        if not theme_loaded:
            from PySide6.QtCore import QSettings
            settings = QSettings('CryptoAnalyzer', 'Theme')
            theme_loaded = settings.value('current_theme', 'dark')
            source = "QSettings"
        
        # 3. Aplica tema carregado
        if theme_loaded in ['light', 'dark']:
            cls._current = theme_loaded
            logger.info(f"Tema '{theme_loaded}' carregado de {source}")
            
            # Sincroniza entre sistemas se necessário
            if source == "QSettings" and cls._config_manager:
                # QSettings foi a fonte, sincroniza com ConfigManager
                cls._config_manager.set('app.theme', theme_loaded)
                logger.debug("Tema sincronizado: QSettings → ConfigManager")
            elif source == "ConfigManager":
                # ConfigManager foi a fonte, sincroniza com QSettings
                cls._save_to_qsettings()
                logger.debug("Tema sincronizado: ConfigManager → QSettings")
        else:
            # Tema inválido, usar padrão
            logger.warning(f"Tema inválido '{theme_loaded}', usando padrão 'dark'")
            cls._current = 'dark'
        
        logger.info(f"Carregamento concluído: tema '{cls._current}'")
    
    @classmethod
    def _save_to_qsettings(cls):
        """
        Salva tema no QSettings --- Compatibilidade e persistência
        """
        try:
            from PySide6.QtCore import QSettings
            settings = QSettings('CryptoAnalyzer', 'Theme')
            settings.setValue('current_theme', cls._current)
            settings.sync()  # Força gravação imediata
        except Exception as e:
            logger = logging.getLogger('ui.theme')
            logger.error(f"Erro ao salvar tema no QSettings: {e}", exc_info=True)
    
