# STORAGE MONITOR DIALOG - MONITORAMENTO DO STORAGE
# ============================================================================

class StorageMonitorWidget(QWidget):
    '''Widget de monitoramento do Klines Storage Worker'''
    
    def __init__(self, cache_system: CacheSystem):
        super().__init__()
        self.cache = cache_system
        self.worker = cache_system.klines_worker
        
        self._setup_ui()
        self._connect_signals()
    
    def _setup_ui(self):
        layout = QVBoxLayout(self)
        
        # Título
        title = QLabel("<h2>📊 Klines Storage Monitor</h2>")
        layout.addWidget(title)
        
        # Métricas
        self.metrics_label = QLabel()
        self.metrics_label.setFont(QFont("Courier", 10))
        layout.addWidget(self.metrics_label)
        
        # Atualizar inicialmente
        self._update_metrics()
    
    def _connect_signals(self):
        '''Conecta sinais do worker'''
        self.worker.metrics_updated.connect(self._on_metrics_updated)
    
    @Slot(dict)
    def _on_metrics_updated(self, metrics: dict):
        '''Atualiza display de métricas'''
        text = f'''
📥 INGESTÃO
   Rate: {metrics.get('klines_per_second', 0):.0f} klines/s
   Queue: {metrics.get('ingest_queue_size', 0)} klines

💾 ARMAZENAMENTO
   Escritas/s: {metrics.get('disk_writes_per_second', 0):.0f}
   Latência: {metrics.get('disk_write_latency_ms', 0):.1f}ms
   Espaço: {metrics.get('total_disk_usage_mb', 0):.1f} MB

🔍 GAPS
   Detectados: {metrics.get('gaps_detected_total', 0)}
   Preenchidos: {metrics.get('gaps_filled_total', 0)}
   Pendentes: {metrics.get('gaps_pending', 0)}

🔄 BACKFILL
   Ativo: {metrics.get('backfill_tasks_active', 0)} tasks
   Taxa Sucesso: {metrics.get('backfill_success_rate', 100):.1f}%

✅ QUALIDADE
   Score: {metrics.get('data_quality_score', 100):.2f}%
'''
        self.metrics_label.setText(text)

