# SYSTEM PAD - COMPONENTE VISUAL DE ATIVIDADE (INSPIRADO EM PADS ELETRÔNICOS)
# ============================================================================

class SystemPad(QWidget):
    """
    Pad Eletrônico de Atividade por Sistema
    
    Representa visualmente a atividade de um sistema específico
    com efeitos de piscar e métricas em tempo real.
    """
    
    clicked = Signal(str)  # system_name
    
    def __init__(self, system_name: str, parent=None):
        super().__init__(parent)
        
        self.system_name = system_name
        self.total_reads = 0
        self.total_writes = 0
        self.activity_level = 0.0  # 0.0 a 1.0
        self.last_activity_time = 0.0
        self.recent_keys = deque(maxlen=10)
        
        self._setup_ui()
    
    def _setup_ui(self):
        """Configura UI do pad"""
        layout = QVBoxLayout(self)
        layout.setContentsMargins(5, 5, 5, 5)
        layout.setSpacing(3)
        
        # Nome do sistema
        self.name_label = QLabel(self.system_name)
        self.name_label.setAlignment(Qt.AlignCenter)
        self.name_label.setFont(QFont("Arial", 10, QFont.Bold))
        layout.addWidget(self.name_label)
        
        # Status visual (LED)
        self.pad_label = QLabel("●")
        self.pad_label.setAlignment(Qt.AlignCenter)
        self.pad_label.setFont(QFont("Arial", 48))
        self.pad_label.setStyleSheet(self._get_idle_style())
        layout.addWidget(self.pad_label)
        
        # Métricas
        self.metrics_label = QLabel("R: 0 | W: 0")
        self.metrics_label.setAlignment(Qt.AlignCenter)
        self.metrics_label.setFont(QFont("Arial", 8))
        layout.addWidget(self.metrics_label)
        
        # Status
        self.status_label = QLabel("IDLE")
        self.status_label.setAlignment(Qt.AlignCenter)
        self.status_label.setFont(QFont("Arial", 7))
        self.status_label.setStyleSheet("color: #888;")
        layout.addWidget(self.status_label)
        
        # Tamanho fixo
        self.setFixedSize(120, 150)
        
        # Tooltip inicial
        self.setToolTip(self._build_tooltip())
        
        # Click handler
        self.setCursor(Qt.PointingHandCursor)
    
    def mousePressEvent(self, event):
        """Handler de click"""
        if event.button() == Qt.LeftButton:
            self.clicked.emit(self.system_name)
    
    def flash_write(self):
        """Efeito de piscar verde (escrita)"""
        self._flash(color="rgba(0, 255, 0, 0.5)", duration_ms=200)
        self.total_writes += 1
        self._update_display()
    
    def flash_read(self):
        """Efeito de piscar azul (leitura)"""
        self._flash(color="rgba(0, 120, 212, 0.5)", duration_ms=150)
        self.total_reads += 1
        self._update_display()
    
    def _flash(self, color: str, duration_ms: int):
        """Aplica efeito de flash"""
        original_style = self.pad_label.styleSheet()
        
        # Estilo de flash
        flash_style = f"""
            QLabel {{
                color: white;
                background-color: {color};
                border-radius: 40px;
            }}
        """
        self.pad_label.setStyleSheet(flash_style)
        
        # Restaurar após duração
        QTimer.singleShot(duration_ms, lambda: self.pad_label.setStyleSheet(original_style))
    
    def update_activity(self, ops_per_second: float):
        """Atualiza nível de atividade"""
        self.activity_level = min(1.0, ops_per_second / 100.0)
        self.last_activity_time = time.time()
        self._update_display()
    
    def add_key(self, key: str):
        """Adiciona chave recente"""
        self.recent_keys.append(key)
        self.setToolTip(self._build_tooltip())
    
    def _update_display(self):
        """Atualiza display visual"""
        # Atualizar métricas
        self.metrics_label.setText(f"R: {self.total_reads:,} | W: {self.total_writes:,}")
        
        # Atualizar status e cor baseado em atividade
        if time.time() - self.last_activity_time < 5:
            if self.activity_level > 0.7:
                self.status_label.setText("HIGH")
                self.pad_label.setStyleSheet(self._get_high_style())
            elif self.activity_level > 0.3:
                self.status_label.setText("MEDIUM")
                self.pad_label.setStyleSheet(self._get_medium_style())
            else:
                self.status_label.setText("LOW")
                self.pad_label.setStyleSheet(self._get_low_style())
        else:
            self.status_label.setText("IDLE")
            self.pad_label.setStyleSheet(self._get_idle_style())
        
        self.setToolTip(self._build_tooltip())
    
    def _get_idle_style(self) -> str:
        return """
            QLabel {
                color: #666;
                background-color: #2a2a2a;
                border: 2px solid #444;
                border-radius: 40px;
            }
        """
    
    def _get_low_style(self) -> str:
        return """
            QLabel {
                color: #90EE90;
                background-color: #2a4a2a;
                border: 2px solid #90EE90;
                border-radius: 40px;
            }
        """
    
    def _get_medium_style(self) -> str:
        return """
            QLabel {
                color: #00FF00;
                background-color: #2a5a2a;
                border: 2px solid #00FF00;
                border-radius: 40px;
            }
        """
    
    def _get_high_style(self) -> str:
        return """
            QLabel {
                color: #00FF00;
                background-color: #2a6a2a;
                border: 3px solid #00FF00;
                border-radius: 40px;
                font-weight: bold;
            }
        """
    
    def _build_tooltip(self) -> str:
        """Constrói tooltip com informações"""
        tooltip = f"""
<b>{self.system_name}</b><br>
────────────────<br>
Total Reads: {self.total_reads:,}<br>
Total Writes: {self.total_writes:,}<br>
Activity Level: {self.activity_level * 100:.1f}%<br>
        """
        
        if self.recent_keys:
            tooltip += "<br><b>Recent Keys:</b><br>"
            for key in list(self.recent_keys)[-5:]:
                short_key = key[:30] + "..." if len(key) > 30 else key
                tooltip += f"• {short_key}<br>"
        
        return tooltip
    
    def get_stats(self) -> Dict:
        """Retorna estatísticas do pad"""
        return {
            'system_name': self.system_name,
            'total_reads': self.total_reads,
            'total_writes': self.total_writes,
            'activity_level': self.activity_level,
            'status': self.status_label.text(),
            'last_activity_time': self.last_activity_time,
            'recent_keys': list(self.recent_keys)
        }
    
    def reset_metrics(self):
        """Reseta métricas do pad"""
        self.total_reads = 0
        self.total_writes = 0
        self.activity_level = 0.0
        self.last_activity_time = 0.0
        self.recent_keys.clear()
        
        self.status_label.setText("IDLE")
        self.metrics_label.setText("R: 0 | W: 0")
        self.pad_label.setStyleSheet(self._get_idle_style())
        self.setToolTip(self._build_tooltip())

# ============================================================================
# CACHE MONITOR DIALOG - MONITOR PROFISSIONAL
# ============================================================================

class CacheMonitorDialog(QDialog):
    """
    Monitor Profissional de Cache - Implementação Revolucionada

    RESPONSABILIDADES:
        - Monitorar operações de leitura/escrita em tempo real
        - Visualizar métricas detalhadas por camada
        - Exibir pads eletrônicos de atividade por sistema
        - Terminal duplo (write | read) com cores diferenciadas
        - Gráficos de performance histórica
        - Ferramentas de debug e teste
    
    CARACTERÍSTICAS:
        ✅ 11 sinais conectados do CacheSystem
        ✅ Health Score inteligente (0-100)
        ✅ Recent Activity com filtros
        ✅ Layers com detalhes por seleção
        ✅ Metrics com 4 gráficos pyqtgraph
        ✅ Pads eletrônicos reativos com piscar
        ✅ Debug tools com restart de workers
    
    ABAS:
        1. 📊 Overview - Health, Cards, Activity
        2. 🔍 Layers - Tabela + Detalhes
        3. 📝 Operations - Terminal duplo
        4. 📈 Metrics - Gráficos temporais
        5. ⚡ Live Activity - Pads eletrônicos
        6. 🔧 Debug - Ferramentas avançadas
    """
    
    def __init__(self, cache, parent=None):
        super().__init__(parent)
        
        self.cache = cache
        self.logger = logging.getLogger('CacheMonitor')
        
        # Mutex para thread-safety
        self._mutex = QMutex()
        
        # Filas para terminais
        self.write_queue = deque(maxlen=1000)
        self.read_queue = deque(maxlen=1000)
        self.activity_queue = deque(maxlen=500)  # Recent Activity
        
        # Métricas locais
        self.metrics = {
            'total_reads': 0,
            'total_writes': 0,
            'total_hits': 0,
            'total_misses': 0,
            'total_errors': 0,
            'hit_rate_percent': 0.0,
            'avg_read_latency_ms': 0.0,
            'avg_write_latency_ms': 0.0,
            'memory_usage_percent': 0.0,
            'health_score': 100,
            'compression_saved_bytes': 0,
            'workers_active': 0
        }
        
        # Histórico para gráficos (60 pontos = 1 minuto)
        self.metrics_history = {
            'hit_rate': deque(maxlen=60),
            'read_latency': deque(maxlen=60),
            'write_latency': deque(maxlen=60),
            'ops_per_second': deque(maxlen=60),
            'memory_usage': deque(maxlen=60)
        }
        
        # Atividade por sistema
        self.system_activity = {
            'BINANCE_DATA': {'reads': 0, 'writes': 0, 'last_activity': 0.0},
            'DASHBOARD': {'reads': 0, 'writes': 0, 'last_activity': 0.0},
            'ANALYSIS': {'reads': 0, 'writes': 0, 'last_activity': 0.0},
            'ML_SYSTEM': {'reads': 0, 'writes': 0, 'last_activity': 0.0},
            'RISK_ENGINE': {'reads': 0, 'writes': 0, 'last_activity': 0.0},
            'EXECUTION': {'reads': 0, 'writes': 0, 'last_activity': 0.0},
            'PORTFOLIO': {'reads': 0, 'writes': 0, 'last_activity': 0.0},
            'ALERTS': {'reads': 0, 'writes': 0, 'last_activity': 0.0}
        }
        
        # Pads eletrônicos (criados na aba Live Activity)
        self.system_pads = {}
        
        # Configuração da UI
        self.setWindowTitle("🔬 Cache System Monitor - Professional")
        self.setMinimumSize(1400, 900)
        
        self._setup_ui()
        self._connect_signals()
        
        # Timers
        self.ui_timer = QTimer(self)
        self.ui_timer.timeout.connect(self._update_ui)
        self.ui_timer.start(100)  # 10 FPS
        
        self.metrics_timer = QTimer(self)
        self.metrics_timer.timeout.connect(self._update_metrics)
        self.metrics_timer.start(1000)  # 1 Hz
        
        self.logger.info("✅ CacheMonitorDialog inicializado")
    
    # ========================================================================
    # SETUP UI
    # ========================================================================
    
    def _setup_ui(self):
        """Configura interface completa"""
        layout = QVBoxLayout(self)
        
