    def _create_dataflow_tab(self) -> QWidget:
        """
        Tab 4: Data Flow - Pipeline de dados
        
        SEÇÕES:
            1. Pipeline Visualization: Fluxo visual (API → Validate → Cache)
            2. Validation Statistics: Métricas de validação
            3. Cache Operations: Operações de escrita no cache
            4. Data Quality: Qualidade dos dados recebidos
        """
        tab = QWidget()
        layout = QVBoxLayout(tab)
        
        # ====================================================================
        # PIPELINE VISUALIZATION
        # ====================================================================
        pipeline_group = QGroupBox("🔄 Data Pipeline")
        pipeline_layout = QVBoxLayout(pipeline_group)
        
        # Diagrama visual do pipeline
        pipeline_diagram = QLabel()
        pipeline_text = """
        ┌──────────────┐     ┌──────────────┐     ┌──────────────┐     ┌──────────────┐
        │   Binance    │ --> │   Validator  │ --> │  Transform   │ --> │    Cache     │
        │     API      │     │   (Schema)   │     │  (Normalize) │     │   System     │
        └──────────────┘     └──────────────┘     └──────────────┘     └──────────────┘
             🌐                     ✅                    🔄                   💾
        """
        pipeline_diagram.setText(pipeline_text)
        pipeline_diagram.setFont(QFont("Courier New", 10))
        pipeline_diagram.setStyleSheet("background-color: #2b2b2b; color: #00ff00; padding: 10px;")
        pipeline_layout.addWidget(pipeline_diagram)
        
        # Métricas do pipeline
        pipeline_metrics = QGridLayout()
        
        pipeline_metrics.addWidget(QLabel("API Fetches:"), 0, 0)
        self.api_fetches_label = QLabel("0")
        pipeline_metrics.addWidget(self.api_fetches_label, 0, 1)
        
        pipeline_metrics.addWidget(QLabel("Validations:"), 0, 2)
        self.validations_label = QLabel("0")
        pipeline_metrics.addWidget(self.validations_label, 0, 3)
        
        pipeline_metrics.addWidget(QLabel("Cache Writes:"), 1, 0)
        self.pipeline_cache_label = QLabel("0")
        pipeline_metrics.addWidget(self.pipeline_cache_label, 1, 1)
        
        pipeline_metrics.addWidget(QLabel("Rejected:"), 1, 2)
        self.rejected_label = QLabel("0")
        self.rejected_label.setStyleSheet("color: #F44336;")
        pipeline_metrics.addWidget(self.rejected_label, 1, 3)
        
        pipeline_layout.addLayout(pipeline_metrics)
        
        layout.addWidget(pipeline_group)
        
        # ====================================================================
        # VALIDATION STATISTICS
        # ====================================================================
        validation_group = QGroupBox("✅ Validation Statistics")
