    # CÁLCULO DE MÉTRICAS
    # ========================================================================
    
    def _calculate_metrics(self):
        """Calcula métricas agregadas (1 Hz)"""
        with QMutexLocker(self._mutex):
            # Uptime
            self.metrics['uptime_seconds'] = int(time.time() - self.start_time)
            
            # Throughput
            if hasattr(self, '_last_request_count'):
                delta_requests = self.metrics['total_requests'] - self._last_request_count
                self.metrics['throughput_per_sec'] = delta_requests
            
            self._last_request_count = self.metrics['total_requests']
            
            # Latency statistics
            if self.latency_history:
                sorted_latencies = sorted(self.latency_history)
                self.metrics['avg_latency_ms'] = sum(sorted_latencies) / len(sorted_latencies)
                p95_index = int(len(sorted_latencies) * 0.95)
                self.metrics['p95_latency_ms'] = sorted_latencies[p95_index] if p95_index < len(sorted_latencies) else 0
    
    def _calculate_health_score(self) -> int:
        """
        Calcula health score (0-100)
        
        FATORES:
            - Conexão ativa: +30 pontos
            - Taxa de sucesso > 95%: +30 pontos
            - Latência < 100ms: +20 pontos
            - Sem erros consecutivos: +20 pontos
        """
        score = 0
        
        # Conexão ativa
        if self.binance.is_connected():
            score += 30
        
        # Taxa de sucesso
        total = self.metrics['total_requests']
        success = self.metrics['successful_requests']
        if total > 0:
            success_rate = success / total
            if success_rate >= 0.95:
                score += 30
            elif success_rate >= 0.80:
                score += 20
            elif success_rate >= 0.60:
                score += 10
        else:
            score += 30  # Sem dados ainda, assume OK
        
        # Latência
        avg_lat = self.metrics['avg_latency_ms']
        if avg_lat < 100:
            score += 20
        elif avg_lat < 200:
            score += 15
        elif avg_lat < 500:
            score += 10
        elif avg_lat < 1000:
            score += 5
        
        # Erros consecutivos
        consecutive_errors = self.metrics['consecutive_errors']
        if consecutive_errors == 0:
            score += 20
        elif consecutive_errors < 3:
            score += 15
        elif consecutive_errors < 5:
            score += 10
        elif consecutive_errors < 10:
            score += 5
        
        return min(score, 100)
    
    def _update_health_bar_color(self, score: int):
        """Atualiza cor da barra de saúde baseado no score"""
        if score >= 90:
            color = "#4CAF50"  # Verde
        elif score >= 70:
            color = "#8BC34A"  # Verde claro
        elif score >= 50:
            color = "#FFC107"  # Amarelo
        elif score >= 30:
            color = "#FF9800"  # Laranja
        else:
            color = "#F44336"  # Vermelho
        
        self.health_bar.setStyleSheet(f"""
            QProgressBar {{
                border: 1px solid #555;
                border-radius: 5px;
                text-align: center;
            }}
            QProgressBar::chunk {{
                background-color: {color};
                border-radius: 4px;
            }}
        """)
    
