    # HELPERS
    # ========================================================================
    
    def _add_log_entry(self, level: str, source: str, message: str):
        """Adiciona entrada ao terminal de logs"""
        timestamp = datetime.now().strftime("%H:%M:%S.%f")[:-3]
        
        # Cor por nível
        colors = {
            'DEBUG': '#808080',
            'INFO': '#4CAF50',
            'WARN': '#FFC107',
            'ERROR': '#F44336'
        }
        color = colors.get(level, '#FFFFFF')
        
        log_html = f'<span style="color: {color};">[{timestamp}] [{level}] [{source}] {message}</span><br>'
        
        self.log_terminal.append(log_html)
        
        # Auto-scroll
        if self.log_autoscroll.isChecked():
            scrollbar = self.log_terminal.verticalScrollBar()
            scrollbar.setValue(scrollbar.maximum())
    
