class SimulatedOrder:
    """Representa uma ordem simulada"""

    def __init__(
        self,
        order_id: str,
        symbol: str,
        side: OrderSide,
        order_type: OrderType,
        quantity: float,
        price: Optional[float] = None,
        stop_price: Optional[float] = None,
        time_in_force: TimeInForce = TimeInForce.GTC
    ):
        self.order_id = order_id
        self.symbol = symbol
        self.side = side
        self.type = order_type
        self.quantity = quantity
        self.price = price
        self.stop_price = stop_price
        self.time_in_force = time_in_force

        self.status = OrderStatus.NEW
        self.filled_quantity = 0.0
        self.avg_fill_price = 0.0
        self.created_at = datetime.now()
        self.updated_at = datetime.now()

    def to_dict(self) -> Dict[str, Any]:
        """Converte para dict (formato Binance)"""
        return {
            'orderId': self.order_id,
            'symbol': self.symbol,
            'side': self.side.value,
            'type': self.type.value,
            'origQty': str(self.quantity),
            'executedQty': str(self.filled_quantity),
            'price': str(self.price) if self.price else '0',
            'stopPrice': str(self.stop_price) if self.stop_price else '0',
            'status': self.status.value,
            'timeInForce': self.time_in_force.value,
            'time': int(self.created_at.timestamp() * 1000),
            'updateTime': int(self.updated_at.timestamp() * 1000),
        }


# ============================================================================
# OFFLINE API SIMULATOR - ENTERPRISE GRADE
# ============================================================================
#
# Simulador completo e fiel à Binance API
#
# RECURSOS:
#   ✅ Execução de ordens (MARKET, LIMIT, STOP_LOSS, STOP_LOSS_LIMIT, TAKE_PROFIT, TAKE_PROFIT_LIMIT)
#   ✅ WebSocket simulado com eventos em tempo real
#   ✅ Carteira virtual com balances multi-asset
#   ✅ Histórico persistente em disco (orders, trades, balances)
#   ✅ Orderbook simulado baseado em dados reais
#   ✅ Integração com BinanceData para preços reais do cache
#   ✅ Comissões e slippage configuráveis
#
# ARQUITETURA:
#   - Usa preços REAIS do cache (via BinanceData)
#   - Persiste TODO histórico em JSON
#   - Emite sinais Qt para UI/ExecutionEngine
#   - Thread-safe com QMutex
#
# ============================================================================


# ============================================================================
# ENUMS E DATACLASSES - OFFLINE SIMULATOR
# ============================================================================

@dataclass
class SimulatedOrder:
    """
    Ordem simulada - fiel ao formato Binance

    Ref: https://binance-docs.github.io/apidocs/spot/en/#new-order-trade
    """
    symbol: str
    orderId: int
    clientOrderId: str
    transactTime: int
    price: float
    origQty: float
    executedQty: float
    cummulativeQuoteQty: float
    status: OrderStatus
    timeInForce: TimeInForce
    type: OrderType
    side: OrderSide
    stopPrice: float = 0.0
    icebergQty: float = 0.0
    time: int = 0
    updateTime: int = 0
    isWorking: bool = True

    def to_dict(self) -> Dict[str, Any]:
        """Converte para dict (formato Binance API)"""
        return {
            'symbol': self.symbol,
            'orderId': self.orderId,
            'clientOrderId': self.clientOrderId,
            'transactTime': self.transactTime,
            'price': str(self.price),
            'origQty': str(self.origQty),
            'executedQty': str(self.executedQty),
            'cummulativeQuoteQty': str(self.cummulativeQuoteQty),
            'status': self.status.value,
            'timeInForce': self.timeInForce.value,
            'type': self.type.value,
            'side': self.side.value,
            'stopPrice': str(self.stopPrice),
            'icebergQty': str(self.icebergQty),
            'time': self.time,
            'updateTime': self.updateTime,
            'isWorking': self.isWorking
        }


@dataclass
class SimulatedTrade:
    """Trade executado - fiel ao formato Binance"""
    id: int
    orderId: int
    symbol: str
    price: float
    qty: float
    quoteQty: float
    commission: float
    commissionAsset: str
    time: int
    isBuyer: bool
    isMaker: bool
    isBestMatch: bool = True

    def to_dict(self) -> Dict[str, Any]:
        """Converte para dict"""
        return {
            'id': self.id,
            'orderId': self.orderId,
            'symbol': self.symbol,
            'price': str(self.price),
            'qty': str(self.qty),
            'quoteQty': str(self.quoteQty),
            'commission': str(self.commission),
            'commissionAsset': self.commissionAsset,
            'time': self.time,
            'isBuyer': self.isBuyer,
            'isMaker': self.isMaker,
            'isBestMatch': self.isBestMatch
        }

# ============================================================================
# OFFLINE API SIMULATOR - CLASSE PRINCIPAL
# ============================================================================

class OfflineAPISimulator(QObject):
    """
    Simulador Enterprise da Binance API

    RESPONSABILIDADES:
        ✅ Execução de ordens baseada em preços reais (BinanceData)
        ✅ WebSocket simulado com eventos executionReport e balanceUpdate
        ✅ Carteira virtual multi-asset com precisão
        ✅ Histórico persistente: orders, trades, balances, snapshots
        ✅ Orderbook simulado para LIMIT orders
        ✅ Comissões Binance (0.1% spot, configurável)
        ✅ Slippage realista em MARKET orders

    INTEGRAÇÃO:
        - Recebe preços via binance_data.price_updated signal
        - Emite sinais para ExecutionEngine
        - Persiste estado em SIMULATOR_DIR

    SINAIS Qt:
        - order_update: Ordem criada/atualizada/cancelada
        - trade_update: Trade executado
        - balance_update: Balance atualizado
        - account_update: Snapshot da conta
    """

    # Sinais Qt
    order_update = Signal(dict)  # order_data (formato Binance)
    trade_update = Signal(dict)  # trade_data (formato Binance)
    balance_update = Signal(dict)  # {asset: {free, locked}}
    account_update = Signal(dict)  # account snapshot completo

    def __init__(
        self,
        binance_data,
        cache_system,
        initial_capital: float = 10000.0,
        commission_rate: float = 0.001,
        slippage_bps: float = 5.0,
        parent=None
    ):
        """
        Inicializa Offline API Simulator

        Args:
            binance_data: Instância de BinanceData (para preços reais)
            cache_system: Instância de CacheSystem (para persistência)
            initial_capital: Capital inicial em USDT
            commission_rate: Taxa de comissão (0.001 = 0.1%)
            slippage_bps: Slippage em basis points (5 = 0.05%)
            parent: QObject pai
        """
        super().__init__(parent)

        self.logger = logging.getLogger('OfflineAPISimulator')
        self.logger.info("=" * 80)
        self.logger.info("🎮 INICIALIZANDO OFFLINE API SIMULATOR ENTERPRISE")
        self.logger.info("=" * 80)

        # Dependências
        self.binance_data = binance_data
        self.cache = cache_system

        # Configurações
        self.commission_rate = commission_rate
        self.slippage_bps = slippage_bps

        # Thread-safety
        self._mutex = QMutex()

        # Diretórios de persistência
        self.simulator_dir = SIMULATOR_DIR

        self.orders_file = self.simulator_dir / "orders.json"
        self.trades_file = self.simulator_dir / "trades.json"
        self.balances_file = self.simulator_dir / "balances.json"
        self.snapshots_file = self.simulator_dir / "account_snapshots.json"

        # Estado da conta
        self.balances = defaultdict(lambda: {'free': 0.0, 'locked': 0.0})
        self.balances['USDT']['free'] = initial_capital

        # Preços atuais (cache)
        self.current_prices = {}

        # Ordens
        self.active_orders: Dict[int, SimulatedOrder] = {}  # orderId -> Order
        self.order_history: List[SimulatedOrder] = []

        # Trades
        self.trades: List[SimulatedTrade] = []

        # Counters
        self._next_order_id = 1
        self._next_trade_id = 1
        self._next_client_order_id = 1

        # Carregar estado persistido
        self._load_state()

        # Conectar aos sinais de ticker da BinanceData
        if self.binance_data:
            self.binance_data.ticker.connect(self._on_price_update)
            self.logger.info("✅ Conectado ao BinanceData (ticker) para dados de mercado reais")

        # Timer para snapshot periódico (a cada 5 minutos)
        self.snapshot_timer = QTimer()
        self.snapshot_timer.timeout.connect(self._save_snapshot)
        self.snapshot_timer.start(300000)  # 5 minutos

        self.logger.info(f"✅ Simulator inicializado:")
        self.logger.info(f"   💰 Capital inicial: ${initial_capital:,.2f} USDT")
        self.logger.info(f"   📊 Comissão: {commission_rate:.3%}")
        self.logger.info(f"   📉 Slippage: {slippage_bps} bps")
        self.logger.info(f"   💾 Persistência: {self.simulator_dir}")

    # ========================================================================
    # LIFECYCLE
    # ========================================================================

    def start(self):
        """Inicia o simulador"""
        self.logger.info("▶️ Offline API Simulator PRONTO")

    def stop(self):
        """Para o simulador e salva estado"""
        try:
            self.logger.info("⏸️ Parando Offline API Simulator...")

            # Salvar estado final
            self._save_state()
            self._save_snapshot()

            # Parar timer
            if self.snapshot_timer.isActive():
                self.snapshot_timer.stop()

            self.logger.info("✅ Simulator parado e estado salvo")

        except Exception as e:
            self.logger.error(f"❌ Erro ao parar simulator: {e}", exc_info=True)

    # ========================================================================
    # PERSISTÊNCIA
    # ========================================================================

    def _load_state(self):
        """Carrega estado persistido do disco"""
        try:
            # Carregar ordens
            if self.orders_file.exists():
                with open(self.orders_file, 'r', encoding='utf-8') as f:
                    orders_data = json.load(f)
                    self.order_history = [self._dict_to_order(o) for o in orders_data.get('history', [])]
                    self.active_orders = {
                        int(oid): self._dict_to_order(o)
                        for oid, o in orders_data.get('active', {}).items()
                    }
                    self._next_order_id = orders_data.get('next_id', 1)
                self.logger.info(f"📂 Carregado: {len(self.order_history)} ordens históricas, {len(self.active_orders)} ativas")

            # Carregar trades
            if self.trades_file.exists():
                with open(self.trades_file, 'r', encoding='utf-8') as f:
                    trades_data = json.load(f)
                    self.trades = [self._dict_to_trade(t) for t in trades_data.get('trades', [])]
                    self._next_trade_id = trades_data.get('next_id', 1)
                self.logger.info(f"📂 Carregado: {len(self.trades)} trades")

            # Carregar balances
            if self.balances_file.exists():
                with open(self.balances_file, 'r', encoding='utf-8') as f:
                    balances_data = json.load(f)
                    for asset, bal in balances_data.items():
                        self.balances[asset] = bal
                self.logger.info(f"📂 Carregado: {len(self.balances)} balances")

        except Exception as e:
            self.logger.warning(f"⚠️ Erro ao carregar estado: {e}")

    def _save_state(self):
        """Salva estado atual no disco"""
        try:
            with QMutexLocker(self._mutex):
                # Salvar ordens
                orders_data = {
                    'history': [o.to_dict() for o in self.order_history],
                    'active': {str(oid): o.to_dict() for oid, o in self.active_orders.items()},
                    'next_id': self._next_order_id
                }
                with open(self.orders_file, 'w', encoding='utf-8') as f:
                    json.dump(orders_data, f, indent=2)

                # Salvar trades
                trades_data = {
                    'trades': [t.to_dict() for t in self.trades],
                    'next_id': self._next_trade_id
                }
                with open(self.trades_file, 'w', encoding='utf-8') as f:
                    json.dump(trades_data, f, indent=2)

                # Salvar balances
                with open(self.balances_file, 'w', encoding='utf-8') as f:
                    json.dump(dict(self.balances), f, indent=2)

            self.logger.debug("💾 Estado salvo em disco")

        except Exception as e:
            self.logger.error(f"❌ Erro ao salvar estado: {e}", exc_info=True)

    def _save_snapshot(self):
        """Salva snapshot da conta (timestamp, balances, equity, pnl)"""
        try:
            snapshot = {
                'timestamp': int(datetime.now().timestamp() * 1000),
                'datetime': datetime.now().isoformat(),
                'balances': dict(self.balances),
                'total_equity_usdt': self._calculate_total_equity(),
                'total_trades': len(self.trades),
                'total_orders': len(self.order_history) + len(self.active_orders)
            }

            # Carregar snapshots existentes
            snapshots = []
            if self.snapshots_file.exists():
                with open(self.snapshots_file, 'r', encoding='utf-8') as f:
                    snapshots = json.load(f)

            # Adicionar novo snapshot
            snapshots.append(snapshot)

            # Manter apenas últimos 10000 snapshots
            if len(snapshots) > 10000:
                snapshots = snapshots[-10000:]

            # Salvar
            with open(self.snapshots_file, 'w', encoding='utf-8') as f:
                json.dump(snapshots, f, indent=2)

            self.logger.debug(f"📸 Snapshot salvo: equity=${snapshot['total_equity_usdt']:,.2f}")

            # Emitir sinal
            self.account_update.emit(snapshot)

        except Exception as e:
            self.logger.error(f"❌ Erro ao salvar snapshot: {e}", exc_info=True)

    # ========================================================================
    # MARKET DATA
    # ========================================================================

    def _on_price_update(self, cache_key: str, ticker_data: dict):
        """
        Handler: Ticker atualizado pelo BinanceData

        Args:
            cache_key: Chave do cache (ex: ticker:BTCUSDT)
            ticker_data: Dados completos do ticker normalizado
        """
        symbol = ticker_data.get('symbol')
        if not symbol:
            return

        with QMutexLocker(self._mutex):
            # Armazenar ticker completo (não apenas o preço)
            self.current_prices[symbol] = {
                'price': float(ticker_data.get('price', 0.0)),
                'bid': float(ticker_data.get('bid', 0.0)),
                'ask': float(ticker_data.get('ask', 0.0)),
                'high': float(ticker_data.get('high', 0.0)),
                'low': float(ticker_data.get('low', 0.0)),
                'open': float(ticker_data.get('open', 0.0)),
                'volume': float(ticker_data.get('volume', 0.0)),
                'quote_volume': float(ticker_data.get('quote_volume', 0.0)),
                'price_change': float(ticker_data.get('price_change', 0.0)),
                'price_change_pct': float(ticker_data.get('price_change_pct', 0.0)),
                'timestamp': int(ticker_data.get('timestamp', 0))
            }

            # Verificar ordens LIMIT/STOP que podem executar
            current_price = self.current_prices[symbol]['price']
            self._check_pending_orders(symbol, current_price)

    def get_price(self, symbol: str) -> Optional[float]:
        """
        Retorna preço atual do símbolo

        Args:
            symbol: Símbolo

        Returns:
            Preço atual ou None
        """
        with QMutexLocker(self._mutex):
            ticker = self.current_prices.get(symbol)
            if ticker is None:
                return None
            # Compatibilidade: se for dict, retorna 'price', se for float, retorna direto
            return ticker['price'] if isinstance(ticker, dict) else ticker

    def get_ticker(self, symbol: str) -> Optional[Dict[str, float]]:
        """
        Retorna ticker completo do símbolo

        Args:
            symbol: Símbolo

        Returns:
            Ticker completo com price, bid, ask, high, low, volume, etc. ou None
        """
        with QMutexLocker(self._mutex):
            ticker = self.current_prices.get(symbol)
            if ticker is None:
                return None
            # Se for dict (novo formato), retorna cópia. Se for float (antigo), converte
            if isinstance(ticker, dict):
                return copy.deepcopy(ticker)
            else:
                # Fallback para formato antigo (apenas price)
                return {'price': ticker}

    # ========================================================================
    # CARTEIRA (WALLET)
    # ========================================================================

    def get_balance(self, asset: str) -> Dict[str, float]:
        """
        Retorna balance de um asset

        Args:
            asset: Asset (ex: USDT, BTC)

        Returns:
            {'free': float, 'locked': float}
        """
        with QMutexLocker(self._mutex):
            return copy.deepcopy(self.balances.get(asset, {'free': 0.0, 'locked': 0.0}))

    def get_all_balances(self) -> Dict[str, Dict[str, float]]:
        """Retorna todos os balances"""
        with QMutexLocker(self._mutex):
            return {asset: copy.deepcopy(bal) for asset, bal in self.balances.items() if bal['free'] > 0 or bal['locked'] > 0}

    def _calculate_total_equity(self) -> float:
        """Calcula equity total em USDT"""
        total = 0.0

        for asset, bal in self.balances.items():
            asset_total = bal['free'] + bal['locked']

            if asset == 'USDT':
                total += asset_total
            else:
                # Converter para USDT usando preço atual
                symbol = f"{asset}USDT"
                price = self.current_prices.get(symbol, 0.0)
                total += asset_total * price

        return total

    def _update_balance(self, asset: str, free_delta: float = 0.0, locked_delta: float = 0.0):
        """
        Atualiza balance de um asset

        Args:
            asset: Asset
            free_delta: Mudança no free balance
            locked_delta: Mudança no locked balance
        """
        if asset not in self.balances:
            self.balances[asset] = {'free': 0.0, 'locked': 0.0}

        self.balances[asset]['free'] += free_delta
        self.balances[asset]['locked'] += locked_delta

        # Emitir sinal
        self.balance_update.emit({asset: copy.deepcopy(self.balances[asset])})

    # ========================================================================
    # ORDENS
    # ========================================================================

    def create_order(
        self,
        symbol: str,
        side: OrderSide,
        order_type: OrderType,
        quantity: float,
        price: float = 0.0,
        stop_price: float = 0.0,
        time_in_force: TimeInForce = TimeInForce.GTC,
        client_order_id: Optional[str] = None
    ) -> Optional[SimulatedOrder]:
        """
        Cria uma nova ordem

        Args:
            symbol: Símbolo (ex: BTCUSDT)
            side: BUY ou SELL
            order_type: MARKET, LIMIT, STOP_LOSS, etc
            quantity: Quantidade (em base asset)
            price: Preço (para LIMIT orders)
            stop_price: Stop price (para STOP orders)
            time_in_force: GTC, IOC, FOK
            client_order_id: ID customizado

        Returns:
            SimulatedOrder criado ou None se falhar
        """
        try:
            with QMutexLocker(self._mutex):
                # Gerar IDs
                order_id = self._next_order_id
                self._next_order_id += 1

                if not client_order_id:
                    client_order_id = f"sim_{self._next_client_order_id}"
                    self._next_client_order_id += 1

                timestamp = int(datetime.now().timestamp() * 1000)

                # Criar ordem
                order = SimulatedOrder(
                    symbol=symbol,
                    orderId=order_id,
                    clientOrderId=client_order_id,
                    transactTime=timestamp,
                    price=price,
                    origQty=quantity,
                    executedQty=0.0,
                    cummulativeQuoteQty=0.0,
                    status=OrderStatus.NEW,
                    timeInForce=time_in_force,
                    type=order_type,
                    side=side,
                    stopPrice=stop_price,
                    time=timestamp,
                    updateTime=timestamp,
                    isWorking=True
                )

                # Validar e reservar fundos
                if not self._validate_and_lock_funds(order):
                    order.status = OrderStatus.REJECTED
                    self.order_history.append(order)
                    self.order_update.emit(order.to_dict())
                    return None

                # MARKET orders executam imediatamente
                if order_type == OrderType.MARKET:
                    self._execute_order(order)
                else:
                    # LIMIT/STOP orders vão para active_orders
                    self.active_orders[order_id] = order

                # Salvar e emitir
                self.order_history.append(order)
                self.order_update.emit(order.to_dict())

                self.logger.info(
                    f"📝 Ordem criada: #{order_id} {side.value} {quantity} {symbol} "
                    f"@ ${price:.2f} ({order_type.value})"
                )

                return order

        except Exception as e:
            self.logger.error(f"❌ Erro ao criar ordem: {e}", exc_info=True)
            return None

    def cancel_order(self, symbol: str, order_id: int) -> bool:
        """
        Cancela uma ordem ativa

        Args:
            symbol: Símbolo
            order_id: ID da ordem

        Returns:
            True se cancelado com sucesso
        """
        try:
            with QMutexLocker(self._mutex):
                if order_id not in self.active_orders:
                    self.logger.warning(f"⚠️ Ordem #{order_id} não encontrada")
                    return False

                order = self.active_orders[order_id]

                # Desbloquear fundos
                self._unlock_funds(order)

                # Atualizar status
                order.status = OrderStatus.CANCELED
                order.updateTime = int(datetime.now().timestamp() * 1000)
                order.isWorking = False

                # Mover para histórico
                del self.active_orders[order_id]

                # Emitir sinal
                self.order_update.emit(order.to_dict())

                self.logger.info(f"🚫 Ordem cancelada: #{order_id}")

                return True

        except Exception as e:
            self.logger.error(f"❌ Erro ao cancelar ordem: {e}", exc_info=True)
            return False

    def get_order(self, symbol: str, order_id: int) -> Optional[Dict[str, Any]]:
        """Retorna ordem por ID"""
        with QMutexLocker(self._mutex):
            if order_id in self.active_orders:
                return self.active_orders[order_id].to_dict()

            for order in self.order_history:
                if order.orderId == order_id:
                    return order.to_dict()

            return None

    def get_open_orders(self, symbol: Optional[str] = None) -> List[Dict[str, Any]]:
        """Retorna ordens abertas"""
        with QMutexLocker(self._mutex):
            orders = []
            for order in self.active_orders.values():
                if symbol is None or order.symbol == symbol:
                    orders.append(order.to_dict())
            return orders

    # ========================================================================
    # EXECUÇÃO DE ORDENS
    # ========================================================================

    def _validate_and_lock_funds(self, order: SimulatedOrder) -> bool:
        """
        Valida se há fundos suficientes e bloqueia os fundos

        Args:
            order: Ordem a validar

        Returns:
            True se válido e fundos bloqueados
        """
        try:
            base_asset = order.symbol.replace('USDT', '')
            quote_asset = 'USDT'

            if order.side == OrderSide.BUY:
                # Comprar: precisa de USDT
                # Calcular custo total (pior caso)
                if order.type == OrderType.MARKET:
                    price = self.current_prices.get(order.symbol, 0.0)
                    if price == 0.0:
                        self.logger.error(f"❌ Preço não disponível para {order.symbol}")
                        return False
                    # Adicionar slippage
                    price *= (1 + self.slippage_bps / 10000.0)
                else:
                    price = order.price

                cost = order.origQty * price
                commission = cost * self.commission_rate
                total_cost = cost + commission

                if self.balances[quote_asset]['free'] < total_cost:
                    self.logger.warning(
                        f"⚠️ Fundos insuficientes: precisa ${total_cost:.2f} USDT, "
                        f"tem ${self.balances[quote_asset]['free']:.2f}"
                    )
                    return False

                # Bloquear USDT
                self._update_balance(quote_asset, free_delta=-total_cost, locked_delta=total_cost)

            else:  # SELL
                # Vender: precisa do base asset
                if self.balances[base_asset]['free'] < order.origQty:
                    self.logger.warning(
                        f"⚠️ Saldo insuficiente: precisa {order.origQty} {base_asset}, "
                        f"tem {self.balances[base_asset]['free']}"
                    )
                    return False

                # Bloquear base asset
                self._update_balance(base_asset, free_delta=-order.origQty, locked_delta=order.origQty)

            return True

        except Exception as e:
            self.logger.error(f"❌ Erro ao validar fundos: {e}", exc_info=True)
            return False

    def _unlock_funds(self, order: SimulatedOrder):
        """Desbloqueia fundos de uma ordem cancelada"""
        base_asset = order.symbol.replace('USDT', '')
        quote_asset = 'USDT'

        if order.side == OrderSide.BUY:
            # Calcular quanto estava bloqueado
            cost = order.origQty * order.price
            commission = cost * self.commission_rate
            total = cost + commission

            self._update_balance(quote_asset, free_delta=total, locked_delta=-total)
        else:
            self._update_balance(base_asset, free_delta=order.origQty, locked_delta=-order.origQty)

    def _check_pending_orders(self, symbol: str, current_price: float):
        """
        Verifica se ordens pendentes LIMIT/STOP devem executar

        Args:
            symbol: Símbolo
            current_price: Preço atual
        """
        orders_to_execute = []

        for order_id, order in list(self.active_orders.items()):
            if order.symbol != symbol:
                continue

            should_execute = False

            # LIMIT orders
            if order.type == OrderType.LIMIT:
                if order.side == OrderSide.BUY and current_price <= order.price:
                    should_execute = True
                elif order.side == OrderSide.SELL and current_price >= order.price:
                    should_execute = True

            # STOP_LOSS orders
            elif order.type == OrderType.STOP_LOSS:
                if order.side == OrderSide.SELL and current_price <= order.stopPrice:
                    should_execute = True
                elif order.side == OrderSide.BUY and current_price >= order.stopPrice:
                    should_execute = True

            # TAKE_PROFIT orders
            elif order.type == OrderType.TAKE_PROFIT:
                if order.side == OrderSide.SELL and current_price >= order.stopPrice:
                    should_execute = True
                elif order.side == OrderSide.BUY and current_price <= order.stopPrice:
                    should_execute = True

            if should_execute:
                orders_to_execute.append(order)

        # Executar ordens
        for order in orders_to_execute:
            self._execute_order(order)
            if order.orderId in self.active_orders:
                del self.active_orders[order.orderId]

    def _execute_order(self, order: SimulatedOrder):
        """
        Executa uma ordem

        Args:
            order: Ordem a executar
        """
        try:
            symbol = order.symbol
            base_asset = symbol.replace('USDT', '')
            quote_asset = 'USDT'

            # Determinar preço de fill
            if order.type == OrderType.MARKET:
                ticker = self.current_prices.get(symbol)
                if ticker is None:
                    order.status = OrderStatus.REJECTED
                    return

                # Usar bid/ask do ticker para execução mais realista
                if isinstance(ticker, dict):
                    # Novo formato: usar ask para BUY, bid para SELL
                    if order.side == OrderSide.BUY:
                        fill_price = ticker.get('ask', ticker.get('price', 0.0))
                    else:
                        fill_price = ticker.get('bid', ticker.get('price', 0.0))
                else:
                    # Formato antigo (compatibilidade)
                    fill_price = ticker

                if fill_price == 0.0:
                    order.status = OrderStatus.REJECTED
                    return

                # Aplicar slippage
                if order.side == OrderSide.BUY:
                    fill_price *= (1 + self.slippage_bps / 10000.0)
                else:
                    fill_price *= (1 - self.slippage_bps / 10000.0)
            else:
                fill_price = order.price

            # Executar trade
            qty = order.origQty
            quote_qty = qty * fill_price
            commission = quote_qty * self.commission_rate
            commission_asset = quote_asset

            if order.side == OrderSide.BUY:
                # Desbloquear USDT bloqueado
                cost_locked = order.origQty * order.price if order.type != OrderType.MARKET else quote_qty
                total_locked = cost_locked + (cost_locked * self.commission_rate)
                self._update_balance(quote_asset, locked_delta=-total_locked)

                # Debitar USDT real
                total_cost = quote_qty + commission
                if self.balances[quote_asset]['free'] < total_cost - total_locked:
                    # Rebloquear e rejeitar
                    self._update_balance(quote_asset, locked_delta=total_locked)
                    order.status = OrderStatus.REJECTED
                    return

                self._update_balance(quote_asset, free_delta=-(total_cost - total_locked))

                # Creditar base asset
                self._update_balance(base_asset, free_delta=qty)

            else:  # SELL
                # Desbloquear base asset
                self._update_balance(base_asset, locked_delta=-qty)

                # Creditar USDT
                proceeds = quote_qty - commission
                self._update_balance(quote_asset, free_delta=proceeds)

            # Atualizar ordem
            order.status = OrderStatus.FILLED
            order.executedQty = qty
            order.cummulativeQuoteQty = quote_qty
            order.updateTime = int(datetime.now().timestamp() * 1000)
            order.isWorking = False

            # Criar trade
            trade = SimulatedTrade(
                id=self._next_trade_id,
                orderId=order.orderId,
                symbol=symbol,
                price=fill_price,
                qty=qty,
                quoteQty=quote_qty,
                commission=commission,
                commissionAsset=commission_asset,
                time=order.updateTime,
                isBuyer=(order.side == OrderSide.BUY),
                isMaker=(order.type != OrderType.MARKET)
            )
            self._next_trade_id += 1
            self.trades.append(trade)

            # Emitir sinais
            self.order_update.emit(order.to_dict())
            self.trade_update.emit(trade.to_dict())

            self.logger.info(
                f"✅ Ordem executada: #{order.orderId} {order.side.value} "
                f"{qty} {symbol} @ ${fill_price:.2f} (comissão: ${commission:.4f})"
            )

        except Exception as e:
            self.logger.error(f"❌ Erro ao executar ordem: {e}", exc_info=True)
            order.status = OrderStatus.REJECTED

    # ========================================================================
    # TRADES
    # ========================================================================

    def get_trades(self, symbol: Optional[str] = None, limit: int = 500) -> List[Dict[str, Any]]:
        """
        Retorna trades

        Args:
            symbol: Filtrar por símbolo (opcional)
            limit: Limite de trades

        Returns:
            Lista de trades
        """
        with QMutexLocker(self._mutex):
            trades = self.trades

            if symbol:
                trades = [t for t in trades if t.symbol == symbol]

            trades = trades[-limit:]

            return [t.to_dict() for t in trades]

    # ========================================================================
    # HELPERS
    # ========================================================================

    def _dict_to_order(self, data: Dict[str, Any]) -> SimulatedOrder:
        """Converte dict para SimulatedOrder"""
        return SimulatedOrder(
            symbol=data['symbol'],
            orderId=data['orderId'],
            clientOrderId=data['clientOrderId'],
            transactTime=data['transactTime'],
            price=float(data['price']),
            origQty=float(data['origQty']),
            executedQty=float(data['executedQty']),
            cummulativeQuoteQty=float(data['cummulativeQuoteQty']),
            status=OrderStatus(data['status']),
            timeInForce=TimeInForce(data['timeInForce']),
            type=OrderType(data['type']),
            side=OrderSide(data['side']),
            stopPrice=float(data.get('stopPrice', 0.0)),
            icebergQty=float(data.get('icebergQty', 0.0)),
            time=data.get('time', 0),
            updateTime=data.get('updateTime', 0),
            isWorking=data.get('isWorking', True)
        )

    def _dict_to_trade(self, data: Dict[str, Any]) -> SimulatedTrade:
        """Converte dict para SimulatedTrade"""
        return SimulatedTrade(
            id=data['id'],
            orderId=data['orderId'],
            symbol=data['symbol'],
            price=float(data['price']),
            qty=float(data['qty']),
            quoteQty=float(data['quoteQty']),
            commission=float(data['commission']),
            commissionAsset=data['commissionAsset'],
            time=data['time'],
            isBuyer=data['isBuyer'],
            isMaker=data['isMaker'],
            isBestMatch=data.get('isBestMatch', True)
        )


# ============================================================================
# BINANCE USER DATA STREAM WORKER - WEBSOCKET EM THREAD SEPARADA
# ============================================================================

class BinanceUserDataStreamWorker(QThread):
    """
    Worker Qt Thread para gerenciar WebSocket User Data Stream da Binance

    Responsabilidades:
        - Conectar ao WebSocket User Data Stream usando listenKey
        - Receber eventos em tempo real (executionReport, balanceUpdate, etc)
        - Emitir sinais Qt quando eventos são recebidos
        - Manter conexão ativa com ping/pong automático
        - Reconectar automaticamente em caso de falha
        - Keep-alive do listenKey a cada 30 minutos

    Sinais emitidos:
        - message_received(event_type: str, data: dict): Evento recebido
        - connection_status(connected: bool, message: str): Status da conexão
    """

    # Sinais Qt
    message_received = Signal(str, dict)  # event_type, data
    connection_status = Signal(bool, str)  # connected, message

    def __init__(
        self,
        ws_url: str,
        listen_key: str,
        keep_alive_callback,
        parent=None
    ):
        """
        Args:
            ws_url: URL base do WebSocket (ex: wss://stream.binance.com:9443/ws)
            listen_key: ListenKey obtido via REST API
            keep_alive_callback: Função para chamar a cada 30 min para manter listenKey vivo
            parent: Parent QObject
        """
        super().__init__(parent)

        self.ws_url = ws_url
        self.listen_key = listen_key
        self.keep_alive_callback = keep_alive_callback

        self._running = False
        self._ws = None
        self._keep_alive_timer = None

        self.logger = logging.getLogger('BinanceUserDataStreamWorker')

    def run(self):
        """Thread principal - executa loop de conexão WebSocket"""
        self._running = True

        try:
            # Instalar event loop asyncio nesta thread
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)

            # Executar loop de conexão
            loop.run_until_complete(self._connection_loop())

        except Exception as e:
            self.logger.error(f"❌ Erro fatal no worker: {e}", exc_info=True)
        finally:
            self._running = False

    async def _connection_loop(self):
        """Loop de conexão com reconexão automática"""

        retry_count = 0
        max_retries = 999  # Reconexão infinita
        backoff_delay = 1

        while self._running and retry_count < max_retries:
            try:
                # Construir URL completa
                full_url = f"{self.ws_url}/{self.listen_key}"

                self.logger.info(f"🌐 Conectando ao User Data Stream...")
                self.logger.info(f"   URL: {full_url[:50]}...")

                # Conectar ao WebSocket
                async with websockets.connect(
                    full_url,
                    ping_interval=180,  # Ping a cada 3 minutos
                    ping_timeout=600,    # Timeout de 10 minutos
                    close_timeout=10
                ) as websocket:
                    self._ws = websocket

                    self.logger.info("✅ WebSocket conectado!")
                    self.connection_status.emit(True, "Conectado ao User Data Stream")

                    # Reset contador de tentativas
                    retry_count = 0
                    backoff_delay = 1

                    # Iniciar keep-alive do listenKey em task separada
                    keep_alive_task = asyncio.create_task(self._keep_alive_loop())

                    try:
                        # Loop de recebimento de mensagens
                        async for message in websocket:
                            if not self._running:
                                break

                            await self._process_message(message)

                    finally:
                        # Cancelar task de keep-alive
                        keep_alive_task.cancel()
                        try:
                            await keep_alive_task
                        except asyncio.CancelledError:
                            pass

            except websockets.exceptions.ConnectionClosed as e:
                self.logger.warning(f"⚠️ Conexão WebSocket fechada: {e}")
                self.connection_status.emit(False, f"Conexão fechada: {e}")
                retry_count += 1

                if self._running and retry_count < max_retries:
                    self.logger.info(f"🔄 Reconectando em {backoff_delay}s... (tentativa {retry_count})")
                    await asyncio.sleep(backoff_delay)
                    backoff_delay = min(backoff_delay * 2, 60)  # Máximo 60s

            except Exception as e:
                self.logger.error(f"❌ Erro no WebSocket: {e}", exc_info=True)
                self.connection_status.emit(False, f"Erro: {e}")
                retry_count += 1

                if self._running and retry_count < max_retries:
                    await asyncio.sleep(backoff_delay)
                    backoff_delay = min(backoff_delay * 2, 60)

        self.logger.info("⏹️ Loop de conexão encerrado")
        self.connection_status.emit(False, "Worker encerrado")

    async def _process_message(self, message: str):
        """Processa mensagem recebida do WebSocket"""
        try:
            data = json.loads(message)

            event_type = data.get('e', 'unknown')

            self.logger.debug(f"📨 Mensagem recebida: {event_type}")

            # Emitir sinal com dados da mensagem
            self.message_received.emit(event_type, data)

        except json.JSONDecodeError as e:
            self.logger.error(f"❌ Erro ao decodificar JSON: {e}")
        except Exception as e:
            self.logger.error(f"❌ Erro ao processar mensagem: {e}", exc_info=True)

    async def _keep_alive_loop(self):
        """Loop para manter listenKey vivo a cada 30 minutos"""

        while self._running:
            try:
                # Esperar 30 minutos
                await asyncio.sleep(30 * 60)

                if not self._running:
                    break

                # Chamar callback para manter listenKey vivo
                self.logger.info("🔄 Enviando keep-alive do listenKey...")

                # Executar callback em thread separada (é bloqueante - requests.put)
                import concurrent.futures
                with concurrent.futures.ThreadPoolExecutor() as executor:
                    await asyncio.get_event_loop().run_in_executor(
                        executor,
                        self.keep_alive_callback
                    )

                self.logger.info("✅ ListenKey mantido vivo")

            except asyncio.CancelledError:
                break
            except Exception as e:
                self.logger.error(f"❌ Erro no keep-alive: {e}", exc_info=True)

    def stop(self):
        """Para o worker e fecha conexão WebSocket"""
        self.logger.info("⏹️ Parando User Data Stream Worker...")
        self._running = False

        # Qt Thread terminará naturalmente quando run() retornar

# ============================================================================
# BINANCETRADINGAPI - CLIENTE ESPECIALIZADO PARA TRADING NA BINANCE
# ============================================================================

class BinanceTradingAPI(QObject):
    """
    Cliente Especializado para Trading na Binance (Spot)

    RESPONSABILIDADES:
        - Executar ordens REAIS na Binance (Testnet ou Mainnet)
        - Autenticação HMAC SHA256 com API Key + Secret
        - Suporte completo a tipos de ordem (MARKET, LIMIT, STOP_LOSS, etc)
        - User Data Stream WebSocket para eventos em tempo real
        - Gestão de ordens (create, cancel, query)
        - Consulta de saldo e informações da conta

    MODOS:
        - Testnet: Paper trading com API real simulada
        - Mainnet: Trading real com dinheiro real

    SINAIS QT:
        - order_submitted(order_id, symbol, side): Ordem enviada
        - order_filled(order_id, fill_data): Ordem executada
        - order_rejected(order_id, reason): Ordem rejeitada
        - order_cancelled(order_id): Ordem cancelada
        - balance_updated(asset, free, locked): Saldo atualizado
        - user_data_received(event_type, data): Evento do User Data Stream

    ENDPOINTS BINANCE:
        ✅ POST /api/v3/order (New Order)
        ✅ DELETE /api/v3/order (Cancel Order)
        ✅ GET /api/v3/order (Query Order)
        ✅ GET /api/v3/openOrders (Open Orders)
        ✅ GET /api/v3/account (Account Information)
        ✅ POST /api/v3/userDataStream (Start User Data Stream)
        ✅ WS /ws/<listenKey> (User Data Stream)

    SEGURANÇA:
        - API Key nunca logada
        - API Secret nunca exposta
        - Assinatura HMAC para todas requisições autenticadas
        - Rate limiting integrado
    """

    # Sinais Qt
    order_submitted = Signal(str, str, str)  # order_id, symbol, side
    order_filled = Signal(str, dict)  # order_id, fill_data
    order_rejected = Signal(str, str)  # order_id, reason
    order_cancelled = Signal(str)  # order_id
    balance_updated = Signal(str, float, float)  # asset, free, locked
    user_data_received = Signal(str, dict)  # event_type, data

    def __init__(
        self,
        api_key: str,
        api_secret: str,
        testnet: bool = False,
        rate_limiter: Optional[RateLimiter] = None,
        parent=None
    ):
        """
        Inicializa BinanceTradingAPI

        Args:
            api_key: Binance API Key
            api_secret: Binance API Secret
            testnet: True para testnet, False para mainnet
            rate_limiter: Rate limiter compartilhado (opcional)
            parent: QObject pai
        """
        super().__init__(parent)

        self.logger = logging.getLogger('BinanceTradingAPI')
        self.logger.info("="*80)
        self.logger.info(f"🔑 INICIALIZANDO BINANCE TRADING API ({'TESTNET' if testnet else '⚠️💸 MAINNET'})")
        self.logger.info("="*80)

        # Credenciais
        self.api_key = api_key
        self.api_secret = api_secret
        self.testnet = testnet
        self.rate_limiter = rate_limiter

        # URLs
        if testnet:
            self.base_url = "https://testnet.binance.vision"
            self.ws_url = "wss://stream.testnet.binance.vision:9443"
        else:
            self.base_url = "https://api.binance.com"
            self.ws_url = "wss://stream.binance.com:9443"

        # Thread-safety
        self._mutex = QMutex()

        # User Data Stream
        self.listen_key = None
        self.ws_thread = None
        self.ws_worker = None

        # Order tracking
        self.active_orders = {}  # order_id → order_data
        self.order_history = deque(maxlen=1000)

        # Account info
        self.account_info = None
        self.balances = {}

        # Statistics
        self.stats = {
            'total_orders': 0,
            'filled_orders': 0,
            'rejected_orders': 0,
            'cancelled_orders': 0,
            'last_order_time': None
        }

        self.logger.info(f"✅ BinanceTradingAPI inicializado")
        self.logger.info(f"   Base URL: {self.base_url}")
        self.logger.info(f"   API Key: {api_key[:8]}...{api_key[-4:] if len(api_key) > 12 else ''}")

    # ========================================================================
    # LIFECYCLE METHODS
    # ========================================================================

    def start(self):
        """Inicia serviços (User Data Stream)"""
        try:
            self.logger.info("▶️ Iniciando BinanceTradingAPI...")

            # Obter informações da conta
            self._refresh_account_info()

            # Iniciar User Data Stream
            self.start_user_data_stream()

            self.logger.info("✅ BinanceTradingAPI operacional")

        except Exception as e:
            self.logger.error(f"❌ Erro ao iniciar: {e}", exc_info=True)

    def stop(self):
        """Para serviços"""
        try:
            self.logger.info("⏹️ Parando BinanceTradingAPI...")

            # Parar User Data Stream
            self.stop_user_data_stream()

            self.logger.info("✅ BinanceTradingAPI parado")

        except Exception as e:
            self.logger.error(f"❌ Erro ao parar: {e}", exc_info=True)

    # ========================================================================
    # TRADING API - SPOT ORDERS
    # ========================================================================

    def create_order(
        self,
        symbol: str,
        side: str,  # "BUY" ou "SELL"
        order_type: str,  # "MARKET", "LIMIT", "STOP_LOSS", "STOP_LOSS_LIMIT", "TAKE_PROFIT", "TAKE_PROFIT_LIMIT"
        quantity: float,
        price: Optional[float] = None,
        stop_price: Optional[float] = None,
        time_in_force: str = "GTC",  # GTC, IOC, FOK
        new_order_resp_type: str = "FULL"  # ACK, RESULT, FULL
    ) -> Dict[str, Any]:
        """
        POST /api/v3/order - Cria ordem na Binance

        Args:
            symbol: Par de trading (ex: 'BTCUSDT')
            side: 'BUY' ou 'SELL'
            order_type: Tipo da ordem
            quantity: Quantidade do ativo base
            price: Preço (obrigatório para LIMIT orders)
            stop_price: Preço de stop (para STOP orders)
            time_in_force: Validade da ordem
            new_order_resp_type: Tipo de resposta

        Returns:
            {
                'symbol': 'BTCUSDT',
                'orderId': 123456,
                'clientOrderId': 'xxx',
                'transactTime': 1234567890,
                'price': '45000.00',
                'origQty': '0.01',
                'executedQty': '0.01',
                'cummulativeQuoteQty': '450.00',
                'status': 'FILLED',  # NEW, PARTIALLY_FILLED, FILLED, CANCELED, REJECTED
                'timeInForce': 'GTC',
                'type': 'MARKET',
                'side': 'BUY',
                'fills': [...]  # Se new_order_resp_type == FULL
            }

        Raises:
            Exception: Se ordem for rejeitada pela Binance
        """
        logger = logging.getLogger('BinanceTradingAPI.create_order')

        try:
            with QMutexLocker(self._mutex):
                self.stats['total_orders'] += 1

                logger.info(f"📝 Criando ordem: {side} {quantity} {symbol}")
                logger.info(f"   Tipo: {order_type}")
                if price:
                    logger.info(f"   Preço: ${price:.2f}")
                if stop_price:
                    logger.info(f"   Stop Price: ${stop_price:.2f}")

                # Preparar parâmetros
                params = {
                    'symbol': symbol,
                    'side': side.upper(),
                    'type': order_type.upper(),
                    'quantity': self._format_quantity(quantity),
                    'newOrderRespType': new_order_resp_type,
                    'timestamp': int(time.time() * 1000)
                }

                # Adicionar parâmetros condicionais
                if order_type.upper() in ['LIMIT', 'STOP_LOSS_LIMIT', 'TAKE_PROFIT_LIMIT']:
                    if price is None:
                        raise ValueError(f"{order_type} requires price")
                    params['price'] = self._format_price(price)
                    params['timeInForce'] = time_in_force

                if order_type.upper() in ['STOP_LOSS', 'STOP_LOSS_LIMIT', 'TAKE_PROFIT', 'TAKE_PROFIT_LIMIT']:
                    if stop_price is None:
                        raise ValueError(f"{order_type} requires stopPrice")
                    params['stopPrice'] = self._format_price(stop_price)

                # Assinar requisição
                signature = self._sign_request(params)
                params['signature'] = signature

                # Headers
                headers = {
                    'X-MBX-APIKEY': self.api_key
                }

                # Rate limiting
                if self.rate_limiter:
                    self.rate_limiter.wait_if_needed('/api/v3/order')

                # Request
                response = requests.post(
                    f"{self.base_url}/api/v3/order",
                    params=params,
                    headers=headers,
                    timeout=10
                )

                # Report success to rate limiter
                if self.rate_limiter:
                    self.rate_limiter.report_success('/api/v3/order')

                # Parse response
                if response.status_code == 200:
                    order_data = response.json()

                    order_id = str(order_data['orderId'])

                    # Rastrear ordem
                    self.active_orders[order_id] = order_data
                    self.stats['last_order_time'] = datetime.now()

                    # Emitir sinal
                    self.order_submitted.emit(order_id, symbol, side)

                    logger.info(f"✅ Ordem criada: ID {order_id}")
                    logger.info(f"   Status: {order_data['status']}")
                    logger.info(f"   Client Order ID: {order_data.get('clientOrderId', 'N/A')}")

                    # Se já preenchida, emitir filled
                    if order_data['status'] == 'FILLED':
                        self.stats['filled_orders'] += 1
                        self.order_filled.emit(order_id, order_data)
                        logger.info(f"✅ Ordem preenchida imediatamente")

                        # Mover para histórico
                        if order_id in self.active_orders:
                            self.order_history.append(self.active_orders[order_id])
                            del self.active_orders[order_id]

                    return order_data

                else:
                    # Ordem rejeitada
                    self.stats['rejected_orders'] += 1

                    try:
                        error_data = response.json()
                        error_code = error_data.get('code', 'UNKNOWN')
                        error_msg = error_data.get('msg', 'Unknown error')
                    except:
                        error_code = response.status_code
                        error_msg = response.text

                    logger.error(f"❌ Ordem rejeitada pela Binance")
                    logger.error(f"   Code: {error_code}")
                    logger.error(f"   Message: {error_msg}")

                    self.order_rejected.emit('unknown', f"{error_code}: {error_msg}")

                    raise Exception(f"Order rejected: [{error_code}] {error_msg}")

        except Exception as e:
            logger.error(f"❌ Erro ao criar ordem: {e}", exc_info=True)
            self.stats['rejected_orders'] += 1
            raise

    def cancel_order(self, symbol: str, order_id: int) -> Dict[str, Any]:
        """
        DELETE /api/v3/order - Cancela ordem

        Args:
            symbol: Par de trading
            order_id: ID da ordem

        Returns:
            Dados da ordem cancelada
        """
        logger = logging.getLogger('BinanceTradingAPI.cancel_order')

        try:
            with QMutexLocker(self._mutex):
                logger.info(f"❌ Cancelando ordem: {order_id} ({symbol})")

                params = {
                    'symbol': symbol,
                    'orderId': order_id,
                    'timestamp': int(time.time() * 1000)
                }

                signature = self._sign_request(params)
                params['signature'] = signature

                headers = {'X-MBX-APIKEY': self.api_key}

                if self.rate_limiter:
                    self.rate_limiter.wait_if_needed('/api/v3/order')

                response = requests.delete(
                    f"{self.base_url}/api/v3/order",
                    params=params,
                    headers=headers,
                    timeout=10
                )

                if self.rate_limiter:
                    self.rate_limiter.report_success('/api/v3/order')

                if response.status_code == 200:
                    order_data = response.json()

                    self.stats['cancelled_orders'] += 1

                    # Mover para histórico
                    order_id_str = str(order_id)
                    if order_id_str in self.active_orders:
                        self.order_history.append(self.active_orders[order_id_str])
                        del self.active_orders[order_id_str]

                    # Emitir sinal
                    self.order_cancelled.emit(order_id_str)

                    logger.info(f"✅ Ordem cancelada: {order_id}")

                    return order_data
                else:
                    error = response.json()
                    raise Exception(f"Cancel failed: {error.get('msg', 'Unknown')}")

        except Exception as e:
            logger.error(f"❌ Erro ao cancelar ordem: {e}", exc_info=True)
            raise

    def get_account(self) -> Dict[str, Any]:
        """
        GET /api/v3/account - Informações da conta

        Returns:
            {
                'makerCommission': 10,
                'takerCommission': 10,
                'canTrade': True,
                'canWithdraw': True,
                'canDeposit': True,
                'updateTime': 1234567890,
                'accountType': 'SPOT',
                'balances': [
                    {'asset': 'BTC', 'free': '0.01', 'locked': '0.0'},
                    {'asset': 'USDT', 'free': '10000.0', 'locked': '0.0'},
                    ...
                ]
            }
        """
        logger = logging.getLogger('BinanceTradingAPI.get_account')

        try:
            params = {
                'timestamp': int(time.time() * 1000)
            }

            signature = self._sign_request(params)
            params['signature'] = signature

            headers = {'X-MBX-APIKEY': self.api_key}

            if self.rate_limiter:
                self.rate_limiter.wait_if_needed('/api/v3/account')

            response = requests.get(
                f"{self.base_url}/api/v3/account",
                params=params,
                headers=headers,
                timeout=10
            )

            if self.rate_limiter:
                self.rate_limiter.report_success('/api/v3/account')

            if response.status_code == 200:
                account_data = response.json()

                # Atualizar cache interno
                self.account_info = account_data

                # Atualizar balances
                for balance in account_data.get('balances', []):
                    asset = balance['asset']
                    free = float(balance['free'])
                    locked = float(balance['locked'])

                    self.balances[asset] = {
                        'free': free,
                        'locked': locked,
                        'total': free + locked
                    }

                    # Emitir sinal para cada ativo com saldo > 0
                    if free > 0 or locked > 0:
                        self.balance_updated.emit(asset, free, locked)

                logger.info(f"✅ Conta atualizada: {len(self.balances)} ativos")

                return account_data
            else:
                error = response.json()
                raise Exception(f"Get account failed: {error.get('msg', 'Unknown')}")

        except Exception as e:
            logger.error(f"❌ Erro ao obter conta: {e}", exc_info=True)
            raise

    # ========================================================================
    # USER DATA STREAM - WEBSOCKET
    # ========================================================================

    def start_user_data_stream(self):
        """
        Inicia User Data Stream para receber eventos em tempo real

        Eventos recebidos via WebSocket:
            - executionReport: Atualização de ordem (NEW, FILLED, CANCELED, etc)
            - balanceUpdate: Atualização de saldo individual
            - outboundAccountPosition: Posição completa da conta

        Fluxo:
            1. Criar listenKey via REST API
            2. Criar BinanceUserDataStreamWorker em thread separada
            3. Worker conecta ao WebSocket com listenKey
            4. Worker emite sinais quando eventos são recebidos
            5. Sinais são processados por _on_user_data_stream_message()
            6. Keep-alive automático do listenKey a cada 30 minutos
        """
        logger = logging.getLogger('BinanceTradingAPI.user_data_stream')

        try:
            logger.info("🌐 Iniciando User Data Stream...")

            # 1. Criar listenKey
            self.listen_key = self._create_listen_key()

            if not self.listen_key:
                logger.error("❌ Falha ao obter listenKey")
                return

            logger.info(f"✅ ListenKey obtido: {self.listen_key[:8]}...")

            # 2. Criar WebSocket Worker em thread separada
            self.ws_worker = BinanceUserDataStreamWorker(
                ws_url=f"{self.ws_url}/ws",  # wss://stream.binance.com:9443/ws
                listen_key=self.listen_key,
                keep_alive_callback=self._keep_alive_listen_key,  # Callback para keep-alive
                parent=self
            )

            # 3. Conectar sinais do worker
            self.ws_worker.message_received.connect(self._on_user_data_stream_message)
            self.ws_worker.connection_status.connect(self._on_ws_connection_status)

            # 4. Iniciar worker thread
            self.ws_worker.start()

            logger.info("✅ User Data Stream Worker iniciado em thread separada")

        except Exception as e:
            logger.error(f"❌ Erro ao iniciar User Data Stream: {e}", exc_info=True)

    def stop_user_data_stream(self):
        """Para User Data Stream e fecha WebSocket Worker"""
        logger = logging.getLogger('BinanceTradingAPI.user_data_stream')

        try:
            logger.info("⏹️ Parando User Data Stream...")

            # Parar worker thread
            if self.ws_worker:
                self.ws_worker.stop()
                self.ws_worker.wait(5000)  # Esperar até 5 segundos
                self.ws_worker = None
                logger.info("✅ Worker thread encerrado")

            # Fechar listenKey
            if self.listen_key:
                self._close_listen_key()
                self.listen_key = None
                logger.info("✅ ListenKey fechado")

        except Exception as e:
            logger.error(f"❌ Erro ao parar User Data Stream: {e}", exc_info=True)

    @Slot(str, dict)
    def _on_user_data_stream_message(self, event_type: str, data: dict):
        """
        Slot: Processa mensagens recebidas do User Data Stream WebSocket

        Args:
            event_type: Tipo do evento ('executionReport', 'balanceUpdate', etc)
            data: Dados do evento (formato JSON da Binance)
        """
        logger = logging.getLogger('BinanceTradingAPI.user_data_stream')

        try:
            logger.debug(f"📨 Evento recebido: {event_type}")

            if event_type == "executionReport":
                # Atualização de ordem
                self._handle_execution_report(data)

            elif event_type == "balanceUpdate":
                # Atualização de saldo individual
                self._handle_balance_update(data)

            elif event_type == "outboundAccountPosition":
                # Posição completa da conta
                self._handle_account_position(data)

            # Emitir sinal genérico para qualquer evento
            self.user_data_received.emit(event_type, data)

        except Exception as e:
            logger.error(f"❌ Erro ao processar mensagem do User Data Stream: {e}", exc_info=True)

    @Slot(bool, str)
    def _on_ws_connection_status(self, connected: bool, message: str):
        """
        Slot: Status da conexão WebSocket

        Args:
            connected: True se conectado, False se desconectado
            message: Mensagem descritiva
        """
        logger = logging.getLogger('BinanceTradingAPI.user_data_stream')

        if connected:
            logger.info(f"✅ WebSocket Status: {message}")
        else:
            logger.warning(f"⚠️ WebSocket Status: {message}")

    def _handle_execution_report(self, data: dict):
        """Processa executionReport - atualização de ordem"""
        logger = logging.getLogger('BinanceTradingAPI.execution_report')

        try:
            order_id = str(data.get('i', 'N/A'))  # Order ID
            symbol = data.get('s', 'UNKNOWN')
            side = data.get('S', 'UNKNOWN')
            order_status = data.get('X', 'UNKNOWN')  # Order status (NEW, FILLED, etc)
            execution_type = data.get('x', 'UNKNOWN')  # Execution type

            logger.info(f"📊 Execution Report: {symbol} {side} - Status: {order_status}")

            # Se ordem foi preenchida (FILLED)
            if order_status == "FILLED":
                logger.info(f"✅ Ordem preenchida: {order_id}")

                # Emitir sinal order_filled
                self.order_filled.emit(order_id, data)

            # Se ordem foi rejeitada
            elif order_status == "REJECTED":
                reason = data.get('r', 'Unknown reason')
                logger.warning(f"❌ Ordem rejeitada: {order_id} - {reason}")

                # Emitir sinal order_rejected
                self.order_rejected.emit(order_id, reason)

            # Se ordem foi cancelada
            elif order_status == "CANCELED":
                logger.info(f"🚫 Ordem cancelada: {order_id}")

                # Emitir sinal order_cancelled
                self.order_cancelled.emit(order_id)

            # Outras situações (NEW, PARTIALLY_FILLED, etc)
            else:
                logger.debug(f"   Status: {order_status}, Execution: {execution_type}")

        except Exception as e:
            logger.error(f"❌ Erro ao processar execution report: {e}", exc_info=True)

    def _handle_balance_update(self, data: dict):
        """Processa balanceUpdate - atualização de saldo individual"""
        logger = logging.getLogger('BinanceTradingAPI.balance_update')

        try:
            asset = data.get('a', 'UNKNOWN')
            delta = float(data.get('d', 0))

            logger.info(f"💰 Balance Update: {asset} delta={delta}")

            # Atualizar saldo local (se disponível)
            if asset in self.balances:
                self.balances[asset]['free'] += delta

                # Emitir sinal
                self.balance_updated.emit(
                    asset,
                    self.balances[asset]['free'],
                    self.balances[asset].get('locked', 0)
                )

        except Exception as e:
            logger.error(f"❌ Erro ao processar balance update: {e}", exc_info=True)

    def _handle_account_position(self, data: dict):
        """Processa outboundAccountPosition - posição completa da conta"""
        logger = logging.getLogger('BinanceTradingAPI.account_position')

        try:
            balances_list = data.get('B', [])

            logger.info(f"💼 Account Position Update: {len(balances_list)} ativos")

            for balance_data in balances_list:
                asset = balance_data.get('a', 'UNKNOWN')
                free = float(balance_data.get('f', 0))
                locked = float(balance_data.get('l', 0))

                # Atualizar saldo local
                self.balances[asset] = {
                    'free': free,
                    'locked': locked
                }

                # Emitir sinal para cada ativo
                self.balance_updated.emit(asset, free, locked)

        except Exception as e:
            logger.error(f"❌ Erro ao processar account position: {e}", exc_info=True)

    def _keep_alive_listen_key(self):
        """
        Mantém listenKey vivo (PUT /api/v3/userDataStream)

        Deve ser chamado a cada 30 minutos para evitar expiração.
        """
        logger = logging.getLogger('BinanceTradingAPI.keep_alive')

        try:
            if not self.listen_key:
                logger.warning("⚠️ Nenhum listenKey para manter vivo")
                return

            headers = {'X-MBX-APIKEY': self.api_key}
            params = {'listenKey': self.listen_key}

            response = requests.put(
                f"{self.base_url}/api/v3/userDataStream",
                params=params,
                headers=headers,
                timeout=10
            )

            if response.status_code == 200:
                logger.debug("✅ ListenKey keep-alive enviado")
            else:
                logger.warning(f"⚠️ Erro ao manter listenKey vivo: {response.text}")

        except Exception as e:
            logger.error(f"❌ Erro ao manter listenKey vivo: {e}", exc_info=True)

    # ========================================================================
    # MÉTODOS PRIVADOS - HELPERS
    # ========================================================================

    def _sign_request(self, params: Dict[str, Any]) -> str:
        """
        Assina requisição com HMAC SHA256

        Args:
            params: Parâmetros da requisição

        Returns:
            Assinatura hexadecimal
        """
        query_string = '&'.join([f"{k}={v}" for k, v in params.items()])
        signature = hmac.new(
            self.api_secret.encode('utf-8'),
            query_string.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()
        return signature

    def _format_quantity(self, quantity: float) -> str:
        """Formata quantidade removendo zeros desnecessários"""
        return f"{quantity:.8f}".rstrip('0').rstrip('.')

    def _format_price(self, price: float) -> str:
        """Formata preço removendo zeros desnecessários"""
        return f"{price:.8f}".rstrip('0').rstrip('.')

    def _create_listen_key(self) -> Optional[str]:
        """POST /api/v3/userDataStream - Cria listenKey"""
        try:
            headers = {'X-MBX-APIKEY': self.api_key}

            response = requests.post(
                f"{self.base_url}/api/v3/userDataStream",
                headers=headers,
                timeout=10
            )

            if response.status_code == 200:
                data = response.json()
                return data.get('listenKey')
            else:
                self.logger.error(f"❌ Erro ao criar listenKey: {response.text}")
                return None

        except Exception as e:
            self.logger.error(f"❌ Erro ao criar listenKey: {e}", exc_info=True)
            return None

    def _close_listen_key(self):
        """DELETE /api/v3/userDataStream - Fecha listenKey"""
        try:
            if not self.listen_key:
                return

            headers = {'X-MBX-APIKEY': self.api_key}
            params = {'listenKey': self.listen_key}

            response = requests.delete(
                f"{self.base_url}/api/v3/userDataStream",
                params=params,
                headers=headers,
                timeout=10
            )

            if response.status_code == 200:
                self.logger.info("✅ ListenKey fechado")
            else:
                self.logger.warning(f"⚠️ Erro ao fechar listenKey: {response.text}")

        except Exception as e:
            self.logger.error(f"❌ Erro ao fechar listenKey: {e}", exc_info=True)

    def _refresh_account_info(self):
        """Atualiza informações da conta"""
        try:
            self.get_account()
        except Exception as e:
            self.logger.warning(f"⚠️ Não foi possível atualizar conta: {e}")

# ============================================================================
# INDICATORSWORKER - WORKER DEDICADO PARA CÁLCULOS
# ============================================================================

class IndicatorsWorker(QObject):
    """
    Worker dedicado para cálculo de indicadores técnicos
    
    Executa em QThread separado para não bloquear a UI.
    Processa tarefas individuais ou em batch.
    
    RESPONSABILIDADES:
        - Calcular 10+ indicadores técnicos
        - Processar single ou batch
        - Emitir progresso incremental
        - Tratamento robusto de erros
    
    SINAIS:
        result_ready: Emitido quando cálculo completa
        error_occurred: Emitido em caso de erro
        progress: Emitido durante batch processing
        task_started: Emitido ao iniciar tarefa
        task_completed: Emitido ao completar tarefa
    """
    
    # Sinais
    result_ready = Signal(int, dict)           # task_id, result
    error_occurred = Signal(int, str)          # task_id, error_message
    progress = Signal(int, int, int)           # task_id, current, total
    task_started = Signal(int)                 # task_id
    task_completed = Signal(int, float)        # task_id, duration_ms
    
    def __init__(self, worker_id: int, config: Dict):
        """
        Inicializa worker
        
        Args:
            worker_id: ID do worker (para logging)
            config: Configurações de indicadores
        """
        super().__init__()
        
        self.worker_id = worker_id
        self.config = config
        self.logger = logging.getLogger(f'IndicatorsWorker_{worker_id}')
        self.is_running = True
        
        # Carregar configurações
        self._load_config()
        
        self.logger.info(f"Worker #{worker_id} inicializado")
    
    def _load_config(self):
        """Carrega configurações de indicadores"""
        indicators_config = self.config.get('indicators', {})
        
        # RSI
        rsi_config = indicators_config.get('rsi', {})
        self.rsi_periods = rsi_config.get('periods', [7, 14, 21])
        
        # MACD
        macd_config = indicators_config.get('macd', {})
        self.macd_fast = macd_config.get('fast', 12)
        self.macd_slow = macd_config.get('slow', 26)
        self.macd_signal = macd_config.get('signal', 9)
        
        # SMA
        sma_config = indicators_config.get('sma', {})
        self.sma_periods = sma_config.get('periods', [5, 10, 20, 50, 200])
        
        # EMA
        ema_config = indicators_config.get('ema', {})
        self.ema_periods = ema_config.get('periods', [12, 26, 50])
        
        # Bollinger Bands
        bb_config = indicators_config.get('bollinger', {})
        self.bb_period = bb_config.get('period', 20)
        self.bb_std = bb_config.get('std_dev', 2)
        
        # ATR
        atr_config = indicators_config.get('atr', {})
        self.atr_period = atr_config.get('period', 14)
        
        # Stochastic
        stoch_config = indicators_config.get('stochastic', {})
        self.stoch_k = stoch_config.get('k_period', 14)
        self.stoch_d = stoch_config.get('d_period', 3)
        self.stoch_smooth = stoch_config.get('smooth', 3)
    
    @Slot(str)
    def calculate_single(self, task_data_json: str):
        """
        Calcula indicadores para um único símbolo
        
        Args:
            task_id: ID da tarefa
            symbol: Símbolo (ex: 'BTCUSDT')
            interval: Intervalo (ex: '1h')
            klines: Lista de candles OHLCV
        """
        logger = self.logger
        
        try:
            # ============================================================
            # DESERIALIZAR DADOS
            # ============================================================
            try:
                task_data = json.loads(task_data_json)
            except json.JSONDecodeError as e:
                logger.error(f"Erro ao desserializar task_data: {e}")
                self.error_occurred.emit(0, f"JSON decode error: {e}")
                return
            
            # Extrair campos
            task_id = task_data.get('task_id')
            symbol = task_data.get('symbol')
            interval = task_data.get('interval')
            klines = task_data.get('klines', [])
            
            if not all([task_id, symbol, interval, klines]):
                logger.error("Dados inválidos na task")
                self.error_occurred.emit(task_id or 0, "Invalid task data")
                return
            
            logger.debug(f"[Task {task_id}] Calculando {symbol}:{interval}")
            
            # Emitir início
            self.task_started.emit(task_id)
            
            start_time = time.time()
            
            # Calcular todos os indicadores
            indicators = self._compute_all_indicators(klines)
            
            duration_ms = (time.time() - start_time) * 1000
            
            # Preparar resultado
            result = {
                'symbol': symbol,
                'interval': interval,
                'indicators': indicators,
                'calculation_time_ms': duration_ms
            }
            
            # Emitir resultado
            self.result_ready.emit(task_id, result)
            self.task_completed.emit(task_id, duration_ms)
            
            logger.debug(f"[Task {task_id}] ✅ Completo ({duration_ms:.1f}ms)")
            
        except Exception as e:
            logger.error(f"Erro no calculate_single: {e}", exc_info=True)
            task_id = task_data.get('task_id', 0) if 'task_data' in locals() else 0
            self.error_occurred.emit(task_id, str(e))
    
    @Slot(str)
    def calculate_batch(self, batch_data_json: str):
        """
        Calcula indicadores para múltiplos símbolos
        
        Args:
            Args:
            batch_data_json: JSON string com formato:
                {
                    'task_id': 123,
                    'batch': [
                        {
                            'symbol': 'BTCUSDT',
                            'interval': '1h',
                            'klines': [...]
                        },
                        ...
                    ]
                }
        """
        logger = self.logger
        
        try:
            # ============================================================
            # DESERIALIZAR DADOS
            # ============================================================
            try:
                batch_data = json.loads(batch_data_json)
            except json.JSONDecodeError as e:
                logger.error(f"Erro ao desserializar batch_data: {e}")
                self.error_occurred.emit(0, f"JSON decode error: {e}")
                return
            
            task_id = batch_data.get('task_id')
            batch = batch_data.get('batch', [])
            
            if not task_id or not batch:
                logger.error("Dados inválidos no batch")
                self.error_occurred.emit(task_id or 0, "Invalid batch data")
                return
            
            total = len(batch)
            logger.info(f"[Task {task_id}] Processando batch ({total} símbolos)")
            
            # Emitir início
            self.task_started.emit(task_id)
            
            start_time = time.time()
            results = []
            
            for idx, item in enumerate(batch):
                try:
                    # Calcular indicadores
                    indicators = self._compute_all_indicators(item['klines'])
                    
                    results.append({
                        'symbol': item['symbol'],
                        'interval': item['interval'],
                        'indicators': indicators
                    })
                    
                    # Emitir progresso
                    self.progress.emit(task_id, idx + 1, total)
                    
                except Exception as e:
                    logger.error(f"Erro em {item['symbol']}: {e}")
                    results.append({
                        'symbol': item['symbol'],
                        'interval': item['interval'],
                        'error': str(e)
                    })
            
            duration_ms = (time.time() - start_time) * 1000
            
            # Preparar resultado do batch
            result = {
                'results': results,
                'total': total,
                'successful': len([r for r in results if 'indicators' in r]),
                'failed': len([r for r in results if 'error' in r]),
                'calculation_time_ms': duration_ms
            }
            
            # Emitir resultado
            self.result_ready.emit(task_id, result)
            self.task_completed.emit(task_id, duration_ms)
            
            logger.info(
                f"[Task {task_id}] ✅ Batch completo: "
                f"{result['successful']}/{total} OK ({duration_ms:.1f}ms)"
            )
            
        except Exception as e:
            logger.error(f"Erro no calculate_batch: {e}", exc_info=True)
            task_id = batch_data.get('task_id', 0) if 'batch_data' in locals() else 0
            self.error_occurred.emit(task_id, str(e))
    
    def _compute_all_indicators(self, klines: List) -> Dict[str, Any]:
        """
        Calcula TODOS os indicadores técnicos
        
        Args:
            klines: Lista de candles OHLCV
            
        Returns:
            Dict com todos os indicadores
        """
        try:
            # Extrair arrays numpy
            closes = np.array([k['close'] for k in klines], dtype=float)
            highs = np.array([k['high'] for k in klines], dtype=float)
            lows = np.array([k['low'] for k in klines], dtype=float)
            volumes = np.array([k['volume'] for k in klines], dtype=float)
            
            indicators = {}
            
            # RSI (múltiplos períodos)
            for period in self.rsi_periods:
                rsi = self._calculate_rsi(closes, period)
                if len(rsi) > 0:
                    indicators[f'rsi_{period}'] = rsi.tolist()  # Array completo
                    indicators[f'rsi_{period}_current'] = float(rsi[-1])  # Último valor
                else:
                    indicators[f'rsi_{period}'] = []
                    indicators[f'rsi_{period}_current'] = None

            # MACD
            macd_line, signal_line, histogram = self._calculate_macd(
                closes, 
                self.macd_fast, 
                self.macd_slow, 
                self.macd_signal
            )

            if len(macd_line) > 0:
                indicators['macd_line'] = macd_line.tolist()  # Array completo
                indicators['macd_signal'] = signal_line.tolist()  # Array completo
                indicators['macd_histogram'] = histogram.tolist()  # Array completo
                indicators['macd_line_current'] = float(macd_line[-1])  # Último valor
                indicators['macd_signal_current'] = float(signal_line[-1])
                indicators['macd_histogram_current'] = float(histogram[-1])
            else:
                indicators['macd_line'] = []
                indicators['macd_signal'] = []
                indicators['macd_histogram'] = []
                indicators['macd_line_current'] = None
                indicators['macd_signal_current'] = None
                indicators['macd_histogram_current'] = None
            
            # SMA (múltiplos períodos)
            for period in self.sma_periods:
                sma = self._calculate_sma(closes, period)
                indicators[f'sma_{period}'] = sma.tolist() if len(sma) > 0 else []
            
            # EMA (múltiplos períodos)
            for period in self.ema_periods:
                ema = self._calculate_ema(closes, period)
                indicators[f'ema_{period}'] = ema.tolist() if len(ema) > 0 else []
            
            # Bollinger Bands
            bb_upper, bb_middle, bb_lower = self._calculate_bollinger_bands(
                closes, 
                self.bb_period, 
                self.bb_std
            )
            indicators['bb_upper'] = bb_upper.tolist()
            indicators['bb_middle'] = bb_middle.tolist()
            indicators['bb_lower'] = bb_lower.tolist()
            
            # ATR
            atr = self._calculate_atr(highs, lows, closes, self.atr_period)
            if len(atr) > 0:
                indicators['atr'] = atr.tolist()  # Array completo
                indicators['atr_current'] = float(atr[-1])  # Último valor
            else:
                indicators['atr'] = []
                indicators['atr_current'] = None

            # Stochastic
            stoch_k, stoch_d = self._calculate_stochastic(
                highs, 
                lows, 
                closes,
                self.stoch_k,
                self.stoch_d,
                self.stoch_smooth
            )

            if len(stoch_k) > 0:
                indicators['stoch_k'] = stoch_k.tolist()  # Array completo
                indicators['stoch_d'] = stoch_d.tolist() if len(stoch_d) > 0 else []
                indicators['stoch_k_current'] = float(stoch_k[-1])  # Último valor
                indicators['stoch_d_current'] = float(stoch_d[-1]) if len(stoch_d) > 0 else None
            else:
                indicators['stoch_k'] = []
                indicators['stoch_d'] = []
                indicators['stoch_k_current'] = None
                indicators['stoch_d_current'] = None
            
            # VWAP
            vwap = self._calculate_vwap(highs, lows, closes, volumes)
            indicators['vwap'] = vwap.tolist()
            
            return indicators
            
        except Exception as e:
            self.logger.error(f"Erro ao calcular indicadores: {e}", exc_info=True)
            return {}
    
    # ========================================================================
    # CÁLCULOS DE INDICADORES
    # ========================================================================
    
    def _calculate_rsi(self, closes: np.ndarray, period: int = 14) -> np.ndarray:
        """Calcula RSI"""
        deltas = np.diff(closes)
        gains = np.where(deltas > 0, deltas, 0)
        losses = np.where(deltas < 0, -deltas, 0)
        
        avg_gain = np.convolve(gains, np.ones(period)/period, mode='valid')
        avg_loss = np.convolve(losses, np.ones(period)/period, mode='valid')
        
        rs = avg_gain / (avg_loss + 1e-10)
        rsi = 100 - (100 / (1 + rs))
        
        return rsi
    
    def _calculate_macd(
        self, 
        closes: np.ndarray, 
        fast: int = 12, 
        slow: int = 26, 
        signal: int = 9
    ) -> tuple:
        """Calcula MACD"""
        ema_fast = self._calculate_ema(closes, fast)
        ema_slow = self._calculate_ema(closes, slow)
        
        macd_line = ema_fast - ema_slow
        signal_line = self._calculate_ema(macd_line, signal)
        histogram = macd_line - signal_line
        
        return macd_line, signal_line, histogram
    
    def _calculate_sma(self, closes: np.ndarray, period: int) -> np.ndarray:
        """Calcula SMA"""
        return np.convolve(closes, np.ones(period)/period, mode='valid')
    
    def _calculate_ema(self, closes: np.ndarray, period: int) -> np.ndarray:
        """Calcula EMA"""
        alpha = 2 / (period + 1)
        ema = np.zeros(len(closes))
        ema[0] = closes[0]
        
        for i in range(1, len(closes)):
            ema[i] = alpha * closes[i] + (1 - alpha) * ema[i-1]
        
        return ema
    
    def _calculate_bollinger_bands(
        self, 
        closes: np.ndarray, 
        period: int = 20, 
        std_dev: float = 2
    ) -> tuple:
        """Calcula Bollinger Bands"""
        sma = self._calculate_sma(closes, period)
        
        # Ajustar closes para ter o mesmo tamanho do SMA
        closes_trimmed = closes[period-1:]
        
        # Calcular desvio padrão móvel
        std = np.array([
            closes_trimmed[max(0, i-period+1):i+1].std() 
            for i in range(len(closes_trimmed))
        ])
        
        upper = sma + (std_dev * std)
        lower = sma - (std_dev * std)
        
        return upper, sma, lower
    
    def _calculate_atr(
        self, 
        highs: np.ndarray, 
        lows: np.ndarray, 
        closes: np.ndarray, 
        period: int = 14
    ) -> np.ndarray:
        """Calcula ATR (Average True Range)"""
        tr1 = highs - lows
        tr2 = np.abs(highs - np.roll(closes, 1))
        tr3 = np.abs(lows - np.roll(closes, 1))
        
        tr = np.maximum(tr1, np.maximum(tr2, tr3))
        tr[0] = tr1[0]  # Primeiro valor não tem previous close
        
        atr = np.convolve(tr, np.ones(period)/period, mode='valid')
        
        return atr
    
    def _calculate_stochastic(
        self,
        highs: np.ndarray,
        lows: np.ndarray,
        closes: np.ndarray,
        k_period: int = 14,
        d_period: int = 3,
        smooth: int = 3
    ) -> tuple:
        """Calcula Stochastic Oscillator"""
        stoch_k = []
        
        for i in range(k_period - 1, len(closes)):
            high_max = highs[i - k_period + 1:i + 1].max()
            low_min = lows[i - k_period + 1:i + 1].min()
            
            if high_max - low_min != 0:
                k = 100 * (closes[i] - low_min) / (high_max - low_min)
            else:
                k = 50
            
            stoch_k.append(k)
        
        stoch_k = np.array(stoch_k)
        
        # Smooth K
        if smooth > 1:
            stoch_k = np.convolve(stoch_k, np.ones(smooth)/smooth, mode='valid')
        
        # Calculate D (SMA of K)
        stoch_d = np.convolve(stoch_k, np.ones(d_period)/d_period, mode='valid')
        
        return stoch_k, stoch_d
    
    def _calculate_vwap(
        self,
        highs: np.ndarray,
        lows: np.ndarray,
        closes: np.ndarray,
        volumes: np.ndarray
    ) -> np.ndarray:
        """Calcula VWAP (Volume Weighted Average Price)"""
        typical_price = (highs + lows + closes) / 3
        vwap = np.cumsum(typical_price * volumes) / np.cumsum(volumes)
        
        return vwap
    
    @Slot()
    def stop(self):
        """Para o worker"""
        self.is_running = False
        self.logger.info(f"Worker #{self.worker_id} parando")

# ============================================================================
# TECHNICALINDICATORS - ORQUESTRADOR PRINCIPAL
# ============================================================================

class TechnicalIndicators(QObject):
    """
    TechnicalIndicators - Orquestrador de Cálculo de Indicadores
    
    ARQUITETURA REVOLUCIONÁRIA:
        - Orquestrador (este objeto) roda na main thread
        - Pool de workers (IndicatorsWorker) rodam em QThreads separados
        - Nunca bloqueia a UI
        - Processa single ou batch
        - 3-5x mais rápido que versão anterior
    
    INTERFACE PÚBLICA:
        ensure_indicators(symbols, interval, ...) - Aceita str ou List[str]
    
    SINAIS:
        indicators_calculated: Emitido quando single completa
        batch_completed: Emitido quando batch completa
        batch_progress: Emitido durante batch processing
        calculation_failed: Emitido em caso de erro
    
    FLUXO:
        1. Verificar cache
        2. Separar cached/uncached
        3. Criar tasks para uncached
        4. Despachar para workers
        5. Aguardar resultados
        6. Escrever no cache
        7. Emitir sinais
    """
    
    # Sinais
    indicators_calculated = Signal(str, str, dict)  # symbol, interval, indicators
    batch_completed = Signal(int, float)            # count, duration
    batch_progress = Signal(int, int)               # current, total
    calculation_failed = Signal(str, str, str)      # symbol, interval, error
    
    def __init__(
        self,
        cache_system,
        config_manager,
        binance_data=None
    ):
        """
        Inicializa TechnicalIndicators
        
        Args:
            cache_system: CacheSystem para ler/escrever
            config_manager: ConfigManager para configurações
            binance_data: BinanceData para conectar sinais (opcional)
        """
        super().__init__()
        
        # Logger
        self.logger = logging.getLogger('TechnicalIndicators')
        self.logger.info("=" * 80)
        self.logger.info("🚀 INICIALIZANDO TECHNICALINDICATORS REVOLUCIONÁRIO")
        self.logger.info("=" * 80)
        
        # Dependências
        self.cache = cache_system
        self.config = config_manager
        self.binance_data = binance_data
        
        # Thread safety
        self.mutex = QMutex()
        
        # Sistema de tarefas
        self.task_counter = 0
        self.task_queue: Deque[CalculationTask] = deque()
        self.active_tasks: Dict[int, CalculationTask] = {}
        self.task_mutex = QMutex()
        
        # Pool de workers
        self.workers: List[IndicatorsWorker] = []
        self.worker_threads: List[QThread] = []
        self.available_workers: List[int] = []  # IDs de workers livres
        self.worker_mutex = QMutex()
        
        # Configurações
        self._load_config()
        
        # Métricas
        self.stats = {
            'total_calculations': 0,
            'successful_calculations': 0,
            'failed_calculations': 0,
            'cache_hits': 0,
            'cache_misses': 0,
            'total_symbols_processed': 0,
            'avg_calculation_time_ms': 0.0,
            'worker_utilization': 0.0
        }
        
        # Inicializar pool de workers
        self._init_worker_pool()
        
        # Conectar ao BinanceData
        self._connect_to_binance()
        
        # Timer para processar fila
        self.queue_timer = QTimer()
        self.queue_timer.timeout.connect(self._process_queue)
        self.queue_timer.start(100)  # Verifica fila a cada 100ms
        
        self.logger.info("✅ TechnicalIndicators inicializado")
        self.logger.info(f"   - Workers: {len(self.workers)}")
        self.logger.info(f"   - Intervalos padrão: {self.default_intervals}")
        self.logger.info(f"   - Mínimo de candles: {self.min_candles}")
        self.logger.info("=" * 80)
    
    def _load_config(self):
        """Carrega configurações"""
        indicators_config = self.config.get('indicators', {})
        
        self.default_intervals = indicators_config.get('default_intervals', '1h')
        self.cache_ttl = indicators_config.get('cache_ttl', 600)
        self.min_candles = indicators_config.get('min_candles', 1000)
        self.max_batch_size = indicators_config.get('max_batch_size', 10)
    
    def _init_worker_pool(self):
        """
        Inicializa pool de workers baseado em CPU cores
        
        Cria N-1 workers onde N = número de cores (deixa 1 para UI)
        """
        logger = self.logger
        
        try:
            # Determinar número de workers
            cpu_count = QThread.idealThreadCount()
            worker_count = max(1, cpu_count - 1)
            
            logger.info(f"Inicializando pool com {worker_count} workers (CPU cores: {cpu_count})")
            
            for i in range(worker_count):
                # Criar thread
                thread = QThread()
                thread.setObjectName(f"IndicatorsWorkerThread_{i}")
                
                # Criar worker
                worker = IndicatorsWorker(
                    worker_id=i,
                    config=self.config._config  # Passar config dict
                )
                
                # Mover worker para thread
                worker.moveToThread(thread)
                
                # Conectar sinais
                worker.result_ready.connect(self._on_worker_result)
                worker.error_occurred.connect(self._on_worker_error)
                worker.progress.connect(self._on_worker_progress)
                worker.task_completed.connect(self._on_worker_task_completed)
                
                # Conectar stop
                thread.finished.connect(worker.stop)
                
                # Armazenar
                self.workers.append(worker)
                self.worker_threads.append(thread)
                self.available_workers.append(i)
                
                # Iniciar thread
                thread.start()
                
                logger.debug(f"✅ Worker #{i} criado e iniciado")
            
            logger.info(f"✅ Pool de {worker_count} workers inicializado")
            
        except Exception as e:
            logger.error(f"Erro ao inicializar pool: {e}", exc_info=True)
    
    def _connect_to_binance(self):
        """Conecta aos sinais do BinanceData"""
        try:
            #self.binance_data.top_n.connect(self._on_top_n_updated)
            self.logger.info("✅ Conectado ao BinanceData.top_n")
            
        except Exception as e:
            self.logger.error(f"Erro ao conectar ao BinanceData: {e}")
    
    # ========================================================================
    # INTERFACE PÚBLICA - ensure_indicators()
    # ========================================================================
    
    def ensure_indicators(
        self,
        symbols: Union[str, List[str]],  # ← ACEITA AMBOS!
        interval: str,
        consumer_id: str = 'unknown',
        force_recalculate: bool = False,
        priority: int = 2
    ) -> Optional[Union[Dict, List[Dict]]]:
        """
        Garante que indicadores estejam disponíveis (OTIMIZADO PARA BATCH)

        FLUXO (com dados históricos robustos):
            1. Verifica cache de indicadores
            2. Para indicadores não em cache:
               - Obtém klines via get_klines() (memória L1 + disco SQLite)
               - Backfill automático se dados não encontrados
            3. Cria tasks de cálculo para símbolos com klines suficientes
            4. Retorna resultados disponíveis ou None (aguardar)

        GARANTIAS:
            ✅ Acessa dados históricos em disco (não apenas memória)
            ✅ Solicita backfill automaticamente quando necessário
            ✅ Cache L1 otimizado (hot cache para acessos repetidos)
            ✅ Processamento em batch para múltiplos símbolos

        Args:
            symbols: Símbolo único (str) ou lista (List[str])
            interval: Intervalo temporal
            consumer_id: ID do consumidor (para logs)
            force_recalculate: Se True, ignora cache de indicadores
            priority: 1=alta, 2=média, 3=baixa

        Returns:
            - Dict se recebeu str (indicadores calculados)
            - List[Dict] se recebeu List[str] (lista de indicadores)
            - None se precisa aguardar cálculo/backfill
        """
        logger = self.logger
        
        try:
            # ================================================================
            # FASE 1: NORMALIZAR ENTRADA
            # ================================================================
            is_single = isinstance(symbols, str)
            symbols_list = [symbols] if is_single else symbols
            
            logger.info("=" * 80)
            logger.info("📊 ENSURE INDICATORS")
            logger.info(f"   Modo: {'SINGLE' if is_single else 'BATCH'}")
            logger.info(f"   Símbolos: {len(symbols_list)}")
            logger.info(f"   Interval: {interval}")
            logger.info("=" * 80)
            
            # ================================================================
            # FASE 2: VERIFICAR CACHE EM BATCH
            # ================================================================
            if not force_recalculate:
                cache_keys = [f'indicators:{s}:{interval}' for s in symbols_list]
                cached_results_dict = self.cache.get(cache_keys, reader='TECHNICAL_INDICATORS')
                
                # Separar cached/uncached
                cached_indicators = {}
                uncached_symbols = []
                
                for symbol, key in zip(symbols_list, cache_keys):
                    cached = cached_results_dict.get(key) if isinstance(cached_results_dict, dict) else None
                    
                    if cached:
                        cached_indicators[symbol] = cached
                        logger.debug(f"  ✅ Cache HIT: {symbol}")
                        self.stats['cache_hits'] += 1
                    else:
                        uncached_symbols.append(symbol)
                        logger.debug(f"  ❌ Cache MISS: {symbol}")
                        self.stats['cache_misses'] += 1
            else:
                cached_indicators = {}
                uncached_symbols = symbols_list
            
            # ================================================================
            # FASE 3: SE TODOS EM CACHE, RETORNAR IMEDIATAMENTE
            # ================================================================
            if not uncached_symbols:
                logger.info(f"  ✅ Todos em cache ({len(cached_indicators)} símbolos)")
                
                if is_single:
                    return cached_indicators[symbols]
                else:
                    return [cached_indicators[s] for s in symbols_list]
            
            # ================================================================
            # FASE 4: OBTER KLINES VIA get_klines() (MEMÓRIA + DISCO)
            # ================================================================
            logger.info(f"  📝 Obtendo klines para {len(uncached_symbols)} símbolos")

            symbols_with_klines = {}

            for symbol in uncached_symbols:
                
                klines = self.cache.get_klines(
                    symbol=symbol,
                    interval=interval,
                    limit=self.min_candles,
                    reader="TechnicalIndicators"
                )

                if klines and len(klines) >= self.min_candles:
                    symbols_with_klines[symbol] = klines
                    logger.debug(f"  ✅ Klines obtidos: {symbol} ({len(klines)} candles)")

            # ================================================================
            # FASE 5: CRIAR TASK PARA SÍMBOLOS COM KLINES
            # ================================================================
            if symbols_with_klines:
                task_type = 'single' if len(symbols_with_klines) == 1 else 'batch'

                task = CalculationTask(
                    task_id=self._get_next_task_id(),
                    task_type=task_type,
                    symbols=list(symbols_with_klines.keys()),
                    interval=interval,
                    priority=priority,
                    requester_id=consumer_id,
                    klines_data=symbols_with_klines
                )

                self._add_task_to_queue(task)
                logger.info(f"  ✅ Task {task.task_id} criada ({len(symbols_with_klines)} símbolos)")
            
            # ================================================================
            # FASE 6: RETORNAR RESULTADOS IMEDIATOS SE HOUVER
            # ================================================================
            if cached_indicators:
                logger.info(f"  ✅ Retornando {len(cached_indicators)} em cache")
                
                if is_single and symbols in cached_indicators:
                    return cached_indicators[symbols]
                elif not is_single:
                    # Retornar lista na ordem original
                    return [cached_indicators.get(s) for s in symbols_list if s in cached_indicators]
            
            logger.info("  ⏳ Aguardando cálculos/dados")
            return None
            
        except Exception as e:
            logger.error(f"Erro em ensure_indicators: {e}", exc_info=True)
            return None
    
    # ========================================================================
    # GERENCIAMENTO DE TAREFAS
    # ========================================================================
    
    def _get_next_task_id(self) -> int:
        """Gera próximo ID de tarefa"""
        with QMutexLocker(self.task_mutex):
            self.task_counter += 1
            return self.task_counter
    
    def _add_task_to_queue(self, task: CalculationTask):
        """Adiciona tarefa à fila"""
        with QMutexLocker(self.task_mutex):
            self.task_queue.append(task)
            self.logger.debug(f"Task {task.task_id} adicionada à fila (tamanho: {len(self.task_queue)})")
    
    @Slot()
    def _process_queue(self):
        """
        Processa fila de tarefas
        
        Chamado periodicamente pelo timer.
        Despacha tarefas para workers disponíveis.
        """
        try:
            with QMutexLocker(self.task_mutex):
                # Verificar se há tarefas e workers disponíveis
                if not self.task_queue or not self.available_workers:
                    return
                
                # Ordenar fila por prioridade
                self.task_queue = deque(
                    sorted(self.task_queue, key=lambda t: (t.priority, t.timestamp))
                )
                
                # Processar tarefas
                while self.task_queue and self.available_workers:
                    task = self.task_queue.popleft()
                    worker_id = self.available_workers.pop(0)
                    
                    # Despachar para worker
                    self._dispatch_to_worker(task, worker_id)
        
        except Exception as e:
            self.logger.error(f"Erro ao processar fila: {e}", exc_info=True)
    
    def _dispatch_to_worker(self, task: CalculationTask, worker_id: int):
        """
        Despacha tarefa para worker específico
        
        Args:
            task: Tarefa a processar
            worker_id: ID do worker
        """
        logger = self.logger
        
        try:
            logger.info(f"📤 Despachando Task {task.task_id} para Worker #{worker_id}")
            
            task.status = TaskStatus.PROCESSING
            task.worker_id = worker_id
            self.active_tasks[task.task_id] = task
            
            worker = self.workers[worker_id]
            
            if task.task_type == 'single':
                # PROCESSAR SINGLE - SERIALIZAR COMO JSON
                symbol = task.symbols[0]
                klines = task.klines_data[symbol]
                
                # Criar payload JSON
                task_data = {
                    'task_id': task.task_id,
                    'symbol': symbol,
                    'interval': task.interval,
                    'klines': klines
                }
                
                task_data_json = json.dumps(task_data)
                
                # Invocar com string JSON
                QMetaObject.invokeMethod(
                    worker,
                    'calculate_single',
                    Qt.QueuedConnection,
                    Q_ARG(str, task_data_json)  # ← STRING, não list!
                )
            
            else:
                # Processar batch
                batch = [
                    {
                        'symbol': symbol,
                        'interval': task.interval,
                        'klines': task.klines_data[symbol]
                    }
                    for symbol in task.symbols
                ]
                
                # Criar payload JSON
                batch_data = {
                    'task_id': task.task_id,
                    'batch': batch
                }
                
                batch_data_json = json.dumps(batch_data)
                
                # Invocar com string JSON
                QMetaObject.invokeMethod(
                    worker,
                    'calculate_batch',
                    Qt.QueuedConnection,
                    Q_ARG(str, batch_data_json)  # ← STRING, não list!
                )
            
            logger.debug(f"✅ Task {task.task_id} despachada")
            
        except Exception as e:
            logger.error(f"Erro ao despachar task: {e}", exc_info=True)
            self._return_worker(worker_id)
    
    def _return_worker(self, worker_id: int):
        """Retorna worker para pool disponível"""
        with QMutexLocker(self.worker_mutex):
            if worker_id not in self.available_workers:
                self.available_workers.append(worker_id)
    
    # ========================================================================
    # HANDLERS DE WORKERS
    # ========================================================================
    
    @Slot(int, dict)
    def _on_worker_result(self, task_id: int, result: dict):
        """
        Handler: Worker completou cálculo com sucesso
        
        Args:
            task_id: ID da tarefa
            result: Resultado do cálculo
        """
        logger = self.logger
        
        try:
            # Recuperar tarefa
            task = self.active_tasks.get(task_id)
            
            if not task:
                logger.warning(f"Task {task_id} não encontrada em active_tasks")
                return
            
            logger.info(f"✅ Resultado recebido: Task {task_id}")
            
            # Processar resultado baseado no tipo
            if task.task_type == 'single':
                self._process_single_result(task, result)
            else:
                self._process_batch_result(task, result)
            
            # Limpar tarefa
            task.status = TaskStatus.COMPLETED
            del self.active_tasks[task_id]
            
            # Retornar worker ao pool
            if task.worker_id is not None:
                self._return_worker(task.worker_id)
            
            # Atualizar estatísticas
            self.stats['successful_calculations'] += 1
            self.stats['total_calculations'] += 1
            
        except Exception as e:
            logger.error(f"Erro ao processar resultado: {e}", exc_info=True)
    
    def _process_single_result(self, task: CalculationTask, result: dict):
        """Processa resultado de cálculo single"""
        symbol = result['symbol']
        interval = result['interval']
        indicators = result['indicators']
        
        # Escrever no cache
        cache_key = f'indicators:{symbol}:{interval}'
        self.cache.set(
            cache_key,
            indicators,
            writer='TECHNICAL_INDICATORS',
            ttl=self.cache_ttl
        )
        
        self.logger.debug(f"✅ Indicadores escritos no cache: {cache_key}")
        
        # Emitir sinal
        self.indicators_calculated.emit(symbol, interval, indicators)
        
        self.stats['total_symbols_processed'] += 1
    
    def _process_batch_result(self, task: CalculationTask, result: dict):
        """Processa resultado de cálculo batch"""
        logger = self.logger
        
        results = result['results']
        successful = result['successful']
        duration = result['calculation_time_ms']
        
        logger.info(f"📊 Batch completo: {successful}/{result['total']} OK ({duration:.1f}ms)")
        
        # Escrever todos os resultados no cache
        for item in results:
            if 'indicators' in item:
                cache_key = f"indicators:{item['symbol']}:{item['interval']}"
                self.cache.set(
                    cache_key,
                    item['indicators'],
                    writer='TECHNICAL_INDICATORS',
                    ttl=self.cache_ttl
                )
                
                # Emitir sinal individual
                self.indicators_calculated.emit(
                    item['symbol'],
                    item['interval'],
                    item['indicators']
                )
        
        # Emitir sinal de batch completo
        self.batch_completed.emit(successful, duration / 1000)
        
        self.stats['total_symbols_processed'] += successful
    
    @Slot(int, str)
    def _on_worker_error(self, task_id: int, error_message: str):
        """Handler: Worker encontrou erro"""
        logger = self.logger
        
        try:
            task = self.active_tasks.get(task_id)
            
            if task:
                logger.error(f"❌ Erro na Task {task_id}: {error_message}")
                
                task.status = TaskStatus.FAILED
                task.error = error_message
                
                # Emitir sinal de falha para cada símbolo
                for symbol in task.symbols:
                    self.calculation_failed.emit(symbol, task.interval, error_message)
                
                # Retornar worker
                if task.worker_id is not None:
                    self._return_worker(task.worker_id)
                
                # Limpar
                del self.active_tasks[task_id]
                
                self.stats['failed_calculations'] += 1
                self.stats['total_calculations'] += 1
        
        except Exception as e:
            logger.error(f"Erro ao processar erro do worker: {e}", exc_info=True)
    
    @Slot(int, int, int)
    def _on_worker_progress(self, task_id: int, current: int, total: int):
        """Handler: Worker emitiu progresso"""
        self.batch_progress.emit(current, total)
    
    @Slot(int, float)
    def _on_worker_task_completed(self, task_id: int, duration_ms: float):
        """Handler: Worker completou tarefa"""
        # Atualizar tempo médio de cálculo
        n = self.stats['total_calculations']
        if n > 0:
            old_avg = self.stats['avg_calculation_time_ms']
            self.stats['avg_calculation_time_ms'] = ((old_avg * (n - 1)) + duration_ms) / n
    
    # ========================================================================
    # HANDLERS DO BINANCEDATA
    # ========================================================================
    
    @Slot(str, dict)
    def _on_top_n_updated(self, cache_key: str, top_n_data: dict):
        """
        Handler: Top-N foi atualizado
        
        Processa todos os símbolos Top-N usando ensure_indicators() com lista
        """
        logger = self.logger
        
        try:
            logger.info("=" * 80)
            logger.info("🎯 TOP-N ATUALIZADO - PROCESSANDO BATCH")
            logger.info("=" * 80)
            
            symbols = top_n_data.get('symbols', [])

            interval = self.default_intervals
            
            if not symbols:
                logger.warning("Top-N vazio")
                return
            
            logger.info(f"Processando {len(symbols)} símbolos Top-N")
            
            # USAR ensure_indicators com LISTA (batch processing!)
            self.ensure_indicators(
                symbols=symbols,  # ← LISTA!
                interval=interval,
                consumer_id='TopN',
                priority=3  # Baixa prioridade (background)
            )
            
            logger.info("✅ Tarefas criadas para Top-N")
            
        except Exception as e:
            logger.error(f"Erro em _on_top_n_updated: {e}", exc_info=True)
    
    # ========================================================================
    # CLEANUP
    # ========================================================================
    
    def stop(self):
        """Para todos os workers e threads"""
        logger = self.logger
        
        try:
            logger.info("Parando TechnicalIndicators...")
            
            # Parar timer
            if hasattr(self, 'queue_timer'):
                self.queue_timer.stop()
            
            # Parar todas as threads
            for i, thread in enumerate(self.worker_threads):
                logger.debug(f"Parando Worker #{i}...")
                thread.quit()
                thread.wait(3000)
            
            logger.info("✅ TechnicalIndicators parado")
            
        except Exception as e:
            logger.error(f"Erro ao parar: {e}", exc_info=True)
    
    def get_stats(self) -> Dict[str, Any]:
        """Retorna estatísticas"""
        with QMutexLocker(self.mutex):
            # Calcular utilização de workers
            total_workers = len(self.workers)
            busy_workers = total_workers - len(self.available_workers)
            utilization = (busy_workers / total_workers * 100) if total_workers > 0 else 0
            
            self.stats['worker_utilization'] = utilization
            
            return self.stats.copy()
    
# ============================================================================
# FEATURE ENGINEERING - TRANSFORMAÇÃO DE DADOS PARA ML
# ============================================================================

class FeatureEngineering:
    """
    FeatureEngineering - Sistema de Engenharia de Features

    FILOSOFIA:
    Sistema completo com 8 CATEGORIAS de features para capturar diferentes aspectos
    do mercado: price action, volume, technical indicators, time patterns, lags,
    rolling statistics, volatility, e microstructure.

    CARACTERÍSTICAS:
        - 8 categorias de features (~100-130 features total)
        - Cache inteligente (feature store com TTL 5min)
        - Integração com TechnicalIndicators
        - Validação e limpeza robusta
        - Thread-safe (pode ser chamado de múltiplas threads)

    CATEGORIAS DE FEATURES:
        1. Price Features: Returns, log returns, momentum, price ratios
        2. Volume Features: Volume changes, VWAP, volume ratios
        3. Technical Features: RSI, MACD, Bollinger Bands, SMAs, EMAs
        4. Time Features: Hour sin/cos, day of week, is weekend
        5. Lag Features: Lags de 1, 2, 3, 6, 12, 24 períodos
        6. Rolling Features: SMA, STD, min, max em múltiplas janelas
        7. Volatility Features: ATR, historical volatility, Parkinson
        8. Microstructure Features: Spread proxies, tick analysis

    CACHE:
        - Feature store local (dict com TTL 5min)
        - Evita recálculo desnecessário
        - Thread-safe com QMutex

    INTEGRAÇÃO:
        - TechnicalIndicators: calcula indicadores técnicos
        - CacheSystem: busca OHLCV

    MÉTODOS PRINCIPAIS:
        - calculate_features(symbol, interval): Calcula features para símbolo atual
        - calculate_features_for_klines(klines_df): Calcula features de DataFrame
    
    NÃO TEM THREAD PRÓPRIA - é um helper class chamado pelos workers.
    Porém é thread-safe com mutex próprio.
    
    FEATURES GERADAS: ~100-130 features
    CATEGORIAS: 8 categorias completas
    """
    
    def __init__(self, cache_system, technical_indicators=None):
        """
        Inicializa FeatureEngineering
        
        Args:
            cache_system: Instância do CacheSystem
            technical_indicators: Instância do TechnicalIndicators (opcional)
        """
        # Logger
        self.logger = logging.getLogger('FeatureEngineering')
        self.logger.info("🔧 FeatureEngineering inicializado (8 categorias)")
        
        # Dependências
        self.cache = cache_system
        self.tech_indicators = technical_indicators
        
        # Thread safety
        self.mutex = QMutex()
        
        # Feature store cache (local)
        self.feature_cache: Dict[tuple, tuple] = {}  # (symbol, interval) -> (timestamp, features)
        self.feature_cache_ttl = 300  # 5 minutos
        
        # Configuração de features
        self.feature_config = {
            # Lags
            'lag_periods': [1, 2, 3, 6, 12, 24],
            
            # Rolling windows
            'rolling_windows': [7, 14, 24, 48],
            
            # RSI periods
            'rsi_periods': [7, 14, 21],
            
            # SMA periods
            'sma_periods': [5, 10, 20, 50, 200],
            
            # EMA periods
            'ema_periods': [12, 26, 50],
            
            # MACD
            'macd_fast': 12,
            'macd_slow': 26,
            'macd_signal': 9,
            
            # Bollinger Bands
            'bb_period': 20,
            'bb_std': 2,
            
            # ATR
            'atr_period': 14,
        }
        
        self.logger.info("📊 Configuração de features:")
        self.logger.info(f"   - Lag periods: {self.feature_config['lag_periods']}")
        self.logger.info(f"   - Rolling windows: {self.feature_config['rolling_windows']}")
        self.logger.info(f"   - RSI periods: {self.feature_config['rsi_periods']}")
        self.logger.info(f"   - SMA periods: {self.feature_config['sma_periods']}")
        self.logger.info(f"   - EMA periods: {self.feature_config['ema_periods']}")

    # ============================================================================
    # FEATURE PARA ML
    # ============================================================================

    def calculate_features_for_ml(
        self,
        klines: List[Dict[str, Any]],
        symbol: str,
        interval: str = '1h'
    ) -> Optional[pd.DataFrame]:
        """
        Calcula features técnicas para lista de klines
        Retorna DataFrame(n_candles, 92) diretamente
        
        FEATURES CALCULADAS (92 total):
        - Price features (11): returns, log_returns, spreads, momentum
        - Volume features (6): volume ratios, turnover, vwap
        - Technical indicators (27): RSI, MACD, Bollinger, Stochastic, etc
        - Time features (5): hour, day_of_week, is_weekend, etc
        - Lag features (18): preços e volumes passados (1-10 períodos)
        - Rolling features (16): médias móveis, desvios, min/max
        - Volatility features (5): ATR, volatilidade realizada
        - Microstructure features (4): spread, ticks, imbalance
        
        PROCESSAMENTO:
        1. Converte klines → DataFrame OHLCV
        2. Calcula cada grupo de features (vetorizado)
        3. Concatena todas as features
        4. Drop de NaNs gerados por lags/rolling
        5. Valida resultado final
        
        Args:
            klines: Lista de dicts com estrutura:
                {
                    'open_time': int,
                    'open': float,
                    'high': float,
                    'low': float,
                    'close': float,
                    'volume': float,
                    'close_time': int,
                    ...
                }
            symbol: Símbolo para logging (opcional)
        
        Returns:
            DataFrame com shape (n_candles_validos, 92) ou None se erro
            Colunas: feature names
            Index: timestamps dos candles
        
        Raises:
            ValueError: Se klines insuficientes ou formato inválido
        """
        logger = self.logger
        
        try:
            # ================================================================
            # VALIDAÇÃO INICIAL
            # ================================================================

            # checar None / tipo / tamanho explicitamente
            if klines is None:
                raise ValueError("Klines inválidos: None recebido")
            # garantir que é DataFrame ou lista compatível
            if not isinstance(klines, (pd.DataFrame, list)):
                raise ValueError(f"Klines com tipo inválido: {type(klines)}")
            
            n_input_candles = len(klines)

            # ================================================================
            # FASE 1: CONVERTER KLINES → DATAFRAME OHLCV
            # ================================================================
            df = self._klines_to_dataframe(klines)

            # Validação de quantidade mínima
            # MÍNIMO: 500 (margem confortável)
            # IDEAL: 1000 (máxima qualidade)
            MINIMUM_KLINES = 500
            IDEAL_KLINES = 1000

            if df is None or len(df) < MINIMUM_KLINES:
                raise ValueError(
                    f"Klines insuficientes: {len(df) if df is not None else 0} < {MINIMUM_KLINES}. "
                    f"Necessário mínimo {MINIMUM_KLINES} (ideal: {IDEAL_KLINES}) para calcular "
                    f"todas as features (SMA_100 + warm-up period)."
                )

            # Warning se abaixo do ideal
            if len(df) < IDEAL_KLINES:
                logger.warning(
                    f"⚠️ Klines abaixo do ideal: {len(df)} < {IDEAL_KLINES}. "
                    f"Features podem ter qualidade reduzida. Recomendado: {IDEAL_KLINES}+ klines."
                )
            
            # ================================================================
            # CALCULAR FEATURES POR GRUPO (VETORIZADO)
            # ================================================================
            feature_dfs = []
            feature_counts = {}

            self.logger.info(f"🚀 Iniciando Cálculo de Features para: {symbol}")
            
            # Grupo 1: Price Features (11 features)
            price_df = self._calculate_price_features_vectorized(df)
            if price_df is not None and not price_df.empty:
                feature_dfs.append(price_df)
                feature_counts['price'] = price_df.shape[1]
                self.logger.info(f"     💰 price_features: {len(price_df)}")
            
            # Grupo 2: Volume Features (6 features)
            volume_df = self._calculate_volume_features_vectorized(df)
            if volume_df is not None and not volume_df.empty:
                feature_dfs.append(volume_df)
                feature_counts['volume'] = volume_df.shape[1]
                self.logger.info(f"     📈 volume_features: {len(volume_df)}")
            
            # Grupo 3: Technical Indicators (27 features)
            technical_df = self._calculate_technical_features_vectorized(df)
            if technical_df is not None and not technical_df.empty:
                feature_dfs.append(technical_df)
                feature_counts['technical'] = technical_df.shape[1]
                self.logger.info(f"     📊 technical_features: {len(technical_df)}")
            
            # Grupo 4: Time Features (adaptativas por intervalo)
            time_df = self._calculate_time_features_vectorized(df, interval=interval)
            if time_df is not None and not time_df.empty:
                feature_dfs.append(time_df)
                feature_counts['time'] = time_df.shape[1]
                self.logger.info(f"     ⏰ time_features: {len(time_df)} ({interval})")
            
            # Grupo 5: Lag Features (18 features)
            lag_df = self._calculate_lag_features_vectorized(df)
            if lag_df is not None and not lag_df.empty:
                feature_dfs.append(lag_df)
                feature_counts['lag'] = lag_df.shape[1]
                self.logger.info(f"     ⏱ lag_features: {len(lag_df)}")
            
            # Grupo 6: Rolling Features (16 features)
            rolling_df = self._calculate_rolling_features_vectorized(df)
            if rolling_df is not None and not rolling_df.empty:
                feature_dfs.append(rolling_df)
                feature_counts['rolling'] = rolling_df.shape[1]
                self.logger.info(f"     🔄 rolling_features: {len(rolling_df)}")
            
            # Grupo 7: Volatility Features (5 features)
            volatility_df = self._calculate_volatility_features_vectorized(df)
            if volatility_df is not None and not volatility_df.empty:
                feature_dfs.append(volatility_df)
                feature_counts['volatility'] = volatility_df.shape[1]
                self.logger.info(f"     🔥 volatility_features: {len(volatility_df)}")
            
            # Grupo 8: Microstructure Features (4 features)
            micro_df = self._calculate_microstructure_features_vectorized(df)
            if micro_df is not None and not micro_df.empty:
                feature_dfs.append(micro_df)
                feature_counts['microstructure'] = micro_df.shape[1]
                self.logger.info(f"     🔍 microstructure_features: {len(micro_df)}")
            
            # ================================================================
            # CONCATENAR TODAS AS FEATURES
            # ================================================================
            if not feature_dfs:
                raise ValueError("Nenhuma feature calculada com sucesso")
            
            features_combined = pd.concat(feature_dfs, axis=1)
            
            # ================================================================
            # LIMPEZA DE DADOS COM WARM-UP PERIOD (ITEM 5 - FASE 4)
            # ================================================================
            # Estratégia: Warm-up period fixo baseado no maior indicador
            # SMA_200 = maior window, portanto warm-up = 200 períodos

            # Definir warm-up por intervalo (maior feature window)
            def get_warmup_period(interval: str) -> int:
                """Retorna warm-up period baseado no intervalo"""
                if interval == '1m':
                    return 100  # SMA máximo = 100 para 1m (evitar perda excessiva)
                elif interval in ['5m', '15m']:
                    return 150  # SMA máximo = 150
                else:  # 1h, 4h, 1d, 1w
                    return 200  # SMA máximo = 200

            warmup_period = get_warmup_period(interval)

            n_before_drop = len(features_combined)

            # Descartar primeiros N candles (warm-up period)
            features_warmup = features_combined.iloc[warmup_period:].copy()

            # Remover NaNs residuais (se houver)
            features_clean = features_warmup.dropna()

            n_after_drop = len(features_clean)
            n_dropped_warmup = warmup_period
            n_dropped_nans = len(features_warmup) - n_after_drop
            n_dropped = n_before_drop - n_after_drop

            logger.info(f"   🔧 Warm-up period aplicado: {warmup_period} candles ({interval})")
            logger.info(f"   📊 Perdas: {n_dropped_warmup} (warm-up) + {n_dropped_nans} (NaNs residuais) = {n_dropped} total")
            
            # ================================================================
            # VALIDAÇÃO FINAL
            # ================================================================
            if len(features_clean) < 200:
                raise ValueError(
                    f"Features válidas insuficientes após limpeza: "
                    f"{len(features_clean)} < 200 mínimos"
                )
            
            # ================================================================
            # LOG CONSOLIDADO (ÚNICO)
            # ================================================================
            total_features = features_clean.shape[1]
            retention_rate = (n_after_drop / n_input_candles) * 100
            
            logger.info("=" * 80)
            logger.info(f"✅ FEATURES CALCULADAS: {symbol}")
            logger.info(f"   Input: {n_input_candles} candles")
            logger.info(f"   Output: {n_after_drop} candles válidos ({retention_rate:.1f}% retenção)")
            logger.info(f"   Dropped: {n_dropped} candles (NaNs de lags/rolling)")
            logger.info(f"   Shape: {features_clean.shape} (rows, cols)")
            logger.info(f"   Total features: {total_features}")
            
            # Breakdown por grupo
            logger.info("   Breakdown:")
            for group, count in feature_counts.items():
                logger.info(f"      - {group}: {count} features")
            
            logger.info("=" * 80)
            
            return features_clean
        
        except ValueError as ve:
            logger.error(f"❌ Validação falhou para {symbol}: {ve}")
            return None
        
        except Exception as e:
            logger.error(
                f"❌ Erro ao calcular features para {symbol}: {e}",
                exc_info=True
            )
            return None

    # MÉTODOS AUXILIARES - CONVERSÃO E FEATURES VETORIZADAS

    def _klines_to_dataframe(self, klines: List[Dict]) -> Optional[pd.DataFrame]:
        """
        Converte lista de klines para DataFrame OHLCV
        
        Args:
            klines: Lista de dicts com estrutura Binance
        
        Returns:
            DataFrame com colunas [open, high, low, close, volume, timestamp]
            Index: DatetimeIndex baseado em open_time
        """
        try:
            # Extrair campos necessários
            data = {
                'timestamp': [k['open_time'] for k in klines],
                'open': [float(k['open']) for k in klines],
                'high': [float(k['high']) for k in klines],
                'low': [float(k['low']) for k in klines],
                'close': [float(k['close']) for k in klines],
                'volume': [float(k['volume']) for k in klines],
            }
            
            df = pd.DataFrame(data)
            
            # Converter timestamp para datetime
            df['datetime'] = pd.to_datetime(df['timestamp'], unit='ms')
            df.set_index('datetime', inplace=True)
            
            # Validar dados
            if df.isnull().any().any():
                self.logger.warning("⚠️ NaNs detectados nos dados OHLCV originais")
                df = df.dropna()
            
            return df
        
        except Exception as e:
            self.logger.error(f"❌ Erro ao converter klines: {e}")
            return None

    def _calculate_price_features_vectorized(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Calcula features de preço (VETORIZADO)
        
        Features (11):
        - returns: Retorno percentual (close/close.shift(1) - 1)
        - log_returns: Log do retorno
        - price_momentum: Momentum de 5 períodos
        - price_acceleration: Aceleração do preço
        - hl_spread: (high - low) / close
        - oc_spread: (open - close) / close
        - typical_price: (high + low + close) / 3
        - weighted_close: (high + low + 2*close) / 4
        - price_range: high - low
        - price_position: (close - low) / (high - low)
        - upper_shadow: (high - max(open, close)) / (high - low + 1e-10)
        """
        try:
            features = pd.DataFrame(index=df.index)
            
            # Returns
            features['return_1'] = df['close'].pct_change()
            features['log_return'] = np.log(df['close'] / df['close'].shift(1))
            
            # Momentum e aceleração
            features['momentum_5'] = df['close'].pct_change(5)
            features['acceleration'] = features['return_1'].diff()
            
            # Spreads
            features['hl_spread'] = (df['high'] - df['low']) / (df['close'] + 1e-10)
            features['oc_spread'] = (df['open'] - df['close']) / (df['close'] + 1e-10)
            
            # Preços derivados
            features['typical_price'] = (df['high'] + df['low'] + df['close']) / 3
            features['weighted_close'] = (df['high'] + df['low'] + 2 * df['close']) / 4
            
            # Range e posição
            features['price_range'] = df['high'] - df['low']
            features['price_position'] = (df['close'] - df['low']) / (df['high'] - df['low'] + 1e-10)
            
            # Shadows (análise de candlestick)
            features['upper_shadow'] = (
                (df['high'] - df[['open', 'close']].max(axis=1)) / 
                (df['high'] - df['low'] + 1e-10)
            )
            
            return features
        
        except Exception as e:
            self.logger.error(f"❌ Erro em price features: {e}")
            return pd.DataFrame()


    def _calculate_volume_features_vectorized(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Calcula features de volume (VETORIZADO)
        
        Features (6):
        - volume_change: Variação de volume
        - volume_ratio: Volume / Média móvel de 20 períodos
        - volume_momentum: Momentum de volume (5 períodos)
        - volume_volatility: Desvio padrão de 10 períodos
        - turnover: volume * close
        - vwap: Volume Weighted Average Price (aproximado)
        """
        try:
            features = pd.DataFrame(index=df.index)
            
            # Volume changes
            features['volume_change'] = df['volume'].pct_change()
            features['volume_ratio'] = df['volume'] / df['volume'].rolling(20).mean()
            features['volume_momentum'] = df['volume'].pct_change(5)
            features['volume_volatility'] = df['volume'].rolling(10).std()
            
            # Turnover
            features['turnover'] = df['volume'] * df['close']
            
            # VWAP aproximado (typical_price * volume)
            typical_price = (df['high'] + df['low'] + df['close']) / 3
            features['vwap'] = (typical_price * df['volume']).rolling(20).sum() / df['volume'].rolling(20).sum()
            
            return features
        
        except Exception as e:
            self.logger.error(f"❌ Erro em volume features: {e}")
            return pd.DataFrame()


    def _calculate_technical_features_vectorized(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Calcula indicadores técnicos (VETORIZADO)
        
        Features (27):
        - RSI (14): Relative Strength Index
        - MACD: Moving Average Convergence Divergence (3 valores: macd, signal, hist)
        - Bollinger Bands (3): upper, middle, lower
        - Stochastic (2): %K, %D
        - ATR (14): Average True Range
        - ADX (14): Average Directional Index
        - CCI (20): Commodity Channel Index
        - Williams %R (14)
        - SMAs: 7, 20, 50, 100 períodos (4 features)
        - EMAs: 12, 26 períodos (2 features)
        - SMA crossovers: sma7 > sma20, sma20 > sma50 (2 features)
        - Price vs SMA: close > sma20, close > sma50 (2 features)
        - Volume SMA ratio (1 feature)
        """
        try:
            features = pd.DataFrame(index=df.index)
            close = df['close']
            high = df['high']
            low = df['low']
            volume = df['volume']
            
            # RSI (14)
            delta = close.diff()
            gain = (delta.where(delta > 0, 0)).ewm(alpha=1/14, min_periods=14, adjust=False).mean()
            loss = (-delta.where(delta < 0, 0)).ewm(alpha=1/14, min_periods=14, adjust=False).mean()
            rs = gain / (loss + 1e-10)
            features['rsi_14'] = 100 - (100 / (1 + rs))
            
            # MACD (12, 26, 9)
            ema12 = close.ewm(span=12, adjust=False).mean()
            ema26 = close.ewm(span=26, adjust=False).mean()
            features['macd'] = ema12 - ema26
            features['macd_signal'] = features['macd'].ewm(span=9, adjust=False).mean()
            features['macd_hist'] = features['macd'] - features['macd_signal']
            
            # Bollinger Bands (20, 2)
            sma20 = close.rolling(20).mean()
            std20 = close.rolling(20).std()
            features['bb_upper'] = sma20 + (2 * std20)
            features['bb_middle'] = sma20
            features['bb_lower'] = sma20 - (2 * std20)
            
            # Stochastic (14, 3)
            low_14 = low.rolling(14).min()
            high_14 = high.rolling(14).max()
            features['stoch_k'] = 100 * (close - low_14) / (high_14 - low_14 + 1e-10)
            features['stoch_d'] = features['stoch_k'].rolling(3).mean()
            
            # ATR (14)
            tr1 = high - low
            tr2 = (high - close.shift(1)).abs()
            tr3 = (low - close.shift(1)).abs()
            true_range = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)
            features['atr_14'] = true_range.rolling(14).mean()
            
            # Williams %R (14)
            features['williams_r'] = -100 * (high_14 - close) / (high_14 - low_14 + 1e-10)
            
            # SMAs
            features['sma_7'] = close.rolling(7).mean()
            features['sma_20'] = close.rolling(20).mean()
            features['sma_50'] = close.rolling(50).mean()
            features['sma_100'] = close.rolling(100).mean()
            
            # EMAs
            features['ema_12'] = ema12
            features['ema_26'] = ema26
            
            # SMA Crossovers (boolean → int)
            features['sma7_above_sma20'] = (features['sma_7'] > features['sma_20']).astype(int)
            features['sma20_above_sma50'] = (features['sma_20'] > features['sma_50']).astype(int)
            
            # Price vs SMA
            features['close_above_sma20'] = (close > features['sma_20']).astype(int)
            features['close_above_sma50'] = (close > features['sma_50']).astype(int)
            
            # Volume SMA
            features['volume_sma_ratio'] = volume / volume.rolling(20).mean()
            
            return features
        
        except Exception as e:
            self.logger.error(f"❌ Erro em technical features: {e}")
            return pd.DataFrame()


    def _calculate_time_features_vectorized(self, df: pd.DataFrame, interval: str = '1h') -> pd.DataFrame:
        """
        Calcula features temporais adaptativas por intervalo

        ESTRATÉGIA:
        - Intraday (1m, 5m, 15m, 1h): Hour features + sessões de trading
        - Multi-hour (4h): Period of day (6 slots)
        - Daily (1d, 1w): Day of week + calendar features

        Args:
            df: DataFrame com DatetimeIndex
            interval: Intervalo dos candles ('1m', '5m', '15m', '1h', '4h', '1d', '1w')

        Returns:
            DataFrame com time features relevantes para o intervalo
        """
        try:
            features = pd.DataFrame(index=df.index)

            # ================================================================
            # VALIDAÇÃO E CONVERSÃO DE INDEX (DEFENSIVE PROGRAMMING)
            # ================================================================
            if not isinstance(df.index, pd.DatetimeIndex):
                self.logger.warning(
                    f"⚠️ Index não é DatetimeIndex (tipo: {type(df.index).__name__}). "
                    f"Tentando converter..."
                )

                # Tentar converter de timestamp column se existir
                if 'timestamp' in df.columns:
                    df = df.copy()
                    df.index = pd.to_datetime(df['timestamp'], unit='ms')
                    self.logger.info("   ✅ Index convertido de 'timestamp' column")
                # Tentar converter o próprio index
                elif df.index.dtype in ['int64', 'float64']:
                    df = df.copy()
                    df.index = pd.to_datetime(df.index, unit='ms')
                    self.logger.info("   ✅ Index convertido de int/float (assumindo ms)")
                else:
                    raise ValueError(
                        f"Não foi possível converter index para DatetimeIndex. "
                        f"Tipo atual: {type(df.index).__name__}, dtype: {df.index.dtype}"
                    )

            # ================================================================
            # FEATURES ADAPTATIVAS POR INTERVALO
            # ================================================================

            # GRUPO 1: Intraday (1m, 5m, 15m, 1h)
            if interval in ['1m', '5m', '15m', '1h']:
                # Hour features (alta variabilidade)
                features['hour'] = df.index.hour
                features['hour_sin'] = np.sin(2 * np.pi * features['hour'] / 24)
                features['hour_cos'] = np.cos(2 * np.pi * features['hour'] / 24)

                # Day of week
                features['day_of_week'] = df.index.dayofweek
                features['is_weekend'] = (df.index.dayofweek >= 5).astype(int)

                # Trading session (baseado em volume histórico de crypto)
                # 00:00-08:00 UTC: Asian session (baixo volume)
                # 08:00-16:00 UTC: European session (médio volume)
                # 16:00-24:00 UTC: US session (alto volume)
                features['is_us_session'] = ((df.index.hour >= 16) | (df.index.hour < 1)).astype(int)
                features['is_eu_session'] = ((df.index.hour >= 8) & (df.index.hour < 16)).astype(int)

                self.logger.debug(f"   Time features (intraday {interval}): 7 features")

            # GRUPO 2: Multi-hour (4h)
            elif interval == '4h':
                # 4h slots: 0, 4, 8, 12, 16, 20 (6 valores)
                # Criar features de "período do dia"
                hour = df.index.hour
                features['period_of_day'] = (hour // 4)  # 0-5
                features['period_sin'] = np.sin(2 * np.pi * features['period_of_day'] / 6)
                features['period_cos'] = np.cos(2 * np.pi * features['period_of_day'] / 6)

                # Day features mais relevantes
                features['day_of_week'] = df.index.dayofweek
                features['is_weekend'] = (df.index.dayofweek >= 5).astype(int)
                features['is_month_start'] = (df.index.day <= 5).astype(int)
                features['is_month_end'] = (df.index.day >= 25).astype(int)

                self.logger.debug(f"   Time features (multi-hour {interval}): 7 features")

            # GRUPO 3: Daily (1d, 1w)
            elif interval in ['1d', '1w']:
                # Hour não faz sentido (sempre 0)
                # Focar em features de calendário
                features['day_of_week'] = df.index.dayofweek
                features['day_of_week_sin'] = np.sin(2 * np.pi * features['day_of_week'] / 7)
                features['day_of_week_cos'] = np.cos(2 * np.pi * features['day_of_week'] / 7)

                features['is_weekend'] = (df.index.dayofweek >= 5).astype(int)
                features['is_monday'] = (df.index.dayofweek == 0).astype(int)  # Monday effect
                features['is_friday'] = (df.index.dayofweek == 4).astype(int)  # Friday effect

                # Month features
                features['day_of_month'] = df.index.day
                features['is_month_start'] = (df.index.day <= 7).astype(int)
                features['is_month_end'] = (df.index.day >= 23).astype(int)
                features['month'] = df.index.month

                self.logger.debug(f"   Time features (daily {interval}): 10 features")

            else:
                self.logger.warning(f"⚠️ Intervalo '{interval}' não reconhecido, usando features padrão")
                features['hour'] = df.index.hour
                features['day_of_week'] = df.index.dayofweek
                features['is_weekend'] = (df.index.dayofweek >= 5).astype(int)

            return features

        except Exception as e:
            self.logger.error(f"❌ Erro em time features: {e}")
            return pd.DataFrame()


    def _calculate_lag_features_vectorized(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Calcula features de lag ESTACIONÁRIAS (VETORIZADO)

        FILOSOFIA:
        RETORNOS PERCENTUAIS para garantir estacionariedade e generalização do modelo ML.
        - return_lag_1 = +2.5% → Generaliza para qualquer nível de preço!

        Features (20 features, todas estacionárias):
        - return_lag_1 até return_lag_10 (10 features) ✅ PERCENTUAIS
        - log_return_lag_1 até log_return_lag_5 (5 features) ✅ LOG RETURNS
        - volume_lag_1 até volume_lag_5 (5 features) ✅ OK (volume relativo)

        REFERÊNCIAS:
        - Box & Jenkins (1970): Time Series Analysis
        - Engle & Granger (1987): Cointegration and Error Correction
        """
        try:
            features = pd.DataFrame(index=df.index)

            # ================================================================
            # RETORNOS PERCENTUAIS (pct_change)
            # ================================================================
            # Calcula retorno percentual: (close_t - close_t-1) / close_t-1
            # Exemplo: 0.025 = +2.5% de retorno
            returns = df['close'].pct_change()

            # Lags de retorno percentual (1-10)
            for lag in range(1, 11):
                features[f'return_lag_{lag}'] = returns.shift(lag)

            # ================================================================
            # LOG RETURNS (mais estável para grandes movimentos)
            # ================================================================
            # Log return = ln(close_t / close_t-1)
            # Vantagens:
            # - Simetria: log(1.1) ≈ -log(0.9)
            # - Aditividade: log(P2/P0) = log(P2/P1) + log(P1/P0)
            # - Melhor para modelar retornos compostos
            log_returns = np.log(df['close'] / df['close'].shift(1))

            # Lags de log return (1-5) - Complementa os retornos simples
            for lag in range(1, 6):
                features[f'log_return_lag_{lag}'] = log_returns.shift(lag)

            # ================================================================
            # LAGS DE VOLUME (já são relativos, OK manter)
            # ================================================================
            # Volume já é uma medida relativa (BTC negociados, não USD)
            # Não sofre do problema de escala absoluta
            for lag in range(1, 6):
                features[f'volume_lag_{lag}'] = df['volume'].shift(lag)

            return features

        except Exception as e:
            self.logger.error(f"❌ Erro em lag features: {e}")
            return pd.DataFrame()


    def _calculate_rolling_features_vectorized(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Calcula features de rolling windows ESTACIONÁRIAS (VETORIZADO)

        FILOSOFIA:
        DISTÂNCIAS RELATIVAS,
        COEFICIENTES DE VARIAÇÃO e
        POSIÇÕES NO RANGE para garantir estacionariedade.

        - close_to_sma20_pct = +5% → Preço 5% acima da média (qualquer escala!)
        - cv_20 = 0.05 → Volatilidade de 5% relativa (qualquer escala!)

        Features (24 features, todas estacionárias):
        - close_to_sma_pct (4 features) ✅ Distância % das médias móveis
        - cv (3 features) ✅ Coeficiente de variação (volatilidade relativa)
        - price_position_in_range (2 features) ✅ Posição [0,1] no range
        - roc (3 features) ✅ Rate of Change (momentum percentual)
        - zscore (2 features) ✅ Z-score (desvios da média)
        - hl_ratio_rolling (1 feature) ✅ Razão High/Low
        - volume_rolling_mean (2 features) ✅ Volume (OK, já relativo)
        - volume_rolling_std (1 feature) ✅ Volume std (OK)
        - volume_surge (3 features) ✅ Volume relativo à média
        - momentum_strength (3 features) ✅ Força do momentum

        REFERÊNCIAS:
        - Bollinger Bands: Usa desvios-padrão relativos
        - RSI: Normalizado [0, 100]
        - Stochastic: Posição relativa no range
        """
        try:
            features = pd.DataFrame(index=df.index)
            close = df['close']
            volume = df['volume']
            high = df['high']
            low = df['low']

            # ================================================================
            # 1. DISTÂNCIA PERCENTUAL DAS MÉDIAS MÓVEIS (SMA)
            # ================================================================
            # Mede quanto % o preço está acima/abaixo da média móvel
            # Exemplo: +5% = preço 5% acima da SMA20
            for window in [5, 10, 20, 50]:
                sma = close.rolling(window).mean()
                features[f'close_to_sma{window}_pct'] = (close - sma) / (sma + 1e-10)

            # ================================================================
            # 2. COEFICIENTE DE VARIAÇÃO (CV) - Volatilidade Relativa
            # ================================================================
            # CV = std / mean → Volatilidade como % do preço
            # Exemplo: 0.05 = 5% de volatilidade relativa
            # Vantagem: Normaliza a volatilidade independente do nível de preço
            for window in [5, 10, 20]:
                rolling_mean = close.rolling(window).mean()
                rolling_std = close.rolling(window).std()
                features[f'cv_{window}'] = rolling_std / (rolling_mean + 1e-10)

            # ================================================================
            # 3. POSIÇÃO NO RANGE [0, 1] - Stochastic-like
            # ================================================================
            # 0 = no mínimo, 1 = no máximo, 0.5 = no meio
            # Similar ao Stochastic Oscillator
            for window in [10, 20]:
                rolling_min = close.rolling(window).min()
                rolling_max = close.rolling(window).max()
                rolling_range = rolling_max - rolling_min
                features[f'price_position_in_range_{window}'] = (
                    (close - rolling_min) / (rolling_range + 1e-10)
                )

            # ================================================================
            # 4. RATE OF CHANGE (ROC) - Momentum Percentual
            # ================================================================
            # ROC = (close - close[n]) / close[n]
            # Mede momentum como variação % em N períodos
            for period in [5, 10, 20]:
                roc = (close - close.shift(period)) / (close.shift(period) + 1e-10)
                features[f'roc_{period}'] = roc

            # ================================================================
            # 5. Z-SCORE - Distância em Desvios Padrão
            # ================================================================
            # Quantos desvios-padrão o preço está da média?
            # Exemplo: 2.5 = preço está 2.5 σ acima da média (overbought?)
            for window in [20, 50]:
                rolling_mean = close.rolling(window).mean()
                rolling_std = close.rolling(window).std()
                features[f'zscore_{window}'] = (
                    (close - rolling_mean) / (rolling_std + 1e-10)
                )

            # ================================================================
            # 6. HIGH/LOW RATIO - Volatilidade Intrabar
            # ================================================================
            # Razão high/low média → Mede spread intrabar
            # Exemplo: 1.02 = spread de 2% em média
            hl_ratio = high / (low + 1e-10)
            features['hl_ratio_rolling_10'] = hl_ratio.rolling(10).mean()

            # ================================================================
            # 7. VOLUME FEATURES (já são relativos, OK manter + melhorias)
            # ================================================================
            # Volume já é relativo (BTC negociados), mas vamos adicionar
            # volume RELATIVO à sua própria média (surge detection)

            # Volume absoluto (OK, é BTC não USD)
            features['volume_rolling_mean_10'] = volume.rolling(10).mean()
            features['volume_rolling_mean_20'] = volume.rolling(20).mean()
            features['volume_rolling_std_10'] = volume.rolling(10).std()

            # Volume RELATIVO à média (surge detection)
            # Exemplo: 2.5 = volume 2.5x acima da média (surge!)
            for window in [5, 10, 20]:
                vol_mean = volume.rolling(window).mean()
                features[f'volume_surge_{window}'] = volume / (vol_mean + 1e-10)

            # ================================================================
            # 8. MOMENTUM STRENGTH - Retorno / Volatilidade
            # ================================================================
            # Sharpe-like: Retorno dividido pela volatilidade
            # Mede "qualidade" do movimento: forte e consistente vs errático
            for window in [5, 10, 20]:
                returns = close.pct_change()
                rolling_return = returns.rolling(window).mean()
                rolling_vol = returns.rolling(window).std()
                features[f'momentum_strength_{window}'] = (
                    rolling_return / (rolling_vol + 1e-10)
                )

            return features

        except Exception as e:
            self.logger.error(f"❌ Erro em rolling features: {e}")
            return pd.DataFrame()


    def _calculate_volatility_features_vectorized(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Calcula features de volatilidade (VETORIZADO)
        
        Features (5):
        - realized_volatility_10: Volatilidade realizada (10 períodos)
        - realized_volatility_20: Volatilidade realizada (20 períodos)
        - parkinson_volatility: Estimador de Parkinson (high-low)
        - garman_klass_volatility: Estimador de Garman-Klass
        - atr_ratio: ATR / close (normalizado)
        """
        try:
            features = pd.DataFrame(index=df.index)
            close = df['close']
            high = df['high']
            low = df['low']
            open_ = df['open']
            
            # Realized volatility (std dos returns)
            returns = close.pct_change()
            features['realized_vol_10'] = returns.rolling(10).std()
            features['realized_vol_20'] = returns.rolling(20).std()
            
            # Parkinson volatility (baseado em high-low)
            features['parkinson_vol'] = np.sqrt(
                (1 / (4 * np.log(2))) * 
                ((np.log(high / low)) ** 2).rolling(10).mean()
            )
            
            # Garman-Klass volatility
            hl = np.log(high / low) ** 2
            co = np.log(close / open_) ** 2
            features['garman_klass_vol'] = np.sqrt(
                (0.5 * hl - (2 * np.log(2) - 1) * co).rolling(10).mean()
            )
            
            # ATR normalizado
            tr1 = high - low
            tr2 = (high - close.shift(1)).abs()
            tr3 = (low - close.shift(1)).abs()
            true_range = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)
            atr = true_range.rolling(14).mean()
            features['atr_ratio'] = atr / (close + 1e-10)
            
            return features
        
        except Exception as e:
            self.logger.error(f"❌ Erro em volatility features: {e}")
            return pd.DataFrame()


    def _calculate_microstructure_features_vectorized(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Calcula features de microestrutura de mercado (VETORIZADO)
        
        Features (4):
        - bid_ask_spread: (high - low) / close (proxy)
        - tick_direction: 1 se close > close.shift(1), -1 caso contrário
        - price_impact: abs(return) * volume (proxy)
        - imbalance_ratio: (close - open) / (high - low + 1e-10)
        """
        try:
            features = pd.DataFrame(index=df.index)
            close = df['close']
            high = df['high']
            low = df['low']
            open_ = df['open']
            volume = df['volume']
            
            # Spread (proxy usando high-low)
            features['spread'] = (high - low) / (close + 1e-10)
            
            # Tick direction
            features['tick_direction'] = np.where(
                close > close.shift(1), 1, -1
            )
            
            # Price impact (proxy)
            returns = close.pct_change().abs()
            features['price_impact'] = returns * volume
            
            # Order imbalance (proxy)
            features['imbalance'] = (close - open_) / (high - low + 1e-10)
            
            return features
        
        except Exception as e:
            self.logger.error(f"❌ Erro em microstructure features: {e}")
            return pd.DataFrame()
    
    # ========== MÉTODO PÚBLICO ==========
    
    def calculate_features(self,
                           symbol: str,
                           interval: str = '1h',
                           limit: int = 1000,) -> Optional[Dict[str, float]]:
        """
        🔄 WRAPPER ENTERPRISE - Calcula features usando motor ML vetorizado

        Este método é um WRAPPER que usa o mesmo motor ML vetorizado
        (calculate_features_for_ml) usado no treinamento.

        BENEFÍCIOS:
        ✅ Fonte única de verdade matemática
        ✅ Mesma precisão do treinamento
        ✅ Performance vetorizada (Pandas)
        ✅ Mantém API pública (retorna Dict)

        FLUXO ENTERPRISE:
        1. Verificar cache (opcional, para performance)
        2. Buscar klines do cache
        3. Chamar calculate_features_for_ml() ← MOTOR ML VETORIZADO!
        4. Extrair última linha (features atuais)
        5. Converter para Dict
        6. Armazenar em cache
        7. Retornar features

        Args:
            symbol: Símbolo (ex: 'BTCUSDT')
            interval: Intervalo (ex: '1h')

        Returns:
            Dict com 92 features ou None

        Examples:
            >>> features = feature_eng.calculate_features('BTCUSDT', '1h')
            >>> print(features['rsi_14'])  # 65.3
            >>> print(features['realized_vol_20'])  # 0.023
        """
        try:
            # ================================================================
            # PASSO 1: VERIFICAR CACHE (Performance)
            # ================================================================
            cached_features = self._check_feature_cache(symbol, interval)
            if cached_features:
                self.logger.debug(f"✅ Cache HIT: {symbol}@{interval}")
                return cached_features

            # ================================================================
            # PASSO 2: BUSCAR KLINES DO CACHE
            # ================================================================
            cache_key = f"kline:{interval}:{symbol}"
            klines = self.cache.get_klines(
                symbol=symbol,
                interval=interval,
                limit=limit,
                reader="FeatureEngineering"
            )

            if not klines or len(klines) < 500:
                self.logger.warning(
                    f"⚠️ Klines insuficientes para {symbol}@{interval}: "
                    f"{len(klines) if klines else 0} < 500"
                )
                return None

            # Pegar últimas 1000 klines para garantir features completas
            # (Rolling windows precisam de histórico)
            klines_recent = klines[-1000:] if len(klines) > 1000 else klines

            self.logger.debug(
                f"📊 Calculando features para {symbol}@{interval} "
                f"com {len(klines_recent)} klines"
            )

            # ================================================================
            # PASSO 3: CALCULAR FEATURES COM MOTOR ML VETORIZADO
            # ================================================================
            # 🚀 IMPORTANTE: Usa o MESMO método do treinamento!
            # Garante consistência matemática total
            features_df = self.calculate_features_for_ml(
                klines=klines_recent,
                symbol=f"{symbol}@{interval}",
                interval=interval  # ← FASE 3: Para time features adaptativas
            )

            if features_df is None or features_df.empty:
                self.logger.error(
                    f"❌ Falha ao calcular features ML para {symbol}@{interval}"
                )
                return None

            # ================================================================
            # PASSO 4: EXTRAIR ÚLTIMA LINHA (Features Atuais)
            # ================================================================
            # Última linha = features mais recentes (tempo real)
            last_row = features_df.iloc[-1]

            # ================================================================
            # PASSO 5: CONVERTER PARA DICT (Mantém API pública)
            # ================================================================
            features_dict = last_row.to_dict()

            # Validar que temos features
            if not features_dict or len(features_dict) == 0:
                self.logger.error(f"❌ Features dict vazio para {symbol}@{interval}")
                return None

            self.logger.info(
                f"✅ Features calculadas: {symbol}@{interval} "
                f"({len(features_dict)} features)"
            )

            # ================================================================
            # PASSO 6: ARMAZENAR EM CACHE
            # ================================================================
            self._store_feature_cache(symbol, interval, features_dict)

            # ================================================================
            # PASSO 7: RETORNAR FEATURES
            # ================================================================
            return features_dict

        except Exception as e:
            self.logger.error(
                f"❌ Erro ao calcular features (wrapper) para {symbol}@{interval}: {e}",
                exc_info=True
            )
            return None
    
    def _check_feature_cache(self, symbol: str, interval: str) -> Optional[Dict]:
        """Verifica cache local"""
        try:
            with QMutexLocker(self.mutex):
                cache_key = (symbol, interval)
                if cache_key in self.feature_cache:
                    timestamp, features = self.feature_cache[cache_key]
                    
                    # Check TTL
                    if (time.time() - timestamp) < self.feature_cache_ttl:
                        self.logger.info(f"✅ Feature cache HIT: {symbol}")
                        return features
                    else:
                        # Expired
                        del self.feature_cache[cache_key]
            
            return None
            
        except Exception as e:
            self.logger.error(f"❌ Erro ao verificar cache: {e}")
            return None
    
    def _store_feature_cache(self, symbol: str, interval: str, features: Dict):
        """Armazena no cache local"""
        try:
            with QMutexLocker(self.mutex):
                cache_key = (symbol, interval)
                self.feature_cache[cache_key] = (time.time(), features)
                self.logger.info(f"💾 Features cached: {symbol}")
                
        except Exception as e:
            self.logger.error(f"❌ Erro ao armazenar cache: {e}")

# ===========================================================================================
# TRAINING WORKER - MACHINE LEARNING MODEL TRAINING
# ===========================================================================================

class TrainingWorker(QObject):
    """
    TrainingWorker - Worker Dedicado para Treinamento de Modelos ML

    FILOSOFIA:
    Este worker executa em QThread separado e é responsável por TODO o processo de
    treinamento de modelos, SEM BLOQUEAR a UI.

    CARACTERÍSTICAS:
        - Executa em thread separada (via moveToThread)
        - Non-blocking: operações pesadas não travam UI
        - Progress reporting: emite sinais com progresso detalhado
        - Cache-integrated: lê OHLCV do cache, escreve modelos
        - Batch processing: pode treinar múltiplos símbolos em fila
        - Model persistence: salva/carrega modelos do disco

    RESPONSABILIDADES:
        ✓ Fetch dados OHLCV do cache (L0)
        ✓ Executar feature engineering
        ✓ Treinar ensemble de modelos (RF, XGB, LGBM)
        ✓ Cross-validation (TimeSeriesSplit)
        ✓ Calcular métricas de performance
        ✓ Salvar modelos em disco
        ✓ Reportar progresso via sinais

    FLUXO DE TREINAMENTO:
        1. Recebe solicitação via slot train_model(symbol, force_retrain)
        2. Emite training_started(symbol)
        3. Busca OHLCV do cache (L0 - SQLite)
        4. Chama FeatureEngineering.calculate_features_for_klines()
        5. Prepara X_train, y_train, X_val, y_val (split temporal)
        6. Para cada modelo (RF, XGB, LGBM):
            a. Treina modelo
            b. Emite training_progress
            c. Cross-validation
        7. Avalia ensemble
        8. Salva modelos em disco
        9. Emite training_completed(symbol, results)

    SINAIS:
        - training_started(symbol): Treinamento iniciou
        - training_progress(message, percent): Progresso
        - training_completed(symbol, result): Treinamento completo
        - training_failed(symbol, error): Treinamento falhou

    THREAD-SAFETY:
        - Não acessa diretamente MLSystem.trained_models
        - Comunicação apenas via sinais Qt
        - Mutex próprio para estado interno
        - NO PARENT quando criado (para moveToThread funcionar)

    INTEGRAÇÃO COM CACHE:
        - Lê: OHLCV (L0 - SQLite, TTL infinito)
        - Escreve: Model metadata (L3, TTL 24h)
    
    Executa em QThread separado. Não bloqueia UI.
    
    IMPORTANTE: Este objeto NÃO DEVE TER PARENT quando criado, pois será
    movido para outra thread com moveToThread().
    """
    
    # ========== SINAIS ==========
    training_started = Signal(str)  # symbol
    training_progress = Signal(str, int)  # message, percent
    training_completed = Signal(str, dict)  # symbol, result
    training_failed = Signal(str, str)  # symbol, error
    
    def __init__(
        self,
        cache_system,
        feature_engineering,
        config: Dict[str, Any]
    ):
        """
        Inicializa TrainingWorker
        
        CRITICAL: NÃO passar parent aqui! Será movido para outra thread.
        
        Args:
            cache_system: Instância do CacheSystem
            feature_engineering: Instância do FeatureEngineering
            config: Configurações ML
        """
        super().__init__()  # NO PARENT!
        
        # Logger
        self.logger = logging.getLogger('TrainingWorker')
        self.logger.info("🔧 TrainingWorker instanciado (aguardando moveToThread)")
        
        # Dependências
        self.cache = cache_system
        self.feature_eng = feature_engineering
        self.config = config
        
        # Estado interno (thread-safe com mutex próprio)
        self.mutex = QMutex()
        self.is_training = False
        self.current_symbol = None
        self.training_queue = deque()
        
        # Configurações
        self.models_dir = Path(config.get('models_dir', 'models'))
        self.models_dir.mkdir(exist_ok=True)
        
        self.test_size = config.get('test_size', 0.2)
        self.n_splits = config.get('n_splits', 5)
        self.random_state = config.get('random_state', 42)
        
        self.models_to_train = config.get('models', ['RandomForest', 'XGBoost', 'LightGBM'])
        
        # Verificar disponibilidade de bibliotecas
        if 'XGBoost' in self.models_to_train and not XGBOOST_AVAILABLE:
            self.logger.warning("⚠️ XGBoost não instalado, será removido da lista")
            self.models_to_train.remove('XGBoost')
        
        if 'LightGBM' in self.models_to_train and not LIGHTGBM_AVAILABLE:
            self.logger.warning("⚠️ LightGBM não instalado, será removido da lista")
            self.models_to_train.remove('LightGBM')
        
        self.logger.info(f"📊 Configurações do TrainingWorker:")
        self.logger.info(f"   - Models dir: {self.models_dir}")
        self.logger.info(f"   - Test size: {self.test_size}")
        self.logger.info(f"   - CV splits: {self.n_splits}")
        self.logger.info(f"   - Models: {self.models_to_train}")
    
    # ========== SLOTS (RECEBEM COMANDOS) ==========

    @Slot(str, bool)
    def train_model(
        self,
        symbol: str,
        force_retrain: bool = False
    ):
        """
        Treina TODOS os modelos necessários para um símbolo

        Este slot é executado na THREAD DO WORKER (não main thread)

        ESTRATÉGIA 2: Target Horizon Estendido + Ensemble
        Para cada símbolo, treina 5 modelos:
        - 1h:t3  (micro: 3h)
        - 1h:t12 (tático: 12h)
        - 4h:t3  (tático: 12h)
        - 4h:t6  (diário: 24h)
        - 1d:t1  (diário: 24h)

        Args:
            symbol: Símbolo a treinar (ex: 'BTCUSDT')
            force_retrain: Forçar retreino mesmo se modelos existem

        Example:
            train_model('BTCUSDT')  # Treina todos os 5 modelos
        """
        self.logger.info("=" * 80)
        self.logger.info(f"INICIANDO TREINAMENTO COMPLETO: {symbol}")
        self.logger.info("=" * 80)

        # Definir configuração de modelos a treinar
        # Para cada símbolo: 5 modelos (1h:t3, 1h:t12, 4h:t3, 4h:t6, 1d:t1)
        training_schedule = [
            {'interval': '1h', 'target_horizon': 3, 'description': 'Micro (3h)'},
            {'interval': '1h', 'target_horizon': 12, 'description': 'Tático (12h)'},
            {'interval': '4h', 'target_horizon': 3, 'description': 'Tático (12h)'},
            {'interval': '4h', 'target_horizon': 6, 'description': 'Diário (24h)'},
            {'interval': '1d', 'target_horizon': 1, 'description': 'Diário (24h)'},
        ]

        total_start_time = time.time()

        try:
            # ============================================================
            # VERIFICAR SE JÁ ESTÁ TREINANDO
            # ============================================================
            with QMutexLocker(self.mutex):
                if self.is_training:
                    self.logger.warning(
                        f"⚠️ Já treinando {self.current_symbol}, "
                        f"enfileirando {symbol}"
                    )
                    self.training_queue.append((symbol, force_retrain))
                    return

                self.is_training = True
                self.current_symbol = symbol
            
            # ============================================================
            # EMITIR SINAL DE INÍCIO
            # ============================================================
            self.training_started.emit(symbol)
            self._emit_progress("Iniciando treinamento...", 0)

            self.logger.info(f"📋 Agenda de treinamento: {len(training_schedule)} modelos")
            for task in training_schedule:
                self.logger.info(f"   - {task['interval']}:t{task['target_horizon']} → {task['description']}")

            # Mapa de horas por intervalo
            interval_hours_map = {
                '1m': 1/60, '5m': 5/60, '15m': 15/60,
                '1h': 1, '4h': 4, '1d': 24, '1w': 168
            }

            # ============================================================
            # LOOP: TREINAR TODOS OS MODELOS
            # ============================================================
            models_trained = 0
            models_failed = 0
            all_results = []

            for idx, task in enumerate(training_schedule, 1):
                interval = task['interval']
                target_horizon = task['target_horizon']
                description = task['description']

                self.logger.info("=" * 80)
                self.logger.info(f"🔄 MODELO {idx}/{len(training_schedule)}: {symbol} {interval}:t{target_horizon}")
                self.logger.info(f"   Horizonte: {description}")
                self.logger.info("=" * 80)

                model_start_time = time.time()

                try:
                    # ============================================================
                    # PASSO 1: Buscar dados OHLCV do cache com limite adequado
                    # ============================================================
                    progress_base = int((idx - 1) / len(training_schedule) * 100)
                    self._emit_progress(f"[{idx}/{len(training_schedule)}] Buscando dados OHLCV {interval}...", progress_base + 1)

                    # Determinar limite de busca baseado no intervalo
                    requirements = ML_TRAINING_DATA_REQUIREMENTS.get(interval)

                    # Buscar quantidade IDEAL + margem de segurança (10%)
                    fetch_limit = int(requirements['ideal_min'] * 1.1)

                    self.logger.info(f"📊 Requisitos para {interval}:")
                    self.logger.info(f"   Crítico: {requirements['critical_min']} ({requirements['period_critical']})")
                    self.logger.info(f"   Alerta: {requirements['warning_min']} ({requirements['period_warning']})")
                    self.logger.info(f"   Ideal: {requirements['ideal_min']} ({requirements['period_ideal']})")
                    self.logger.info(f"   Buscando: {fetch_limit} candles")

                    klines = self._fetch_ohlcv(symbol, interval, limit=fetch_limit, as_dataframe=False)

                    if klines is None:
                        raise ValueError(f"Dados OHLCV não disponíveis para {symbol}@{interval}")

                    n_candles = len(klines)

                    # ============================================================
                    # AVALIAÇÃO DA QUANTIDADE DE DADOS (Sistema de 3 Níveis)
                    # ============================================================

                    critical_min = requirements['critical_min']
                    warning_min = requirements['warning_min']
                    ideal_min = requirements['ideal_min']

                    self.logger.info("=" * 80)
                    self.logger.info(f"📊 AVALIAÇÃO DE DADOS: {symbol}@{interval}")
                    self.logger.info(f"   Disponível: {n_candles} candles")
                    self.logger.info("=" * 80)

                    # NÍVEL 1: CRÍTICO (Bloqueio)
                    if n_candles < critical_min:
                        self.logger.error("=" * 80)
                        self.logger.error(f"❌ TREINAMENTO BLOQUEADO - DADOS INSUFICIENTES")
                        self.logger.error(f"   Status: CRÍTICO ❌")
                        self.logger.error(f"   Disponível: {n_candles} candles")
                        self.logger.error(f"   Mínimo crítico: {critical_min} candles ({requirements['period_critical']})")
                        self.logger.error(f"   Faltam: {critical_min - n_candles} candles")
                        self.logger.error(f"   Impacto: TREINAMENTO IMPOSSÍVEL")
                        self.logger.error(f"   Ação: Aguardar coleta de mais dados históricos")
                        self.logger.error("=" * 80)
                        raise ValueError(
                            f"Dados insuficientes para treinamento: {n_candles} < {critical_min} (mínimo crítico)"
                        )

                    # NÍVEL 2: ALERTA (Permite treinar com aviso)
                    elif n_candles < warning_min:
                        self.logger.warning("=" * 80)
                        self.logger.warning(f"⚠️ TREINAMENTO COM DADOS ABAIXO DO RECOMENDADO")
                        self.logger.warning(f"   Status: ALERTA ⚠️")
                        self.logger.warning(f"   Disponível: {n_candles} candles")
                        self.logger.warning(f"   Mínimo recomendado: {warning_min} candles ({requirements['period_warning']})")
                        self.logger.warning(f"   Ideal: {ideal_min} candles ({requirements['period_ideal']})")
                        self.logger.warning(f"   Faltam para ideal: {ideal_min - n_candles} candles")
                        self.logger.warning(f"   Impacto: Modelo pode ter QUALIDADE REDUZIDA")
                        self.logger.warning(f"   Recomendação: Continuar coletando dados para melhorar precisão")
                        self.logger.warning("=" * 80)

                    # NÍVEL 3: SUBIDEAL (Permite treinar com aviso leve)
                    elif n_candles < ideal_min:
                        self.logger.warning("=" * 80)
                        self.logger.warning(f"⚠️ TREINAMENTO COM DADOS ABAIXO DO IDEAL")
                        self.logger.warning(f"   Status: ACEITÁVEL ⚠️")
                        self.logger.warning(f"   Disponível: {n_candles} candles")
                        self.logger.warning(f"   Ideal: {ideal_min} candles ({requirements['period_ideal']})")
                        self.logger.warning(f"   Faltam para ideal: {ideal_min - n_candles} candles")
                        self.logger.warning(f"   Impacto: Modelo funcional, mas pode melhorar com mais dados")
                        self.logger.warning(f"   Recomendação: Continuar coletando para máxima precisão")
                        self.logger.warning("=" * 80)

                    # NÍVEL 4: IDEAL (Tudo perfeito!)
                    else:
                        self.logger.info("=" * 80)
                        self.logger.info(f"✅ TREINAMENTO COM DADOS IDEAIS")
                        self.logger.info(f"   Status: IDEAL ✅")
                        self.logger.info(f"   Disponível: {n_candles} candles")
                        self.logger.info(f"   Ideal mínimo: {ideal_min} candles ({requirements['period_ideal']})")
                        self.logger.info(f"   Excedente: {n_candles - ideal_min} candles")
                        self.logger.info(f"   Qualidade esperada: MÁXIMA 🎯")
                        self.logger.info("=" * 80)

                    # ============================================================
                    # PASSO 2: Feature Engineering
                    # ============================================================
                    progress_base = int((idx - 1) / len(training_schedule) * 100)
                    self._emit_progress(f"[{idx}/{len(training_schedule)}] Calculando features...", progress_base + 5)
                    features_df = self._calculate_features(symbol, interval, klines)

                    if features_df is None or len(features_df) < 200:
                        raise ValueError(f"Features insuficientes: {len(features_df) if features_df is not None else 0}")

                    self.logger.info(f"✅ Features calculated: {features_df.shape}")

                    # ============================================================
                    # PASSO 3: Calcular estatísticas de treinamento (Data Drift Detection)
                    # ============================================================
                    self._emit_progress(f"[{idx}/{len(training_schedule)}] Calculando estatísticas...", progress_base + 10)

                    training_stats = self._calculate_training_stats(features_df)

                    if training_stats:
                        self.logger.info("=" * 80)
                        self.logger.info("📊 ESTATÍSTICAS DE TREINAMENTO CALCULADAS")
                        self.logger.info(f"   Features monitoradas: {len(training_stats)}")

                        # Exibir amostra de estatísticas
                        for feature_name, stats in list(training_stats.items())[:3]:
                            self.logger.info(f"   {feature_name}:")
                            self.logger.info(f"      Mean: {stats['mean']:.6f}, Std: {stats['std']:.6f}")
                            self.logger.info(f"      Range: [{stats['min']:.6f}, {stats['max']:.6f}]")

                        if len(training_stats) > 3:
                            self.logger.info(f"   ... e mais {len(training_stats) - 3} features")
                        self.logger.info("=" * 80)
                    else:
                        self.logger.warning("⚠️ Nenhuma estatística de treinamento foi calculada")

                    # Calcular horizon_hours para logs
                    horizon_hours = interval_hours_map.get(interval, 1) * target_horizon

                    # ============================================================
                    # PASSO 4: Preparar dados de treinamento
                    # ============================================================
                    self._emit_progress(f"[{idx}/{len(training_schedule)}] Preparando dados...", progress_base + 15)
                    X_train, y_train, X_val, y_val, scaler, feature_names = self._prepare_training_data(
                        features_df,
                        symbol=symbol,
                        interval=interval,
                        target_horizon=target_horizon,  # <- DINÂMICO!
                        test_size=0.2      # 20% para validação
                    )

                    self.logger.info(f"✅ Data prepared:")
                    self.logger.info(f"   - Train: {X_train.shape[0]} samples")
                    self.logger.info(f"   - Val: {X_val.shape[0]} samples")
                    self.logger.info(f"   - Features: {X_train.shape[1]}")
                    self.logger.info(f"   - Feature names: {len(feature_names)} salvos")

                    # ============================================================
                    # PASSO 5: Treinar modelos
                    # ============================================================
                    trained_models = {}
                    model_metrics = {}

                    progress_per_model = 10 / len(self.models_to_train)
                    current_progress = progress_base + 20

                    for i, model_name in enumerate(self.models_to_train):
                        self._emit_progress(f"[{idx}/{len(training_schedule)}] Treinando {model_name}...", int(current_progress))

                        model, metrics = self._train_single_model(
                            model_name, X_train, y_train, X_val, y_val
                        )

                        if model is not None:
                            trained_models[model_name] = model
                            model_metrics[model_name] = metrics
                            self.logger.info(f"      ✅ {model_name} trained: R²={metrics.get('r2_score', 0):.4f}")
                        else:
                            self.logger.warning(f"⚠️ {model_name} training failed")

                        current_progress += progress_per_model

                    if not trained_models:
                        raise ValueError("Nenhum modelo foi treinado com sucesso")

                    # ============================================================
                    # PASSO 6: Cross-validation
                    # ============================================================
                    self._emit_progress(f"[{idx}/{len(training_schedule)}] Cross-validation...", progress_base + 60)
                    cv_metrics = self._cross_validate_models(
                        trained_models,
                        X=np.vstack([X_train, X_val]),
                        y=np.concatenate([y_train, y_val]),
                        n_splits=self.n_splits
                    )

                    # ============================================================
                    # PASSO 7: Calcular feature importance
                    # ============================================================
                    self._emit_progress(f"[{idx}/{len(training_schedule)}] Feature importance...", progress_base + 70)

                    # Feature names já foram passados do _prepare_training_data
                    # Agora temos nomes descritivos: 'rsi_14', 'sma_50', etc.
                    self.logger.debug(f"   Feature names para importance: {feature_names[:5]}...")

                    feature_importance = self._calculate_feature_importance(
                        trained_models,
                        feature_names
                    )

                    # ============================================================
                    # PASSO 8: Calcular métricas ensemble
                    # ============================================================
                    self._emit_progress(f"[{idx}/{len(training_schedule)}] Avaliando ensemble...", progress_base + 75)
                    ensemble_metrics = self._calculate_ensemble_metrics(model_metrics)

                    # ============================================================
                    # PASSO 9: Salvar modelos
                    # ============================================================
                    model_duration = time.time() - model_start_time

                    self._emit_progress(f"[{idx}/{len(training_schedule)}] Salvando modelos...", progress_base + 85)
                    model_path = self._save_models(
                        symbol=symbol,
                        interval=interval,
                        trained_models=trained_models,
                        scaler=scaler,
                        ensemble_metrics=ensemble_metrics,
                        model_metrics=model_metrics,
                        cv_metrics=cv_metrics,
                        feature_importance=feature_importance,
                        features_df=features_df,  # <- Passar features para salvar última amostra
                        training_stats=training_stats,  # <- Estatísticas para Data Drift Detection
                        training_metadata={
                            'trained_at': time.time(),
                            'training_duration_s': model_duration,
                            'n_candles_used': n_candles,
                            'n_features': X_train.shape[1],
                            'n_samples_train': X_train.shape[0],
                            'n_samples_val': X_val.shape[0],
                            'feature_names': feature_names,
                            'target_horizon': target_horizon,  # <- Horizonte de previsão
                            'horizon_hours': horizon_hours      # <- Horizonte em horas
                        }
                    )

                    # ============================================================
                    # PASSO 10: Preparar resultado
                    # ============================================================

                    result = {
                        'symbol': symbol,
                        'interval': interval,
                        'target_horizon': target_horizon,
                        'horizon_hours': horizon_hours,    # <- Para logs
                        'metrics': ensemble_metrics,
                        'model_metrics': model_metrics,
                        'cv_metrics': cv_metrics,
                        'feature_importance': feature_importance,
                        'n_features': X_train.shape[1],
                        'n_samples_train': X_train.shape[0],
                        'n_samples_val': X_val.shape[0],
                        'training_duration_s': model_duration,
                        'model_file_path': str(model_path),  # <- Path para lazy loading
                        'n_candles_used': n_candles,
                        'trained_at': time.time(),
                    }

                    # Incrementar contador de sucesso
                    models_trained += 1
                    all_results.append(result)

                    # Emitir sucesso para ESTE modelo individual
                    self._emit_progress(f"[{idx}/{len(training_schedule)}] Modelo treinado!", progress_base + 95)
                    self.training_completed.emit(symbol, result)

                    self.logger.info("=" * 80)
                    self.logger.info(f"✅ MODELO TREINADO: {symbol} {interval}:t{target_horizon}")
                    self.logger.info(f"   Duração: {model_duration:.1f}s")
                    self.logger.info(f"   R² Score: {ensemble_metrics.get('r2_score', 0):.4f}")
                    self.logger.info(f"   MAE: {ensemble_metrics.get('mae', 0):.4f}")
                    self.logger.info(f"   Candles: {n_candles}")
                    self.logger.info("=" * 80)

                except Exception as e:
                    # Log do erro para ESTE modelo específico
                    models_failed += 1
                    self.logger.error("=" * 80)
                    self.logger.error(f"❌ ERRO NO MODELO {idx}/{len(training_schedule)}: {symbol} {interval}:t{target_horizon}")
                    self.logger.error(f"   Erro: {e}")
                    self.logger.error("=" * 80)
                    self.logger.error(f"Traceback completo:", exc_info=True)
                    # Continuar para próximo modelo (não falhar tudo)
                    continue

            # ============================================================
            # FIM DO LOOP - LOG FINAL DE TREINAMENTO COMPLETO
            # ============================================================
            total_duration = time.time() - total_start_time

            self.logger.info("=" * 80)
            self.logger.info(f"✅ TREINAMENTO COMPLETO: {symbol}")
            self.logger.info(f"   Modelos treinados: {models_trained}/5")
            self.logger.info(f"   Modelos falhados: {models_failed}/5")
            self.logger.info(f"   Duração total: {total_duration:.1f}s")
            self.logger.info("=" * 80)

        except Exception as e:
            self.logger.error(f"❌ Erro geral no treinamento de {symbol}: {e}", exc_info=True)
            self.training_failed.emit(symbol, str(e))
        
        finally:
            # Liberar lock e processar fila
            with QMutexLocker(self.mutex):
                self.is_training = False
                self.current_symbol = None
            
            # Processar próximo da fila
            self._process_queue()
    
    @Slot()
    def _process_queue(self):
        """
        Processa próximo item da fila de treinamento
        """
        with QMutexLocker(self.mutex):
            if self.training_queue and not self.is_training:
                # Desempacotar tupla com 2 elementos
                symbol, force_retrain = self.training_queue.popleft()

                self.logger.info(f"🔥 Processando da fila: {symbol}")

                # Chamar train_model recursivamente
                from PySide6.QtCore import QTimer
                QTimer.singleShot(
                    100,
                    lambda: self.train_model(symbol, force_retrain)
                )
    
    # ========== MÉTODOS PRIVADOS ==========
    
    def _emit_progress(self, message: str, percent: int):
        """
        Helper para emitir progresso
        
        Args:
            message: Mensagem de progresso
            percent: Porcentagem (0-100)
        """
        self.training_progress.emit(message, percent)
        self.logger.debug(f"📊 [{percent}%] {message}")
    
    def _fetch_ohlcv(
        self,
        symbol: str,
        interval: str = '1h',
        limit: int = 20000,
        as_dataframe: bool = True
    ) -> Union[Optional[pd.DataFrame], Optional[List[Dict]]]:
        """
        Busca dados OHLCV do cache (formato flexível)
        
        REFATORAÇÃO: Agora suporta retorno em 2 formatos
        
        FORMATOS DE RETORNO:
        1. as_dataframe=True (padrão):
        - Retorna pd.DataFrame com colunas [open, high, low, close, volume]
        - Index: DatetimeIndex
        - Uso: Para análises que precisam de DataFrame diretamente
        
        2. as_dataframe=False:
        - Retorna List[Dict] (formato raw do cache)
        - Estrutura: [{'open_time': ..., 'open': ..., ...}, ...]
        - Uso: Para passar ao FeatureEngineering sem conversões extras
        
        VANTAGENS:
        - Elimina conversões redundantes
        - Mais eficiente em memória e CPU
        - Flexível para diferentes use cases
        
        Args:
            symbol: Símbolo (ex: 'BTCUSDT')
            interval: Intervalo temporal (ex: '1h', '4h', '1d')
            limit: Número máximo de candles (padrão: 10000)
            as_dataframe: Se True retorna DataFrame, se False retorna List[Dict]
        
        Returns:
            - Se as_dataframe=True: pd.DataFrame ou None
            - Se as_dataframe=False: List[Dict] ou None
        
        Examples:
            >>> # Para Feature Engineering (raw)
            >>> klines = self._fetch_ohlcv('BTCUSDT', '1h', as_dataframe=False)
            >>> features = self.feature_eng.calculate_features_for_klines(klines)
            
            >>> # Para análise direta (DataFrame)
            >>> df = self._fetch_ohlcv('BTCUSDT', '1h', as_dataframe=True)
            >>> print(df.describe())
        """
        logger = self.logger
        
        try:
            # ================================================================
            # FASE 1: BUSCAR DADOS VIA get_klines() API PÚBLICA
            # ================================================================
            logger.info(f"📥 Buscando OHLCV: {symbol}@{interval} (limit={limit}, as_dataframe={as_dataframe})")

            klines = self.cache.get_klines(
                symbol=symbol,
                interval=interval,
                limit=limit,
                reader="TrainingWorker"
            )

            if not klines or len(klines) == 0:
                logger.error(f"❌ Dados não encontrados: {symbol}@{interval}")
                return None

            n_candles = len(klines)
            logger.debug(f"✅ {n_candles} klines obtidos de {symbol}@{interval}")

            # ================================================================
            # FASE 2: RETORNAR NO FORMATO SOLICITADO
            # ================================================================
            
            if not as_dataframe:
                # --------------------------------------------------------
                # OPÇÃO A: Retornar formato RAW (List[Dict])
                # --------------------------------------------------------
                logger.debug(
                    f"✅ OHLCV fetched (raw): {n_candles} klines de {symbol}@{interval}"
                )
                return klines

            else:
                # --------------------------------------------------------
                # OPÇÃO B: Retornar formato DATAFRAME
                # --------------------------------------------------------
                df = self._convert_to_dataframe(klines)

                if df is None:
                    logger.error(f"❌ Falha ao converter klines para DataFrame")
                    return None

                logger.debug(
                    f"✅ OHLCV fetched (DataFrame): {len(df)} candles de {symbol}@{interval}"
                )
                return df
        
        except Exception as e:
            logger.error(f"❌ Erro ao buscar OHLCV: {e}", exc_info=True)
            return None
        
    def _calculate_features(
        self,
        symbol: str,
        interval: str,
        klines: List[Dict[str, Any]]
    ) -> Optional[pd.DataFrame]:
        """
        Calcula features para treinamento com validação enterprise

        ARQUITETURA APRIMORADA:
        =====================
        1. Passa klines para FeatureEngineering
        2. Recebe DataFrame com features calculadas
        3. Valida qualidade das features (Sistema de 3 Níveis)
        4. Retorna features validadas ou None se crítico

        VALIDAÇÃO ENTERPRISE (3 Níveis):
        ================================
        1. CRÍTICO: < min_samples_after_cleaning → BLOQUEIO
        2. ALERTA: < min_retention_rate ou < min_features → AVISO FORTE
        3. SUBIDEAL: < ideal_retention_rate ou < ideal_features → AVISO LEVE
        4. IDEAL: ≥ thresholds ideais → PERFEITO

        Args:
            symbol: Símbolo (ex: 'BTCUSDT')
            interval: Intervalo (ex: '1h')
            klines: Lista de klines raw do PASSO 1

        Returns:
            DataFrame com features validadas ou None se crítico
        """
        logger = self.logger

        try:
            # Obter requisitos de qualidade baseado no intervalo
            quality_reqs = ML_FEATURE_QUALITY_REQUIREMENTS.get(interval)

            n_input_klines = len(klines)

            logger.info("=" * 80)
            logger.info(f"🔧 INICIANDO FEATURE ENGINEERING: {symbol}@{interval}")
            logger.info(f"   Input: {n_input_klines} klines")
            logger.info(f"   Requisitos de qualidade:")
            logger.info(f"      Min samples pós-limpeza: {quality_reqs['min_samples_after_cleaning']}")
            logger.info(f"      Min retenção: {quality_reqs['min_retention_rate']*100:.0f}%")
            logger.info(f"      Ideal retenção: {quality_reqs['ideal_retention_rate']*100:.0f}%")
            logger.info(f"      Min features: {quality_reqs['min_features']}")
            logger.info(f"      Ideal features: {quality_reqs['ideal_features']}")
            logger.info("=" * 80)

            # ================================================================
            # CALCULAR FEATURES (DELEGA PARA FEATUREENGINEERING)
            # ================================================================
            features_df = self.feature_eng.calculate_features_for_ml(
                klines=klines,
                symbol=f"{symbol}_{interval}",
                interval=interval  # ← FASE 3: Para time features adaptativas
            )

            if features_df is None:
                logger.error(f"❌ FeatureEngineering retornou None")
                return None

            if features_df.empty:
                logger.error(f"❌ FeatureEngineering retornou DataFrame vazio")
                return None

            # ================================================================
            # VALIDAÇÃO DE QUALIDADE DE FEATURES (Sistema de 3 Níveis)
            # ================================================================
            n_samples, n_features = features_df.shape
            retention_rate = n_samples / n_input_klines if n_input_klines > 0 else 0

            logger.info("=" * 80)
            logger.info(f"📊 AVALIAÇÃO DE QUALIDADE DE FEATURES: {symbol}@{interval}")
            logger.info(f"   Output: {n_samples} samples, {n_features} features")
            logger.info(f"   Taxa de retenção: {retention_rate*100:.1f}%")
            logger.info(f"   Perda por lags/rolling: {n_input_klines - n_samples} klines")
            logger.info("=" * 80)

            # NÍVEL 1: CRÍTICO (Bloqueio)
            if n_samples < quality_reqs['min_samples_after_cleaning']:
                logger.error("=" * 80)
                logger.error(f"❌ FEATURE ENGINEERING BLOQUEADO - AMOSTRAS INSUFICIENTES")
                logger.error(f"   Status: CRÍTICO ❌")
                logger.error(f"   Samples após limpeza: {n_samples}")
                logger.error(f"   Mínimo crítico: {quality_reqs['min_samples_after_cleaning']}")
                logger.error(f"   Faltam: {quality_reqs['min_samples_after_cleaning'] - n_samples} samples")
                logger.error(f"   Impacto: TREINAMENTO IMPOSSÍVEL")
                logger.error(f"   Causa provável: Muitos NaNs por lags/rolling (perda {100-retention_rate*100:.1f}%)")
                logger.error(f"   Ação: Coletar mais dados históricos ou reduzir janelas de rolling")
                logger.error("=" * 80)
                raise ValueError(
                    f"Features insuficientes pós-limpeza: {n_samples} < {quality_reqs['min_samples_after_cleaning']}"
                )

            # NÍVEL 2: ALERTA (Permite com aviso forte)
            elif (retention_rate < quality_reqs['min_retention_rate'] or
                  n_features < quality_reqs['min_features']):
                logger.warning("=" * 80)
                logger.warning(f"⚠️ FEATURES COM QUALIDADE ABAIXO DO RECOMENDADO")
                logger.warning(f"   Status: ALERTA ⚠️")
                logger.warning(f"   Samples: {n_samples} (mín: {quality_reqs['min_samples_after_cleaning']})")
                logger.warning(f"   Features: {n_features} (mín: {quality_reqs['min_features']})")
                logger.warning(f"   Retenção: {retention_rate*100:.1f}% (mín: {quality_reqs['min_retention_rate']*100:.0f}%)")

                if retention_rate < quality_reqs['min_retention_rate']:
                    logger.warning(f"   ⚠️ Taxa de retenção baixa: perda excessiva por lags/rolling")
                if n_features < quality_reqs['min_features']:
                    logger.warning(f"   ⚠️ Poucas features: algumas categorias podem ter falhado")

                logger.warning(f"   Impacto: Modelo pode ter QUALIDADE REDUZIDA")
                logger.warning(f"   Recomendação: Coletar mais dados ou revisar feature engineering")
                logger.warning("=" * 80)

            # NÍVEL 3: SUBIDEAL (Permite com aviso leve)
            elif (retention_rate < quality_reqs['ideal_retention_rate'] or
                  n_features < quality_reqs['ideal_features']):
                logger.warning("=" * 80)
                logger.warning(f"⚠️ FEATURES COM QUALIDADE ABAIXO DO IDEAL")
                logger.warning(f"   Status: ACEITÁVEL ⚠️")
                logger.warning(f"   Samples: {n_samples}")
                logger.warning(f"   Features: {n_features} (ideal: {quality_reqs['ideal_features']})")
                logger.warning(f"   Retenção: {retention_rate*100:.1f}% (ideal: {quality_reqs['ideal_retention_rate']*100:.0f}%)")
                logger.warning(f"   Impacto: Modelo funcional, mas pode melhorar")
                logger.warning(f"   Recomendação: Otimizar janelas de lags/rolling para melhor retenção")
                logger.warning("=" * 80)

            # NÍVEL 4: IDEAL (Tudo perfeito!)
            else:
                logger.info("=" * 80)
                logger.info(f"✅ FEATURES COM QUALIDADE IDEAL")
                logger.info(f"   Status: IDEAL ✅")
                logger.info(f"   Samples: {n_samples}")
                logger.info(f"   Features: {n_features}/{quality_reqs['ideal_features']}")
                logger.info(f"   Retenção: {retention_rate*100:.1f}%")
                logger.info(f"   Qualidade esperada: MÁXIMA 🎯")
                logger.info("=" * 80)

            logger.info(f"✅ Features prontas: {features_df.shape}")

            return features_df

        except ValueError as ve:
            # Erro de validação crítica
            logger.error(f"❌ Validação crítica falhou: {ve}")
            return None

        except Exception as e:
            logger.error(
                f"❌ Erro ao calcular features para {symbol}_{interval}: {e}",
                exc_info=True
            )
            return None

    def _calculate_training_stats(
        self,
        features_df: pd.DataFrame
    ) -> Dict[str, Dict[str, float]]:
        """
        📊 Calcula estatísticas de treinamento para Data Drift Detection

        OBJETIVO ENTERPRISE:
        ===================
        Salvar estatísticas das features durante o treinamento para depois
        detectar Data Drift quando fazemos predições em produção.

        MÉTODO:
        ======
        Para cada feature crítica, calculamos:
        - mean: Média
        - std: Desvio padrão
        - min/max: Faixa de valores
        - q25/q75: Quartis (para detectar outliers)

        FEATURES CRÍTICAS MONITORADAS:
        ==============================
        - realized_vol_20: Volatilidade realizada (mercado instável?)
        - volume_rolling_mean_20: Volume médio (liquidez mudou?)
        - rsi_14: RSI (momentum diferente?)
        - returns: Retornos (comportamento mudou?)
        - close_lag_1: Preço recente (range diferente?)

        USO POSTERIOR:
        =============
        Durante predição, comparamos features atuais com estas estatísticas:
        - Se Z-score > 3: Drift moderado (reduzir confidence)
        - Se Z-score > 5: Drift crítico (bloquear predição)

        Args:
            features_df: DataFrame com features do treinamento

        Returns:
            Dict com estatísticas por feature:
            {
                'realized_vol_20': {
                    'mean': 0.023,
                    'std': 0.008,
                    'min': 0.005,
                    'max': 0.15,
                    'q25': 0.018,
                    'q75': 0.028
                },
                ...
            }
        """
        logger = self.logger

        try:
            stats = {}

            # Features críticas para monitorar drift
            # Escolhidas por serem indicadores-chave de mudanças no mercado
            critical_features = [
                'realized_vol_20',         # Volatilidade (indica instabilidade)
                'volume_rolling_mean_20',  # Volume (indica liquidez)
                'rsi_14',                  # RSI (indica momentum)
                'return_1',                # Retornos (indica tendência)
                'return_lag_1',            # Preço recente (indica range)
                'sma_50',                  # SMA 50 (indica tendência média)
                'volume_ratio',            # Volume ratio (indica atividade)
                'atr_14',                  # ATR (indica volatilidade)
            ]

            logger.debug("📊 Calculando estatísticas de treinamento para drift detection...")

            features_found = 0
            for feature in critical_features:
                if feature in features_df.columns:
                    # Calcular estatísticas robustas
                    feature_series = features_df[feature]

                    # Remove NaN se houver algum restante
                    feature_series = feature_series.dropna()

                    if len(feature_series) == 0:
                        logger.warning(f"   ⚠️ Feature {feature} está vazia após dropna()")
                        continue

                    stats[feature] = {
                        'mean': float(feature_series.mean()),
                        'std': float(feature_series.std()),
                        'min': float(feature_series.min()),
                        'max': float(feature_series.max()),
                        'q25': float(feature_series.quantile(0.25)),
                        'q50': float(feature_series.quantile(0.50)),  # Mediana
                        'q75': float(feature_series.quantile(0.75)),
                        'count': int(len(feature_series))
                    }

                    features_found += 1
                    logger.debug(
                        f"   ✅ {feature}: mean={stats[feature]['mean']:.6f}, "
                        f"std={stats[feature]['std']:.6f}"
                    )
                else:
                    logger.warning(f"   ⚠️ Feature crítica não encontrada: {feature}")

            if features_found == 0:
                logger.error("❌ Nenhuma feature crítica encontrada para drift detection!")
                return {}

            logger.info(
                f"✅ Estatísticas calculadas: {features_found} features críticas "
                f"monitoradas para drift detection"
            )

            return stats

        except Exception as e:
            logger.error(f"❌ Erro ao calcular training stats: {e}", exc_info=True)
            return {}

    def _prepare_training_data(
        self,
        features_df: pd.DataFrame,
        symbol: str,
        interval: str,
        target_horizon: int = 1,
        test_size: float = 0.2
    ) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, StandardScaler, List[str]]:
        """
        Prepara dados para treinamento de modelos ML
        
        - Recebe DataFrame(n_samples, 92)
        - Cria target (y) a partir dos dados (retorno futuro)
        - Split temporal sequencial (preserva ordem cronológica)
        - Scaling robusto sem data leakage
        
        PROCESSO:
        1. Validar entrada
        2. Criar target (y = retorno futuro)
        3. Extrair features (X)
        4. Split temporal (80% train, 20% validation)
        5. Scaling (fit no train, transform em ambos)
        6. Validação final
        
        Args:
            features_df: DataFrame com features calculadas
                        Shape: (n_samples, n_features)
                        Index: DatetimeIndex
            target_horizon: Horizonte de predição em períodos (padrão: 1)
                        1 = próximo período
                        5 = 5 períodos à frente
            test_size: Proporção para validação (padrão: 0.2 = 20%)
        
        Returns:
            Tuple contendo:
            - X_train: Features de treino (n_train, n_features)
            - y_train: Target de treino (n_train,)
            - X_val: Features de validação (n_val, n_features)
            - y_val: Target de validação (n_val,)
            - scaler: StandardScaler fitted
            - feature_names: Lista com nomes das features
        
        Raises:
            ValueError: Se dados insuficientes ou formato inválido
        """
        logger = self.logger
        
        try:
            logger.info("=" * 80)
            logger.info("📊 PREPARANDO DADOS DE TREINAMENTO")
            
            # ================================================================
            # FASE 1: VALIDAÇÃO DE ENTRADA
            # ================================================================
            if features_df is None or features_df.empty:
                raise ValueError("Features DataFrame é None ou vazio")
            
            n_samples, n_features = features_df.shape
            
            logger.info(f"   Input shape: {features_df.shape}")
            logger.info(f"   Samples: {n_samples}")
            logger.info(f"   Features: {n_features}")
            
            if n_samples < 100:
                raise ValueError(
                    f"Samples insuficientes: {n_samples} < 100 mínimos"
                )
            
            logger.info("=" * 80)
            
            # ================================================================
            # FASE 2: CRIAR TARGET (y) - FÓRMULA EXPLÍCITA
            # ================================================================
            logger.info("   📊 Criando target (retorno futuro)...")

            # Buscar klines raw para obter close prices
            klines = self._fetch_ohlcv(
                symbol=symbol,
                interval=interval,
                limit=20000,
                as_dataframe=False
            )

            if not klines:
                raise ValueError("Não foi possível buscar klines para criar target")

            # Converter para DataFrame temporário para alinhar timestamps
            klines_df = pd.DataFrame([
                {
                    'timestamp': k['open_time'],
                    'close': float(k['close'])
                }
                for k in klines
            ])

            klines_df['datetime'] = pd.to_datetime(klines_df['timestamp'], unit='ms')
            klines_df.set_index('datetime', inplace=True)

            # Alinhar com features_df usando reindex
            aligned_close = klines_df['close'].reindex(features_df.index)

            # ================================================================
            # CRIAR TARGET COM FÓRMULA EXPLÍCITA
            # ================================================================
            # Target: retorno futuro de t para t+horizon
            # Formula: (close[t+horizon] - close[t]) / close[t]

            future_close = aligned_close.shift(-target_horizon)
            # Multiplicar por 100 transforma 0.005 (0.5%) em 0.5
            # Isso ajuda modelos baseados em gradiente (XGB/LGBM) a convergirem melhor
            target = ((future_close - aligned_close) / aligned_close) * 100.0

            # Log para auditoria
            logger.info(f"   📐 Target formula: (close[t+{target_horizon}] - close[t]) / close[t]")
            logger.info(f"   📊 Target range: [{target.min():.4f}, {target.max():.4f}]")
            logger.info(f"   📊 Target mean: {target.mean():.4f}, std: {target.std():.4f}")

            # ================================================================
            # MASK ÚNICO PARA SINCRONIZAÇÃO
            # ================================================================
            # Validar dados de uma só vez:
            # 1. Features completas (sem NaN)
            # 2. Close price disponível
            # 3. Target disponível (não NaN)

            logger.info("   🔍 Aplicando mask único para sincronização...")

            # Mask de features válidas (nenhuma feature NaN)
            feature_valid_mask = ~features_df.isna().any(axis=1)

            # Mask de close válido
            close_valid_mask = ~aligned_close.isna()

            # Mask de target válido (existe futuro)
            target_valid_mask = ~target.isna()

            # MASK ÚNICO: válido se TODAS as condições são verdadeiras
            combined_mask = feature_valid_mask & close_valid_mask & target_valid_mask

            # Aplicar mask uma única vez
            features_clean = features_df[combined_mask].copy()
            y = target[combined_mask].values

            # ================================================================
            # LOG TRANSPARENTE DE PERDAS
            # ================================================================
            total_samples = len(features_df)
            valid_samples = combined_mask.sum()
            lost_to_features = (~feature_valid_mask).sum()
            lost_to_close = (~close_valid_mask).sum()
            lost_to_target = (~target_valid_mask).sum()
            lost_total = (~combined_mask).sum()
            retention_rate = (valid_samples / total_samples) * 100

            logger.info("=" * 80)
            logger.info("📊 LIMPEZA SINCRONIZADA (Mask Único)")
            logger.info(f"   Total inicial: {total_samples} samples")
            logger.info(f"   Perdidos (features com NaN): {lost_to_features}")
            logger.info(f"   Perdidos (close ausente): {lost_to_close}")
            logger.info(f"   Perdidos (target sem futuro): {lost_to_target}")
            logger.info(f"   Perdidos (total): {lost_total}")
            logger.info(f"   ✅ Válidos finais: {valid_samples} ({retention_rate:.1f}% retenção)")
            logger.info("=" * 80)

            n_valid = len(y)

            if n_valid < 50:
                raise ValueError(
                    f"Samples válidos insuficientes após limpeza: {n_valid} < 50"
                )

            # ================================================================
            # FASE 3: EXTRAIR FEATURES (X) E SALVAR NOMES
            # ================================================================
            logger.debug("   📋 Extraindo features e salvando nomes...")

            # SALVAR NOMES DAS FEATURES antes de converter para numpy
            feature_names = features_clean.columns.tolist()

            # Converter para numpy array
            X = features_clean.values

            logger.debug(f"   X shape: {X.shape}")
            logger.debug(f"   y shape: {y.shape}")
            logger.debug(f"   Feature names: {len(feature_names)} features")

            # ================================================================
            # FASE 3.5: TRATAMENTO DE OUTLIERS
            # ================================================================
            logger.info("   📊 Aplicando Winsorization para outliers extremos...")

            from scipy.stats import mstats

            # Winsorize: clip valores extremos para percentis 0.5% e 99.5%
            # Importante para crypto que tem spikes extremos (pump & dump, liquidations)
            X_winsorized = mstats.winsorize(X, limits=[0.005, 0.005], axis=0)

            # Log de features afetadas
            n_clipped = (X != X_winsorized).sum()
            if n_clipped > 0:
                pct_clipped = (n_clipped / X.size) * 100
                logger.info(
                    f"   🔧 Winsorization aplicada: {n_clipped} valores "
                    f"({pct_clipped:.2f}%) clipped para [p0.5, p99.5]"
                )
            else:
                logger.info("   ✅ Nenhum outlier extremo detectado")

            X = X_winsorized

            # ================================================================
            # FASE 4: SPLIT TEMPORAL (SEQUENCIAL)
            # ================================================================
            logger.debug("   Realizando split temporal...")

            # Calcular índice de split (80/20)
            split_idx = int(n_valid * (1 - test_size))

            # Split sequencial (preserva ordem cronológica)
            X_train = X[:split_idx]
            y_train = y[:split_idx]
            X_val = X[split_idx:]
            y_val = y[split_idx:]

            logger.debug(f"   Train: {X_train.shape[0]} samples")
            logger.debug(f"   Validation: {X_val.shape[0]} samples")

            # ================================================================
            # FASE 5: SCALING ROBUSTO
            # ================================================================
            logger.info("   📊 Aplicando RobustScaler (robusto a outliers)...")

            from sklearn.preprocessing import RobustScaler

            # RobustScaler usa mediana e IQR (menos sensível a outliers que StandardScaler)
            scaler = RobustScaler(quantile_range=(5, 95))

            # Fit APENAS no train (evita data leakage)
            X_train_scaled = scaler.fit_transform(X_train)

            # Transform no validation (usa parâmetros do train)
            X_val_scaled = scaler.transform(X_val)

            logger.info("   ✅ RobustScaler aplicado (mediana + IQR, quantiles 5-95%)")
            logger.info("   💡 Mais robusto a outliers que StandardScaler (mean + std)")
            
            # ================================================================
            # FASE 6: VALIDAÇÃO FINAL
            # ================================================================
            logger.debug("   Validando saída...")
            
            # Verificar NaNs
            if np.isnan(X_train_scaled).any():
                n_nans = np.isnan(X_train_scaled).sum()
                logger.warning(f"⚠️ {n_nans} NaNs detectados em X_train após scaling")
                raise ValueError("NaNs detectados em X_train após scaling")
            
            if np.isnan(X_val_scaled).any():
                n_nans = np.isnan(X_val_scaled).sum()
                logger.warning(f"⚠️ {n_nans} NaNs detectados em X_val após scaling")
                raise ValueError("NaNs detectados em X_val após scaling")
            
            if np.isnan(y_train).any():
                logger.warning("⚠️ NaNs detectados em y_train")
                raise ValueError("NaNs detectados em y_train")
            
            if np.isnan(y_val).any():
                logger.warning("⚠️ NaNs detectados em y_val")
                raise ValueError("NaNs detectados em y_val")
            
            # Verificar infinitos
            if np.isinf(X_train_scaled).any() or np.isinf(X_val_scaled).any():
                logger.warning("⚠️ Valores infinitos detectados nas features")
                raise ValueError("Valores infinitos detectados")
            
            # ================================================================
            # LOG FINAL
            # ================================================================
            logger.info("=" * 80)
            logger.info("✅ DADOS DE TREINAMENTO PREPARADOS")
            logger.info(f"   Input: {n_samples} samples, {n_features} features")
            logger.info(f"   Output (após target): {n_valid} samples válidos")
            logger.info(f"   Train: {X_train_scaled.shape}")
            logger.info(f"   Validation: {X_val_scaled.shape}")
            logger.info(f"   Target horizon: {target_horizon} período(s)")
            logger.info(f"   Test size: {test_size * 100:.0f}%")
            logger.info(f"   Scaler: StandardScaler fitted")
            logger.info(f"   Feature names: {len(feature_names)} salvos")
            logger.info("=" * 80)

            return X_train_scaled, y_train, X_val_scaled, y_val, scaler, feature_names
        
        except ValueError as ve:
            logger.error(f"❌ Validação falhou: {ve}")
            raise
        
        except Exception as e:
            logger.error(
                f"❌ Erro ao preparar dados de treinamento: {e}",
                exc_info=True
            )
            raise

    def _calculate_metrics(self, y_true: np.ndarray, y_pred: np.ndarray) -> Dict[str, float]:
        """
        Calcula métricas apropriadas para predição de returns

        MÉTRICAS ADEQUADAS PARA RETURNS:
        - MAE: Mean Absolute Error (em pontos percentuais)
        - RMSE: Root Mean Squared Error
        - R²: Coefficient of determination
        - Direction Accuracy: % de vezes que prevê direção correta (+/-) [CRÍTICO PARA TRADING]
        - Sharpe-like: Return/Risk do modelo
        - Correlation: Correlação entre predições e valores reais

        EVITAR:
        - MAPE: Inadequado para valores próximos de zero

        Args:
            y_true: Target real (returns)
            y_pred: Target predito (returns)

        Returns:
            Dict com métricas calculadas
        """
        from sklearn.metrics import mean_absolute_error, mean_squared_error, r2_score

        # Métricas básicas
        mae = mean_absolute_error(y_true, y_pred)
        rmse = np.sqrt(mean_squared_error(y_true, y_pred))
        r2 = r2_score(y_true, y_pred)

        # Direction Accuracy (% de acerto de sinal) - CRÍTICO PARA TRADING
        direction_true = np.sign(y_true)
        direction_pred = np.sign(y_pred)
        direction_accuracy = (direction_true == direction_pred).mean()

        # Métricas financeiras
        # Sharpe-like: retorno médio previsto / volatilidade do erro
        prediction_return = y_pred.mean()
        prediction_std = y_pred.std()
        error_std = (y_true - y_pred).std()

        sharpe_like = prediction_return / prediction_std if prediction_std > 0 else 0
        info_ratio = (y_pred.mean() - y_true.mean()) / error_std if error_std > 0 else 0

        # Correlation
        correlation = np.corrcoef(y_true, y_pred)[0, 1] if len(y_true) > 1 else 0

        # MAPE apenas se |y_true| > threshold (evitar divisão por valores pequenos)
        valid_for_mape = np.abs(y_true) > 0.001  # 0.1% threshold
        if valid_for_mape.sum() > 0:
            mape = np.mean(np.abs((y_true[valid_for_mape] - y_pred[valid_for_mape]) / y_true[valid_for_mape])) * 100
        else:
            mape = np.nan

        return {
            'mae': mae,
            'rmse': rmse,
            'r2_score': r2,
            'direction_accuracy': direction_accuracy,  # CRÍTICO
            'sharpe_like': sharpe_like,
            'info_ratio': info_ratio,
            'correlation': correlation,
            'mape': mape,  # Pode ser NaN
            # Métricas de distribuição
            'pred_mean': y_pred.mean(),
            'pred_std': y_pred.std(),
            'true_mean': y_true.mean(),
            'true_std': y_true.std(),
        }

    def _train_single_model(
        self,
        model_name: str,
        X_train: np.ndarray,
        y_train: np.ndarray,
        X_val: np.ndarray,
        y_val: np.ndarray
    ) -> Tuple[Any, Dict]:
        """
        Treina um modelo específico
        
        Args:
            model_name: Nome do modelo ('RandomForest', 'XGBoost', 'LightGBM')
            X_train: Features de treino
            y_train: Target de treino
            X_val: Features de validação
            y_val: Target de validação
            
        Returns:
            (model, metrics)
        """
        try:
            self.logger.info(f"🔧🧠 Treinando {model_name}...")
            
            # Criar modelo
            if model_name == 'RandomForest':
                model = RandomForestRegressor(
                    n_estimators=500,
                    max_depth=12,
                    min_samples_split=20,
                    min_samples_leaf=10,
                    max_features='sqrt',
                    bootstrap=True,
                    random_state=self.random_state,
                    n_jobs=-1
                )
            
            elif model_name == 'XGBoost' and XGBOOST_AVAILABLE:
                model = xgb.XGBRegressor(
                    n_estimators=1000,
                    max_depth=4,
                    learning_rate=0.01,
                    subsample=0.7,
                    colsample_bytree=0.7,
                    reg_alpha=0.1,
                    reg_lambda=1.0,
                    random_state=self.random_state,
                    n_jobs=-1
                )
            
            elif model_name == 'LightGBM' and LIGHTGBM_AVAILABLE:
                model = lgb.LGBMRegressor(
                    n_estimators=1000,
                    max_depth=5,
                    min_child_samples=30,
                    learning_rate=0.01,
                    num_leaves=20,
                    subsample=0.7,
                    colsample_bytree=0.7,
                    reg_alpha=0.1,
                    reg_lambda=0.1,
                    random_state=self.random_state,
                    n_jobs=-1,
                    verbose=-1
                )
            
            else:
                self.logger.error(f"❌ Modelo desconhecido ou biblioteca não disponível: {model_name}")
                return None, {}
            
            # Treinar
            model.fit(X_train, y_train)

            # Validar
            y_pred = model.predict(X_val)

            # Calcular métricas usando função melhorada (ITEM 4 - FASE 2)
            metrics = self._calculate_metrics(y_val, y_pred)

            # Log com métricas de trading
            self.logger.info(
                f"      ✅ {model_name} trained: "
                f"R²={metrics['r2_score']:.4f}, "
                f"MAE={metrics['mae']:.4f}, "
                f"Dir={metrics['direction_accuracy']:.1%}"
            )

            return model, metrics
            
        except Exception as e:
            self.logger.error(f"❌ Erro ao treinar {model_name}: {e}", exc_info=True)
            return None, {}
    
    def _cross_validate_models(
        self,
        trained_models: Dict[str, Any],
        X: np.ndarray,
        y: np.ndarray,
        n_splits: int = 2
    ) -> Dict[str, Dict[str, float]]:
        """
        Cross-validation com TimeSeriesSplit OTIMIZADO para crypto (ITEM 16 - FASE 4)

        MELHORIAS:
        - Janela deslizante: usa apenas últimos N candles (dados recentes)
        - Expanding window (treina com tudo até validation)
        - Métricas de trading incluídas

        ESTRATÉGIA:
        - Fold 1: Train[0:60%] → Val[60%:80%]
        - Fold 2: Train[0:80%] → Val[80%:100%]

        Args:
            trained_models: Dict {model_name: model_instance}
            X: Features completas (n_samples, n_features)
            y: Target completo (n_samples,)
            n_splits: Número de splits para CV (padrão: 2 para crypto)

        Returns:
            Dict com métricas agregadas incluindo direction_accuracy
        """
        logger = self.logger

        try:
            logger.info("=" * 80)
            logger.info(f"🔍 CROSS-VALIDATION TEMPORAL: {len(trained_models)} modelos")

            # ================================================================
            # VALIDAÇÃO DE ENTRADA
            # ================================================================
            if not trained_models:
                logger.warning("⚠️ Nenhum modelo para validar")
                return {}

            if X is None or y is None:
                raise ValueError("X ou y é None")

            if len(X) != len(y):
                raise ValueError(f"X e y têm tamanhos diferentes: {len(X)} vs {len(y)}")

            n_samples = len(X)

            # ================================================================
            # JANELA DESLIZANTE
            # ================================================================
            # Para crypto: usar apenas últimos N candles (janela deslizante)
            # Descarta dados muito antigos que podem ser obsoletos
            window_size = min(n_samples, 5000)  # Max 5000 candles
            X_recent = X[-window_size:]
            y_recent = y[-window_size:]

            logger.info(f"   Total samples: {n_samples}")
            logger.info(f"   Janela recente: {window_size} candles (últimos)")
            logger.info(f"   Features: {X.shape[1]}")
            logger.info(f"   Splits: {n_splits} (expanding window)")

            # ================================================================
            # INICIALIZAR TIME SERIES SPLIT
            # ================================================================
            tscv = TimeSeriesSplit(n_splits=n_splits)

            logger.debug(f"   TimeSeriesSplit configurado com {n_splits} splits")

            # ================================================================
            # CROSS-VALIDATION LOOP
            # ================================================================
            cv_results = {}
            
            for model_name, model in trained_models.items():
                logger.debug(f"   Validando modelo: {model_name}")

                # Armazenar scores de cada fold (incluindo métricas de trading)
                fold_scores = {
                    'mae': [],
                    'rmse': [],
                    'r2': [],
                    'direction_accuracy': [],
                    'correlation': [],
                }

                # Iterar sobre folds (agora usando X_recent/y_recent)
                fold_num = 0
                for train_idx, val_idx in tscv.split(X_recent):
                    fold_num += 1

                    # Split dos dados (JANELA RECENTE)
                    X_train_cv = X_recent[train_idx]
                    X_val_cv = X_recent[val_idx]
                    y_train_cv = y_recent[train_idx]
                    y_val_cv = y_recent[val_idx]

                    # --------------------------------------------------------
                    # SCALING ROBUSTO
                    # --------------------------------------------------------
                    from sklearn.preprocessing import RobustScaler
                    scaler = RobustScaler(quantile_range=(5, 95))
                    X_train_cv_scaled = scaler.fit_transform(X_train_cv)
                    X_val_cv_scaled = scaler.transform(X_val_cv)

                    # --------------------------------------------------------
                    # CLONAR E TREINAR MODELO
                    # --------------------------------------------------------
                    from sklearn.base import clone
                    model_cv = clone(model)

                    try:
                        model_cv.fit(X_train_cv_scaled, y_train_cv)

                        # Predições
                        y_pred = model_cv.predict(X_val_cv_scaled)

                        # Calcular métricas usando função melhorada
                        fold_metrics = self._calculate_metrics(y_val_cv, y_pred)

                        # Armazenar scores
                        fold_scores['mae'].append(fold_metrics['mae'])
                        fold_scores['rmse'].append(fold_metrics['rmse'])
                        fold_scores['r2'].append(fold_metrics['r2_score'])
                        fold_scores['direction_accuracy'].append(fold_metrics['direction_accuracy'])
                        fold_scores['correlation'].append(fold_metrics['correlation'])

                        logger.info(
                            f"      Fold {fold_num}: "
                            f"Dir={fold_metrics['direction_accuracy']:.1%}, "
                            f"MAE={fold_metrics['mae']:.4f}, "
                            f"R²={fold_metrics['r2_score']:.4f}"
                        )

                    except Exception as e:
                        logger.warning(f"      Fold {fold_num} falhou: {e}")
                        continue

                # ============================================================
                # AGREGAR RESULTADOS DO MODELO
                # ============================================================
                if fold_scores['mae']:  # Se houve pelo menos 1 fold bem-sucedido
                    cv_results[model_name] = {
                        'mae_mean': np.mean(fold_scores['mae']),
                        'mae_std': np.std(fold_scores['mae']),
                        'rmse_mean': np.mean(fold_scores['rmse']),
                        'rmse_std': np.std(fold_scores['rmse']),
                        'r2_mean': np.mean(fold_scores['r2']),
                        'r2_std': np.std(fold_scores['r2']),
                        'direction_accuracy_mean': np.mean(fold_scores['direction_accuracy']),
                        'direction_accuracy_std': np.std(fold_scores['direction_accuracy']),
                        'correlation_mean': np.mean(fold_scores['correlation']),
                        'correlation_std': np.std(fold_scores['correlation']),
                        'n_folds': len(fold_scores['mae'])
                    }
                    
                    logger.info(
                        f"   ✅ {model_name} CV: "
                        f"Dir={cv_results[model_name]['direction_accuracy_mean']:.1%} "
                        f"(±{cv_results[model_name]['direction_accuracy_std']:.1%}), "
                        f"MAE={cv_results[model_name]['mae_mean']:.4f} "
                        f"(±{cv_results[model_name]['mae_std']:.4f})"
                    )
                else:
                    logger.warning(f"   ⚠️ {model_name}: Todos os folds falharam")

            # ================================================================
            # LOG FINAL
            # ================================================================
            logger.info("=" * 80)
            logger.info("✅ CROSS-VALIDATION COMPLETA (OTIMIZADA)")
            logger.info(f"   Modelos validados: {len(cv_results)}/{len(trained_models)}")
            logger.info(f"   Folds: {n_splits} (4× mais rápido que 5 folds)")
            logger.info(f"   Janela: últimos {window_size} candles (dados recentes)")
            logger.info("=" * 80)
            
            return cv_results
        
        except Exception as e:
            logger.error(
                f"❌ Erro na cross-validation: {e}",
                exc_info=True
            )
            return {}
    
    def _calculate_feature_importance(
        self,
        trained_models: Dict[str, Any],
        feature_names: List[str]
    ) -> pd.DataFrame:
        """
        Calcula importância das features do ensemble
        
        PROCESSO:
        1. Extrai feature_importances_ de cada modelo
        2. Cria DataFrame com importâncias por modelo
        3. Calcula média entre modelos
        4. Ordena por importância média
        5. Retorna top features
        
        IMPORTANTE:
        - Nem todos os modelos têm feature_importances_
        - RandomForest, XGBoost, LightGBM: TÊM ✅
        - LinearRegression, SVM: NÃO TÊM ❌
        
        Args:
            trained_models: Dict {model_name: model_instance}
            feature_names: Lista de nomes das features
        
        Returns:
            DataFrame com colunas:
            - [model_name]: Importância por modelo
            - 'mean': Importância média
            - 'std': Desvio padrão
            Index: feature names ordenados por importância
        """
        logger = self.logger
        
        try:
            logger.info("📊 Calculando feature importance...")
            
            # ================================================================
            # VALIDAÇÃO
            # ================================================================
            if not trained_models:
                logger.warning("⚠️ Nenhum modelo fornecido")
                return pd.DataFrame()
            
            if not feature_names:
                logger.warning("⚠️ Nenhum nome de feature fornecido")
                return pd.DataFrame()
            
            # ================================================================
            # EXTRAIR IMPORTÂNCIAS
            # ================================================================
            importance_dict = {}
            
            for model_name, model in trained_models.items():
                if hasattr(model, 'feature_importances_'):
                    importances = model.feature_importances_
                    
                    # Validar tamanho
                    if len(importances) != len(feature_names):
                        logger.warning(
                            f"⚠️ {model_name}: Tamanho de importâncias "
                            f"({len(importances)}) != features ({len(feature_names)})"
                        )
                        continue
                    
                    importance_dict[model_name] = importances
                    logger.debug(f"   ✅ {model_name}: {len(importances)} importâncias extraídas")
                else:
                    logger.debug(f"   ⏭️  {model_name}: Não suporta feature_importances_")
            
            # ================================================================
            # CRIAR DATAFRAME
            # ================================================================
            if not importance_dict:
                logger.warning("⚠️ Nenhum modelo com feature_importances_")
                return pd.DataFrame()
            
            # Criar DataFrame
            importance_df = pd.DataFrame(
                importance_dict,
                index=feature_names
            )
            
            # ================================================================
            # NORMALIZAÇÃO POR MODELO
            # ================================================================
            # Normalizar importâncias de cada modelo para somar 1.0
            # Isso remove bias de modelos com scales diferentes
            importance_df_normalized = pd.DataFrame(index=feature_names)

            for model_name in importance_dict.keys():
                raw_importances = importance_df[model_name]
                normalized = raw_importances / raw_importances.sum()  # Soma = 1.0
                importance_df_normalized[model_name] = normalized

            # Calcular estatísticas da versão normalizada
            importance_df_normalized['mean'] = importance_df_normalized.mean(axis=1)
            if len(importance_dict) > 1:
                importance_df_normalized['std'] = importance_df_normalized.std(axis=1)
                importance_df_normalized['cv'] = importance_df_normalized['std'] / importance_df_normalized['mean']  # Coeficiente de variação
            else:
                importance_df_normalized['std'] = 0.0
                importance_df_normalized['cv'] = 0.0

            # Ordenar por importância média
            importance_df_normalized = importance_df_normalized.sort_values('mean', ascending=False)

            # ================================================================
            # ANÁLISE DE MULTICOLINEARIDADE
            # ================================================================
            # Agrupar features por família para entender distribuição
            feature_groups = {
                'price': [f for f in feature_names if any(x in f.lower() for x in ['return', 'spread', 'momentum'])],
                'volume': [f for f in feature_names if 'volume' in f.lower() or 'vwap' in f.lower()],
                'technical': [f for f in feature_names if any(x in f.lower() for x in ['rsi', 'macd', 'bb', 'stoch'])],
                'sma_ema': [f for f in feature_names if 'sma' in f.lower() or 'ema' in f.lower()],
                'lag': [f for f in feature_names if 'lag' in f.lower()],
                'rolling': [f for f in feature_names if 'rolling' in f.lower() or ('std' in f.lower() and 'rolling' not in f.lower())],
                'volatility': [f for f in feature_names if any(x in f.lower() for x in ['atr', 'vol', 'parkinson'])],
                'time': [f for f in feature_names if any(x in f.lower() for x in ['hour', 'day', 'weekend', 'sin', 'cos', 'session', 'period', 'month'])],
            }

            # Calcular importância agregada por grupo
            group_importance = {}
            for group, features in feature_groups.items():
                group_features = [f for f in features if f in importance_df_normalized.index]
                if group_features:
                    group_importance[group] = importance_df_normalized.loc[group_features, 'mean'].sum()

            # ================================================================
            # LOGGING DETALHADO
            # ================================================================
            logger.info("=" * 80)
            logger.info("✅ FEATURE IMPORTANCE CALCULADA (Normalizada)")
            logger.info(f"   Total features: {len(feature_names)}")
            logger.info(f"   Modelos analisados: {len(importance_dict)}")

            logger.info("")
            logger.info("📊 IMPORTÂNCIA POR GRUPO:")
            for group, importance in sorted(group_importance.items(), key=lambda x: x[1], reverse=True):
                logger.info(f"   {group:15s}: {importance:.4f} ({importance*100:.1f}%)")

            logger.info("")
            logger.info("🔝 TOP 10 FEATURES:")
            for i, (feat, row) in enumerate(importance_df_normalized.head(10).iterrows(), 1):
                cv_str = f", CV={row['cv']:.2f}" if 'cv' in row and row['cv'] > 0 else ""
                logger.info(
                    f"   {i:2d}. {feat:30s} → {row['mean']:.4f} "
                    f"(±{row.get('std', 0):.4f}{cv_str})"
                )

            logger.info("=" * 80)

            # Retornar versão normalizada
            return importance_df_normalized
        
        except Exception as e:
            logger.error(
                f"❌ Erro ao calcular feature importance: {e}",
                exc_info=True
            )
            return pd.DataFrame()
    
    def _calculate_ensemble_metrics(
        self,
        model_metrics: Dict[str, Dict[str, float]]
    ) -> Dict[str, float]:
        """
        Calcula métricas agregadas do ensemble com priorização para trading

        MELHORIAS:
        - Direction Accuracy como métrica principal (40% do score)
        - Ranking explícito de modelos por score geral
        - Pesos otimizados para crypto trading
        - Componentes de score transparentes

        Args:
            model_metrics: Dict {model_name: {metric: value}}

        Returns:
            Dict com métricas agregadas e ranking de modelos
        """
        logger = self.logger

        try:
            logger.debug("📊 Calculando métricas do ensemble...")

            # ================================================================
            # VALIDAÇÃO
            # ================================================================
            if not model_metrics:
                logger.warning("⚠️ Nenhuma métrica fornecida")
                return {}

            # ================================================================
            # EXTRAIR MÉTRICAS POR TIPO (incluindo novas métricas)
            # ================================================================
            metrics_by_type = {
                'mae': [],
                'rmse': [],
                'r2_score': [],
                'mape': [],
                'direction_accuracy': [],  # - CRÍTICA
                'sharpe_like': [],
                'correlation': [],
            }

            model_names = []

            for model_name, metrics in model_metrics.items():
                model_names.append(model_name)

                for metric_name in metrics_by_type.keys():
                    value = metrics.get(metric_name)
                    if value is not None and not np.isnan(value):
                        metrics_by_type[metric_name].append({
                            'model': model_name,
                            'value': value
                        })

            # ================================================================
            # CALCULAR AGREGAÇÕES
            # ================================================================
            ensemble_metrics = {}

            for metric_name, values_list in metrics_by_type.items():
                if not values_list:
                    continue

                values = [v['value'] for v in values_list]

                ensemble_metrics[f'{metric_name}_mean'] = np.mean(values)
                ensemble_metrics[f'{metric_name}_median'] = np.median(values)
                ensemble_metrics[f'{metric_name}_std'] = np.std(values)
                ensemble_metrics[f'{metric_name}_min'] = np.min(values)
                ensemble_metrics[f'{metric_name}_max'] = np.max(values)

                # Identificar melhor modelo
                if metric_name in ['mae', 'rmse', 'mape']:
                    best_idx = np.argmin(values)
                elif metric_name in ['r2_score', 'direction_accuracy', 'sharpe_like', 'correlation']:
                    best_idx = np.argmax(values)

                best_model = values_list[best_idx]['model']
                best_value = values_list[best_idx]['value']

                ensemble_metrics[f'best_{metric_name}_model'] = best_model
                ensemble_metrics[f'best_{metric_name}_value'] = best_value

            # ================================================================
            # SCORE GERAL PARA TRADING
            # ================================================================

            # Componentes de score (normalizar para 0-1, onde 1 = melhor)
            components = {}

            # 1. R² (normalizar [-0.5, 1] → [0, 1])
            if 'r2_score_mean' in ensemble_metrics:
                r2 = ensemble_metrics['r2_score_mean']
                components['r2'] = max(0, min(1, (r2 + 0.5) / 1.5))

            # 2. MAE (inverter: menor é melhor)
            if 'mae_mean' in ensemble_metrics:
                mae = ensemble_metrics['mae_mean']
                components['mae'] = 1.0 / (1.0 + 20 * mae)

            # 3. Direction Accuracy (CRÍTICO PARA TRADING)
            if 'direction_accuracy_mean' in ensemble_metrics:
                dir_acc = ensemble_metrics['direction_accuracy_mean']
                # Mapear 0.5-1.0 → 0-1 (50% = baseline = 0 score)
                components['direction'] = max(0, (dir_acc - 0.5) * 2)

            # 4. Correlation
            if 'correlation_mean' in ensemble_metrics:
                corr = ensemble_metrics['correlation_mean']
                components['correlation'] = max(0, corr)

            # ================================================================
            # PESOS PARA TRADING DE CRYPTO (OTIMIZADOS)
            # ================================================================
            weights = {
                'direction': 0.40,     # 40% - MAIS IMPORTANTE para trading
                'mae': 0.25,           # 25% - Magnitude do erro
                'r2': 0.20,            # 20% - Fit quality
                'correlation': 0.15,   # 15% - Correlação das predições
            }

            # Calcular score geral ponderado
            overall_score = sum(
                components.get(metric, 0) * weight
                for metric, weight in weights.items()
            )

            ensemble_metrics['overall_score'] = overall_score
            ensemble_metrics['score_components'] = components
            ensemble_metrics['score_weights'] = weights

            # ================================================================
            # RANKING DE MODELOS (BASEADO EM VALIDATION)
            # ================================================================
            model_rankings = []

            for model_name, metrics in model_metrics.items():
                # Score individual do modelo
                model_components = {
                    'direction': max(0, (metrics.get('direction_accuracy', 0.5) - 0.5) * 2),
                    'mae': 1.0 / (1.0 + 20 * metrics.get('mae', 0.05)),
                    'r2': max(0, min(1, (metrics.get('r2_score', 0) + 0.5) / 1.5)),
                    'correlation': max(0, metrics.get('correlation', 0)),
                }

                model_score = sum(
                    model_components.get(metric, 0) * weights.get(metric, 0)
                    for metric in weights.keys()
                )

                model_rankings.append({
                    'model': model_name,
                    'score': model_score,
                    'direction_accuracy': metrics.get('direction_accuracy', 0),
                    'mae': metrics.get('mae', 0),
                    'r2': metrics.get('r2_score', 0),
                    'correlation': metrics.get('correlation', 0),
                })

            # Ordenar por score
            model_rankings.sort(key=lambda x: x['score'], reverse=True)

            ensemble_metrics['model_rankings'] = model_rankings
            ensemble_metrics['best_model_overall'] = model_rankings[0]['model']
            ensemble_metrics['best_model_score'] = model_rankings[0]['score']

            # ================================================================
            # MÉTRICAS ADICIONAIS
            # ================================================================
            ensemble_metrics['n_models'] = len(model_names)
            ensemble_metrics['model_names'] = model_names

            # ================================================================
            # LOG FINAL MELHORADO
            # ================================================================
            logger.info("=" * 80)
            logger.info("✅ MÉTRICAS DO ENSEMBLE (TRADING-OPTIMIZED)")
            logger.info(f"   Modelos: {len(model_names)}")
            logger.info("")

            # Métricas principais
            if 'direction_accuracy_mean' in ensemble_metrics:
                logger.info(
                    f"   🎯 Direction Accuracy: {ensemble_metrics['direction_accuracy_mean']:.1%} "
                    f"(min: {ensemble_metrics['direction_accuracy_min']:.1%}, "
                    f"max: {ensemble_metrics['direction_accuracy_max']:.1%})"
                )

            if 'mae_mean' in ensemble_metrics:
                logger.info(
                    f"   📊 MAE: {ensemble_metrics['mae_mean']:.4f} "
                    f"(min: {ensemble_metrics['mae_min']:.4f}, "
                    f"max: {ensemble_metrics['mae_max']:.4f})"
                )

            if 'r2_score_mean' in ensemble_metrics:
                logger.info(
                    f"   📈 R² Score: {ensemble_metrics['r2_score_mean']:.4f} "
                    f"(min: {ensemble_metrics['r2_score_min']:.4f}, "
                    f"max: {ensemble_metrics['r2_score_max']:.4f})"
                )

            if 'correlation_mean' in ensemble_metrics:
                logger.info(
                    f"   🔗 Correlation: {ensemble_metrics['correlation_mean']:.4f}"
                )

            logger.info("")
            logger.info(f"   ⭐ Overall Score: {ensemble_metrics['overall_score']:.4f}")
            logger.info("")

            # Ranking de modelos
            logger.info("🏆 RANKING DE MODELOS (Score Geral):")
            for i, ranking in enumerate(model_rankings, 1):
                logger.info(
                    f"   {i}. {ranking['model']:15s} → Score: {ranking['score']:.3f} "
                    f"(Dir: {ranking['direction_accuracy']:.1%}, "
                    f"MAE: {ranking['mae']:.4f}, "
                    f"R²: {ranking['r2']:.3f})"
                )

            logger.info("=" * 80)

            return ensemble_metrics

        except Exception as e:
            logger.error(
                f"❌ Erro ao calcular métricas do ensemble: {e}",
                exc_info=True
            )
            return {}
    
    def _save_models(
        self,
        symbol: str,
        interval: str,
        trained_models: Dict[str, Any],
        scaler: Any,
        ensemble_metrics: Dict[str, float],
        model_metrics: Dict[str, Dict[str, float]],
        cv_metrics: Dict[str, Dict[str, float]],
        feature_importance: Any,
        features_df: pd.DataFrame,  # ← DataFrame com features calculadas
        training_stats: Dict[str, Dict[str, float]],  # ← Estatísticas para Data Drift Detection
        training_metadata: Dict[str, Any]
    ) -> Path:
        """
        Salva modelos treinados em disco com estrutura flat simplificada

        NOVA ARQUITETURA (2025-01-17):
        - Estrutura FLAT: models/{symbol}/{file}
        - SEM subpastas de interval
        - SEM versionamento (sempre sobrescreve)
        - SEM timestamp no nome
        - Naming: {symbol}_{interval}_t{target_horizon}.pkl.gz
        - Manifest único por símbolo com todos os 5 modelos

        ESTRUTURA DE DIRETÓRIOS:
        models/
        ├── BTCUSDT/
        │   ├── BTCUSDT_1h_t3.pkl.gz
        │   ├── BTCUSDT_1h_t3.json
        │   ├── BTCUSDT_1h_t12.pkl.gz
        │   ├── BTCUSDT_1h_t12.json
        │   ├── BTCUSDT_4h_t3.pkl.gz
        │   ├── BTCUSDT_4h_t3.json
        │   ├── BTCUSDT_4h_t6.pkl.gz
        │   ├── BTCUSDT_4h_t6.json
        │   ├── BTCUSDT_1d_t1.pkl.gz
        │   ├── BTCUSDT_1d_t1.json
        │   └── manifest.json
        └── ETHUSDT/
            └── ...

        CONTEÚDO DO MODELO (.pkl.gz):
        {
            'symbol': 'BTCUSDT',
            'interval': '1h',
            'target_horizon': 3,
            'models': {'RandomForest': model1, 'XGBoost': model2, ...},
            'scaler': StandardScaler_instance,
            'feature_names': ['feature_0', 'feature_1', ...],
            'trained_at': 1705327822.123,
            'training_duration_s': 45.3,
            'n_candles_used': 5000,
            'training_stats': {...}
        }

        CONTEÚDO DOS METADADOS (.json):
        {
            'symbol': 'BTCUSDT',
            'interval': '1h',
            'target_horizon': 3,
            'trained_at': '2025-01-15T18:00:45Z',
            'training_duration_s': 45.3,
            'n_candles_used': 5000,
            'n_features': 92,
            'ensemble_metrics': {...},
            'model_metrics': {...},
            'cv_metrics': {...},
            'feature_importance_top10': [...],
            'checksum_sha256': 'abc123...'
        }

        Args:
            symbol: Símbolo (ex: 'BTCUSDT')
            interval: Intervalo (ex: '1h')
            trained_models: Dict {model_name: model_instance}
            scaler: StandardScaler instance
            ensemble_metrics: Métricas agregadas do ensemble
            model_metrics: Métricas individuais por modelo
            cv_metrics: Métricas de cross-validation
            feature_importance: DataFrame ou dict com importâncias
            features_df: DataFrame com features calculadas
            training_stats: Estatísticas para Data Drift Detection
            training_metadata: Metadados adicionais do treinamento

        Returns:
            Path: Caminho do arquivo do modelo salvo (.pkl.gz)

        Raises:
            ValueError: Se dados inválidos
            IOError: Se falha ao salvar
        """
        logger = self.logger

        try:
            # Extrair target_horizon do training_metadata
            target_horizon = training_metadata.get('target_horizon', 1)

            logger.info("=" * 80)
            logger.info(f"💾 SALVANDO MODELOS: {symbol}@{interval} (t{target_horizon})")
            logger.info("=" * 80)

            # ================================================================
            # FASE 1: VALIDAÇÃO DE ENTRADA
            # ================================================================
            if not trained_models:
                raise ValueError("trained_models está vazio")

            if scaler is None:
                raise ValueError("scaler é None")

            logger.debug("   ✅ Validação de entrada: OK")

            # ================================================================
            # FASE 2: CRIAR ESTRUTURA DE DIRETÓRIOS (FLAT)
            # ================================================================
            symbol_dir = self.models_dir / symbol

            # Criar diretório se não existir
            symbol_dir.mkdir(parents=True, exist_ok=True)

            logger.debug(f"   📁 Diretório: {symbol_dir}")

            # ================================================================
            # FASE 3: GERAR NOMES DE ARQUIVOS (SEM VERSÃO/TIMESTAMP)
            # ================================================================
            # Naming: BTCUSDT_1h_t3
            base_filename = f"{symbol}_{interval}_t{target_horizon}"

            model_file = symbol_dir / f"{base_filename}.pkl"
            model_file_compressed = symbol_dir / f"{base_filename}.pkl.gz"
            metadata_file = symbol_dir / f"{base_filename}.json"

            logger.debug(f"   📄 Arquivo modelo: {model_file_compressed.name}")
            logger.debug(f"   📄 Arquivo metadata: {metadata_file.name}")

            # ================================================================
            # FASE 4: PREPARAR DADOS DO MODELO
            # ================================================================

            # Extrair última amostra de features para usar em previsões futuras
            last_features_sample = None
            last_features_timestamp = None

            if features_df is not None and not features_df.empty:
                try:
                    # Converter última linha para dict (sem índice)
                    last_row = features_df.iloc[-1]
                    last_features_sample = last_row.to_dict()

                    # Salvar timestamp se disponível
                    if hasattr(features_df, 'index') and len(features_df.index) > 0:
                        last_features_timestamp = features_df.index[-1]
                        # Converter Timestamp do pandas para float (Unix timestamp)
                        if isinstance(last_features_timestamp, pd.Timestamp):
                            last_features_timestamp = last_features_timestamp.timestamp()
                    else:
                        last_features_timestamp = time.time()

                    logger.info(
                        f"   ✅ Última amostra de features extraída: "
                        f"{len(last_features_sample)} features"
                    )
                except Exception as e:
                    logger.warning(f"   ⚠️ Erro ao extrair features: {e}")
                    last_features_sample = None
                    last_features_timestamp = None
            else:
                logger.warning("   ⚠️ features_df está vazio ou None, não será salvo")

            # ================================================================
            # CRIAR model_data COM target_horizon
            # ================================================================
            model_data = {
                'symbol': symbol,
                'interval': interval,
                'target_horizon': target_horizon,  # ← Adicionar target_horizon
                'models': trained_models,
                'scaler': scaler,
                'trained_at': training_metadata.get('trained_at', time.time()),
                'training_duration_s': training_metadata.get('training_duration_s', 0),
                'n_candles_used': training_metadata.get('n_candles_used', 0),
                'n_features': training_metadata.get('n_features', 0),
                'feature_names': training_metadata.get('feature_names', []),
                'last_features_sample': last_features_sample,
                'last_features_timestamp': last_features_timestamp,
                'training_stats': training_stats,  # ← Estatísticas para Data Drift Detection
            }

            logger.info(f"   📦 Modelo preparado: {len(trained_models)} modelos, {model_data['n_features']} features")

            # ================================================================
            # FASE 5: SALVAR MODELO (PICKLE + GZIP)
            # ================================================================
            # Salvar pickle não comprimido primeiro
            with open(model_file, 'wb') as f:
                pickle.dump(model_data, f, protocol=pickle.HIGHEST_PROTOCOL)

            logger.info(f"   💾 Pickle salvo: {model_file.stat().st_size / 1024:.2f} KB")

            # Comprimir com gzip
            with open(model_file, 'rb') as f_in:
                with gzip.open(model_file_compressed, 'wb', compresslevel=6) as f_out:
                    shutil.copyfileobj(f_in, f_out)

            compressed_size = model_file_compressed.stat().st_size
            original_size = model_file.stat().st_size
            compression_ratio = (1 - compressed_size / original_size) * 100

            logger.debug(
                f"   🗜️  Comprimido: {compressed_size / 1024:.2f} KB "
                f"(economia: {compression_ratio:.1f}%)"
            )

            # Remover arquivo não comprimido
            model_file.unlink()

            # ================================================================
            # FASE 6: CALCULAR CHECKSUM
            # ================================================================
            checksum = self._calculate_checksum(model_file_compressed)

            logger.debug(f"   🔐 Checksum: {checksum[:16]}...")

            # ================================================================
            # FASE 7: PREPARAR METADADOS
            # ================================================================
            # Converter feature_importance para formato JSON-serializável
            feature_importance_serializable = self._serialize_feature_importance(
                feature_importance
            )

            metadata = {
                'symbol': symbol,
                'interval': interval,
                'target_horizon': target_horizon,  # ← Adicionar target_horizon
                'schema_version': 1,
                'model_file': f"{base_filename}.pkl.gz",
                'trained_at': datetime.fromtimestamp(
                    model_data['trained_at']
                ).isoformat() + 'Z',
                'trained_at_timestamp': model_data['trained_at'],
                'training_duration_s': model_data['training_duration_s'],
                'n_candles_used': model_data['n_candles_used'],
                'n_features': model_data['n_features'],
                'n_samples_train': training_metadata.get('n_samples_train', 0),
                'n_samples_val': training_metadata.get('n_samples_val', 0),
                'ensemble_metrics': ensemble_metrics,
                'model_metrics': model_metrics,
                'cv_metrics': cv_metrics,
                'feature_importance_top10': feature_importance_serializable,
                'model_names': list(trained_models.keys()),
                'checksum_sha256': checksum,
                'file_size_bytes': compressed_size,
                'file_size_kb': compressed_size / 1024,
                'compressed': True,
                'compression_ratio': compression_ratio,
                'python_version': f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}",
                'sklearn_version': self._get_sklearn_version(),
                'saved_at': datetime.now().isoformat() + 'Z'
            }

            # ================================================================
            # FASE 8: SALVAR METADADOS (JSON)
            # ================================================================
            # Converter tipos numpy para Python nativos (JSON-serializável)
            metadata_serializable = self._convert_numpy_to_python(metadata)

            with open(metadata_file, 'w', encoding='utf-8') as f:
                json.dump(metadata_serializable, f, indent=2, ensure_ascii=False)

            logger.debug(f"   📝 Metadados salvos: {metadata_file.stat().st_size / 1024:.2f} KB")

            # ================================================================
            # FASE 9: ATUALIZAR MANIFESTO
            # ================================================================
            self._update_manifest(
                symbol_dir,
                symbol,
                interval,
                target_horizon,
                metadata
            )

            logger.debug("   📋 Manifesto atualizado")

            # ================================================================
            # LOG FINAL
            # ================================================================
            logger.info("=" * 80)
            logger.info(f"✅ MODELOS SALVOS COM SUCESSO: {symbol}@{interval} (t{target_horizon})")
            logger.info(f"   Arquivo: {model_file_compressed.name}")
            logger.info(f"   Tamanho: {compressed_size / 1024:.2f} KB")
            logger.info(f"   Compressão: {compression_ratio:.1f}%")
            logger.info(f"   Checksum: {checksum[:16]}...")
            logger.info(f"   Modelos: {', '.join(trained_models.keys())}")
            logger.info(f"   Features: {model_data['n_features']}")
            logger.info(f"   R² Score: {ensemble_metrics.get('r2_score_mean', 0):.4f}")
            logger.info("=" * 80)

            return model_file_compressed

        except Exception as e:
            logger.error(
                f"❌ Erro ao salvar modelos para {symbol}@{interval}: {e}",
                exc_info=True
            )
            raise

    def _calculate_checksum(self, filepath: Path) -> str:
        """
        Calcula SHA256 checksum de um arquivo
        
        Args:
            filepath: Caminho do arquivo
        
        Returns:
            str: Checksum hexadecimal
        """
        try:
            sha256 = hashlib.sha256()
            
            with open(filepath, 'rb') as f:
                # Ler em chunks para não sobrecarregar memória
                for chunk in iter(lambda: f.read(8192), b''):
                    sha256.update(chunk)
            
            return sha256.hexdigest()
        
        except Exception as e:
            self.logger.error(f"❌ Erro ao calcular checksum: {e}")
            return "error"


    def _convert_numpy_to_python(self, obj: Any) -> Any:
        """
        Converte recursivamente tipos numpy para tipos Python nativos (JSON-serializável)

        Args:
            obj: Objeto a ser convertido (dict, list, numpy types, etc.)

        Returns:
            Objeto com tipos Python nativos
        """
        import numpy as np
        import pandas as pd

        # Tipos numpy scalar
        if isinstance(obj, (np.integer, np.int32, np.int64)):
            return int(obj)
        elif isinstance(obj, (np.floating, np.float32, np.float64)):
            return float(obj)
        elif isinstance(obj, np.bool_):
            return bool(obj)
        elif isinstance(obj, np.ndarray):
            return obj.tolist()

        # Tipos pandas
        elif isinstance(obj, pd.Timestamp):
            return obj.isoformat()
        elif isinstance(obj, pd.Series):
            return obj.to_dict()
        elif isinstance(obj, pd.DataFrame):
            return obj.to_dict(orient='records')

        # Dict recursivo
        elif isinstance(obj, dict):
            return {
                key: self._convert_numpy_to_python(value)
                for key, value in obj.items()
            }

        # List recursivo
        elif isinstance(obj, (list, tuple)):
            return [self._convert_numpy_to_python(item) for item in obj]

        # Tipos Python nativos (já serializáveis)
        else:
            return obj


    def _serialize_feature_importance(self, feature_importance: Any) -> list:
        """
        Serializa feature importance para formato JSON
        
        Args:
            feature_importance: DataFrame ou dict com importâncias
        
        Returns:
            list: Top 10 features como lista de dicts
        """
        try:
            import pandas as pd
            
            if feature_importance is None:
                return []
            
            # Se é DataFrame
            if isinstance(feature_importance, pd.DataFrame):
                if 'mean' in feature_importance.columns:
                    top_10 = feature_importance.nlargest(10, 'mean')
                    
                    return [
                        {
                            'feature': str(idx),
                            'importance': float(row['mean']),
                            'std': float(row.get('std', 0))
                        }
                        for idx, row in top_10.iterrows()
                    ]
            
            # Se é dict
            elif isinstance(feature_importance, dict):
                sorted_features = sorted(
                    feature_importance.items(),
                    key=lambda x: x[1],
                    reverse=True
                )[:10]
                
                return [
                    {'feature': str(feat), 'importance': float(imp)}
                    for feat, imp in sorted_features
                ]
            
            return []
        
        except Exception as e:
            self.logger.warning(f"⚠️ Erro ao serializar feature importance: {e}")
            return []


    def _get_sklearn_version(self) -> str:
        """Retorna versão do sklearn"""
        try:
            import sklearn
            return sklearn.__version__
        except:
            return "unknown"


    def _update_manifest(
        self,
        directory: Path,
        symbol: str,
        interval: str,
        target_horizon: int,
        metadata: dict
    ):
        """
        Atualiza arquivo manifest.json com lista de todos os modelos do símbolo

        ARQUITETURA (2025-01-17):
        - Manifest único por símbolo (não por interval)
        - Lista todos os 5 modelos treinados
        - SEM histórico de versões
        - Estrutura simplificada

        Args:
            directory: Diretório do símbolo onde salvar manifest
            symbol: Símbolo
            interval: Intervalo do modelo
            target_horizon: Horizonte de previsão
            metadata: Metadados completos do modelo
        """
        try:
            manifest_file = directory / "manifest.json"

            # Carregar manifest existente ou criar novo
            if manifest_file.exists():
                with open(manifest_file, 'r', encoding='utf-8') as f:
                    manifest = json.load(f)
            else:
                manifest = {
                    'symbol': symbol,
                    'models': []
                }

            # Procurar se já existe entrada para este modelo
            model_key = f"{interval}_t{target_horizon}"
            existing_index = None
            for i, model_entry in enumerate(manifest['models']):
                if (model_entry.get('interval') == interval and
                    model_entry.get('target_horizon') == target_horizon):
                    existing_index = i
                    break

            # Criar nova entrada de modelo
            model_entry = {
                'interval': interval,
                'target_horizon': target_horizon,
                'file': metadata['model_file'],
                'trained_at': metadata['trained_at'],
                'metrics': {
                    'r2_score': metadata['ensemble_metrics'].get('r2_score_mean', 0),
                    'mae': metadata['ensemble_metrics'].get('mae_mean', 0),
                    'mape': metadata['ensemble_metrics'].get('mape_mean', 0),
                    'direction_accuracy': metadata['ensemble_metrics'].get('direction_accuracy_mean', 0)
                },
                'n_candles': metadata['n_candles_used'],
                'file_size_kb': metadata['file_size_kb']
            }

            # Atualizar ou adicionar entrada
            if existing_index is not None:
                manifest['models'][existing_index] = model_entry
            else:
                manifest['models'].append(model_entry)

            # Ordenar modelos por interval e target_horizon
            manifest['models'].sort(key=lambda x: (x['interval'], x['target_horizon']))

            # Atualizar timestamp
            manifest['last_updated'] = datetime.now().isoformat() + 'Z'

            # Salvar manifest atualizado
            with open(manifest_file, 'w', encoding='utf-8') as f:
                json.dump(manifest, f, indent=2, ensure_ascii=False)

            self.logger.debug(f"   📋 Manifest atualizado: {len(manifest['models'])} modelos")

        except Exception as e:
            self.logger.warning(f"⚠️ Erro ao atualizar manifest: {e}")

    # ============================================================================
    # MÉTODO AUXILIAR: CARREGAR MODELO
    # ============================================================================

    def load_model(
        self,
        symbol: str,
        interval: str,
        version: Optional[int] = None
    ) -> Optional[dict]:
        """
        Carrega modelo salvo do disco
        
        Args:
            symbol: Símbolo
            interval: Intervalo
            version: Versão específica (None = carregar latest)
        
        Returns:
            dict: Dados do modelo ou None se não encontrado
        """
        logger = self.logger
        
        try:
            symbol_dir = self.models_dir / symbol / interval
            
            if not symbol_dir.exists():
                logger.warning(f"⚠️ Diretório não encontrado: {symbol_dir}")
                return None
            
            # Determinar arquivo a carregar
            if version is None:
                # Carregar latest
                model_file = symbol_dir / f"{symbol}_{interval}_latest.pkl.gz"
            else:
                # Buscar versão específica
                pattern = f"{symbol}_{interval}_v{version}_*.pkl.gz"
                files = list(symbol_dir.glob(pattern))
                
                if not files:
                    logger.warning(f"⚠️ Versão não encontrada: v{version}")
                    return None
                
                model_file = files[0]
            
            if not model_file.exists():
                logger.warning(f"⚠️ Arquivo não encontrado: {model_file}")
                return None
            
            # Descomprimir e carregar
            with gzip.open(model_file, 'rb') as f:
                model_data = pickle.load(f)
            
            logger.info(f"✅ Modelo carregado: {model_file.name}")
            
            return model_data
        
        except Exception as e:
            logger.error(f"❌ Erro ao carregar modelo: {e}", exc_info=True)
            return None

# ===========================================================================================
# PREDICTION ENGINE - REAL-TIME ML PREDICTIONS
# ===========================================================================================

class PredictionEngine(QObject):
    """
    PredictionEngine - Engine de Previsões ML em Tempo Real

    FILOSOFIA:
    Este engine executa em QThread separado com timer periódico, gerando previsões
    automaticamente para símbolos prioritários SEM BLOQUEAR a UI.

    CARACTERÍSTICAS:
        - Executa em thread separada (via moveToThread)
        - Timer periódico: gera previsões a cada 30s-1min
        - Priority queue: processa símbolos prioritários primeiro
        - Cache-aware: usa cache de previsões (TTL 5min)
        - Ensemble prediction: combina múltiplos modelos
        - Confidence scoring: calcula confiança robusta
        - Anomaly detection: detecta previsões anômalas

    RESPONSABILIDADES:
        ✓ Buscar features atuais do cache
        ✓ Fazer previsões com modelos treinados
        ✓ Calcular ensemble prediction
        ✓ Calcular confidence score
        ✓ Detectar anomalias
        ✓ Armazenar previsões no cache
        ✓ Emitir sinais de previsões prontas

    FLUXO DE PREVISÃO:
        1. Timer dispara (a cada 30s)
        2. Para cada símbolo prioritário:
            a. Verifica cache de previsões (TTL 5min)
            b. Se cache miss:
                i.   Busca features atuais (cache L2)
                ii.  Verifica se modelo existe
                iii. Faz ensemble prediction
                iv.  Calcula confidence
                v.   Detecta anomalias
                vi.  Armazena no cache (L1 + local)
                vii. Emite prediction_generated

    SINAIS:
        - prediction_generated(symbol, horizon, prediction):  previsão
        - anomaly_detected(symbol, type, details): Anomalia detectada
        - confidence_low(symbol, confidence): Confiança baixa
        - error_occurred(type, message): Erro no engine

    THREAD-SAFETY:
        - Não acessa diretamente MLSystem.trained_models (usa cópia read-only)
        - Comunicação via sinais Qt
        - Mutex próprio para estado interno
        - NO PARENT quando criado

    INTEGRAÇÃO COM CACHE:
        - Lê: Features (L2, TTL 5min), Model metadata (L3)
        - Escreve: Predictions (L1, TTL 1h)
    
    Executa em QThread separado com timer periódico.
    
    IMPORTANTE: NÃO TER PARENT quando criado (será movido para thread)
    """
    
    # ========== SINAIS ==========
    prediction_generated = Signal(str, str, dict)  # symbol, horizon, prediction
    anomaly_detected = Signal(str, str, dict)  # symbol, type, details
    confidence_low = Signal(str, float)  # symbol, confidence
    error_occurred = Signal(str, str)  # error_type, message
    
    def __init__(
        self,
        cache_system,
        feature_engineering,
        config: Dict[str, Any]
    ):
        """
        Inicializa PredictionEngine
        
        CRITICAL: NÃO passar parent aqui! Será movido para outra thread.
        
        Args:
            cache_system: Instância do CacheSystem
            config: Configurações ML
        """
        super().__init__()  # NO PARENT!
        
        # Logger
        self.logger = logging.getLogger('PredictionEngine')
        self.logger.info("🔧 PredictionEngine instanciado (aguardando moveToThread)")
        
        # Dependências
        self.cache = cache_system
        self.feature_eng = feature_engineering
        self.config = config
        
        # Thread safety
        self.mutex = QMutex()
        
        # Estado
        self.trained_models: Dict[str, Dict] = {}  # Referência read-only (atualizada pelo MLSystem)
        self.prediction_cache: Dict[Tuple[str, str], Tuple[float, Dict]] = {}  # (symbol, horizon) -> (timestamp, prediction)
        self.priority_symbols: List[str] = []
        
        # Timer para execução periódica
        self.prediction_timer = QTimer()
        self.prediction_timer.timeout.connect(self.generate_predictions)
        
        # Configurações
        self.prediction_interval_ms = config.get('prediction_interval_ms', 30000)  # 30s default
        self.horizons = config.get('horizons', {
            'micro': 3,      # 3h - Scalping
            'tatico': 12,    # 12h - Grid entry
            'diario': 24     # 24h - Grid exit
        })
        self.min_confidence = config.get('min_confidence', 0.6)
        self.anomaly_threshold = config.get('anomaly_threshold', 3.0)  # 3 sigma
        self.prediction_cache_ttl = config.get('prediction_cache_ttl', 300)  # 5min
        self.max_symbols_per_cycle = config.get('max_symbols_per_cycle', 50)
        
        # Estatísticas
        self.stats = {
            'total_predictions': 0,
            'successful_predictions': 0,
            'failed_predictions': 0,
            'cache_hits': 0,
            'cache_misses': 0,
            'features_from_model': 0,  # ← NOVO: Features carregadas do modelo
            'anomalies_detected': 0,
            'low_confidence_count': 0,
            'last_cycle_time': None,
            'average_prediction_time_ms': 0.0,
        }
        
        self.logger.info(f"📊 Configurações do PredictionEngine:")
        self.logger.info(f"   - Interval: {self.prediction_interval_ms}ms")
        self.logger.info(f"   - Horizons: {self.horizons}")
        self.logger.info(f"   - Min confidence: {self.min_confidence}")
        self.logger.info(f"   - Anomaly threshold: {self.anomaly_threshold}σ")
        self.logger.info(f"   - Cache TTL: {self.prediction_cache_ttl}s")
    
    # ========== LIFECYCLE ==========
    
    def start(self):
        """
        Inicia engine (timer)
        """
        self.logger.info("="*80)
        self.logger.info("INICIANDO PREDICTION ENGINE")
        self.logger.info("="*80)
        
        #self.prediction_timer.start(self.prediction_interval_ms)
        self.logger.info(f"✅ Timer iniciado ({self.prediction_interval_ms}ms)")
    
    def stop(self):
        """
        Para engine
        """
        self.logger.info("⏹️ Parando PredictionEngine...")
        self.prediction_timer.stop()
        self.logger.info("✅ PredictionEngine parado")
    
    # ========== MÉTODOS PÚBLICOS ==========
    
    def set_priority_symbols(self, symbols: List[str]):
        """
        Define símbolos prioritários para previsão
        
        Args:
            symbols: Lista de símbolos
        """
        with QMutexLocker(self.mutex):
            self.priority_symbols = symbols.copy()
            self.logger.debug(f"📋 Priority symbols updated: {len(symbols)} symbols")
    
    def add_priority_symbol(self, symbol: str):
        """
        Adiciona símbolo à priority queue
        
        Args:
            symbol: Símbolo a adicionar
        """
        with QMutexLocker(self.mutex):
            if symbol not in self.priority_symbols:
                self.priority_symbols.append(symbol)
                self.logger.debug(f"➕ Added to priority: {symbol}")
    
    def update_models(self, models: Dict[str, Dict]):
        """
        Atualiza referência aos modelos treinados E extrai símbolos prioritários

        Chamado pelo MLSystem quando novos modelos são treinados

        LÓGICA:
            1. Atualiza dict trained_models (referência read-only)
            2. Extrai lista ÚNICA de símbolos dos modelos
            3. Popula self.priority_symbols para uso no timer periódico

        ESTRUTURA DO DICT models:
            models = {
                "BTCUSDT:1h:t3": {
                    'symbol': 'BTCUSDT',
                    'interval': '1h',
                    'target_horizon': 3,
                    'model_file_path': '...',
                    'loaded': False,
                    'metrics': {...},
                    ...
                },
                "BTCUSDT:4h:t6": {...},
                "ETHUSDT:1h:t12": {...},
                ...
            }

        EXEMPLO:
            models = {
                "BTCUSDT:1h:t3": {'symbol': 'BTCUSDT', 'target_horizon': 3, ...},
                "BTCUSDT:4h:t6": {'symbol': 'BTCUSDT', 'target_horizon': 6, ...},
                "ETHUSDT:1h:t12": {'symbol': 'ETHUSDT', 'target_horizon': 12, ...},
            }

            → priority_symbols = ['BTCUSDT', 'ETHUSDT']

        Args:
            models: Dict {model_key: model_info}
                    model_key formato: "SYMBOL:INTERVAL:tHORIZON"
                    model_info contém 'symbol', 'interval', 'target_horizon', etc.
        """
        logger = self.logger

        with QMutexLocker(self.mutex):
            # ================================================================
            # FASE 1: Atualizar trained_models (cópia read-only)
            # ================================================================
            self.trained_models = models.copy()

            # ================================================================
            # FASE 2: Extrair símbolos únicos dos modelos
            # ================================================================
            # Usar set() para eliminar duplicatas automaticamente
            # (um símbolo pode ter múltiplos intervalos: 1h, 4h, 1d, etc)
            symbols_set = set()

            for model_key, model_info in models.items():
                symbol = model_info.get('symbol')

                if symbol:
                    symbols_set.add(symbol)
                else:
                    # Fallback: extrair do model_key (formato "SYMBOL:INTERVAL:tHORIZON")
                    if ':' in model_key:
                        symbol_from_key = model_key.split(':')[0]
                        symbols_set.add(symbol_from_key)
                        logger.warning(
                            f"⚠️ model_info sem campo 'symbol', extraído de key: {symbol_from_key}"
                        )

            # ================================================================
            # FASE 3: Atualizar priority_symbols (lista para iteração)
            # ================================================================
            self.priority_symbols = sorted(list(symbols_set))  # Ordenar para consistência

            # ================================================================
            # LOGS E MÉTRICAS
            # ================================================================
            logger.info(
                f"🔄 Modelos atualizados: {len(models)} modelos, "
                f"{len(self.priority_symbols)} símbolos únicos"
            )

            # Mostrar model_keys recebidos
            if models:
                sample_keys = list(models.keys())[:5]  # Primeiros 5
                logger.info(f"   🔑 Model keys (amostra): {sample_keys}")

            if self.priority_symbols:
                # Log dos primeiros 10 símbolos (evitar spam)
                sample_symbols = self.priority_symbols[:10]
                more_count = len(self.priority_symbols) - 10

                if more_count > 0:
                    logger.info(f"   📊 Símbolos prioritários: {sample_symbols} (+{more_count} outros)")
                else:
                    logger.info(f"   📊 Símbolos prioritários: {sample_symbols}")
            else:
                logger.warning("   ⚠️ Nenhum símbolo extraído dos modelos!")
    
    def get_stats(self) -> Dict[str, Any]:
        """
        Retorna estatísticas (thread-safe)
        
        Returns:
            Dict com estatísticas
        """
        with QMutexLocker(self.mutex):
            return self.stats.copy()
    
    # ========== SLOTS ==========
    
    @Slot()
    def generate_predictions(self):
        """
        Gera previsões para símbolos prioritários
        
        Executado pelo timer a cada N segundos
        """
        cycle_start_time = time.time()
        
        try:
            # Obter priority symbols (thread-safe)
            with QMutexLocker(self.mutex):
                symbols_to_process = self.priority_symbols[:self.max_symbols_per_cycle]
                if not symbols_to_process:
                    self.logger.info("📭 Nenhum símbolo prioritário para processar")
                    return
            
            predictions_generated = 0

            self._increment_stat('cache_misses')

            self.logger.info(f"🔄 Prediction cycle iniciado: {len(symbols_to_process)} símbolos")
            
            for symbol in symbols_to_process:
                try:
                    # Processar cada horizonte
                    for horizon_name, horizon_hours in self.horizons.items():
                        # Verificar cache local
                        cached_pred = self._check_prediction_cache(symbol, horizon_name)
                        if cached_pred:
                            self._increment_stat('cache_hits')
                            continue  # Cache hit, pular
                        
                        # Gerar previsão
                        prediction = self._generate_single_prediction(symbol, horizon_name, horizon_hours)
                        
                        if prediction:
                            predictions_generated += 1
                            self._increment_stat('successful_predictions')
                            
                            # Armazenar no cache
                            self._store_prediction(symbol, horizon_name, prediction)
                            
                            # Emitir sinal
                            self.prediction_generated.emit(symbol, horizon_name, prediction)
                        else:
                            self._increment_stat('failed_predictions')

                except Exception as e:
                    self.logger.error(f"❌ Erro ao processar {symbol}: {e}", exc_info=True)
                    self._increment_stat('failed_predictions')
                    self.error_occurred.emit("PREDICTION_ERROR", f"{symbol}: {str(e)}")
            
            # Atualizar stats do ciclo
            cycle_duration = time.time() - cycle_start_time
            with QMutexLocker(self.mutex):
                self.stats['last_cycle_time'] = datetime.now().isoformat()
                self.stats['last_cycle_duration_s'] = cycle_duration

            self.logger.info(f"✅ Prediction cycle completo: {predictions_generated} previsões "
                             f"em {cycle_duration:.2f}s")
            
        except Exception as e:
            self.logger.error(f"❌ Erro no prediction cycle: {e}", exc_info=True)
            self.error_occurred.emit("CYCLE_ERROR", str(e))
    
    # ========== MÉTODOS PRIVADOS ==========

    def _load_model_from_disk(self, model_key: str) -> bool:
        """
        Carrega modelo do disco (LAZY LOADING)

        Chamado quando modelo ainda não foi carregado em memória.
        Lê arquivo .pkl.gz e popula models/scaler no dict.

        Args:
            model_key: Chave do modelo (formato "symbol:interval:tHORIZON")

        Returns:
            bool: True se carregou com sucesso, False caso contrário
        """
        try:
            with QMutexLocker(self.mutex):
                # Verificar se modelo existe
                if model_key not in self.trained_models:
                    self.logger.warning(f"⚠️ Modelo não encontrado: {model_key}")
                    return False

                model_info = self.trained_models[model_key]

                # Verificar se já está carregado
                if model_info.get('loaded', False):
                    self.logger.debug(f"✅ Modelo já carregado: {model_key}")
                    return True

                # Obter caminho do arquivo
                model_file_path = model_info.get('model_file_path')
                if not model_file_path:
                    self.logger.error(f"❌ Path do modelo não encontrado: {model_key}")
                    return False

                # Verificar se arquivo existe
                model_path = Path(model_file_path)
                if not model_path.exists():
                    self.logger.error(f"❌ Arquivo não encontrado: {model_file_path}")
                    return False

            # Carregar arquivo (FORA do lock para não bloquear)
            self.logger.info(f"📥 Carregando modelo do disco: {model_key}")

            import gzip
            import pickle

            with gzip.open(model_path, 'rb') as f:
                model_data = pickle.load(f)

            # Extrair models, scaler e features
            trained_models = model_data.get('models', {})
            scaler = model_data.get('scaler')
            last_features_sample = model_data.get('last_features_sample')
            last_features_timestamp = model_data.get('last_features_timestamp')
            feature_names = model_data.get('feature_names', [])
            training_stats = model_data.get('training_stats', {})  # Carregar training_stats

            if not trained_models or scaler is None:
                self.logger.error(f"❌ Dados inválidos no arquivo: {model_file_path}")
                return False

            # Atualizar dict com dados carregados (incluindo features e training_stats)
            with QMutexLocker(self.mutex):
                self.trained_models[model_key]['models'] = trained_models
                self.trained_models[model_key]['scaler'] = scaler
                self.trained_models[model_key]['feature_names'] = feature_names
                self.trained_models[model_key]['last_features_sample'] = last_features_sample
                self.trained_models[model_key]['last_features_timestamp'] = last_features_timestamp
                self.trained_models[model_key]['training_stats'] = training_stats
                self.trained_models[model_key]['loaded'] = True

            # Log com informação sobre features e drift detection
            features_info = ""
            if last_features_sample:
                age_hours = (time.time() - last_features_timestamp) / 3600 if last_features_timestamp else 999
                features_info = f", features: {len(last_features_sample)} (idade: {age_hours:.1f}h)"

            drift_info = ""
            if training_stats:
                drift_info = f", drift_detection: {len(training_stats)} features"

            self.logger.info(f"✅ Modelo carregado com sucesso: {model_key} "
                           f"({len(trained_models)} sub-models, "
                           f"{model_path.stat().st_size / 1024:.1f} KB{features_info}{drift_info})")

            return True

        except Exception as e:
            self.logger.error(f"❌ Erro ao carregar modelo {model_key}: {e}", exc_info=True)
            return False

    def _generate_single_prediction(
        self, symbol: str, horizon_name: str, horizon_hours: int
    ) -> Optional[Dict]:
        """
        🚀 ENTERPRISE PREDICTION ENGINE - Multi-Timeframe Ensemble com Consenso

        ARQUITETURA REVOLUCIONÁRIA:
        ========================
        Este método implementa um sistema de predição enterprise-grade com:

        1. MULTI-TIMEFRAME ANALYSIS (1h, 4h, 1d)
           - Busca modelos treinados em múltiplos timeframes
           - Combina perspectivas de curto, médio e longo prazo
           - Feature engineering adaptativo por timeframe

        2. ENSEMBLE METHODS
           - Hard Voting: Consenso democrático (maioria dos votos)
           - Soft Voting: Weighted average com pesos adaptativos
           - Stacking: Meta-learning entre predições

        3. CROSS-TIMEFRAME CONSENSUS
           - Valida consistência entre timeframes
           - Detecta divergências estruturais
           - Ajusta confiança baseado em consenso

        4. ADVANCED CONFIDENCE SCORING
           - Performance histórica (R² score)
           - Concordância do ensemble (std)
           - Consistência temporal
           - Validação cruzada entre timeframes
           - Meta-features de qualidade

        5. ANOMALY DETECTION MULTI-LAYER
           - Detecção por timeframe individual
           - Detecção cross-timeframe
           - Z-score adaptativo

        FLUXO:
        =====
        1. Buscar TODOS os modelos disponíveis (todos timeframes)
        2. Para cada modelo:
           a. Lazy loading se necessário
           b. Extrair features e preparar
           c. Gerar predições individuais
        3. Ensemble por timeframe (soft voting)
        4. Cross-timeframe consensus
        5. Meta-ensemble final (hard + soft voting)
        6. Advanced confidence scoring
        7. Multi-layer anomaly detection

        Args:
            symbol: Símbolo (ex: 'BTCUSDT')
            horizon_name: Nome do horizonte ('short', 'medium', 'long')
            horizon_hours: Horas do horizonte (24, 168, 720)

        Returns:
            Dict com previsão enterprise ou None
        """
        prediction_start_time = time.time()

        try:
            self.logger.info(f"🚀 INICIANDO PREDIÇÃO ENTERPRISE: {symbol} ({horizon_name}, {horizon_hours}h)")

            # ================================================================
            # PASSO 1: ESTRATÉGIA 2 - BUSCAR MODELOS ESPECÍFICOS POR HORIZONTE
            # ================================================================
            # Mapeamento: horizon_name → target_horizons esperados
            horizon_config = {
                'micro': {
                    'models': [
                        {'interval': '1h', 'target_horizon': 3, 'weight': 1.0}
                    ],
                    'description': 'Micro (3h): Modelo 1h target=3'
                },
                'tatico': {
                    'models': [
                        {'interval': '1h', 'target_horizon': 12, 'weight': 0.50},
                        {'interval': '4h', 'target_horizon': 3, 'weight': 0.50}
                    ],
                    'description': 'Tático (12h): Ensemble 1h_t12 + 4h_t3'
                },
                'diario': {
                    'models': [
                        {'interval': '4h', 'target_horizon': 6, 'weight': 0.40},
                        {'interval': '1d', 'target_horizon': 1, 'weight': 0.60}
                    ],
                    'description': 'Diário (24h): Ensemble 4h_t6 + 1d_t1'
                }
            }

            config = horizon_config.get(horizon_name)
            if not config:
                self.logger.warning(f"⚠️ Horizonte desconhecido: {horizon_name}, usando fallback")
                # Fallback: buscar qualquer modelo disponível
                config = {'models': [], 'description': 'Fallback mode'}

            self.logger.info(f"📊 {config['description']}")

            timeframe_models = {}  # {interval_target: {model_key, model_info, interval, target_horizon, weight}}

            with QMutexLocker(self.mutex):
                # Buscar modelos específicos da configuração
                for model_spec in config['models']:
                    interval = model_spec['interval']
                    target_horizon = model_spec['target_horizon']
                    weight = model_spec['weight']

                    # Model key: symbol:interval:tX
                    model_key = f"{symbol}:{interval}:t{target_horizon}"

                    if model_key in self.trained_models:
                        info = self.trained_models[model_key]
                        key_name = f"{interval}_t{target_horizon}"

                        timeframe_models[key_name] = {
                            'model_key': model_key,
                            'model_info': info,
                            'interval': interval,
                            'target_horizon': target_horizon,
                            'weight': weight
                        }
                        self.logger.debug(f"✅ Modelo encontrado: {model_key} (peso: {weight})")
                    else:
                        self.logger.warning(f"⚠️ Modelo não encontrado: {model_key}")

                # Fallback: se nenhum modelo específico, buscar qualquer modelo do símbolo
                if not timeframe_models:
                    self.logger.warning(f"⚠️ Nenhum modelo específico, buscando fallback...")
                    for key, info in self.trained_models.items():
                        if key.startswith(symbol + ":"):
                            interval = info.get('interval', 'unknown')
                            target_horizon = info.get('target_horizon', 1)
                            key_name = f"{interval}_t{target_horizon}"

                            timeframe_models[key_name] = {
                                'model_key': key,
                                'model_info': info,
                                'interval': interval,
                                'target_horizon': target_horizon,
                                'weight': 1.0 / max(1, len(timeframe_models) + 1)  # Peso igual
                            }
                            self.logger.debug(f"✅ Fallback: {key}")

            if not timeframe_models:
                self.logger.warning(
                    f"⚠️ Nenhum modelo treinado para {symbol}. "
                    f"Modelos disponíveis: {list(self.trained_models.keys())}"
                )
                return None

            self.logger.info(f"📊 Timeframes disponíveis: {list(timeframe_models.keys())}")

            # ================================================================
            # PASSO 2: GERAR PREDIÇÕES POR TIMEFRAME
            # ================================================================
            timeframe_predictions = {}  # {timeframe: {predictions, ensemble, confidence, metrics}}

            for timeframe_key, tm_data in timeframe_models.items():
                try:
                    self.logger.debug(f"🔄 Processando: {timeframe_key}")

                    model_key = tm_data['model_key']
                    model_info = tm_data['model_info']
                    interval = tm_data['interval']  # ← Interval correto (ex: '1h', '4h')

                    # ----------------------------------------------------------
                    # 2.1. LAZY LOADING se necessário
                    # ----------------------------------------------------------
                    is_loaded = model_info.get('loaded', False)
                    if not is_loaded:
                        self.logger.debug(f"🔄 Lazy loading: {model_key}")
                        success = self._load_model_from_disk(model_key)
                        if not success:
                            self.logger.error(f"❌ Falha ao carregar: {model_key}")
                            continue

                        # Re-buscar model_info atualizado
                        with QMutexLocker(self.mutex):
                            model_info = self.trained_models[model_key]

                    # ----------------------------------------------------------
                    # 2.2. CALCULAR FEATURES EM TEMPO REAL (ENTERPRISE)
                    # ----------------------------------------------------------

                    with QMutexLocker(self.mutex):
                        models = model_info.get('models', {})
                        scaler = model_info.get('scaler')
                        weights = model_info.get('metrics', {}).get('weights', {})
                        metrics = model_info.get('metrics', {})

                    # Validações
                    if not models or scaler is None:
                        self.logger.warning(f"⚠️ Dados incompletos para {model_key}")
                        continue

                    # ============================================================
                    # CALCULAR FEATURES ATUAIS (Real-time)
                    # ============================================================
                    try:
                        self.logger.debug(f"🔄 Calculando features em tempo real para {symbol}@{interval}")

                        # Calcular features usando motor vetorizado (mesma matemática do treinamento)
                        current_features_dict = self.feature_eng.calculate_features(
                            symbol=symbol,
                            interval=interval,  # ← Usar interval correto
                            limit=1000
                        )

                        if current_features_dict is None:
                            self.logger.warning(
                                f"⚠️ Erro ao calcular features em tempo real para {symbol}@{interval}"
                            )
                            continue

                        # Preparar array de features
                        features_array = np.array(list(current_features_dict.values())).reshape(1, -1)

                        self.logger.debug(
                            f"✅ Features calculadas: {features_array.shape[1]} features, "
                            f"valores: [{features_array[0, :3]}...]"
                        )

                    except Exception as e:
                        self.logger.error(
                            f"❌ Erro ao calcular features em tempo real para {interval}: {e}",
                            exc_info=True
                        )
                        continue

                    # ============================================================
                    # DATA DRIFT DETECTION (ENTERPRISE)
                    # ============================================================
                    # Detectar se features atuais divergem das distribuições de treinamento
                    training_stats = model_info.get('training_stats')
                    drift_analysis = None

                    if training_stats:
                        drift_analysis = self._detect_data_drift(
                            current_features=current_features_dict,
                            training_stats=training_stats,
                            interval=interval  # ← Usar interval correto
                        )

                        # BLOQUEAR predição se drift HIGH (crítico)
                        if drift_analysis['drift_level'] == 'HIGH':
                            self.logger.warning(
                                f"❌ PREDIÇÃO BLOQUEADA - Data Drift HIGH detectado para {symbol}@{interval}"
                            )
                            self.logger.warning(f"   {drift_analysis['recommendation']}")
                            continue  # Skip este modelo
                    else:
                        self.logger.debug(f"⚠️ training_stats não disponível para {model_key}, drift detection skip")

                    # Escalar features usando o scaler do treinamento
                    try:
                        features_scaled = scaler.transform(features_array)
                    except Exception as e:
                        self.logger.error(f"❌ Erro ao escalar features: {e}")
                        continue

                    # ----------------------------------------------------------
                    # 2.3. GERAR PREDIÇÕES COM TODOS OS MODELOS (RF, XGB, LGBM)
                    # ----------------------------------------------------------
                    individual_predictions = {}
                    for model_name, model in models.items():
                        try:
                            pred = model.predict(features_scaled)[0]
                            individual_predictions[model_name] = pred
                            self.logger.debug(f"   {model_name}: {pred*100:+.2f}%")
                        except Exception as e:
                            self.logger.error(f"❌ Erro {model_name}: {e}")
                            continue

                    if not individual_predictions:
                        self.logger.warning(f"⚠️ Sem predições para {timeframe_key}")
                        continue

                    # ----------------------------------------------------------
                    # 2.4. ENSEMBLE SOFT VOTING (weighted average)
                    # ----------------------------------------------------------
                    if weights:
                        ensemble_pred = sum(
                            individual_predictions[name] * weights.get(name, 1/len(individual_predictions))
                            for name in individual_predictions.keys()
                        )
                    else:
                        ensemble_pred = np.mean(list(individual_predictions.values()))

                    # ----------------------------------------------------------
                    # 2.5. CALCULAR CONFIDENCE POR TIMEFRAME
                    # ----------------------------------------------------------
                    tf_confidence = self._calculate_confidence(individual_predictions, metrics)

                    # ============================================================
                    # APLICAR PENALIDADE DE DATA DRIFT
                    # ============================================================
                    if drift_analysis and drift_analysis['drift_detected']:
                        confidence_penalty = drift_analysis['confidence_penalty']
                        tf_confidence_original = tf_confidence
                        tf_confidence *= confidence_penalty

                        self.logger.info(
                            f"   📉 Confiança ajustada por Data Drift: "
                            f"{tf_confidence_original*100:.1f}% → {tf_confidence*100:.1f}% "
                            f"(penalty: {confidence_penalty*100:.0f}%, level: {drift_analysis['drift_level']})"
                        )

                    # ============================================================
                    # Armazenar resultado do modelo
                    # ============================================================
                    timeframe_predictions[timeframe_key] = {
                        'individual_predictions': individual_predictions,
                        'ensemble_prediction': ensemble_pred,
                        'confidence': tf_confidence,
                        'metrics': metrics,
                        'weights': weights,
                        'num_models': len(individual_predictions),
                        'drift_analysis': drift_analysis,  # ← Análise de drift
                        'weight': tm_data.get('weight', 1.0),  # ← Peso do ensemble
                        'interval': interval,  # ← Guardar interval para referência
                        'target_horizon': tm_data.get('target_horizon', 1)  # ← Target horizon do modelo
                    }

                    self.logger.info(
                        f"✅ {timeframe_key}: {ensemble_pred*100:+.2f}% "
                        f"(conf: {tf_confidence*100:.1f}%, models: {len(individual_predictions)}, "
                        f"weight: {tm_data.get('weight', 1.0):.2f})"
                    )

                except Exception as e:
                    self.logger.error(f"❌ Erro processando {timeframe_key}: {e}", exc_info=True)
                    continue

            if not timeframe_predictions:
                self.logger.warning(f"⚠️ Nenhuma predição gerada para {symbol}")
                return None

            # ================================================================
            # PASSO 3: ENSEMBLE PONDERADO COM PESOS CONFIGURADOS
            # ================================================================

            # Ensemble usando pesos pré-definidos da configuração
            final_prediction = 0.0
            total_weight = 0.0
            ensemble_method = f"weighted_ensemble_{horizon_name}"

            for tf_key, data in timeframe_predictions.items():
                pred = data['ensemble_prediction']
                weight = data.get('weight', 1.0)  # Peso da configuração

                final_prediction += pred * weight
                total_weight += weight

                self.logger.debug(
                    f"   {tf_key}: pred={pred*100:+.2f}%, "
                    f"weight={weight:.2f}, "
                    f"contrib={pred*weight*100:+.2f}%"
                )

            # Normalizar
            if total_weight > 0:
                final_prediction = final_prediction / total_weight
            else:
                # Fallback: média simples
                preds = [d['ensemble_prediction'] for d in timeframe_predictions.values()]
                final_prediction = np.mean(preds) if preds else 0.0
                ensemble_method = 'simple_average_fallback'

            self.logger.info(
                f"🎯 Ensemble {horizon_name}: "
                f"{final_prediction*100:+.2f}% "
                f"({len(timeframe_predictions)} modelos, método: {ensemble_method})"
            )

            # Consensus analysis (mantém para advanced confidence)
            consensus_analysis = self._analyze_cross_timeframe_consensus(timeframe_predictions)

            self.logger.info(
                f"🔍 Consenso: direção={consensus_analysis['direction_consensus']:.1%}, "
                f"magnitude={consensus_analysis['magnitude_consensus']:.1%}"
            )

            # ================================================================
            # PASSO 5: ADVANCED CONFIDENCE SCORING
            # ================================================================
            advanced_confidence = self._calculate_advanced_confidence(
                timeframe_predictions,
                consensus_analysis
            )

            self.logger.info(f"📊 Advanced Confidence: {advanced_confidence*100:.1f}%")

            # ================================================================
            # PASSO 6: MULTI-LAYER ANOMALY DETECTION
            # ================================================================
            is_anomaly, anomaly_details = self._detect_multi_layer_anomaly(
                symbol,
                final_prediction,
                timeframe_predictions,
                consensus_analysis
            )

            if is_anomaly:
                self._increment_stat('anomalies_detected')
                self.anomaly_detected.emit(symbol, "PREDICTION_ANOMALY", anomaly_details)
                self.logger.warning(f"⚠️ Anomalia detectada: {anomaly_details.get('reason', 'unknown')}")

            # ================================================================
            # PASSO 7: VERIFICAÇÕES E ALERTAS
            # ================================================================
            if advanced_confidence < self.min_confidence:
                self._increment_stat('low_confidence_count')
                self.confidence_low.emit(symbol, advanced_confidence)
                self.logger.warning(f"⚠️ Confiança baixa: {advanced_confidence*100:.1f}%")

            # ================================================================
            # PASSO 8: CALCULAR MÉTRICAS DE PERFORMANCE
            # ================================================================
            prediction_time_ms = (time.time() - prediction_start_time) * 1000

            with QMutexLocker(self.mutex):
                total = self.stats['successful_predictions'] + 1
                current_avg = self.stats['average_prediction_time_ms']
                self.stats['average_prediction_time_ms'] = (
                    (current_avg * (total - 1) + prediction_time_ms) / total
                )

            # ================================================================
            # PASSO 9: CRIAR RESULTADO ENTERPRISE
            # ================================================================
            result = {
                # Informações básicas
                'symbol': symbol,
                'horizon': horizon_name,
                'horizon_hours': horizon_hours,
                'timestamp': time.time(),
                'datetime': datetime.now().isoformat(),

                # Predições
                'predicted_return': final_prediction,
                'predicted_change_percent': final_prediction * 100,
                'ensemble_method': ensemble_method,

                # Confidence & Quality
                'confidence': advanced_confidence,
                'is_anomaly': is_anomaly,
                'anomaly_details': anomaly_details,

                # Multi-Timeframe Analysis
                'timeframe_predictions': {
                    tf: {
                        'prediction': data['ensemble_prediction'],
                        'confidence': data['confidence'],
                        'num_models': data['num_models']
                    }
                    for tf, data in timeframe_predictions.items()
                },
                'num_timeframes': len(timeframe_predictions),
                'timeframes_used': list(timeframe_predictions.keys()),

                # Consensus Analysis
                'consensus_analysis': consensus_analysis,

                # Todas as predições individuais
                'all_individual_predictions': {
                    tf: data['individual_predictions']
                    for tf, data in timeframe_predictions.items()
                },

                # Performance
                'prediction_time_ms': prediction_time_ms,
            }

            # ================================================================
            # LOG FINAL
            # ================================================================
            self.logger.info(
                f" \n"
                f"✅ 🚀 PREDIÇÃO ENTERPRISE COMPLETA: {symbol} ({horizon_name})\n"
                f"   Predição: {final_prediction*100:+.2f}%\n"
                f"   Confiança: {advanced_confidence*100:.1f}%\n"
                f"   Timeframes: {len(timeframe_predictions)} ({', '.join(timeframe_predictions.keys())})\n"
                f"   Consenso Direcional: {consensus_analysis['direction_consensus']*100:.1f}%\n"
                f"   Método: {ensemble_method}\n"
                f"   Tempo: {prediction_time_ms:.1f}ms"
                f" \n"
            )

            self._increment_stat('features_from_model')

            return result

        except Exception as e:
            self.logger.error(f"❌ Erro ao gerar predição enterprise: {e}", exc_info=True)
            return None

    # ========================================================================
    # MÉTODOS AUXILIARES DO ENTERPRISE PREDICTION ENGINE
    # ========================================================================

    def _analyze_cross_timeframe_consensus(
        self, timeframe_predictions: Dict[str, Dict]
    ) -> Dict[str, Any]:
        """
        Analisa consenso entre múltiplos timeframes

        Verifica:
        1. Consenso direcional (todos bullish/bearish/neutral?)
        2. Consenso de magnitude (valores próximos?)
        3. Divergências estruturais

        Args:
            timeframe_predictions: Dict {timeframe: {predictions, ensemble, confidence...}}

        Returns:
            Dict com análise de consenso
        """
        try:
            if len(timeframe_predictions) < 2:
                return {
                    'direction_consensus': 1.0,
                    'magnitude_consensus': 1.0,
                    'divergence_detected': False,
                    'overall_consensus': 1.0,   # Ajustado para não penalizar na média ponderada
                    'dominant_direction': 'neutral',
                    'consensus_strength': 'strong'
                }

            # Extrair predições de cada timeframe
            predictions = [data['ensemble_prediction'] for data in timeframe_predictions.values()]
            confidences = [data['confidence'] for data in timeframe_predictions.values()]

            # 1. CONSENSO DIRECIONAL
            # Classificar cada predição (bullish > 0.001, bearish < -0.001, neutral)
            directions = []
            for pred in predictions:
                if pred > 0.001:
                    directions.append('bullish')
                elif pred < -0.001:
                    directions.append('bearish')
                else:
                    directions.append('neutral')

            # Contar direções
            direction_counts = Counter(directions)
            dominant_direction = direction_counts.most_common(1)[0][0]
            dominant_count = direction_counts[dominant_direction]

            # Consenso direcional = proporção da direção dominante
            direction_consensus = dominant_count / len(directions)

            # 2. CONSENSO DE MAGNITUDE
            # Verificar se os valores estão próximos (std baixo)
            pred_mean = np.mean(predictions)
            pred_std = np.std(predictions)

            # Coefficient of variation normalizado
            if abs(pred_mean) > 1e-6:
                cv = pred_std / abs(pred_mean)
                magnitude_consensus = max(0, 1 - min(cv, 1))  # Inverter: baixo CV = alto consenso
            else:
                magnitude_consensus = 1.0 if pred_std < 0.01 else 0.5

            # 3. DETECTAR DIVERGÊNCIAS ESTRUTURAIS
            # Divergência = timeframes apontam direções opostas com alta confiança
            divergence_detected = False
            if len(predictions) >= 2:
                # Verificar se há sinais opostos com confiança > 0.6
                bullish_confident = sum(1 for i, p in enumerate(predictions)
                                      if p > 0.001 and confidences[i] > 0.6)
                bearish_confident = sum(1 for i, p in enumerate(predictions)
                                      if p < -0.001 and confidences[i] > 0.6)

                if bullish_confident > 0 and bearish_confident > 0:
                    divergence_detected = True

            # 4. FORÇA DO CONSENSO
            overall_consensus = (direction_consensus + magnitude_consensus) / 2

            if overall_consensus > 0.8:
                consensus_strength = 'strong'
            elif overall_consensus > 0.6:
                consensus_strength = 'moderate'
            else:
                consensus_strength = 'weak'

            return {
                'direction_consensus': float(direction_consensus),
                'magnitude_consensus': float(magnitude_consensus),
                'overall_consensus': float(overall_consensus),
                'divergence_detected': divergence_detected,
                'dominant_direction': dominant_direction,
                'consensus_strength': consensus_strength,
                'predictions_std': float(pred_std),
                'predictions_mean': float(pred_mean),
                'num_timeframes': len(timeframe_predictions),
                'direction_distribution': dict(direction_counts)
            }

        except Exception as e:
            self.logger.error(f"❌ Erro na análise de consenso: {e}", exc_info=True)
            return {
                'direction_consensus': 0.5,
                'magnitude_consensus': 0.5,
                'overall_consensus': 0.5,
                'divergence_detected': False,
                'dominant_direction': 'neutral',
                'consensus_strength': 'unknown',
                'predictions_std': 0.0,
                'predictions_mean': 0.0,
                'num_timeframes': 0,
                'direction_distribution': {}
            }

    def _soft_voting_ensemble(
        self, timeframe_predictions: Dict[str, Dict]
    ) -> float:
        """
        Soft Voting Ensemble - Weighted average baseado em confidence

        Cada timeframe contribui proporcionalmente à sua confiança.
        Timeframes mais confiantes têm maior peso.

        Args:
            timeframe_predictions: Dict {timeframe: {predictions, confidence...}}

        Returns:
            Predição ensemble (weighted average)
        """
        try:
            total_weight = 0.0
            weighted_sum = 0.0

            for tf, data in timeframe_predictions.items():
                prediction = data['ensemble_prediction']
                confidence = data['confidence']

                # Peso = confidence (timeframes mais confiantes têm maior peso)
                weight = confidence
                weighted_sum += prediction * weight
                total_weight += weight

            if total_weight > 0:
                return weighted_sum / total_weight
            else:
                # Fallback: média simples
                predictions = [data['ensemble_prediction'] for data in timeframe_predictions.values()]
                return np.mean(predictions)

        except Exception as e:
            self.logger.error(f"❌ Erro no soft voting: {e}", exc_info=True)
            predictions = [data['ensemble_prediction'] for data in timeframe_predictions.values()]
            return np.mean(predictions) if predictions else 0.0

    def _hard_voting_ensemble(
        self, timeframe_predictions: Dict[str, Dict]
    ) -> float:
        """
        Hard Voting Ensemble - Maioria dos votos (democrático)

        Cada timeframe "vota" em uma direção (bullish/bearish/neutral).
        A predição final é a média das predições que votaram na direção vencedora.

        Args:
            timeframe_predictions: Dict {timeframe: {predictions, confidence...}}

        Returns:
            Predição ensemble (média das predições da direção vencedora)
        """
        try:
            # Classificar cada timeframe
            votes = {
                'bullish': [],
                'bearish': [],
                'neutral': []
            }

            for tf, data in timeframe_predictions.items():
                prediction = data['ensemble_prediction']

                if prediction > 0.001:
                    votes['bullish'].append(prediction)
                elif prediction < -0.001:
                    votes['bearish'].append(prediction)
                else:
                    votes['neutral'].append(prediction)

            # Determinar vencedor (maioria)
            vote_counts = {
                'bullish': len(votes['bullish']),
                'bearish': len(votes['bearish']),
                'neutral': len(votes['neutral'])
            }

            winner = max(vote_counts, key=vote_counts.get)

            # Predição = média das predições do vencedor
            if votes[winner]:
                return np.mean(votes[winner])
            else:
                # Fallback: média de tudo
                all_preds = [data['ensemble_prediction'] for data in timeframe_predictions.values()]
                return np.mean(all_preds)

        except Exception as e:
            self.logger.error(f"❌ Erro no hard voting: {e}", exc_info=True)
            all_preds = [data['ensemble_prediction'] for data in timeframe_predictions.values()]
            return np.mean(all_preds) if all_preds else 0.0

    def _calculate_advanced_confidence(
        self,
        timeframe_predictions: Dict[str, Dict],
        consensus_analysis: Dict[str, Any]
    ) -> float:
        """
        Calcula Advanced Confidence Score com múltiplas métricas

        COMPONENTES OTIMIZADOS (100% total):
        1. Performance histórica (R² médio) - 30%
        2. Consenso cross-timeframe - 30%
        3. Concordância do ensemble (low std) - 20%
        4. Qualidade dos modelos individuais - 15%
        5. Bonus: Múltiplos timeframes - 5%

        REFATORAÇÃO: Método otimizado, apenas 2 parâmetros necessários
        Features calculadas em tempo real, sempre atuais!

        Args:
            timeframe_predictions: Predições por timeframe com métricas
            consensus_analysis: Análise de consenso cross-timeframe

        Returns:
            Confidence score (0-1)
        """
        try:
            confidence_components = {}

            # ============================================================
            # 1. PERFORMANCE HISTÓRICA (R² médio dos modelos) - 30%
            # ============================================================
            r2_scores = []
            for tf, data in timeframe_predictions.items():
                r2 = data['metrics'].get('r2_score', 0.5)
                r2_scores.append(max(0, min(1, r2)))

            performance_confidence = np.mean(r2_scores) if r2_scores else 0.5
            confidence_components['performance_r2'] = performance_confidence

            # ============================================================
            # 2. CONSENSO CROSS-TIMEFRAME - 30%
            # ============================================================
            consensus_confidence = consensus_analysis.get('overall_consensus', 0.5)

            # Validação de tipo
            if consensus_confidence is None or not isinstance(consensus_confidence, (int, float)):
                consensus_confidence = 0.5

            # Penalizar divergências fortes
            if consensus_analysis.get('divergence_detected', False):
                consensus_confidence *= 0.7  # Penalidade de 30%

            confidence_components['cross_timeframe_consensus'] = consensus_confidence

            # ============================================================
            # 3. CONCORDÂNCIA DO ENSEMBLE (low std = alta concordância) - 20%
            # ============================================================
            predictions = [data['ensemble_prediction'] for data in timeframe_predictions.values()]
            pred_std = np.std(predictions)
            pred_mean = np.mean(predictions)

            # Coefficient of Variation (CV): std/mean
            if abs(pred_mean) > 1e-6:
                cv = pred_std / abs(pred_mean)
                # Quanto menor o CV, maior a concordância
                agreement_confidence = max(0, 1 - min(cv, 1))
            else:
                # Se média próxima de zero, verificar std absoluto
                agreement_confidence = 1.0 if pred_std < 0.01 else 0.5

            confidence_components['ensemble_agreement'] = agreement_confidence

            # ============================================================
            # 4. QUALIDADE DOS MODELOS INDIVIDUAIS - 15%
            # ============================================================
            # Mede a confiança interna de cada timeframe
            # Baseado na confiança individual e ausência de drift
            individual_confidences = []
            drift_penalties = []

            for tf, data in timeframe_predictions.items():
                # Confiança calculada para este timeframe
                tf_conf = data.get('confidence', 0.5)
                individual_confidences.append(tf_conf)

                # Verificar se houve drift detection
                drift = data.get('drift_analysis', {})
                if drift and drift.get('drift_detected', False):
                    drift_level = drift.get('drift_level', 'NONE')
                    # Maior penalidade para drift mais severo
                    penalty_map = {'NONE': 1.0, 'LOW': 0.9, 'MEDIUM': 0.7, 'HIGH': 0.5}
                    drift_penalties.append(penalty_map.get(drift_level, 1.0))
                else:
                    drift_penalties.append(1.0)

            # Média das confianças individuais
            avg_individual_conf = np.mean(individual_confidences) if individual_confidences else 0.5
            # Média das penalidades de drift
            avg_drift_penalty = np.mean(drift_penalties) if drift_penalties else 1.0

            # Combinar confiança individual com penalidade de drift
            model_quality = avg_individual_conf * avg_drift_penalty
            confidence_components['model_quality'] = model_quality

            # ============================================================
            # 5. BONUS: MÚLTIPLOS TIMEFRAMES - 5%
            # ============================================================
            # Mais timeframes = maior diversidade e robustez
            num_timeframes = len(timeframe_predictions)

            # Escala: 1 timeframe = 33%, 2 = 67%, 3+ = 100%
            if num_timeframes >= 3:
                timeframe_bonus = 1.0
            elif num_timeframes == 2:
                timeframe_bonus = 0.67
            else:
                timeframe_bonus = 0.33

            confidence_components['timeframe_diversity'] = timeframe_bonus

            # ============================================================
            # 6. COMBINAR COMPONENTES (weighted average)
            # ============================================================
            # Validação final: garantir que todos os componentes são numéricos
            performance_confidence = float(performance_confidence) if isinstance(performance_confidence, (int, float)) else 0.5
            consensus_confidence = float(consensus_confidence) if isinstance(consensus_confidence, (int, float)) else 0.5
            agreement_confidence = float(agreement_confidence) if isinstance(agreement_confidence, (int, float)) else 0.5
            model_quality = float(model_quality) if isinstance(model_quality, (int, float)) else 0.5
            timeframe_bonus = float(timeframe_bonus) if isinstance(timeframe_bonus, (int, float)) else 0.5

            advanced_confidence = (
                0.30 * performance_confidence +      # 30% - Performance histórica
                0.30 * consensus_confidence +        # 30% - Consenso cross-timeframe
                0.20 * agreement_confidence +        # 20% - Concordância do ensemble
                0.15 * model_quality +               # 15% - Qualidade individual + drift
                0.05 * timeframe_bonus               # 5%  - Bonus diversidade
            )

            advanced_confidence = float(np.clip(advanced_confidence, 0, 1))

            # Log detalhado
            self.logger.debug("=" * 60)
            self.logger.debug("📊 ADVANCED CONFIDENCE BREAKDOWN:")
            self.logger.debug(f"   1. Performance R² (30%):        {performance_confidence*100:6.2f}%")
            self.logger.debug(f"   2. Cross-TF Consensus (30%):    {consensus_confidence*100:6.2f}%")
            self.logger.debug(f"   3. Ensemble Agreement (20%):    {agreement_confidence*100:6.2f}%")
            self.logger.debug(f"   4. Model Quality (15%):         {model_quality*100:6.2f}%")
            self.logger.debug(f"   5. TF Diversity Bonus (5%):     {timeframe_bonus*100:6.2f}%")
            self.logger.debug("-" * 60)
            self.logger.debug(f"   🎯 FINAL CONFIDENCE:            {advanced_confidence*100:6.2f}%")
            self.logger.debug("=" * 60)

            return advanced_confidence

        except Exception as e:
            self.logger.error(f"❌ Erro no cálculo de advanced confidence: {e}", exc_info=True)
            return 0.5  # Default

    def _detect_data_drift(
        self,
        current_features: Dict[str, float],
        training_stats: Dict[str, Dict[str, float]],
        interval: str
    ) -> Dict[str, Any]:
        """
        🔍 DATA DRIFT DETECTION - Sistema Enterprise de Detecção de Desvio de Distribuição

        Detecta quando as features atuais do mercado divergem significativamente
        das distribuições observadas durante o treinamento, indicando que o modelo
        pode estar operando fora do seu domínio de validade.

        METODOLOGIA:
        - Z-Score Analysis: (valor_atual - média_treino) / std_treino
        - Classification:
            * NONE:   |z| < 2.0  (dentro de 95% de confiança) ✅
            * LOW:    2.0 ≤ |z| < 3.0  (fora de 95%, alerta) ⚠️
            * MEDIUM: 3.0 ≤ |z| < 4.0  (fora de 99.7%, atenção) ⚠️⚠️
            * HIGH:   |z| ≥ 4.0  (extremo, crítico) ❌

        FEATURES MONITORADAS (8 críticas):
        1. realized_vol_20     - Volatilidade realizada
        2. volume_rolling_mean_20 - Volume médio
        3. rsi_14              - RSI
        4. returns             - Retornos
        5. close_lag_1         - Preço recente
        6. sma_50              - SMA 50
        7. volume_ratio        - Volume ratio
        8. atr_14              - ATR

        AÇÕES RECOMENDADAS POR DRIFT LEVEL:
        - NONE:   Predição normal, confiança total
        - LOW:    Predição permitida, reduzir confiança 10%
        - MEDIUM: Predição permitida, reduzir confiança 30%
        - HIGH:   BLOQUEAR predição, modelo inválido ❌

        Args:
            current_features: Features atuais do mercado (Dict[feature_name, value])
            training_stats: Estatísticas calculadas no treinamento
            interval: Intervalo temporal (1h, 4h, 1d)

        Returns:
            {
                'drift_detected': bool,
                'drift_level': 'NONE'|'LOW'|'MEDIUM'|'HIGH',
                'overall_drift_score': float,  # Max Z-score absoluto
                'features_with_drift': [
                    {
                        'feature': str,
                        'z_score': float,
                        'current_value': float,
                        'training_mean': float,
                        'training_std': float,
                        'drift_level': str
                    },
                    ...
                ],
                'num_features_drifted': int,
                'recommendation': str,
                'confidence_penalty': float  # Multiplicador de confiança (0.7-1.0)
            }
        """
        try:
            self.logger.debug(f"🔍 Iniciando Data Drift Detection para {interval}")

            # Validação de entrada
            if not training_stats or not current_features:
                self.logger.warning("⚠️ training_stats ou current_features vazio, drift detection desabilitado")
                return {
                    'drift_detected': False,
                    'drift_level': 'NONE',
                    'overall_drift_score': 0.0,
                    'features_with_drift': [],
                    'num_features_drifted': 0,
                    'recommendation': 'Drift detection não disponível (sem training_stats)',
                    'confidence_penalty': 1.0
                }

            # ================================================================
            # CALCULAR Z-SCORES PARA CADA FEATURE MONITORADA
            # ================================================================
            features_with_drift = []
            z_scores = []

            for feature_name, stats in training_stats.items():
                # Verificar se feature existe nas features atuais
                if feature_name not in current_features:
                    self.logger.debug(f"⚠️ Feature {feature_name} não encontrada em current_features")
                    continue

                current_value = current_features[feature_name]
                training_mean = stats['mean']
                training_std = stats['std']

                # Validar std (evitar divisão por zero)
                if training_std < 1e-10:
                    self.logger.debug(f"⚠️ Feature {feature_name} tem std ~0, skip drift detection")
                    continue

                # Calcular Z-score
                z_score = (current_value - training_mean) / training_std
                z_score_abs = abs(z_score)
                z_scores.append(z_score_abs)

                # Classificar drift level
                if z_score_abs >= 4.0:
                    drift_level = 'HIGH'
                elif z_score_abs >= 3.0:
                    drift_level = 'MEDIUM'
                elif z_score_abs >= 2.0:
                    drift_level = 'LOW'
                else:
                    drift_level = 'NONE'

                # Registrar se há drift
                if drift_level != 'NONE':
                    features_with_drift.append({
                        'feature': feature_name,
                        'z_score': float(z_score),
                        'z_score_abs': float(z_score_abs),
                        'current_value': float(current_value),
                        'training_mean': float(training_mean),
                        'training_std': float(training_std),
                        'drift_level': drift_level,
                        'percentile': f"{(1 - 2 * (1 - 0.5 * (1 + z_score_abs))) * 100:.2f}%"  # Aproximado
                    })

                    self.logger.debug(
                        f"   📊 {feature_name}: z={z_score:+.2f} (|z|={z_score_abs:.2f}) "
                        f"→ {drift_level} | current={current_value:.6f}, "
                        f"train_mean={training_mean:.6f}"
                    )

            # ================================================================
            # ANÁLISE AGREGADA DE DRIFT
            # ================================================================
            overall_drift_score = max(z_scores) if z_scores else 0.0
            num_features_drifted = len(features_with_drift)

            # Determinar drift level geral (pior caso)
            if overall_drift_score >= 4.0:
                drift_level = 'HIGH'
            elif overall_drift_score >= 3.0:
                drift_level = 'MEDIUM'
            elif overall_drift_score >= 2.0:
                drift_level = 'LOW'
            else:
                drift_level = 'NONE'

            drift_detected = (drift_level != 'NONE')

            # ================================================================
            # CALCULAR PENALIDADE DE CONFIANÇA
            # ================================================================
            confidence_penalties = {
                'NONE': 1.0,     # Sem penalidade
                'LOW': 0.90,     # -10%
                'MEDIUM': 0.70,  # -30%
                'HIGH': 0.0      # BLOQUEAR (0%)
            }
            confidence_penalty = confidence_penalties[drift_level]

            # ================================================================
            # GERAR RECOMENDAÇÃO
            # ================================================================
            recommendations = {
                'NONE': 'Predição normal - features dentro da distribuição de treinamento',
                'LOW': 'Alerta leve - features ligeiramente fora da distribuição (95%-99.7%)',
                'MEDIUM': 'Alerta moderado - features significativamente fora da distribuição (>99.7%)',
                'HIGH': '⚠️ CRÍTICO - BLOQUEAR PREDIÇÃO - modelo operando fora do domínio de validade'
            }
            recommendation = recommendations[drift_level]

            # ================================================================
            # LOG DE RESULTADO
            # ================================================================
            if drift_detected:
                self.logger.warning("=" * 80)
                self.logger.warning(f"⚠️ DATA DRIFT DETECTADO - {interval}")
                self.logger.warning(f"   Nível: {drift_level}")
                self.logger.warning(f"   Overall Z-Score: {overall_drift_score:.2f}")
                self.logger.warning(f"   Features com drift: {num_features_drifted}/{len(training_stats)}")
                self.logger.warning(f"   Penalidade confiança: {confidence_penalty*100:.0f}%")
                self.logger.warning(f"   Recomendação: {recommendation}")

                # Listar features com drift
                for feat in features_with_drift:
                    self.logger.warning(
                        f"      • {feat['feature']}: z={feat['z_score']:+.2f} ({feat['drift_level']})"
                    )
                self.logger.warning("=" * 80)
            else:
                self.logger.debug(f"✅ Sem data drift detectado - {interval}")

            # ================================================================
            # RETORNAR ANÁLISE COMPLETA
            # ================================================================
            return {
                'drift_detected': drift_detected,
                'drift_level': drift_level,
                'overall_drift_score': float(overall_drift_score),
                'features_with_drift': features_with_drift,
                'num_features_drifted': num_features_drifted,
                'total_features_monitored': len(training_stats),
                'recommendation': recommendation,
                'confidence_penalty': confidence_penalty,
                'interval': interval
            }

        except Exception as e:
            self.logger.error(f"❌ Erro no Data Drift Detection: {e}", exc_info=True)
            # Em caso de erro, retornar sem drift (fail-safe)
            return {
                'drift_detected': False,
                'drift_level': 'NONE',
                'overall_drift_score': 0.0,
                'features_with_drift': [],
                'num_features_drifted': 0,
                'recommendation': f'Erro no drift detection: {str(e)}',
                'confidence_penalty': 1.0
            }

    def _detect_multi_layer_anomaly(
        self,
        symbol: str,
        final_prediction: float,
        timeframe_predictions: Dict[str, Dict],
        consensus_analysis: Dict[str, Any]
    ) -> Tuple[bool, Optional[Dict]]:
        """
        Detecção de Anomalias Multi-Layer

        Camadas de detecção:
        1. Anomalia por timeframe individual (z-score por TF)
        2. Anomalia cross-timeframe (divergências extremas)
        3. Anomalia de magnitude (predição muito extrema)
        4. Anomalia de consenso (consenso muito baixo)

        Args:
            symbol: Símbolo
            final_prediction: Predição final
            timeframe_predictions: Predições por timeframe
            consensus_analysis: Análise de consenso

        Returns:
            (is_anomaly, details)
        """
        try:
            anomalies = []

            # LAYER 1: Anomalia Histórica (z-score vs histórico)
            history_key = f"ml_prediction_history:{symbol}"
            history = self.cache.get(history_key, reader="PredictionEngine")

            if history and len(history) >= 10:
                hist_values = [h.get('predicted_return', 0) for h in history]
                hist_mean = np.mean(hist_values)
                hist_std = np.std(hist_values)

                if hist_std > 1e-6:
                    z_score = abs((final_prediction - hist_mean) / hist_std)

                    if z_score > self.anomaly_threshold:
                        anomalies.append({
                            'type': 'historical_anomaly',
                            'z_score': float(z_score),
                            'threshold': self.anomaly_threshold,
                            'severity': 'high' if z_score > 4 else 'medium'
                        })

            # LAYER 2: Anomalia Cross-Timeframe (divergência estrutural)
            if consensus_analysis.get('divergence_detected', False):
                anomalies.append({
                    'type': 'cross_timeframe_divergence',
                    'direction_consensus': consensus_analysis['direction_consensus'],
                    'severity': 'medium'
                })

            # LAYER 3: Anomalia de Magnitude (predição muito extrema)
            if abs(final_prediction) > 0.20:  # > 20% de mudança
                anomalies.append({
                    'type': 'extreme_magnitude',
                    'prediction': float(final_prediction),
                    'threshold': 0.20,
                    'severity': 'high' if abs(final_prediction) > 0.30 else 'medium'
                })

            # LAYER 4: Anomalia de Consenso (consenso muito baixo)
            if consensus_analysis.get('overall_consensus', 1.0) < 0.4:
                anomalies.append({
                    'type': 'low_consensus',
                    'consensus': consensus_analysis['overall_consensus'],
                    'threshold': 0.4,
                    'severity': 'low'
                })

            # Determinar se é anomalia
            is_anomaly = len(anomalies) > 0

            if is_anomaly:
                # Agregar detalhes
                details = {
                    'num_anomalies': len(anomalies),
                    'anomalies': anomalies,
                    'reason': ', '.join([a['type'] for a in anomalies]),
                    'max_severity': max([a['severity'] for a in anomalies],
                                       key=lambda x: {'low': 1, 'medium': 2, 'high': 3}[x])
                }
                return True, details
            else:
                return False, None

        except Exception as e:
            self.logger.error(f"❌ Erro na detecção de anomalias: {e}", exc_info=True)
            return False, None

    # ========================================================================
    # MÉTODOS AUXILIARES ORIGINAIS (mantidos)
    # ========================================================================

    def _calculate_confidence(
        self, predictions: Dict[str, float], metrics: Dict
    ) -> float:
        """
        Calcula confidence score
        
        Baseado em:
        - Performance histórica dos modelos (R² score)
        - Concordância do ensemble (std das previsões)
        
        Args:
            predictions: Dict {model_name: prediction}
            metrics: Métricas dos modelos
            
        Returns:
            Confidence score (0-1)
        """
        try:
            if not predictions:
                return 0.0
            
            # 1. Performance histórica (R² score médio)
            r2_score = metrics.get('r2_score', 0.5)  # Default: 0.5 se não existir

            # Validar tipo (pode ser None em alguns casos)
            if r2_score is None or not isinstance(r2_score, (int, float)):
                r2_score = 0.5

            performance_confidence = max(0, min(1, r2_score))
            
            # 2. Concordância do ensemble
            pred_values = list(predictions.values())
            if len(pred_values) > 1:
                pred_std = np.std(pred_values)
                pred_mean = np.mean(pred_values)
                
                # Coefficient of variation
                if abs(pred_mean) > 1e-6:
                    cv = pred_std / abs(pred_mean)
                    agreement_confidence = max(0, 1 - cv)  # Menor variação = maior confiança
                else:
                    agreement_confidence = 0.5
            else:
                agreement_confidence = 1.0  # Apenas um modelo
            
            # 3. Combinar confiânças (weighted average)
            confidence = (
                0.7 * performance_confidence +
                0.3 * agreement_confidence
            )
            
            return float(np.clip(confidence, 0, 1))
            
        except Exception as e:
            self.logger.error(f"❌ Erro ao calcular confidence: {e}", exc_info=True)
            return 0.5  # Default
    
    def _check_prediction_cache(
        self, symbol: str, horizon: str
    ) -> Optional[Dict]:
        """
        Verifica cache local de previsões
        
        Args:
            symbol: Símbolo
            horizon: Horizonte
            
        Returns:
            Dict com previsão ou None
        """
        try:
            with QMutexLocker(self.mutex):
                cache_key = (symbol, horizon)
                if cache_key in self.prediction_cache:
                    timestamp, prediction = self.prediction_cache[cache_key]
                    
                    # Verificar TTL
                    age = time.time() - timestamp
                    if age < self.prediction_cache_ttl:
                        self.logger.debug(f"✅ Cache HIT (local): {symbol} {horizon}")
                        return prediction
                    else:
                        # Expirado, remover
                        del self.prediction_cache[cache_key]
            
            return None
            
        except Exception as e:
            self.logger.error(f"❌ Erro ao verificar cache: {e}", exc_info=True)
            return None
    
    def _store_prediction(self, symbol: str, horizon: str, prediction: Dict):
        """
        Armazena previsão no cache (L1 + local)
        
        Args:
            symbol: Símbolo
            horizon: Horizonte
            prediction: Dict com previsão
        """
        try:
            # 1. Cache local
            with QMutexLocker(self.mutex):
                cache_key = (symbol, horizon)
                self.prediction_cache[cache_key] = (time.time(), prediction)
            
            # 2. CacheSystem (L1 - 1h TTL)
            cache_key_l1 = f"ml_prediction:{symbol}:{horizon}"
            self.cache.set_conditional(
                cache_key_l1,
                prediction,
                ttl=3600,  # 1h
                writer="PredictionEngine"
            )
            
            # 3. Adicionar ao histórico (para detecção de anomalias)
            history_key = f"ml_prediction_history:{symbol}"
            history = self.cache.get(history_key, reader="PredictionEngine") or []
            
            # Manter apenas últimas 100 previsões
            history.append({
                'predicted_return': prediction['predicted_return'],
                'confidence': prediction['confidence'],
                'timestamp': prediction['timestamp'],
            })
            history = history[-100:]  # Keep last 100
            
            self.cache.set_conditional(
                history_key,
                history,
                ttl=86400,  # 24h
                writer="PredictionEngine"
            )
            
            self.logger.info(f"💾 Previsão armazenada: {cache_key_l1}")
            
        except Exception as e:
            self.logger.error(f"❌ Erro ao armazenar previsão: {e}", exc_info=True)
    
    def _increment_stat(self, stat_name: str):
        """
        Incrementa estatística (thread-safe)
        
        Args:
            stat_name: Nome da estatística
        """
        try:
            with QMutexLocker(self.mutex):
                if stat_name in self.stats:
                    self.stats[stat_name] += 1
                    
                    # Atualizar total
                    if stat_name in ['successful_predictions', 'failed_predictions']:
                        self.stats['total_predictions'] = (
                            self.stats['successful_predictions'] + 
                            self.stats['failed_predictions']
                        )
        except Exception as e:
            self.logger.error(f"❌ Erro ao incrementar stat: {e}", exc_info=True)

# ===========================================================================================
# MLSYSTEM - MACHINE LEARNING ORCHESTRATOR (REVOLUTIONARY VERSION)
# ===========================================================================================

class MLSystem(QObject):
    """
    MLSystem - Orquestrador Central de Machine Learning
    
    Sistema que NÃO executa operações bloqueantes.
    Coordena workers em threads separadas e mantém estado dos modelos.

    FILOSOFIA REVOLUCIONÁRIA:
    Este sistema foi desenvolvido para ser um ORCHESTRATOR PURO.
    Não executa operações bloqueantes - apenas coordena workers em threads separadas.

    CARACTERÍSTICAS:
        - Thread-safe com QMutex
        - Non-blocking: todas operações pesadas delegadas a workers
        - Event-driven: arquitetura baseada em sinais Qt
        - Cache-integrated: lê/escreve no CacheSystem
        - Monitorável: sinais para MLSystemMonitorDialog

    ARQUITETURA:
        MLSystem (QObject - Main Thread)
            ├── TrainingWorker (QThread separado)
            ├── PredictionEngine (QThread separado)
            └── FeatureEngineering (Helper - chamado pelos workers)

    RESPONSABILIDADES DO MLSystem:
        ✓ Coordenar workers (training + prediction)
        ✓ Gerenciar estado dos modelos em memória
        ✓ Emitir sinais Qt para consumidores
        ✓ Interface pública para tabs/monitor
        ✓ Thread-safety com QMutex

    NÃO FAZ (delegado aos workers):
        ✗ Operações bloqueantes
        ✗ I/O pesado
        ✗ Treinamento direto
        ✗ Cálculos intensivos

    FLUXO DE DADOS:
        BinanceData → Cache → FeatureEngineering → TrainingWorker → MLSystem (models)
                                                ↓
                                    PredictionEngine → Cache → Consumers

    SINAIS QT:
        - training_started(symbol): Treinamento iniciado
        - training_completed(symbol, metrics): Treinamento concluído
        - training_progress(message, percent): Progresso do treinamento
        - prediction_generated(symbol, horizon, prediction): Nova previsão
        - model_performance_warning(symbol, metric, value): Performance degradada
        - error_occurred(type, message): Erro no sistema
        - stats_updated(stats): Estatísticas atualizadas

    THREAD-SAFETY:
        - QMutex protege estado compartilhado (trained_models, scalers, etc)
        - Sinais Qt garantem comunicação thread-safe
        - Workers isolados não acessam diretamente estado do MLSystem

    INTEGRAÇÃO COM CACHE:
        - Lê: OHLCV (L0), Features (L2)
        - Escreve: Predictions (L1), Models metadata (L3)
    """
    
    # ========== SINAIS QT ==========
    training_started = Signal(str)  # symbol
    training_completed = Signal(str, dict)  # symbol, metrics
    training_progress = Signal(str, int)  # message, percent
    prediction_generated = Signal(str, str, dict)  # symbol, horizon, prediction
    model_performance_warning = Signal(str, str, float)  # symbol, metric, value
    error_occurred = Signal(str, str)  # error_type, message
    stats_updated = Signal(dict)  # statistics
    
    def __init__(
        self,
        cache_system,
        binance_data,
        feature_engineering,
        config: Dict[str, Any]
    ):
        """
        Inicializa MLSystem Orchestrator
        
        Args:
            cache_system: Instância do CacheSystem
            feature_engineering: Instância do FeatureEngineering
            config: Configurações ML (dict com seção 'ml' do config.json)
        """
        super().__init__()
        
        # Logger
        self.logger = logging.getLogger('MLSystem')
        self.logger.info("="*80)
        self.logger.info("INICIALIZANDO MLSYSTEM - ORCHESTRATOR")
        self.logger.info("="*80)
        
        # Dependências
        self.cache = cache_system
        self.binance = binance_data
        self.feature_eng = feature_engineering
        self.config = config

        # Diretório dos Modelos Salvos
        self.models_dir = Path(self.config.get('models_dir', 'models'))
        
        # Thread safety
        self.mutex = QMutex()
        self._queue_mutex = QMutex()
        self.logger.debug("✅ QMutex inicializado para thread-safety")
        
        # ===== ESTADO INTERNO (THREAD-SAFE) =====
        self.trained_models: Dict[str, Dict[str, Any]] = {}  # symbol -> {models, metadata, scaler}
        self.feature_importance: Dict[str, pd.DataFrame] = {}  # symbol -> importance_df
        self.training_history: Dict[str, List[Dict]] = defaultdict(list)  # symbol -> [training_events]

        # ===== CACHES E ESTRUTURAS =====
        self._top_n_cache = []  # Lista de símbolos ordenados por ranking
        self._trained_symbols_cache = {} # Cache de treinamentos realizados: {(symbol, interval): timestamp}
        self._training_queue_set = set()  # Set de (symbol, interval) para dedup
        self._training_queue_priority = []  # Heap queue: [(priority, symbol, interval)]
        self._symbols_being_fetched = {}  # {symbol: {'interval': str, 'status': str}}
        
        # ===== ESTATÍSTICAS =====
        self.stats = {
            'total_trainings': 0,
            'successful_trainings': 0,
            'failed_trainings': 0,
            'total_predictions': 0,
            'successful_predictions': 0,
            'failed_predictions': 0,
            'models_in_memory': 0,
            'average_training_time_s': 0.0,
            'average_prediction_time_ms': 0.0,
            'last_training_time': None,
            'last_prediction_time': None,
        }
        
        # ===== CONFIGURAÇÕES =====
        self.models_config = config.get('models', ['RandomForest', 'XGBoost', 'LightGBM'])
        self.horizons = config.get('horizons', {
            'micro': 3,      # 3h - Scalping
            'tatico': 12,    # 12h - Grid entry
            'diario': 24     # 24h - Grid exit
        })
        self.retrain_interval_hours = config.get('retrain_interval_hours', 24)
        self.auto_retrain_enabled = config.get('auto_retrain_enabled', True)
        
        self.logger.info(f"📊 Configurações carregadas:")
        self.logger.info(f"   - Modelos: {self.models_config}")
        self.logger.info(f"   - Horizontes: {self.horizons}")
        self.logger.info(f"   - Auto-retrain: {self.auto_retrain_enabled} ({self.retrain_interval_hours}h)")
        
        # ===== WORKERS (SERÃO CRIADOS NO start()) =====
        self.training_worker = None
        self.training_thread = None
        self.prediction_engine = None
        self.prediction_thread = None
        
        # ===== TIMERS =====
        self.stats_timer = QTimer()
        self.stats_timer.timeout.connect(self._update_stats)
        
        self.retrain_timer = QTimer()
        self.retrain_timer.timeout.connect(self._auto_retrain_check)
        
        self.logger.info("✅ MLSystem Orchestrator inicializado (workers serão criados no start())")

    # ========== PERSISTENCE METHODS ==========

    def _load_training_results(
        self,
        top_n_symbols: Optional[List[str]] = None,
        intervals: Optional[List[str]] = None
    ) -> int:
        """
        Carrega resultados de treinamentos salvos em disco (PERSISTÊNCIA DE ESTADO)

        OBJETIVO:
            Restaurar estado interno da MLSystem a partir de metadados salvos
            em sessões anteriores. Isso evita perder todo o trabalho de treinamento
            quando o sistema é reiniciado.

        ARQUITETURA LAZY LOADING:
            Carrega apenas símbolos/intervalos do Top N atual

            BENEFÍCIOS:
            - Reduz uso de memória no startup
            - Alinha com arquitetura reativa (Top N driven)
            - Atualiza dinamicamente quando Top N muda

        LÓGICA:
            1. Varre diretório models/ recursivamente
            2. Busca todos arquivos de metadata *_t*.json (exceto manifest.json)
            3. FILTRA por símbolos/intervalos do Top N (se fornecido)
            4. Valida integridade (schema, checksum, idade)
            5. Reconstrói estado interno:
               - trained_models (sem carregar .pkl.gz - lazy loading)
               - training_history
               - stats
            6. Carrega modelos .pkl.gz LAZY (só quando predict() for chamado)

        VALIDAÇÕES:
            ✅ Schema version compatível
            ✅ Modelo não muito antigo (< 30 dias)
            ✅ Arquivo .pkl.gz existe
            ✅ Checksum SHA256 bate (se disponível)

        Args:
            top_n_symbols: Lista de símbolos Top N (None = carregar todos)
            intervals: Lista de intervalos desejados (None = carregar todos)

        Returns:
            int: Quantidade de modelos restaurados

        Exemplo de uso:
            # Carregar apenas Top N símbolos
            restored_count = self._load_training_results(
                top_n_symbols=['BTCUSDT', 'ETHUSDT'],
                intervals=['1h', '4h', '1d']
            )
        """
        logger = self.logger
        restored_count = 0
        skipped_count = 0  # Contador de modelos filtrados
        max_age_days = 30  # Ignorar modelos com mais de 30 dias

        try:
            logger.info("=" * 80)
            logger.info("📂 RESTAURANDO ESTADO DE TREINAMENTOS ANTERIORES")

            # Log de filtros ativos
            if top_n_symbols:
                logger.info(f"   🔍 FILTRO ATIVO: {len(top_n_symbols)} símbolos Top N")
            if intervals:
                logger.info(f"   🔍 FILTRO ATIVO: Intervalos {intervals}")

            logger.info("=" * 80)

            if not self.models_dir.exists():
                logger.info("   📁 Diretório models/ não existe - nenhum modelo para restaurar")
                return 0

            # ================================================================
            # FASE 1: BUSCAR TODOS OS ARQUIVOS DE METADATA (exceto manifest.json)
            # ================================================================
            metadata_files = list(self.models_dir.rglob("*_t*.json"))

            if not metadata_files:
                logger.info("   📁 Nenhum arquivo de metadata encontrado")
                return 0

            logger.info(f"   📄 {len(metadata_files)} arquivo(s) de metadata encontrado(s)")

            # ================================================================
            # FASE 2: PROCESSAR CADA ARQUIVO
            # ================================================================
            for metadata_file in metadata_files:
                try:
                    # Ler metadata
                    with open(metadata_file, 'r', encoding='utf-8') as f:
                        metadata = json.load(f)

                    symbol = metadata.get('symbol')
                    interval = metadata.get('interval')
                    target_horizon = metadata.get('target_horizon', 1)

                    if not symbol or not interval:
                        logger.warning(f"   ⚠️ Metadata inválido (falta symbol/interval): {metadata_file.name}")
                        continue

                    # ========================================================
                    # FILTRO: Top N Symbols e Intervals
                    # ========================================================
                    if top_n_symbols and symbol not in top_n_symbols:
                        skipped_count += 1
                        logger.debug(f"   ⏭️  Pulando {symbol}_{interval}:t{target_horizon} (não está no Top N)")
                        continue

                    if intervals and interval not in intervals:
                        skipped_count += 1
                        logger.debug(f"   ⏭️  Pulando {symbol}_{interval}:t{target_horizon} (intervalo não solicitado)")
                        continue

                    # ========================================================
                    # VALIDAÇÃO 1: Schema Version
                    # ========================================================
                    schema_version = metadata.get('schema_version', 0)
                    if schema_version != 1:
                        logger.warning(
                            f"   ⚠️ Schema incompatível ({symbol}_{interval}:t{target_horizon}): "
                            f"v{schema_version} (esperado v1)"
                        )
                        continue

                    # ========================================================
                    # VALIDAÇÃO 2: Idade do Modelo
                    # ========================================================
                    trained_at = metadata.get('trained_at_timestamp', 0)
                    age_seconds = time.time() - trained_at
                    age_days = age_seconds / (24 * 3600)

                    if age_days > max_age_days:
                        logger.info(
                            f"   ⏩ Modelo muito antigo ({symbol}_{interval}:t{target_horizon}): "
                            f"{age_days:.1f} dias (max: {max_age_days})"
                        )
                        continue

                    # ========================================================
                    # VALIDAÇÃO 3: Arquivo .pkl.gz Existe
                    # ========================================================
                    model_file_name = metadata.get('model_file')
                    if not model_file_name:
                        logger.warning(f"   ⚠️ Metadata sem 'model_file': {symbol}_{interval}:t{target_horizon}")
                        continue

                    model_file_path = metadata_file.parent / model_file_name

                    if not model_file_path.exists():
                        logger.warning(
                            f"   ⚠️ Arquivo de modelo não encontrado: {model_file_name}"
                        )
                        continue

                    # ========================================================
                    # VALIDAÇÃO 4: Checksum (Opcional)
                    # ========================================================
                    saved_checksum = metadata.get('checksum_sha256')
                    if saved_checksum:
                        # Calcular checksum atual
                        import hashlib
                        sha256 = hashlib.sha256()
                        with open(model_file_path, 'rb') as f:
                            for chunk in iter(lambda: f.read(8192), b''):
                                sha256.update(chunk)
                        current_checksum = sha256.hexdigest()

                        if current_checksum != saved_checksum:
                            logger.warning(
                                f"   ⚠️ Checksum inválido ({symbol}_{interval}:t{target_horizon}): "
                                f"arquivo corrompido ou modificado"
                            )
                            continue

                    # ========================================================
                    # RESTAURAR ESTADO INTERNO (SEM CARREGAR .pkl.gz)
                    # ========================================================
                    with QMutexLocker(self.mutex):
                        model_key = f"{symbol}:{interval}:t{target_horizon}"

                        # Armazenar metadata + caminho do arquivo (LAZY LOADING)
                        self.trained_models[model_key] = {
                            'symbol': symbol,
                            'interval': interval,
                            'target_horizon': target_horizon,
                            'model_file_path': str(model_file_path),  # ← Caminho para load
                            'loaded': False,  # ← Flag de lazy loading
                            'metrics': metadata.get('ensemble_metrics', {}),
                            'trained_at': trained_at,
                            'training_duration_s': metadata.get('training_duration_s', 0),
                            'n_features': metadata.get('n_features', 0),
                            'n_samples_train': metadata.get('n_samples_train', 0),
                            'n_samples_val': metadata.get('n_samples_val', 0),
                            'n_candles_used': metadata.get('n_candles_used', 0),
                        }

                        # Adicionar ao histórico
                        self.training_history[symbol].append({
                            'timestamp': trained_at,
                            'datetime': metadata.get('trained_at'),
                            'metrics': metadata.get('ensemble_metrics', {}),
                            'duration_s': metadata.get('training_duration_s', 0),
                            'restored_from_disk': True  # ← Flag indicando restauração
                        })

                        # Atualizar cache de símbolos treinados
                        task_key = (symbol, interval)
                        self._trained_symbols_cache[task_key] = trained_at

                    restored_count += 1

                    logger.info(
                        f"   ✅ Restaurado: {symbol}_{interval}:t{target_horizon} "
                        f"(R²={metadata.get('ensemble_metrics', {}).get('r2_score_mean', 0):.4f}, "
                        f"idade={age_days:.1f}d)"
                    )

                except Exception as e:
                    logger.error(
                        f"   ❌ Erro ao processar {metadata_file.name}: {e}",
                        exc_info=True
                    )
                    continue

            # ================================================================
            # FASE 3: ATUALIZAR STATS
            # ================================================================
            if restored_count > 0:
                with QMutexLocker(self.mutex):
                    self.stats['models_in_memory'] = len(self.trained_models)
                    self.stats['successful_trainings'] += restored_count  # Contar como treinamentos

            # ================================================================
            # FASE 4: ATUALIZAR PREDICTIONENGINE
            # ================================================================
            if restored_count > 0 and self.prediction_engine:
                QTimer.singleShot(10, lambda: self.prediction_engine.update_models(self.trained_models))
                logger.info(f"✅ PredictionEngine atualizado com {restored_count} modelo(s) restaurado(s)")

            # ================================================================
            # LOG FINAL
            # ================================================================
            logger.info("=" * 80)
            if restored_count > 0:
                logger.info(f"✅ {restored_count} MODELO(S) RESTAURADO(S) DE SESSÃO ANTERIOR")
                logger.info(f"   Total em memória: {len(self.trained_models)}")
                if skipped_count > 0:
                    logger.info(f"   📊 {skipped_count} modelo(s) filtrado(s) (fora do Top N ou intervalo)")
                logger.info("   Nota: Modelos serão carregados LAZY (quando predict() for chamado)")
            else:
                logger.info("📭 NENHUM MODELO RESTAURADO (treinar novos modelos)")
                if skipped_count > 0:
                    logger.info(f"   📊 {skipped_count} modelo(s) filtrado(s) (fora do Top N ou intervalo)")
            logger.info("=" * 80)

            return restored_count

        except Exception as e:
            logger.error(f"❌ Erro ao carregar training results: {e}", exc_info=True)
            return 0

    # ========== LIFECYCLE METHODS ==========

    def start(self):
        """
        Inicia MLSystem e seus workers
        
        IMPORTANTE: Deve ser chamado APÓS QApplication.exec_() estar rodando
        """
        self.logger.info("="*80)
        self.logger.info("INICIANDO MLSYSTEM E WORKERS")
        self.logger.info("="*80)
        
        try:
            # 1. Criar workers
            self._create_workers()

            # 2. Conectar sinais
            self._connect_signals()

            # 3. Iniciar threads
            self.training_thread.start()
            self.prediction_thread.start()

            self.logger.info("✅ Training thread iniciada")
            self.logger.info("✅ Prediction thread iniciada")

            # 4. Iniciar workers (emitir signal para moverem para suas threads)
            self.prediction_engine.start()
            self.logger.info("✅ PredictionEngine iniciado")

            # 5. Iniciar timers
            self.stats_timer.start(1000 * 60)  # Update stats a cada minuto
            if self.auto_retrain_enabled:
                self.retrain_timer.start(self.retrain_interval_hours * 3600 * 1000)  # Converter para ms
                self.logger.info(f"✅ Auto-retrain timer iniciado ({self.retrain_interval_hours}h)")
            
            self.logger.info("="*80)
            self.logger.info("🚀 MLSYSTEM TOTALMENTE OPERACIONAL")
            self.logger.info("="*80)
            
        except Exception as e:
            self.logger.error(f"❌ Erro ao iniciar MLSystem: {e}", exc_info=True)
            self.error_occurred.emit("STARTUP", str(e))
    
    def stop(self):
        """
        Para MLSystem gracefully
        """
        self.logger.info("="*80)
        self.logger.info("PARANDO MLSYSTEM")
        self.logger.info("="*80)
        
        try:
            # 1. Parar timers
            self.stats_timer.stop()
            self.retrain_timer.stop()
            self.logger.info("✅ Timers parados")
            
            # 2. Parar workers
            if self.prediction_engine:
                self.prediction_engine.stop()
                self.logger.info("✅ PredictionEngine parado")
            
            # 3. Parar threads
            if self.training_thread and self.training_thread.isRunning():
                self.training_thread.quit()
                self.training_thread.wait(5000)  # Wait up to 5s
                self.logger.info("✅ Training thread parada")
            
            if self.prediction_thread and self.prediction_thread.isRunning():
                self.prediction_thread.quit()
                self.prediction_thread.wait(5000)
                self.logger.info("✅ Prediction thread parada")
            
            self.logger.info("="*80)
            self.logger.info("✅ MLSYSTEM PARADO GRACEFULLY")
            self.logger.info("="*80)
            
        except Exception as e:
            self.logger.error(f"❌ Erro ao parar MLSystem: {e}", exc_info=True)
    
    # ========== MÉTODOS PÚBLICOS (INTERFACE PARA TABS/CONSUMERS) ==========
    
    def train_model(
        self,
        symbol: str,
        force_retrain: bool = False
    ) -> bool:
        """
        Solicita treinamento de TODOS os modelos para um símbolo (não-bloqueante)

        Treina 5 modelos automaticamente:
        - 1h:t3  (micro: 3h)
        - 1h:t12 (tático: 12h)
        - 4h:t3  (tático: 12h)
        - 4h:t6  (diário: 24h)
        - 1d:t1  (diário: 24h)

        Args:
            symbol: Símbolo a treinar (ex: 'BTCUSDT')
            force_retrain: Forçar retreino mesmo se modelos recentes existem

        Returns:
            bool: True se solicitação aceita, False caso contrário
        """
        logger = self.logger
        logger.info(f"🔥 Solicitação de treinamento: {symbol} (force={force_retrain})")

        try:
            # ============================================================
            # VERIFICAR MODELO RECENTE (se não force_retrain)
            # ============================================================
            # NOTA: Agora verificamos se ALGUM dos 5 modelos precisa retreino
            if not force_retrain:
                # Verificar se pelo menos um dos modelos principais precisa retreino
                needs_retrain = False
                for interval in ['1h', '4h', '1d']:
                    hours_since = self._check_training_cache(symbol, interval)
                    if hours_since is None or hours_since >= self.retrain_interval_hours:
                        needs_retrain = True
                        break

                if not needs_retrain:
                    logger.info(
                        f"⏭️ Todos os modelos recentes existem: {symbol} "
                        f"(treinado recentemente)"
                    )
                    return False

            # ============================================================
            # ENVIAR PARA TRAININGWORKER (THREAD SEPARADA)
            # ============================================================
            if self.training_worker:
                from PySide6.QtCore import QMetaObject, Qt, Q_ARG

                QMetaObject.invokeMethod(
                    self.training_worker,
                    "train_model",
                    Qt.QueuedConnection,
                    Q_ARG(str, symbol),
                    Q_ARG(bool, force_retrain)
                )

                logger.info(f"✅ Treinamento enfileirado: {symbol} (5 modelos)")
                return True
            else:
                logger.error("❌ TrainingWorker não inicializado")
                return False

        except Exception as e:
            logger.error(f"❌ Erro ao solicitar treinamento: {e}", exc_info=True)
            self.error_occurred.emit("TRAIN_REQUEST", str(e))
            return False
    
    def predict(self, symbol: str, horizon: str = 'short') -> Optional[Dict]:
        """
        Solicita previsão (não-bloqueante)
        
        NOTA: Esta função retorna None imediatamente. A previsão será
        emitida via sinal prediction_generated quando pronta.
        
        Para previsões síncronas (blocking), use get_cached_prediction().
        
        Args:
            symbol: Símbolo
            horizon: 'short', 'medium', ou 'long'
            
        Returns:
            None (previsão será emitida via signal)
        """
        self.logger.debug(f"📥 Solicitação de previsão: {symbol} ({horizon})")
        
        try:
            # Verificar se modelo existe
            with QMutexLocker(self.mutex):
                if symbol not in self.trained_models:
                    self.logger.warning(f"⚠️ Modelo não treinado para {symbol}")
                    self.error_occurred.emit("PREDICT_NO_MODEL", f"Model not trained for {symbol}")
                    return None
            
            # PredictionEngine processa automaticamente via timer
            # Mas podemos adicionar à priority queue
            if self.prediction_engine:
                self.prediction_engine.add_priority_symbol(symbol)
                self.logger.debug(f"✅ {symbol} adicionado à priority queue")
            
            return None  # Previsão será emitida via signal
            
        except Exception as e:
            self.logger.error(f"❌ Erro ao solicitar previsão de {symbol}: {e}", exc_info=True)
            self.error_occurred.emit("PREDICT_REQUEST", str(e))
            return None
    
    def get_cached_prediction(self, symbol: str, horizon: str = 'short') -> Optional[Dict]:
        """
        Obtém previsão do cache (síncrono, não-bloqueante)
        
        Args:
            symbol: Símbolo
            horizon: 'short', 'medium', ou 'long'
            
        Returns:
            Dict com previsão ou None se não existe
        """
        try:
            cache_key = f"ml_prediction:{symbol}:{horizon}"
            prediction = self.cache.get(cache_key, reader="ML_SYSTEM")
            
            if prediction:
                self.logger.debug(f"✅ Cache HIT: {cache_key}")
                return prediction
            else:
                self.logger.debug(f"❌ Cache MISS: {cache_key}")
                return None
                
        except Exception as e:
            self.logger.error(f"❌ Erro ao buscar previsão do cache: {e}", exc_info=True)
            return None
    
    def get_model_info(self, symbol: str) -> Optional[Dict]:
        """
        Retorna informações sobre modelo treinado (thread-safe)
        
        Args:
            symbol: Símbolo
            
        Returns:
            Dict com info do modelo ou None
        """
        try:
            with QMutexLocker(self.mutex):
                if symbol in self.trained_models:
                    model_info = self.trained_models[symbol].copy()
                    return model_info
                else:
                    return None
                    
        except Exception as e:
            self.logger.error(f"❌ Erro ao buscar info do modelo: {e}", exc_info=True)
            return None
    
    def get_all_models_info(self) -> Dict[str, Dict]:
        """
        Retorna informações de todos os modelos treinados (thread-safe)
        
        Returns:
            Dict {symbol: model_info}
        """
        try:
            with QMutexLocker(self.mutex):
                return {symbol: info.copy() for symbol, info in self.trained_models.items()}
                
        except Exception as e:
            self.logger.error(f"❌ Erro ao buscar todos os modelos: {e}", exc_info=True)
            return {}
    
    def get_stats(self) -> Dict[str, Any]:
        """
        Retorna estatísticas do sistema ML (thread-safe)
        
        Returns:
            Dict com estatísticas
        """
        try:
            with QMutexLocker(self.mutex):
                return self.stats.copy()
                
        except Exception as e:
            self.logger.error(f"❌ Erro ao buscar stats: {e}", exc_info=True)
            return {}
    
    def get_training_history(self, symbol: str) -> List[Dict]:
        """
        Retorna histórico de treinamentos (thread-safe)
        
        Args:
            symbol: Símbolo
            
        Returns:
            Lista de eventos de treinamento
        """
        try:
            with QMutexLocker(self.mutex):
                return self.training_history[symbol].copy() if symbol in self.training_history else []
                
        except Exception as e:
            self.logger.error(f"❌ Erro ao buscar histórico: {e}", exc_info=True)
            return []
    
    # ========== MÉTODOS PRIVADOS ==========
    
    def _create_workers(self):
        """
        Cria workers em threads separadas
        
        CRITICAL: Workers são criados SEM parent para poderem ser movidos para outras threads
        """
        self.logger.debug("Criando workers...")
        
        try:
            # 1. Training Worker
            self.training_thread = QThread()
            self.training_thread.setObjectName("TrainingThread")
            
            self.training_worker = TrainingWorker(
                cache_system=self.cache,
                feature_engineering=self.feature_eng,
                config=self.config
            )
            # NO PARENT! Isso é crítico para moveToThread funcionar
            self.training_worker.moveToThread(self.training_thread)
            
            self.logger.info("✅ TrainingWorker criado e movido para thread")
            
            # 2. Prediction Engine
            self.prediction_thread = QThread()
            self.prediction_thread.setObjectName("PredictionThread")
            
            self.prediction_engine = PredictionEngine(
                cache_system=self.cache,
                feature_engineering=self.feature_eng,
                config=self.config
            )
            # NO PARENT!
            self.prediction_engine.moveToThread(self.prediction_thread)
            
            self.logger.info("✅ PredictionEngine criado e movido para thread")
            
        except ImportError as e:
            self.logger.error(f"❌ Erro ao importar workers: {e}")
            self.logger.error("Verifique se TrainingWorker e PredictionEngine estão implementados")
            raise
        except Exception as e:
            self.logger.error(f"❌ Erro ao criar workers: {e}", exc_info=True)
            raise
    
    def _connect_signals(self):
        """
        Conecta sinais dos workers ao orchestrator
        """
        logger = self.logger

        logger.info("=" * 80)
        logger.info("Conectando sinais dos workers...")
        
        try:
            # ===== TRAINING WORKER =====
            if self.training_worker:
                self.training_worker.training_started.connect(self._on_training_started)
                self.training_worker.training_progress.connect(self._on_training_progress)
                self.training_worker.training_completed.connect(self._on_training_completed)
                self.training_worker.training_failed.connect(self._on_training_failed)
                
                logger.info("✅ TrainingWorker: 4 sinais conectados")
            
            # ===== PREDICTION ENGINE =====
            if self.prediction_engine:
                self.prediction_engine.prediction_generated.connect(self._on_prediction_ready)
                self.prediction_engine.anomaly_detected.connect(self._on_anomaly_detected)
                self.prediction_engine.confidence_low.connect(self._on_confidence_low)
                self.prediction_engine.error_occurred.connect(self._on_worker_error)
                
                logger.info("✅ PredictionEngine: 4 sinais conectados")
                logger.info("=" * 80)

            # ===== CONECTANDO AO SINAL TOP N DO BINANCEDATA =====
            #self.binance.top_n.connect(self._on_top_n_received)
            logger.info("✅ Conectado: BinanceData.top_n → MLSystem._on_top_n_received")
            
        except Exception as e:
            logger.error(f"❌ Erro ao conectar sinais: {e}", exc_info=True)
            raise
    
    # ========== SLOTS (RECEBEM SINAIS DOS WORKERS) ==========
    
    @Slot(str)
    def _on_training_started(self, symbol: str):
        """
        Handler: Treinamento iniciado
        
        Este slot é executado na MAIN THREAD (onde MLSystem vive)
        """
        self.logger.info(f"🎯 Treinamento iniciado: {symbol}")
        
        try:
            with QMutexLocker(self.mutex):
                self.stats['total_trainings'] += 1
            
            # Repassar sinal para consumers (tabs, monitor)
            self.training_started.emit(symbol)
            
        except Exception as e:
            self.logger.error(f"❌ Erro no handler _on_training_started: {e}", exc_info=True)
    
    @Slot(str, int)
    def _on_training_progress(self, message: str, percent: int):
        """
        Handler: Progresso do treinamento
        """
        self.logger.debug(f"📊 Treinamento: {message} ({percent}%)")
        
        try:
            # Repassar sinal
            self.training_progress.emit(message, percent)
            
        except Exception as e:
            self.logger.error(f"❌ Erro no handler _on_training_progress: {e}", exc_info=True)
    
    @Slot(str, dict)
    def _on_training_completed(self, symbol: str, result: dict):
        """
        Handler: Treinamento completo
        
        Atualiza estado interno com novos modelos
        """
        logger = self.logger
        interval = result.get('interval')
        target_horizon = result.get('target_horizon', 1)

        logger.info(f"✅ Treinamento completo: {symbol}_{interval}:t{target_horizon}")
        #logger.info(f"   Métricas: {result.get('metrics', {})}")

        try:
            with QMutexLocker(self.mutex):
                # Armazenar metadados do modelo (SEM carregar models/scaler)
                model_key = f"{symbol}:{interval}:t{target_horizon}"

                self.trained_models[model_key] = {
                    'symbol': symbol,
                    'interval': interval,
                    'target_horizon': target_horizon,
                    'model_file_path': result.get('model_file_path'),  # ← Path para load
                    'loaded': False,  # ← Flag de lazy loading
                    'metrics': result.get('metrics', {}),
                    'trained_at': time.time(),
                    'training_duration_s': result.get('training_duration_s', 0),
                    'n_features': result.get('n_features', 0),
                    'n_samples_train': result.get('n_samples_train', 0),
                    'n_samples_val': result.get('n_samples_val', 0),
                    'n_candles_used': result.get('n_candles_used', 0),
                }

                # NOTA: Scaler NÃO armazenado aqui - PredictionEngine carrega quando necessário
                
                # Armazenar feature importance
                if 'feature_importance' in result:
                    self.feature_importance[symbol] = result['feature_importance']
                
                # Adicionar ao histórico
                self.training_history[symbol].append({
                    'timestamp': time.time(),
                    'datetime': datetime.now().isoformat(),
                    'metrics': result.get('metrics', {}),
                    'duration_s': result.get('training_duration_s', 0),
                })
                
                # Atualizar stats
                self.stats['successful_trainings'] += 1
                self.stats['models_in_memory'] = len(self.trained_models)
                self.stats['last_training_time'] = datetime.now().isoformat()
                
                # Update average training time
                total = self.stats['successful_trainings']
                current_avg = self.stats['average_training_time_s']
                new_duration = result.get('training_duration_s', 0)
                self.stats['average_training_time_s'] = (current_avg * (total - 1) + new_duration) / total

                task_key = (symbol, interval)
                self._trained_symbols_cache[task_key] = time.time()
            
            # Atualizar modelos no PredictionEngine
            if self.prediction_engine:
                self.prediction_engine.update_models(self.trained_models)
                self.logger.info("✅ Modelos atualizados no PredictionEngine")
            
            # Escrever metadata no cache (L3 - ML layer)
            cache_key = f"ml_model_metadata:{symbol}"
            metadata = {
                'symbol': symbol,
                'trained_at': time.time(),
                'metrics': result.get('metrics', {}),
                'n_features': result.get('n_features', 0),
            }
            self.cache.set_conditional(cache_key,
                                       metadata,
                                       ttl=86400,
                                       writer=f"MLSystem: {symbol}_{interval}:t{target_horizon}"
                                       )  # 24h TTL

            # Repassar sinal
            self.training_completed.emit(symbol, result.get('metrics', {}))

            self.logger.info(f"✅ Estado atualizado para {symbol}_{interval}:t{target_horizon}")

            # PROCESSAR PRÓXIMO DA FILA
            self._process_ready_trainings()
            
        except Exception as e:
            self.logger.error(f"❌ Erro no handler _on_training_completed: {e}", exc_info=True)
            self.error_occurred.emit("TRAINING_COMPLETE_HANDLER", str(e))
    
    @Slot(str, str)
    def _on_training_failed(self, symbol: str, error_msg: str):
        """
        Handler: Treinamento falhou
        """
        self.logger.error(f"❌ Treinamento falhou: {symbol} - {error_msg}")
        
        try:
            with QMutexLocker(self.mutex):
                self.stats['failed_trainings'] += 1
            
            # Emitir erro
            self.error_occurred.emit("TRAINING_FAILED", f"{symbol}: {error_msg}")
            
        except Exception as e:
            self.logger.error(f"❌ Erro no handler _on_training_failed: {e}", exc_info=True)
    
    @Slot(str, str, dict)
    def _on_prediction_ready(self, symbol: str, horizon: str, prediction: dict):
        """
        Handler: Previsão pronta
        """
        self.logger.info(f"🎯 Previsão pronta: {symbol} ({horizon}) - "
                         f"{prediction.get('predicted_change_percent', 0):+.2f}% "
                         f"(conf: {prediction.get('confidence', 0)*100:.1f}%)")
        
        try:
            with QMutexLocker(self.mutex):
                self.stats['successful_predictions'] += 1
                self.stats['last_prediction_time'] = datetime.now().isoformat()
                
                # Update average prediction time
                if 'prediction_time_ms' in prediction:
                    total = self.stats['successful_predictions']
                    current_avg = self.stats['average_prediction_time_ms']
                    new_time = prediction['prediction_time_ms']
                    self.stats['average_prediction_time_ms'] = (current_avg * (total - 1) + new_time) / total
            
            # Repassar sinal para consumers
            self.prediction_generated.emit(symbol, horizon, prediction)
            
        except Exception as e:
            self.logger.error(f"❌ Erro no handler _on_prediction_ready: {e}", exc_info=True)
    
    @Slot(str, str, dict)
    def _on_anomaly_detected(self, symbol: str, anomaly_type: str, details: dict):
        """
        Handler: Anomalia detectada na previsão
        """
        self.logger.warning(f"⚠️ Anomalia detectada: {symbol} ({anomaly_type})")
        self.logger.debug(f"   Detalhes: {details}")
        
        # Emitir warning
        self.model_performance_warning.emit(symbol, anomaly_type, details.get('score', 0))
    
    @Slot(str, float)
    def _on_confidence_low(self, symbol: str, confidence: float):
        """
        Handler: Confiança baixa na previsão
        """
        self.logger.warning(f"⚠️ Confiança baixa: {symbol} ({confidence*100:.1f}%)")
        
        # Emitir warning
        self.model_performance_warning.emit(symbol, "LOW_CONFIDENCE", confidence)
    
    @Slot(str, str)
    def _on_worker_error(self, error_type: str, error_msg: str):
        """
        Handler: Erro em worker
        """
        self.logger.error(f"❌ Erro em worker: {error_type} - {error_msg}")
        
        try:
            with QMutexLocker(self.mutex):
                self.stats['failed_predictions'] += 1
            
            # Repassar erro
            self.error_occurred.emit(error_type, error_msg)
            
        except Exception as e:
            self.logger.error(f"❌ Erro no handler _on_worker_error: {e}", exc_info=True)

    # ============================================================================
    # HANDLER PRINCIPAL - _on_top_n_received()
    # ============================================================================
    @Slot(str, dict)
    def _on_top_n_received(self, cache_key: str, top_n_data: dict):
        """
        🎯 ORQUESTRADOR PRINCIPAL - Handler reativo para Top-N
        
        DISPARA TODO O PIPELINE ML:
        1. Atualiza cache interno
        2. Decide schedule de treinamento (símbolos + intervalos)
        3. Enfileira tarefas com deduplicação
        4. Requisita dados históricos em batch
        5. Processa símbolos cujos dados já estão prontos
        
        CHAMADO: A cada 5 minutos quando BinanceData atualiza Top-N
        
        Args:
            cache_key: "top_n_key" (constante)
            top_n_data: Dict com lista de símbolos ordenados
        """
        logger = self.logger
        
        try:
            logger.info("=" * 80)
            logger.info("🎯 TOP-N RECEBIDO - INICIANDO PIPELINE ML")
            
            symbols = top_n_data.get('symbols', [])
            
            if not symbols:
                logger.warning("⚠️ Top-N vazio recebido")
                return
            
            logger.info(f"📊 Processando {len(symbols)} símbolos do Top-N")
            
            # ============================================================
            # ETAPA 1: Atualizar cache interno
            # ============================================================
            with QMutexLocker(self.mutex):
                self._top_n_cache = symbols.copy()

            logger.info("✅ Cache interno Top-N atualizado")

            # ============================================================
            # ETAPA 2: Carregar metadados de modelos treinados (LAZY)
            # ============================================================
            # ARQUITETURA OTIMIZADA:
            # Carrega apenas metadados de símbolos/intervalos do Top N atual
            # Isso reduz uso de memória e alinha com arquitetura reativa
            intervals_to_load = ['1h', '4h', '1d']  # Intervalos usados em treinamento
            restored_count = self._load_training_results(
                top_n_symbols=symbols,
                intervals=intervals_to_load
            )

            if restored_count > 0:
                logger.info(f"✅ {restored_count} modelo(s) restaurado(s) para Top N atual")

            # ============================================================
            # ETAPA 3: Enfileirar símbolos para treinamento
            # ============================================================
            # Cada símbolo treina TODOS os 5 modelos (1h:t3, 1h:t12, 4h:t3, 4h:t6, 1d:t1)

            logger.info(f"📋 Enfileirando {len(symbols)} símbolos (cada um treina 5 modelos)")

            enqueued_count = 0
            skipped_count = 0

            for symbol in symbols:
                if self._enqueue_training(symbol, priority=1):
                    enqueued_count += 1
                else:
                    skipped_count += 1
            
            logger.info(f"✅ {enqueued_count} tarefas enfileiradas")
            logger.info(f"⏭️  {skipped_count} tarefas puladas (duplicatas/recentes)")

            # ============================================================
            # ETAPA 5: Processar símbolos cujos dados já estão prontos
            # ============================================================
            logger.info("🔄 Processando tarefas com dados disponíveis...")
            processed = self._process_ready_trainings()
            
            if processed > 0:
                logger.info(f"✅ {processed} treinamentos disparados imediatamente")
            else:
                logger.info("⏳ Nenhum treinamento pronto - aguardando dados históricos")
            
            logger.info("✅ PIPELINE ML INICIADO COM SUCESSO")
            logger.info("=" * 80)
            
        except Exception as e:
            logger.error(f"❌ Erro no handler _on_top_n_received: {e}", exc_info=True)

    # ============================================================================
    # MÉTODOS AUXILIARS
    # ============================================================================

    def _enqueue_training(
        self,
        symbol: str,
        priority: int = 5
    ) -> bool:
        """
        Adiciona tarefa de treinamento à fila com deduplicação
        Cada símbolo treina TODOS os 5 modelos (1h:t3, 1h:t12, 4h:t3, 4h:t6, 1d:t1)

        DEDUPLICAÇÃO:
        - Verifica se símbolo já está na fila

        Args:
            symbol: Símbolo
            priority: Prioridade (menor = maior prioridade)

        Returns:
            True se enfileirado, False se duplicata/skip
        """
        logger = self.logger

        try:
            with QMutexLocker(self._queue_mutex):
                # ========================================================
                # 1. VERIFICAR DUPLICATA NA FILA
                # ========================================================
                if symbol in self._training_queue_set:
                    logger.debug(f"⏭️ Duplicata na fila: {symbol}")
                    return False

                # ========================================================
                # 2. ADICIONAR À FILA (HEAP QUEUE)
                # ========================================================
                self._training_queue_set.add(symbol)
                heapq.heappush(
                    self._training_queue_priority,
                    (priority, symbol)
                )

                logger.debug(
                    f"✅ Enfileirado: {symbol} (priority={priority}, "
                    f"queue_size={len(self._training_queue_set)})"
                )

                return True

        except Exception as e:
            logger.error(f"❌ Erro ao enfileirar {symbol}: {e}", exc_info=True)
            return False

    def _dequeue_training(self) -> Optional[str]:
        """
        Remove próxima tarefa da fila (maior prioridade)

        Returns:
            Símbolo ou None se fila vazia
        """
        try:
            with QMutexLocker(self._queue_mutex):
                if not self._training_queue_priority:
                    return None

                # Heap pop retorna (priority, symbol)
                priority, symbol = heapq.heappop(self._training_queue_priority)

                # Remover do set
                self._training_queue_set.discard(symbol)

                self.logger.info(
                    f"📤 Desenfileirado: {symbol} (priority={priority})"
                )

                return symbol

        except Exception as e:
            self.logger.error(f"❌ Erro ao desenfileirar: {e}", exc_info=True)
            return None

    def _check_training_cache(self, symbol: str, interval: str) -> Optional[float]:
        """
        Verifica cache de treinamentos recentes
        
        Args:
            symbol: Símbolo
            interval: Intervalo
        
        Returns:
            Horas desde último treinamento, ou None se nunca treinado
        """
        try:
            task_key = (symbol, interval)
            
            with QMutexLocker(self.mutex):
                if task_key not in self._trained_symbols_cache:
                    return None
                
                trained_timestamp = self._trained_symbols_cache[task_key]
                hours_ago = (time.time() - trained_timestamp) / 3600
                
                return hours_ago
        
        except Exception as e:
            self.logger.error(f"❌ Erro ao verificar cache: {e}", exc_info=True)
            return None

    def _process_ready_trainings(self) -> int:
        """
        Processa tarefas da fila cujos dados já estão disponíveis no cache

        LÓGICA REFATORADA:
        1. Itera sobre a fila de treinamento (símbolos, não mais intervalos)
        2. Para cada símbolo, verifica se os 3 intervalos (1h, 4h, 1d) têm dados suficientes
        3. Verifica quantidade de candles para cada intervalo
        4. Se todos os 3 intervalos têm candles suficientes: dispara treinamento
        5. Senão: re-enfileira e continua

        Returns:
            Número de treinamentos disparados
        """
        logger = self.logger
        processed_count = 0
        max_process_per_batch = 10  # Limitar para não travar

        try:
            logger.info("🔄 Processando fila de treinamento...")

            for _ in range(max_process_per_batch):
                # ========================================================
                # 1. BUSCAR PRÓXIMA TAREFA
                # ========================================================
                task = self._dequeue_training()

                if not task:
                    logger.info("🔄 Fila vazia para treinamento")
                    break  # Fila vazia

                symbol = task  # Agora a fila contém apenas símbolos

                logger.info(f"📋 Verificando requisitos para treinamento: {symbol}")

                # ========================================================
                # 2. VERIFICAR MODELOS RECENTES (cache de treinamento)
                # ========================================================
                needs_retrain = False
                for interval in ['1h', '4h', '1d']:
                    hours_since = self._check_training_cache(symbol, interval)
                    if hours_since is None or hours_since >= self.retrain_interval_hours:
                        needs_retrain = True
                        logger.info(f"   {interval}: precisa treinar (last trained: {hours_since:.1f}h ago)" if hours_since else f"   {interval}: precisa treinar (never trained)")
                        break
                    else:
                        logger.info(f"   {interval}: modelo recente ({hours_since:.1f}h ago)")

                if not needs_retrain:
                    logger.info(f"⏭️ Todos os modelos recentes para {symbol}, skip")
                    continue

                # ========================================================
                # 3. VERIFICAR KLINES PARA OS 3 INTERVALOS
                # ========================================================
                intervals_required = ['1h', '4h', '1d']
                all_ready = True
                klines_status = {}

                for interval in intervals_required:
                    requirements = ML_TRAINING_DATA_REQUIREMENTS.get(interval)
                    fetch_limit = int(requirements['ideal_min'] * 1.1)

                    klines = self.cache.get_klines(
                        symbol=symbol,
                        interval=interval,
                        limit=fetch_limit,
                        reader="MLSystem"
                    )

                    if not klines:
                        logger.warning(f"   {interval}: ❌ sem dados no cache")
                        klines_status[interval] = {'ready': False, 'reason': 'no_data'}
                        all_ready = False
                        continue

                    n_candles = len(klines)
                    critical_min = requirements['critical_min']
                    ideal_min = requirements['ideal_min']

                    if n_candles < critical_min:
                        logger.warning(f"   {interval}: ❌ insuficiente ({n_candles}<{critical_min})")
                        klines_status[interval] = {'ready': False, 'reason': 'insufficient', 'count': n_candles}
                        all_ready = False
                    elif n_candles < ideal_min:
                        logger.info(f"   {interval}: ✅ suficiente ({n_candles} candles, mas abaixo do ideal {ideal_min})")
                        klines_status[interval] = {'ready': True, 'count': n_candles, 'quality': 'sufficient'}
                    else:
                        logger.info(f"   {interval}: ✅ ideal ({n_candles}>={ideal_min} candles)")
                        klines_status[interval] = {'ready': True, 'count': n_candles, 'quality': 'ideal'}

                # ========================================================
                # 4. DECISÃO: TREINAR OU RE-ENFILEIRAR
                # ========================================================
                if not all_ready:
                    logger.warning(f"⏸️ {symbol}: nem todos os intervalos prontos, re-enfileirado")
                    self._enqueue_training(symbol, priority=5)
                    continue

                # ========================================================
                # 5. DISPARAR TREINAMENTO (todos os 3 intervalos prontos!)
                # ========================================================
                logger.info(f"🚀 Disparando treinamento COMPLETO: {symbol}")
                logger.info(f"   Treinar 5 modelos: 1h:t3, 1h:t12, 4h:t3, 4h:t6, 1d:t1")

                self.train_model(symbol, force_retrain=False)
                processed_count += 1

                # Limitar para não travar (TrainingWorker gerencia fila interna)
                if processed_count >= 3:
                    logger.debug("⏸️ Limite de processamento atingido (3), parando batch")
                    break
            
            if processed_count > 0:
                logger.info(f"✅ {processed_count} treinamentos disparados")
            else:
                logger.debug("⏳ Nenhum treinamento pronto no momento")
            
            return processed_count
        
        except Exception as e:
            logger.error(f"❌ Erro ao processar fila: {e}", exc_info=True)
            return processed_count
    
    # ========== TIMERS ==========
    
    @Slot()
    def _update_stats(self):
        """
        Atualiza estatísticas periodicamente (5s)
        """
        try:
            with QMutexLocker(self.mutex):
                self.stats['models_in_memory'] = len(self.trained_models)
                self.stats['total_predictions'] = (
                    self.stats['successful_predictions'] + 
                    self.stats['failed_predictions']
                )
            
            # Emitir stats
            self.stats_updated.emit(self.stats.copy())
            
        except Exception as e:
            self.logger.error(f"❌ Erro ao atualizar stats: {e}", exc_info=True)
    
    @Slot()
    def _auto_retrain_check(self):
        """
        Verifica se algum modelo precisa ser retreinado
        
        Executado pelo timer de auto-retrain
        """
        if not self.auto_retrain_enabled:
            return
        
        self.logger.info("🔍 Verificando necessidade de auto-retrain...")
        
        try:
            current_time = time.time()
            symbols_to_retrain = []
            
            with QMutexLocker(self.mutex):
                for symbol, model_info in self.trained_models.items():
                    trained_at = model_info.get('trained_at', 0)
                    hours_since_training = (current_time - trained_at) / 3600
                    
                    if hours_since_training >= self.retrain_interval_hours:
                        symbols_to_retrain.append(symbol)
            
            if symbols_to_retrain:
                self.logger.info(f"🔄 Auto-retrain necessário para {len(symbols_to_retrain)} símbolos")
                for symbol in symbols_to_retrain:
                    self.train_model(symbol, force_retrain=True)
            else:
                self.logger.debug("✅ Nenhum auto-retrain necessário")
                
        except Exception as e:
            self.logger.error(f"❌ Erro no auto-retrain check: {e}", exc_info=True)

# ===========================================================================================
# ML SYSTEM MONITOR DIALOG - PROFESSIONAL DEBUGGING INTERFACE
# ===========================================================================================

class MLSystemMonitorDialog(QDialog):
    """
    MLSystemMonitorDialog - Monitor Profissional do Sistema ML

    FILOSOFIA:
    Interface de debugging e monitoramento completa para o Sistema ML, similar aos
    monitores do CacheSystem e BinanceData, mas específica para ML.

    CARACTERÍSTICAS:
        - 6 tabs profissionais: Overview | Training | Predictions | Models | Stats | Debug
        - Real-time updates (timers + sinais)
        - Não-modal (trabalha com MainWindow aberta)
        - Singleton (apenas uma instância)
        - Logs dedicados
        - Métricas visuais
        - Tools de debug manual

    TABS:
        1. Overview: Health status, quick stats, recent events
        2. Training: Training queue, current training, history
        3. Predictions: Live predictions table, confidence distribution
        4. Models: Models list, details, feature importance
        5. Stats: Aggregated statistics, performance graphs
        6. Debug: Manual controls, system dump, logs

    INTEGRAÇÃO:
        - Conecta sinais do MLSystem
        - Lê stats em tempo real
        - Permite controle manual (force train, force predict)

    ACESSO:
        - Toolbar da MainWindow (botão dedicado)
        - Atalho: Ctrl+M
    
    Interface não-modal de monitoramento e debugging.
    """
    
    # Sinais
    force_train_requested = Signal(str, bool)  # symbol, force_retrain
    force_predict_requested = Signal(str, str)  # symbol, horizon
    
    def __init__(self, ml_system, parent=None):
        """
        Inicializa MLSystemMonitorDialog
        
        Args:
            ml_system: Instância do MLSystem
            parent: Parent widget (MainWindow)
        """
        super().__init__(parent)
        
        self.ml_system = ml_system
        self.logger = logging.getLogger('MLSystemMonitor')
        
        # Configuração
        self.setWindowTitle("🤖 ML System Monitor - Professional Debugging")
        self.setMinimumSize(1200, 800)
        self.setModal(False)  # Não-modal
        
        # Estruturas de dados
        self.events_queue = deque(maxlen=1000)
        self.metrics_history = defaultdict(lambda: deque(maxlen=100))
        
        # Setup UI
        self._setup_ui()
        
        # Conectar sinais
        self._connect_ml_signals()
        
        # Timers
        self.ui_timer = QTimer()
        self.ui_timer.timeout.connect(self._update_ui)
        self.ui_timer.start(100)  # 10 FPS
        
        self.metrics_timer = QTimer()
        self.metrics_timer.timeout.connect(self._calculate_metrics)
        self.metrics_timer.start(1000)  # 1 Hz
        
        self.logger.info("✅ MLSystemMonitorDialog inicializado")
    
    # ========== SETUP UI ==========
    
    def _setup_ui(self):
        """Setup da interface"""
        layout = QVBoxLayout(self)
        
        # Tab widget
        self.tabs = QTabWidget()
        
        # Criar tabs
        self.tab_overview = self._create_overview_tab()
        self.tab_training = self._create_training_tab()
        self.tab_predictions = self._create_predictions_tab()
        self.tab_models = self._create_models_tab()
        self.tab_stats = self._create_stats_tab()
        self.tab_debug = self._create_debug_tab()
        
        # Adicionar tabs
        self.tabs.addTab(self.tab_overview, "📊 Overview")
        self.tabs.addTab(self.tab_training, "⚙️ Training")
        self.tabs.addTab(self.tab_predictions, "🎯 Predictions")
        self.tabs.addTab(self.tab_models, "📚 Models")
        self.tabs.addTab(self.tab_stats, "📈 Stats")
        self.tabs.addTab(self.tab_debug, "🔧 Debug")
        
        layout.addWidget(self.tabs)
        
        # Footer
        footer = self._create_footer()
        layout.addWidget(footer)
    
    # ========== TAB 1: OVERVIEW ==========
    
