    # ========== CONNECT SIGNALS ==========
    
    def _connect_ml_signals(self):
        """Conecta sinais do MLSystem"""
        try:
            self.ml_system.training_started.connect(self._on_training_started)
            self.ml_system.training_completed.connect(self._on_training_completed)
            self.ml_system.training_progress.connect(self._on_training_progress)
            self.ml_system.prediction_generated.connect(self._on_prediction_generated)
            self.ml_system.model_performance_warning.connect(self._on_model_warning)
            self.ml_system.error_occurred.connect(self._on_error)
            self.ml_system.stats_updated.connect(self._on_stats_updated)
            
            self.logger.info("✅ Sinais do MLSystem conectados")
            
        except Exception as e:
            self.logger.error(f"❌ Erro ao conectar sinais: {e}", exc_info=True)
    
    # ========== SLOTS (RECEBEM SINAIS) ==========
    
    @Slot(str)
    def _on_training_started(self, symbol: str):
        """Handler: Treinamento iniciado"""
        event = {
            'timestamp': datetime.now(),
            'type': 'TRAINING_STARTED',
            'symbol': symbol,
            'message': f"Training started: {symbol}"
        }
        self.events_queue.append(event)
        self._log_event(event)
        self._update_current_training(symbol, "Training...", 0)
    
    @Slot(str, dict)
    def _on_training_completed(self, symbol: str, metrics: dict):
        """Handler: Treinamento completo"""
        r2 = metrics.get('r2_score', 0)
        event = {
            'timestamp': datetime.now(),
            'type': 'TRAINING_COMPLETED',
            'symbol': symbol,
            'metrics': metrics,
            'message': f"Training completed: {symbol} (R²: {r2:.2f})"
        }
        self.events_queue.append(event)
        self._log_event(event)
        self._update_current_training(symbol, "Complete", 100)
        self._refresh_models_list()
    
    @Slot(str, int)
    def _on_training_progress(self, message: str, percent: int):
        """Handler: Progresso do treinamento"""
        self.training_progress_label.setText(f"Progress: {percent}%")
        self.training_progress_bar.setValue(percent)
        self.current_training_details.append(f"[{datetime.now().strftime('%H:%M:%S')}] {message}")
    
    @Slot(str, str, dict)
    def _on_prediction_generated(self, symbol: str, horizon: str, prediction: dict):
        """Handler: Previsão gerada"""
        pred_pct = prediction.get('predicted_change_percent', 0)
        conf = prediction.get('confidence', 0) * 100
        
        event = {
            'timestamp': datetime.now(),
            'type': 'PREDICTION',
            'symbol': symbol,
            'horizon': horizon,
            'prediction': prediction,
            'message': f"Prediction: {symbol} {horizon} {pred_pct:+.1f}% (conf: {conf:.0f}%)"
        }
        self.events_queue.append(event)
        self._log_event(event)
        self._add_prediction_to_table(symbol, horizon, prediction)
    
    @Slot(str, str, float)
    def _on_model_warning(self, symbol: str, metric: str, value: float):
        """Handler: Warning de performance"""
        event = {
            'timestamp': datetime.now(),
            'type': 'WARNING',
            'symbol': symbol,
            'message': f"⚠️ Warning: {symbol} - {metric}: {value:.2f}"
        }
        self.events_queue.append(event)
        self._log_event(event)
    
    @Slot(str, str)
    def _on_error(self, error_type: str, message: str):
        """Handler: Erro"""
        event = {
            'timestamp': datetime.now(),
            'type': 'ERROR',
            'message': f"❌ Error: {error_type} - {message}"
        }
        self.events_queue.append(event)
        self._log_event(event)
    
    @Slot(dict)
    def _on_stats_updated(self, stats: dict):
        """Handler: Stats atualizadas"""
        self._update_stats_display(stats)
    
    # ========== UPDATE UI ==========
    
    def _update_ui(self):
        """Atualiza UI (10 FPS)"""
        # Update labels, progress bars, etc
        pass
    
    def _calculate_metrics(self):
        """Calcula métricas agregadas (1 Hz)"""
        # Processar eventos recentes
        # Calcular estatísticas
        pass
    
    def _log_event(self, event: dict):
        """Adiciona evento ao terminal de logs"""
        timestamp = event['timestamp'].strftime('%H:%M:%S')
        msg_type = event['type']
        message = event['message']
        
        # Adicionar ao log
        log_entry = f"[{timestamp}] [{msg_type}] {message}"
        self.ml_logs_text.append(log_entry)
        
        # Adicionar aos recent events (Overview tab)
        if len(self.events_queue) > 0:
            recent = "\n".join([
                f"[{e['timestamp'].strftime('%H:%M:%S')}] {e['message']}"
                for e in list(self.events_queue)[-10:]
            ])
            self.events_text.setPlainText(recent)
    
    def _update_current_training(self, symbol: str, status: str, progress: int):
        """Atualiza display do treinamento atual"""
        self.current_training_label.setText(f"CURRENT TRAINING: {symbol}")
        self.training_status_label.setText(f"Status: {status}")
        self.current_training_progress.setValue(progress)
    
    def _add_prediction_to_table(self, symbol: str, horizon: str, prediction: dict):
        """Adiciona previsão à tabela"""
        row = self.predictions_table.rowCount()
        self.predictions_table.insertRow(row)
        
        pred_pct = prediction.get('predicted_change_percent', 0)
        conf = prediction.get('confidence', 0) * 100
        direction = "🔺 UP" if pred_pct > 0 else "🔻 DOWN"
        timestamp = datetime.now().strftime('%H:%M:%S')
        
        self.predictions_table.setItem(row, 0, QTableWidgetItem(symbol))
        self.predictions_table.setItem(row, 1, QTableWidgetItem(horizon))
        self.predictions_table.setItem(row, 2, QTableWidgetItem(f"{pred_pct:+.1f}%"))
        self.predictions_table.setItem(row, 3, QTableWidgetItem(f"{conf:.0f}%"))
        self.predictions_table.setItem(row, 4, QTableWidgetItem(direction))
        self.predictions_table.setItem(row, 5, QTableWidgetItem(timestamp))
        
        # Limit table size
        if self.predictions_table.rowCount() > 100:
            self.predictions_table.removeRow(0)
    
    def _update_stats_display(self, stats: dict):
        """Atualiza display de estatísticas"""
        # Update models card
        models_in_memory = stats.get('models_in_memory', 0)
        self.models_trained_label.setText(f"Trained: {models_in_memory}")
        self.models_memory_label.setText(f"In Memory: {models_in_memory}")
        
        # Update predictions card
        total_pred = stats.get('total_predictions', 0)
        success_pred = stats.get('successful_predictions', 0)
        success_rate = (success_pred / total_pred * 100) if total_pred > 0 else 0
        
        self.predictions_today_label.setText(f"Today: {total_pred}")
        self.predictions_success_label.setText(f"Success: {success_rate:.1f}%")
        
        # Update health bar
        health_score = min(100, int(success_rate))
        self.health_bar.setValue(health_score)
    
    def _refresh_models_list(self):
        """Atualiza lista de modelos"""
        models_info = self.ml_system.get_all_models_info()
        
        self.models_table.setRowCount(0)
        for symbol, info in models_info.items():
            row = self.models_table.rowCount()
            self.models_table.insertRow(row)
            
            metrics = info.get('metrics', {})
            r2 = metrics.get('r2_score', 0)
            mae = metrics.get('mae', 0)
            rmse = metrics.get('rmse', 0)
            trained_at = info.get('trained_at', 0)
            
            time_ago = self._time_ago(trained_at)
            
            self.models_table.setItem(row, 0, QTableWidgetItem(symbol))
            self.models_table.setItem(row, 1, QTableWidgetItem('ensemble'))
            self.models_table.setItem(row, 2, QTableWidgetItem(f"{r2:.4f}"))
            self.models_table.setItem(row, 3, QTableWidgetItem(f"{mae:.4f}"))
            self.models_table.setItem(row, 4, QTableWidgetItem(f"{rmse:.4f}"))
            self.models_table.setItem(row, 5, QTableWidgetItem(time_ago))
    
    def _time_ago(self, timestamp: float) -> str:
        """Calcula 'time ago' string"""
        import time
        seconds_ago = time.time() - timestamp
        
        if seconds_ago < 60:
            return f"{int(seconds_ago)}s ago"
        elif seconds_ago < 3600:
            return f"{int(seconds_ago/60)}m ago"
        elif seconds_ago < 86400:
            return f"{int(seconds_ago/3600)}h ago"
        else:
            return f"{int(seconds_ago/86400)}d ago"
    
