    def _on_force_train(self):
        """Handler: Force train"""
        symbol = self.debug_symbol_combo.currentText()
        if symbol:
            self.ml_system.train_model(symbol, force_retrain=True)
            self._log_event({
                'timestamp': datetime.now(),
                'type': 'DEBUG',
                'message': f"Manual train requested: {symbol}"
            })
    
    def _on_force_predict(self):
        """Handler: Force predict"""
        symbol = self.debug_symbol_combo.currentText()
        horizon = self.debug_horizon_combo.currentText()
        if symbol and horizon:
            self.ml_system.predict(symbol, horizon)
            self._log_event({
                'timestamp': datetime.now(),
                'type': 'DEBUG',
                'message': f"Manual prediction requested: {symbol} ({horizon})"
            })
    
