# CREATE ALERT DIALOG - FORMULÁRIO COMPLETO
# ============================================================================

class CreateAlertDialog(QDialog):
    """
    Diálogo completo para criar/editar alertas
    
    CAMPOS:
        - Símbolo (combo editável)
        - Tipo (Price, Volume, Indicator, ML, Pattern)
        - Condição (Above, Below, Cross Up, Cross Down)
        - Valor target (double spinner)
        - Descrição (texto livre)
        - Repetir (checkbox)
        - Som (checkbox)
        - Telegram (checkbox)
        - ML Confidence (spinner 0-100%)
    """
    
    def __init__(self, systems: Dict, alert: Alert = None, parent=None):
        """
        Inicializa diálogo
        
        Args:
            systems: Dicionário com referências aos sistemas
            alert: Alerta existente (para edição) ou None (criação)
            parent: Widget pai
        """
        super().__init__(parent)
        self.systems = systems
        self.alert = alert
        self.is_edit_mode = alert is not None
        
        self.setWindowTitle("Editar Alerta" if self.is_edit_mode else "Criar Novo Alerta")
        self.setModal(True)
        self.resize(500, 600)
        
        self.setup_ui()
        
        if self.is_edit_mode:
            self.load_alert_data(alert)
    
    def setup_ui(self):
        """Configura interface"""
        layout = QVBoxLayout()
        
        # === FORMULÁRIO ===
        form_group = QGroupBox("Configurações do Alerta")
        form_layout = QFormLayout(form_group)
        
        # Símbolo
        self.combo_symbol = QComboBox()
        self.combo_symbol.setEditable(True)
        self.combo_symbol.addItems([
            "BTCUSDT", "ETHUSDT", "BNBUSDT", "ADAUSDT", "DOTUSDT",
            "XRPUSDT", "SOLUSDT", "MATICUSDT", "LINKUSDT", "AVAXUSDT",
            "ATOMUSDT", "LTCUSDT", "UNIUSDT", "VETUSDT", "FILUSDT"
        ])
        form_layout.addRow("Símbolo:", self.combo_symbol)
        
        # Tipo
        self.combo_type = QComboBox()
        self.combo_type.addItems(["Preço", "Volume", "Indicador", "ML", "Padrão"])
        self.combo_type.currentTextChanged.connect(self._on_type_changed)
        form_layout.addRow("Tipo:", self.combo_type)
        
        # Condição
        self.combo_condition = QComboBox()
        self._update_condition_options("Preço")
        form_layout.addRow("Condição:", self.combo_condition)
        
        # Valor
        self.spin_value = QDoubleSpinBox()
        self.spin_value.setDecimals(8)
        self.spin_value.setMaximum(99999999.0)
        self.spin_value.setValue(0.0)
        form_layout.addRow("Valor Target:", self.spin_value)
        
        # Descrição
        self.edit_description = QLineEdit()
        self.edit_description.setPlaceholderText("Descrição opcional do alerta...")
        form_layout.addRow("Descrição:", self.edit_description)
        
        layout.addWidget(form_group)
        
        # === OPÇÕES ===
        options_group = QGroupBox("Opções")
        options_layout = QVBoxLayout(options_group)
        
        self.check_repeat = QCheckBox("Repetir alerta após disparo")
        self.check_repeat.setChecked(True)
        options_layout.addWidget(self.check_repeat)
        
        self.check_sound = QCheckBox("Reproduzir som ao disparar")
        self.check_sound.setChecked(True)
        options_layout.addWidget(self.check_sound)
        
        self.check_telegram = QCheckBox("Enviar notificação Telegram")
        self.check_telegram.setChecked(False)
        options_layout.addWidget(self.check_telegram)
        
        # ML Confidence
        ml_layout = QHBoxLayout()
        ml_layout.addWidget(QLabel("ML Confidence Threshold:"))
        self.spin_ml_confidence = QDoubleSpinBox()
        self.spin_ml_confidence.setDecimals(2)
        self.spin_ml_confidence.setRange(0.0, 1.0)
        self.spin_ml_confidence.setSingleStep(0.05)
        self.spin_ml_confidence.setValue(0.75)
        self.spin_ml_confidence.setSuffix("%")
        ml_layout.addWidget(self.spin_ml_confidence)
        ml_layout.addStretch()
        options_layout.addLayout(ml_layout)
        
        layout.addWidget(options_group)
        
        # === BOTÕES ===
        buttons_layout = QHBoxLayout()
        
        self.btn_save = QPushButton("💾 Salvar" if self.is_edit_mode else "✅ Criar Alerta")
        self.btn_save.clicked.connect(self.accept)
        
        self.btn_cancel = QPushButton("❌ Cancelar")
        self.btn_cancel.clicked.connect(self.reject)
        
        buttons_layout.addWidget(self.btn_save)
        buttons_layout.addWidget(self.btn_cancel)
        
        layout.addLayout(buttons_layout)
        
        self.setLayout(layout)
    
    def _on_type_changed(self, type_text: str):
        """Atualiza opções de condição baseado no tipo"""
        self._update_condition_options(type_text)
    
    def _update_condition_options(self, type_text: str):
        """Atualiza combo de condições"""
        self.combo_condition.clear()
        
        if type_text == "Preço":
            self.combo_condition.addItems([
                "Acima de", "Abaixo de", "Cruzar para cima", "Cruzar para baixo"
            ])
        elif type_text == "Volume":
            self.combo_condition.addItems(["Acima de", "Abaixo de"])
        elif type_text == "Indicador":
            self.combo_condition.addItems([
                "RSI acima de", "RSI abaixo de",
                "MACD acima de", "MACD abaixo de",
                "Bollinger banda superior", "Bollinger banda inferior"
            ])
        elif type_text == "ML":
            self.combo_condition.addItems(["Confiança acima de"])
        elif type_text == "Padrão":
            self.combo_condition.addItems(["Padrão detectado"])
    
    def load_alert_data(self, alert: Alert):
        """Carrega dados de alerta existente"""
        self.combo_symbol.setCurrentText(alert.symbol)
        
        # Mapeia tipo
        type_map = {
            'price': 'Preço',
            'volume': 'Volume',
            'indicator': 'Indicador',
            'ml': 'ML',
            'pattern': 'Padrão'
        }
        self.combo_type.setCurrentText(type_map.get(alert.alert_type, 'Preço'))
        
        # Mapeia condição
        condition_map = {
            'above': 'Acima de',
            'below': 'Abaixo de',
            'cross_up': 'Cruzar para cima',
            'cross_down': 'Cruzar para baixo'
        }
        self.combo_condition.setCurrentText(condition_map.get(alert.condition, 'Acima de'))
        
        self.spin_value.setValue(alert.value)
        self.edit_description.setText(alert.description)
        self.check_repeat.setChecked(alert.repeat)
        self.check_sound.setChecked(alert.sound_enabled)
        self.check_telegram.setChecked(alert.telegram_enabled)
        self.spin_ml_confidence.setValue(alert.ml_confidence_threshold)
    
    def get_alert_data(self) -> Dict:
        """Retorna dados do formulário"""
        type_map = {
            'Preço': 'price',
            'Volume': 'volume',
            'Indicador': 'indicator',
            'ML': 'ml',
            'Padrão': 'pattern'
        }
        
        condition_map = {
            'Acima de': 'above',
            'Abaixo de': 'below',
            'Cruzar para cima': 'cross_up',
            'Cruzar para baixo': 'cross_down',
            'Confiança acima de': 'above',
            'Padrão detectado': 'detected',
            'RSI acima de': 'above',
            'RSI abaixo de': 'below',
            'MACD acima de': 'above',
            'MACD abaixo de': 'below',
            'Bollinger banda superior': 'upper',
            'Bollinger banda inferior': 'lower'
        }
        
        return {
            'symbol': self.combo_symbol.currentText().upper(),
            'alert_type': type_map[self.combo_type.currentText()],
            'condition': condition_map.get(self.combo_condition.currentText(), 'above'),
            'value': self.spin_value.value(),
            'description': self.edit_description.text(),
            'repeat': self.check_repeat.isChecked(),
            'sound_enabled': self.check_sound.isChecked(),
            'telegram_enabled': self.check_telegram.isChecked(),
            'ml_confidence_threshold': self.spin_ml_confidence.value()
        }


# ============================================================================
# ML SUGGESTIONS DIALOG - SUGESTÕES IA
# ============================================================================

class MLSuggestionsDialog(QDialog):
    """
    Diálogo de sugestões de IA
    
    FEATURES:
        - Análise técnica do símbolo
        - Sugestões inteligentes de alertas
        - Criação em lote
    """
    
    def __init__(self, ml_generator: MLAlertGenerator, alert_manager, parent=None):
        """
        Inicializa diálogo
        
        Args:
            ml_generator: Gerador ML
            alert_manager: AlertManager
            parent: Widget pai
        """
        super().__init__(parent)
        self.ml_generator = ml_generator
        self.alert_manager = alert_manager
        self.suggestions = {}
        
        self.setWindowTitle("🤖 Sugestões de Alertas por IA")
        self.setModal(True)
        self.resize(800, 600)
        
        self.setup_ui()
    
    def setup_ui(self):
        """Configura interface"""
        layout = QVBoxLayout()
        
        # === CONTROLES ===
        controls_layout = QHBoxLayout()
        
        controls_layout.addWidget(QLabel("Símbolo:"))
        
        self.combo_symbol = QComboBox()
        self.combo_symbol.setEditable(True)
        self.combo_symbol.addItems(["BTCUSDT", "ETHUSDT", "ADAUSDT", "DOTUSDT"])
        controls_layout.addWidget(self.combo_symbol)
        
        self.btn_analyze = QPushButton("🔍 Analisar")
        self.btn_analyze.clicked.connect(self.analyze_symbol)
        controls_layout.addWidget(self.btn_analyze)
        
        controls_layout.addStretch()
        
        layout.addLayout(controls_layout)
        
        # === RESULTADOS ===
        self.tab_results = QTabWidget()
        
        # Tab 1: Análise Técnica
        self.create_analysis_tab()
        
        # Tab 2: Sugestões
        self.create_suggestions_tab()
        
        layout.addWidget(self.tab_results)
        
        # === BOTÕES ===
        buttons_layout = QHBoxLayout()
        
        self.btn_create_all = QPushButton("✅ Criar Todos os Alertas")
        self.btn_create_all.clicked.connect(self.create_all_suggestions)
        self.btn_create_all.setEnabled(False)
        
        self.btn_close = QPushButton("Fechar")
        self.btn_close.clicked.connect(self.reject)
        
        buttons_layout.addWidget(self.btn_create_all)
        buttons_layout.addStretch()
        buttons_layout.addWidget(self.btn_close)
        
        layout.addLayout(buttons_layout)
        
        self.setLayout(layout)
    
    def create_analysis_tab(self):
        """Cria tab de análise técnica"""
        analysis_widget = QWidget()
        analysis_layout = QVBoxLayout(analysis_widget)
        
        # Métricas principais
        metrics_frame = QFrame()
        metrics_frame.setFrameStyle(QFrame.StyledPanel)
        metrics_layout = QGridLayout(metrics_frame)
        
        self.lbl_current_price = QLabel("Preço: -")
        self.lbl_volatility = QLabel("Volatilidade: -")
        self.lbl_trend_strength = QLabel("Força Tendência: -")
        self.lbl_breakout_prob = QLabel("Prob. Breakout: -")
        
        metrics_layout.addWidget(self.lbl_current_price, 0, 0)
        metrics_layout.addWidget(self.lbl_volatility, 0, 1)
        metrics_layout.addWidget(self.lbl_trend_strength, 1, 0)
        metrics_layout.addWidget(self.lbl_breakout_prob, 1, 1)
        
        analysis_layout.addWidget(metrics_frame)
        
        # Suporte e Resistência
        levels_group = QGroupBox("Níveis de Suporte e Resistência")
        levels_layout = QVBoxLayout(levels_group)
        
        self.text_support = QTextEdit()
        self.text_support.setReadOnly(True)
        self.text_support.setMaximumHeight(100)
        levels_layout.addWidget(QLabel("Suportes:"))
        levels_layout.addWidget(self.text_support)
        
        self.text_resistance = QTextEdit()
        self.text_resistance.setReadOnly(True)
        self.text_resistance.setMaximumHeight(100)
        levels_layout.addWidget(QLabel("Resistências:"))
        levels_layout.addWidget(self.text_resistance)
        
        analysis_layout.addWidget(levels_group)
        
        self.tab_results.addTab(analysis_widget, "📊 Análise Técnica")
    
    def create_suggestions_tab(self):
        """Cria tab de sugestões"""
        suggestions_widget = QWidget()
        suggestions_layout = QVBoxLayout(suggestions_widget)
        
        # Tabela de sugestões
        self.table_suggestions = QTableWidget()
        self.table_suggestions.setColumnCount(5)
        self.table_suggestions.setHorizontalHeaderLabels([
            "Tipo", "Condição", "Valor", "Razão", "Confiança"
        ])
        self.table_suggestions.horizontalHeader().setStretchLastSection(True)
        self.table_suggestions.setSelectionBehavior(QAbstractItemView.SelectRows)
        
        suggestions_layout.addWidget(self.table_suggestions)
        
        self.tab_results.addTab(suggestions_widget, "💡 Sugestões")
    
    def analyze_symbol(self):
        """Analisa símbolo e gera sugestões"""
        symbol = self.combo_symbol.currentText()
        
        # Análise ML
        analysis = self.ml_generator.analyze_symbol_patterns(symbol)
        
        if not analysis:
            QMessageBox.warning(self, "Erro", "Falha ao analisar símbolo.")
            return
        
        self.suggestions = analysis
        
        # Atualiza análise técnica
        self.lbl_current_price.setText(f"Preço: ${analysis.get('current_price', 0):.2f}")
        self.lbl_volatility.setText(f"Volatilidade: {analysis.get('volatility', 0):.2f}%")
        self.lbl_trend_strength.setText(f"Força Tendência: {analysis.get('trend_strength', 0):.2%}")
        self.lbl_breakout_prob.setText(f"Prob. Breakout: {analysis.get('breakout_probability', 0):.2%}")
        
        # Suportes
        supports = analysis.get('support_levels', [])
        self.text_support.setText("\n".join([f"${s:.2f}" for s in supports]))
        
        # Resistências
        resistances = analysis.get('resistance_levels', [])
        self.text_resistance.setText("\n".join([f"${r:.2f}" for r in resistances]))
        
        # Atualiza tabela de sugestões
        suggested = analysis.get('suggested_alerts', [])
        self.table_suggestions.setRowCount(len(suggested))
        
        for row, alert in enumerate(suggested):
            self.table_suggestions.setItem(row, 0, QTableWidgetItem(alert['type']))
            self.table_suggestions.setItem(row, 1, QTableWidgetItem(alert['condition']))
            self.table_suggestions.setItem(row, 2, QTableWidgetItem(f"{alert['value']:.2f}"))
            self.table_suggestions.setItem(row, 3, QTableWidgetItem(alert['reason']))
            self.table_suggestions.setItem(row, 4, QTableWidgetItem(f"{alert['confidence']:.0%}"))
        
        self.btn_create_all.setEnabled(len(suggested) > 0)
    
    def create_all_suggestions(self):
        """Cria todos os alertas sugeridos"""
        suggested = self.suggestions.get('suggested_alerts', [])
        
        created_count = 0
        for alert in suggested:
            alert_id = self.alert_manager.create_alert(
                level=AlertLevel.INFO,
                source=AlertSource.ML,
                title=f"ML Suggestion: {alert['reason']}",
                message=f"IA sugeriu alerta para {self.combo_symbol.currentText()}",
                symbol=self.combo_symbol.currentText(),
                alert_type=alert['type'],
                condition=alert['condition'],
                value=alert['value'],
                description=alert['reason']
            )
            
            if alert_id:
                created_count += 1
        
        QMessageBox.information(
            self,
            "Sucesso",
            f"{created_count} alertas criados com sucesso!"
        )
        
        self.accept()


