class TemplatesDialog(QDialog):
    """
    Diálogo de templates reutilizáveis
    
    FEATURES:
        - Galeria de templates predefinidos
        - Aplicação rápida
        - Preview de valores
    """
    
    def __init__(self, templates: List[AlertTemplate], alert_manager, parent=None):
        """
        Inicializa diálogo
        
        Args:
            templates: Lista de templates
            alert_manager: AlertManager
            parent: Widget pai
        """
        super().__init__(parent)
        self.templates = templates
        self.alert_manager = alert_manager
        
        self.setWindowTitle("📋 Galeria de Templates")
        self.setModal(True)
        self.resize(700, 500)
        
        self.setup_ui()
    
    def setup_ui(self):
        """Configura interface"""
        layout = QVBoxLayout()
        
        # === CONFIGURAÇÃO ===
        config_layout = QHBoxLayout()
        
        config_layout.addWidget(QLabel("Símbolo:"))
        
        self.combo_symbol = QComboBox()
        self.combo_symbol.setEditable(True)
        self.combo_symbol.addItems(["BTCUSDT", "ETHUSDT", "BNBUSDT"])
        config_layout.addWidget(self.combo_symbol)
        
        config_layout.addWidget(QLabel("Preço Atual:"))
        
        self.spin_price = QDoubleSpinBox()
        self.spin_price.setDecimals(2)
        self.spin_price.setMaximum(999999.0)
        self.spin_price.setValue(45000.0)
        config_layout.addWidget(self.spin_price)
        
        config_layout.addStretch()
        
        layout.addLayout(config_layout)
        
        # === LISTA DE TEMPLATES ===
        self.table_templates = QTableWidget()
        self.table_templates.setColumnCount(5)
        self.table_templates.setHorizontalHeaderLabels([
            "Nome", "Descrição", "Tipo", "Valor Calculado", "Ação"
        ])
        self.table_templates.horizontalHeader().setStretchLastSection(True)
        self.table_templates.setSelectionBehavior(QAbstractItemView.SelectRows)
        
        # Preenche templates
        self.populate_templates()
        
        layout.addWidget(self.table_templates)
        
        # === BOTÕES ===
        buttons_layout = QHBoxLayout()
        
        self.btn_close = QPushButton("Fechar")
        self.btn_close.clicked.connect(self.reject)
        
        buttons_layout.addStretch()
        buttons_layout.addWidget(self.btn_close)
        
        layout.addLayout(buttons_layout)
        
        self.setLayout(layout)
    
    def populate_templates(self):
        """Preenche tabela com templates"""
        self.table_templates.setRowCount(len(self.templates))
        
        for row, template in enumerate(self.templates):
            # Nome
            self.table_templates.setItem(row, 0, QTableWidgetItem(template.name))
            
            # Descrição
            self.table_templates.setItem(row, 1, QTableWidgetItem(template.description))
            
            # Tipo
            self.table_templates.setItem(row, 2, QTableWidgetItem(template.alert_type))
            
            # Valor calculado
            try:
                calculated_value = eval(template.value_formula, {"price": self.spin_price.value()})
                self.table_templates.setItem(row, 3, QTableWidgetItem(f"{calculated_value:.2f}"))
            except:
                self.table_templates.setItem(row, 3, QTableWidgetItem("N/A"))
            
            # Botão aplicar
            btn_apply = QPushButton("✅ Aplicar")
            btn_apply.clicked.connect(lambda checked, t=template: self.apply_template(t))
            self.table_templates.setCellWidget(row, 4, btn_apply)
    
    def apply_template(self, template: AlertTemplate):
        """Aplica template"""
        symbol = self.combo_symbol.currentText()
        current_price = self.spin_price.value()
        
        alert_id = self.alert_manager.apply_template(template, symbol, current_price)
        
        if alert_id:
            QMessageBox.information(
                self,
                "Sucesso",
                f"Template '{template.name}' aplicado!\nAlerta criado: {alert_id[:8]}..."
            )
        else:
            QMessageBox.warning(self, "Erro", "Falha ao aplicar template.")


