    def _connect_signals(self):
        """Conecta sinais"""
        self.alert_manager.alert_created.connect(self._on_alert_created)
        self.alert_manager.alert_triggered.connect(self._on_alert_triggered)
        self.alert_manager.statistics_updated.connect(self._update_metrics)
    
    def _on_alert_created(self, alert: Alert):
        """Handler para alerta criado"""
        self.update_active_alerts_table()
        self._update_metrics_now()
    
    def _on_alert_triggered(self, alert_id: str, current_value: float):
        """Handler para alerta disparado"""
        self.update_history_table()
        self._update_metrics_now()
    
    def _update_metrics(self, stats: Dict):
        """Atualiza métricas do dashboard"""
        self.lbl_total_alerts.setText(f"📊 Total: {stats.get('total_alerts', 0)}")
        self.lbl_active_alerts.setText(f"🟢 Ativos: {stats.get('active_alerts', 0)}")
        self.lbl_triggered_today.setText(f"🔔 Hoje: {stats.get('triggered_today', 0)}")
        self.lbl_success_rate.setText(f"✅ Taxa: {stats.get('success_rate', 0):.1f}%")
        self.lbl_most_active.setText(f"🏆 Ativo: {stats.get('most_active_symbol', 'N/A')}")
        self.lbl_reliability.setText(f"🎯 Score: {stats.get('reliability_score', 0):.0f}")
    
    def _update_metrics_now(self):
        """Força atualização imediata de métricas"""
        stats = self.alert_manager.get_statistics()
        self._update_metrics(stats)
    
    def update_active_alerts_table(self):
        """Atualiza tabela de alertas ativos"""
        alerts = self.alert_manager.get_all_alerts()
        self.table_active.setRowCount(len(alerts))
        
        for row, alert in enumerate(alerts):
            # Checkbox
            checkbox = QCheckBox()
            self.table_active.setCellWidget(row, 0, checkbox)
            
            # Status
            status = "🟢" if alert.is_active else "🔴"
            self.table_active.setItem(row, 1, QTableWidgetItem(status))
            
            # Símbolo
            self.table_active.setItem(row, 2, QTableWidgetItem(alert.symbol))
            
            # Tipo
            self.table_active.setItem(row, 3, QTableWidgetItem(alert.alert_type))
            
            # Condição
            self.table_active.setItem(row, 4, QTableWidgetItem(alert.condition))
            
            # Target
            self.table_active.setItem(row, 5, QTableWidgetItem(f"{alert.value:.4f}"))
            
            # Atual
            self.table_active.setItem(row, 6, QTableWidgetItem(f"{alert.current_value:.4f}"))
            
            # Progress bar
            progress = self.create_progress_bar(alert)
            self.table_active.setCellWidget(row, 7, progress)
            
            # Criado
            self.table_active.setItem(row, 8, QTableWidgetItem(alert.created_at[:16] if alert.created_at else ""))
            
            # Ações
            actions = self.create_actions_widget(alert)
            self.table_active.setCellWidget(row, 9, actions)
    
    def create_progress_bar(self, alert: Alert) -> QWidget:
        """Cria barra de progresso visual"""
        widget = QWidget()
        layout = QHBoxLayout(widget)
        layout.setContentsMargins(5, 2, 5, 2)
        
        progress_bar = QProgressBar()
        progress_bar.setMaximumHeight(20)
        progress_bar.setTextVisible(True)
        
        try:
            if alert.current_value > 0 and alert.value > 0:
                if alert.condition == 'above':
                    progress = min(100, (alert.current_value / alert.value) * 100)
                elif alert.condition == 'below':
                    progress = max(0, 100 - ((alert.current_value / alert.value) * 100))
                else:
                    progress = 50
                
                progress_bar.setValue(int(progress))
                progress_bar.setFormat(f"{progress:.1f}%")
                
                # Cor por progresso
                if progress >= 90:
                    progress_bar.setStyleSheet("QProgressBar::chunk { background-color: #f44336; }")
                elif progress >= 70:
                    progress_bar.setStyleSheet("QProgressBar::chunk { background-color: #ff9800; }")
                else:
                    progress_bar.setStyleSheet("QProgressBar::chunk { background-color: #4caf50; }")
            else:
                progress_bar.setValue(0)
                progress_bar.setFormat("N/A")
        except:
            progress_bar.setValue(0)
            progress_bar.setFormat("Erro")
        
        layout.addWidget(progress_bar)
        return widget
    
    def create_actions_widget(self, alert: Alert) -> QWidget:
        """Cria widget de ações"""
        widget = QWidget()
        layout = QHBoxLayout(widget)
        layout.setContentsMargins(2, 0, 2, 0)
        layout.setSpacing(2)
        
        # Toggle
        btn_toggle = QPushButton("⏸️" if alert.is_active else "▶️")
        btn_toggle.setMaximumWidth(25)
        btn_toggle.clicked.connect(lambda: self.toggle_alert(alert.id))
        layout.addWidget(btn_toggle)
        
        # Edit
        btn_edit = QPushButton("✏️")
        btn_edit.setMaximumWidth(25)
        btn_edit.clicked.connect(lambda: self.edit_alert(alert))
        layout.addWidget(btn_edit)
        
        # Delete
        btn_delete = QPushButton("🗑️")
        btn_delete.setMaximumWidth(25)
        btn_delete.clicked.connect(lambda: self.delete_alert(alert.id))
        layout.addWidget(btn_delete)
        
        return widget
    
    def update_history_table(self):
        """Atualiza tabela de histórico"""
        history = self.alert_manager.get_history(1000)
        self.table_history.setRowCount(len(history))
        
        for row, record in enumerate(history):
            self.table_history.setItem(row, 0, QTableWidgetItem(record.trigger_time))
            self.table_history.setItem(row, 1, QTableWidgetItem(record.symbol))
            self.table_history.setItem(row, 2, QTableWidgetItem("Price"))  # Extrair do record
            self.table_history.setItem(row, 3, QTableWidgetItem(record.alert_description))
            self.table_history.setItem(row, 4, QTableWidgetItem(f"{record.trigger_value:.4f}"))
            
            status = "✅" if record.notification_sent else "❌"
            self.table_history.setItem(row, 5, QTableWidgetItem(status))
    
