# BINANCE CREDENTIALS DIALOG - DIÁLOGO PROFISSIONAL DE CREDENCIAIS
# ============================================================================

class BinanceCredentialsDialog(QDialog):
    """
    Diálogo profissional enterprise para configuração de credenciais Binance

    Features:
        - Interface profissional e intuitiva
        - Campos com validação visual
        - Botão para mostrar/ocultar credenciais
        - Links diretos para Binance (criar conta testnet e gerenciar API keys)
        - Validação robusta antes de salvar
        - Botão "Salvar" só ativa após validação bem-sucedida
        - Feedback visual de loading durante validação
    """

    def __init__(self, config_manager, validate_callback, mode: str = "live", parent=None):
        """
        Args:
            config_manager: Instância do ConfigManager para salvar credenciais
            validate_callback: Função de validação (deve retornar bool)
            mode: Modo de operação ('offline', 'paper', 'live')
            parent: Parent widget
        """
        super().__init__(parent)

        self.config = config_manager
        self.validate_callback = validate_callback
        self.mode = mode  # Modo de operação (offline/paper/live)
        self.is_validated = False

        # Configurar título e dimensões baseado no modo
        mode_titles = {
            'offline': 'Offline Mode - Simulated Credentials',
            'paper': 'Paper Trading - Testnet Credentials',
            'live': 'Real Trading - Live Credentials'
        }

        self.setWindowTitle(f"Binance API Credentials - {mode_titles.get(mode, 'Unknown Mode')}")
        self.setModal(True)
        self.setMinimumWidth(600)
        self.setMinimumHeight(500)

        self._init_ui()

    def _init_ui(self):
        """Inicializa interface do diálogo"""
        layout = QVBoxLayout(self)
        layout.setSpacing(20)
        layout.setContentsMargins(30, 30, 30, 30)

        # ====================================================================
        # HEADER
        # ====================================================================
        header_layout = QHBoxLayout()

        # Ícone
        icon_label = QLabel("🔐")
        icon_label.setStyleSheet("font-size: 48px;")
        header_layout.addWidget(icon_label)

        # Título e descrição baseados no modo
        title_layout = QVBoxLayout()

        mode_configs = {
            'offline': {
                'icon': '🔒',
                'title': 'Offline Mode Configuration',
                'desc': 'Configure simulated credentials for offline mode.\nNo real API connection - data is simulated locally.',
                'color': '#808080'
            },
            'paper': {
                'icon': '📄',
                'title': 'Paper Trading Configuration',
                'desc': 'Enter your Binance TESTNET credentials for paper trading.\nTestnet uses fake money for practice trading.',
                'color': '#FFA500'
            },
            'live': {
                'icon': '⚠️',
                'title': 'Real Trading Configuration',
                'desc': 'Enter your Binance LIVE credentials for real trading.\n⚠️ WARNING: This uses REAL MONEY! Your credentials are encrypted and stored securely.',
                'color': '#CC0000'
            }
        }

        config = mode_configs.get(self.mode, mode_configs['live'])

        # Atualizar ícone no header
        icon_label.setText(config['icon'])

        title_label = QLabel(config['title'])
        title_label.setStyleSheet("font-size: 18px; font-weight: bold;")

        desc_label = QLabel(config['desc'])
        desc_label.setWordWrap(True)
        desc_label.setStyleSheet(f"color: {config['color']}; font-size: 12px; font-weight: bold;")

        title_layout.addWidget(title_label)
