        rate_limit_spin = QSpinBox()
        rate_limit_spin.setRange(600, 2400)
        rate_limit_spin.setSingleStep(100)
        rate_limit_spin.setSuffix(" req/min")
        rate_limit_spin.setToolTip("Limite de requisições para evitar ban da API")
        self._register_widget('api.binance.rate_limit', rate_limit_spin)
        rate_layout.addWidget(rate_limit_spin)
        
        # Timeout
        rate_layout.addWidget(QLabel("Timeout de Requisição:"))
        timeout_spin = QSpinBox()
        timeout_spin.setRange(5, 60)
        timeout_spin.setSuffix(" segundos")
