    def _setup_timers(self):
        """
        Configura Timers Qt --- Monitoramento Periódico
        
        TIMERS:
            1. Health Check (30s) - Verifica saúde de todos os sistemas
            2. Metrics Update (2s) - Atualiza métricas no status bar
            3. Time Display (1s) - Atualiza relógio no status bar
        
        DESIGN:
            Timers Qt são thread-safe e não bloqueiam UI.
            Operações pesadas devem ser executadas em workers.
        """
        logger = self.logger
        
        try:
            logger.info("Configurando timers de monitoramento...")
            
            # Timer 1: Health Check (30 segundos)
            self.health_timer = QTimer(self)
            self.health_timer.timeout.connect(self._perform_health_check)
            #self.health_timer.start(1000 * 240)  # 4min
            logger.debug("✅ Health check timer iniciado (30s)")
            
            # Timer 2: Metrics Update (2 segundos)
            self.metrics_timer = QTimer(self)
            self.metrics_timer.timeout.connect(self._update_metrics)
            self.metrics_timer.start(METRICS_REFRESH_INTERVAL)
            logger.debug(f"✅ Metrics timer iniciado ({METRICS_REFRESH_INTERVAL}ms)")
            
            # Timer 3: Time Display (1 segundo)
            self.time_timer = QTimer(self)
            self.time_timer.timeout.connect(self._update_time_display)
            self.time_timer.start(1000)  # 1s
            logger.debug("✅ Time display timer iniciado (1s)")
            
            # Executar primeira verificação imediatamente
            
            logger.info("✅ Todos os timers configurados e iniciados")
            
        except Exception as e:
            logger.error(f"Erro ao configurar timers: {e}", exc_info=True)
    
    def _restore_previous_state(self):
        """
        Restaura Estado Anterior --- Persistência Entre Sessões
        
        ESTADO PERSISTIDO:
            - Posição e tamanho da janela
            - Aba ativa
            - Configurações de UI
            - Filtros e ordenação de tabelas
        
        ARQUIVO:
            ui_state.json no diretório de configuração
        
        FALLBACK:
            Se arquivo não existe ou está corrompido, usa defaults.
        """
        logger = self.logger
        
        try:
            state_file = CONFIG_DIR / "ui_state.json"
            
            if not state_file.exists():
                logger.info("Nenhum estado anterior encontrado - usando defaults")
                return
            
            logger.info(f"Restaurando estado anterior de {state_file}...")
            
            with open(state_file, 'r', encoding='utf-8') as f:
                state = json.load(f)
            
            # Restaurar geometria da janela
            if 'window_geometry' in state:
                geom = state['window_geometry']
                self.setGeometry(
                    geom['x'],
                    geom['y'],
                    geom['width'],
                    geom['height']
                )
                logger.debug(f"Geometria restaurada: {geom}")
            
            # Restaurar aba ativa
            if 'active_tab' in state:
                tab_index = state['active_tab']
                if 0 <= tab_index < self.tabs.count():
                    self.tabs.setCurrentIndex(tab_index)
                    logger.debug(f"Aba ativa restaurada: {tab_index}")
            
            # Restaurar tema
            if 'theme' in state:
                self._on_theme_changed(state['theme'])
                logger.debug(f"Tema restaurado: {state['theme']}")
            
            logger.info("✅ Estado anterior restaurado com sucesso")
            
        except json.JSONDecodeError as e:
            logger.warning(f"Arquivo de estado corrompido, usando defaults: {e}")
        except Exception as e:
            logger.error(f"Erro ao restaurar estado: {e}", exc_info=True)
    
